local Engine = {}

-- ── УТЕЧКА СОЕДИНЕНИЙ (исправлено) ──────���─────────────��──────────────────────
-- __g.NOVA_ENGINE пересобирается КАЖДЫЙ раз, когда скрипт запускают заново без
-- рестарта экзекутора (NOVA_FX/NOVA_FONTS кэшируются, а движок -- нет). Внутри
-- висят 12 :Connect (UIS-ввод + paint-слои Z.*). Без отключения старые коннекты
-- копились БЕСКОНЕЧНО и каждый кадр вхолостую дёргали мёртвый Engine.
-- Реестр + Engine.destroy() отключают ВСЁ прошлого инстанса перед новым.
local engineConns = {}
local drawFns, mobileFns, overlayQueue
local keybindEls = {}
Engine.keybindEls = keybindEls
local function track(c) if c then engineConns[#engineConns + 1] = c end return c end
-- TC(obj):Connect(fn) == track(obj:Connect(fn)); заворачивает и UIS-сигналы, и
-- paint-слои, не трогая тело/закрывающий end) замыкания.
local function TC(obj)
    return { Connect = function(_, fn) return track(obj:Connect(fn)) end }
end
do
    local prev = rawget(__g, "NOVA_ENGINE")
    if type(prev) == "table" and type(prev.destroy) == "function" then
        pcall(prev.destroy)
    end
end
function Engine.destroy()
    Engine.destroyed = true
    for i = #engineConns, 1, -1 do
        local c = engineConns[i]
        if c then c:Disconnect() end
        engineConns[i] = nil
    end
    if Engine.unloadFx then pcall(Engine.unloadFx) end
    if drawFns then table.clear(drawFns) end
    if mobileFns then table.clear(mobileFns) end
    if overlayQueue then table.clear(overlayQueue) end
    for k in pairs(Engine.keybindEls or {}) do Engine.keybindEls[k] = nil end
end

local function svc(name)
    local s = game:GetService(name)
    return cloneref and cloneref(s) or s
end

local UIS = svc("UserInputService")
local HttpService = svc("HttpService")  -- для SaveConfig/LoadConfig (JSON)
local CAS = svc("ContextActionService") -- чтобы «съедать» колесо/зум над окном

-- ── DrawingImmediate + ШИМ поверх обычного Drawing ─────────────────────────
-- Раньше здесь стоял жёсткий error(), если у экзекутора нет DrawingImmediate.
-- Но у части экзекуторов DrawingImmediate попросту отсутствует, хотя обычный
-- retained Drawing есть. Разницы в РЕЗУЛЬТАТЕ по сути нет -- только в оптимизации
-- (immediate перерисовывает налету, retained держит пул объектов). Поэтому если
-- DrawingImmediate нет -- эмулируем его поверх Drawing: тот же API (GetPaint +
-- глобальные примитивы), а под капотом пул retained-объектов, который каждый кадр
-- переиспользуется. Единственная видимая деградация -- скругление углов (у
-- Drawing "Square" может не быть Rounding) и чуть выше стоимость кадра.
if typeof(Drawing) ~= "table" then
    error("[NOVA] requires an executor with Drawing", 2)
end

local DI = DrawingImmediate

-- Флаги выбора рендер-бэкенда (demo.lua пробрасывает их через getgenv()):
--   NOVA_USE_DRAWING  -> форсить старый шим поверх retained Drawing;
--   NOVA_USE_INSTANCE -> форсить Instance-бэкенд (Frame/UICorner/UIStroke).
-- Без флагов: есть DrawingImmediate -> нативный путь; нет -> Instance-бэкенд.
-- Почему Instance лучше шима на мобильных/слабых экзекуторах: (1) у Instance'ов
-- НЕТ лимита на число объектов (у Drawing он есть -> UI обрезался), (2) круги и
-- скругления настоящие через UICorner (Drawing-круги вырождаются в «пирамиды», а
-- Square.Rounding на мобиле визуально игнорируется -> всё было квадратным),
-- (3) чёткий нативный рендер вместо «жёстко оптимизированного» мобильного Drawing.
local forceDrawing  = __g.NOVA_USE_DRAWING == true
local forceInstance = __g.NOVA_USE_INSTANCE == true
local needFallback  = forceDrawing or forceInstance or typeof(DI) ~= "table"

-- ── Общий retained-core: пул объектов + пофреймовый diff-кэш ──────────────────
-- Оба бэкенда (Drawing-шим и Instance) эмулируют immediate-модель поверх пула
-- persistent-объектов. Свойство пишется ТОЛЬКО при изменении (diff), иначе на
-- ~2600 объектах кадр тонет в C++/GPU-записях. createObj(kind)->object и
-- removeObj(object) специфичны для бэкенда; всё остальное общее. Мета-поля
-- (__vis/__init/дети) держим в кэше c, а НЕ на объекте: Instance бросает при
-- записи неизвестного свойства.
local function makeRetainedCore(createObj, removeObj)
    local pools, layers, zCursor = {}, {}, 0
    local warnedCreate, warnedErr = false, false
    local function pool(kind)
        local p = pools[kind]
        if not p then p = { objs = {}, cache = {}, n = 0, cursor = 0 }; pools[kind] = p end
        return p
    end
    local function acquire(kind)
        local p = pool(kind)
        p.cursor = p.cursor + 1
        local i = p.cursor
        local o, c = p.objs[i], p.cache[i]
        if not o then
            local ok, obj = pcall(createObj, kind)
            if not ok or obj == nil then
                if not warnedCreate then
                    warnedCreate = true
                    warn("[NOVA] object create failed for '" .. tostring(kind)
                        .. "' -- some UI may be missing")
                end
                o, c = {}, { __stub = true }
                p.objs[i] = o; p.cache[i] = c
                if i > p.n then p.n = i end
                return o, c
            end
            o = obj; c = {}
            p.objs[i] = o; p.cache[i] = c
            if i > p.n then p.n = i end
        end
        zCursor = zCursor + 1
        if c.__z ~= zCursor then c.__z = zCursor; if not c.__stub then o.ZIndex = zCursor end end
        if c.__vis ~= true then c.__vis = true; if not c.__stub then o.Visible = true end end
        return o, c
    end
    local function sp(o, c, k, v)
        if c[k] ~= v then c[k] = v; if not c.__stub then o[k] = v end end
    end
    local function GetPaint(z)
        return { Connect = function(_, fn)
            local entry = { z = z or 0, fn = fn }
            layers[#layers + 1] = entry
            table.sort(layers, function(a, b) return a.z < b.z end)
            return { Connected = true, Disconnect = function(self2)
                for i = #layers, 1, -1 do if layers[i] == entry then table.remove(layers, i) end end
                if self2 then self2.Connected = false end
            end }
        end }
    end
    local function render()
        zCursor = 0
        for _, p in pairs(pools) do p.cursor = 0 end
        for i = 1, #layers do
            layers[i].fn()
        end
        -- zCursor после фазы отрисовки == число объектов, затребованных (и
        -- показанных) в этом кадре. Выносим наружу для диагностики: 0 на мобиле
        -- => рисовалки не вызывались (окно не в дереве слоёв); >0, но пусто на
        -- экране => Drawing этого экзекутора не отображает объекты.
        Engine._shimVisible = zCursor
        for _, p in pairs(pools) do
            for i = p.cursor + 1, p.n do
                local o, c = p.objs[i], p.cache[i]
                if c and c.__vis ~= false then
                    c.__vis = false; if not c.__stub then o.Visible = false end
                end
            end
        end
    end
    local function free()
        for _, p in pairs(pools) do
            for i = 1, p.n do
                local o, c = p.objs[i], p.cache[i]
                if o and c and not c.__stub then pcall(removeObj, o) end
                p.objs[i] = nil; p.cache[i] = nil
            end
            p.n, p.cursor = 0, 0
        end
    end
    return { acquire = acquire, sp = sp, GetPaint = GetPaint, render = render, free = free }
end

-- ── Instance-бэкенд (Frame / UICorner / UIStroke / TextLabel) ────────────────
-- Реализует те же 8 DI-примитивов, что и Drawing-шим, но на Roblox Instance'ах.
-- Каждый примитив имеет свой пул (kind), чтобы объекты не «перемешивались» между
-- разными формами (иначе остались бы чужие UICorner/Rotation/UIStroke).
local function buildInstanceBackend()
    -- Родитель ScreenGui: gethui() -> CoreGui -> PlayerGui.
    local parent = gethui()
    if not parent then
        parent = game:GetService("CoreGui")
    end
    if not parent then
        parent = game:GetService("Players").LocalPlayer:FindFirstChildOfClass("PlayerGui")
    end
    if not parent then error("no GUI parent available") end

    local gui = Instance.new("ScreenGui")
    gui.Name = "NOVA_" .. tostring(math.random(100000, 999999))
    gui.IgnoreGuiInset = true
    gui.ResetOnSpawn = false
    gui.DisplayOrder = 2147483647
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    gui.Parent = parent
    if gui.Parent == nil then
        gui:Destroy()
        error("cannot parent ScreenGui")
    end

    -- Числовой Drawing-шрифт -> Enum.Font (ширины меряет отдельный Drawing probe,
    -- поэтому небольшие расхождения метрик некритичны).
    local DF = Drawing.Fonts or {}
    local EF = Enum.Font
    local FMAP = {}
    FMAP[DF.UI or 0] = EF.Gotham
    FMAP[DF.System or 1] = EF.SourceSans
    FMAP[DF.Plex or 2] = EF.Gotham
    FMAP[DF.Monospace or 3] = EF.Code
    local function mapFont(f) return FMAP[f] or EF.Gotham end

    local CLASS = { Rect = "Frame", Stroke = "Frame", Line = "Frame", Ring = "Frame",
                    Disc = "Frame", Txt = "TextLabel", TxtO = "TextLabel" }
    local core = makeRetainedCore(function(kind)
        local o = Instance.new(CLASS[kind] or kind)
        o.Parent = gui
        return o
    end, function(o) o:Destroy() end)
    local acquire, sp = core.acquire, core.sp

    -- Композитные поля/дети через кэш (создаются один раз, апдейт по diff).
    local function anchor(o, c, ax, ay)
        if c.__ax ~= ax or c.__ay ~= ay then c.__ax = ax; c.__ay = ay
            o.AnchorPoint = Vector2.new(ax, ay) end
    end
    local function posOff(o, c, x, y)
        if c.__px ~= x or c.__py ~= y then c.__px = x; c.__py = y
            o.Position = UDim2.fromOffset(x, y) end
    end
    local function sizeOff(o, c, w, h)
        if c.__sw ~= w or c.__sh ~= h then c.__sw = w; c.__sh = h
            o.Size = UDim2.fromOffset(w, h) end
    end
    local function setCorner(o, c, rad)   -- rad<0 => полный круг (UDim.new(1,0))
        local uc = c.__corner
        if not uc then uc = Instance.new("UICorner"); uc.Parent = o; c.__corner = uc end
        if c.__crad ~= rad then c.__crad = rad
            uc.CornerRadius = rad < 0 and UDim.new(1, 0) or UDim.new(0, rad) end
    end
    local function setStroke(o, c, color, thick, transp)
        local us = c.__stroke
        if not us then us = Instance.new("UIStroke"); us.Parent = o; c.__stroke = us end
        if c.__soff then c.__soff = false; us.Enabled = true end
        if c.__scol ~= color then c.__scol = color; us.Color = color end
        if c.__sth ~= thick then c.__sth = thick; us.Thickness = thick end
        if c.__str ~= transp then c.__str = transp; us.Transparency = transp end
    end

    local B = { GetPaint = core.GetPaint, __core = core, __name = "Instance backend" }

    function B.FilledRectangle(pos, size, color, opacity, rounding)
        local o, c = acquire("Rect")
        if not c.__stub and not c.__init then c.__init = true
            o.BorderSizePixel = 0; anchor(o, c, 0, 0) end
        sp(o, c, "BackgroundColor3", color)
        sp(o, c, "BackgroundTransparency", 1 - (opacity or 1))
        posOff(o, c, pos.X, pos.Y); sizeOff(o, c, size.X, size.Y)
        if not c.__stub then setCorner(o, c, (rounding and rounding > 0) and rounding or 0) end
    end
    function B.Rectangle(pos, size, color, opacity, rounding, thickness)
        local o, c = acquire("Stroke")
        if not c.__stub and not c.__init then c.__init = true
            o.BorderSizePixel = 0; o.BackgroundTransparency = 1; anchor(o, c, 0, 0) end
        posOff(o, c, pos.X, pos.Y); sizeOff(o, c, size.X, size.Y)
        if not c.__stub then
            setCorner(o, c, (rounding and rounding > 0) and rounding or 0)
            setStroke(o, c, color, thickness or 1, 1 - (opacity or 1))
        end
    end
    function B.Text(pos, font, size, color, opacity, str, center)
        local o, c = acquire("Txt")
        if not c.__stub and not c.__init then c.__init = true
            o.BackgroundTransparency = 1; o.BorderSizePixel = 0
            o.AutomaticSize = Enum.AutomaticSize.XY; o.Size = UDim2.fromOffset(0, 0)
            o.TextYAlignment = Enum.TextYAlignment.Top end
        sp(o, c, "Text", str or "")
        sp(o, c, "TextColor3", color)
        sp(o, c, "TextTransparency", 1 - (opacity or 1))
        sp(o, c, "TextSize", size)
        sp(o, c, "Font", mapFont(font))
        if not c.__stub then if center then anchor(o, c, 0.5, 0) else anchor(o, c, 0, 0) end end
        posOff(o, c, pos.X, pos.Y)
    end
    function B.OutlinedText(pos, font, size, color, opacity, ocolor, oopacity, str, center)
        local o, c = acquire("TxtO")
        if not c.__stub and not c.__init then c.__init = true
            o.BackgroundTransparency = 1; o.BorderSizePixel = 0
            o.AutomaticSize = Enum.AutomaticSize.XY; o.Size = UDim2.fromOffset(0, 0)
            o.TextYAlignment = Enum.TextYAlignment.Top end
        sp(o, c, "Text", str or "")
        sp(o, c, "TextColor3", color)
        sp(o, c, "TextTransparency", 1 - (opacity or 1))
        sp(o, c, "TextSize", size)
        sp(o, c, "Font", mapFont(font))
        if not c.__stub then
            if center then anchor(o, c, 0.5, 0) else anchor(o, c, 0, 0) end
            setStroke(o, c, ocolor or Color3.new(0, 0, 0), 1, 1 - (oopacity or 1))
        end
        posOff(o, c, pos.X, pos.Y)
    end
    function B.Line(p1, p2, color, opacity, thickness)
        local o, c = acquire("Line")
        if not c.__stub and not c.__init then c.__init = true
            o.BorderSizePixel = 0; anchor(o, c, 0.5, 0.5) end
        local dx, dy = p2.X - p1.X, p2.Y - p1.Y
        local len = math.sqrt(dx * dx + dy * dy)
        sp(o, c, "BackgroundColor3", color)
        sp(o, c, "BackgroundTransparency", 1 - (opacity or 1))
        sizeOff(o, c, len < 1 and 1 or len, thickness or 1)
        posOff(o, c, (p1.X + p2.X) / 2, (p1.Y + p2.Y) / 2)
        if not c.__stub then
            local rot = math.deg(math.atan2(dy, dx))
            if c.__rot ~= rot then c.__rot = rot; o.Rotation = rot end
        end
    end
    function B.Circle(center, radius, color, opacity, sides, thickness)
        local o, c = acquire("Ring")
        if not c.__stub and not c.__init then c.__init = true
            o.BorderSizePixel = 0; o.BackgroundTransparency = 1; anchor(o, c, 0.5, 0.5) end
        local d = radius * 2
        sizeOff(o, c, d, d); posOff(o, c, center.X, center.Y)
        if not c.__stub then
            setCorner(o, c, -1)
            setStroke(o, c, color, thickness or 1, 1 - (opacity or 1))
        end
    end
    function B.FilledCircle(center, radius, color, sides, opacity)
        local o, c = acquire("Disc")
        if not c.__stub and not c.__init then c.__init = true
            o.BorderSizePixel = 0; anchor(o, c, 0.5, 0.5) end
        sp(o, c, "BackgroundColor3", color)
        sp(o, c, "BackgroundTransparency", 1 - (opacity or 1))
        local d = radius * 2
        sizeOff(o, c, d, d); posOff(o, c, center.X, center.Y)
        if not c.__stub then setCorner(o, c, -1) end
    end
    function B.FilledTriangle(a, b, c2, color, opacity)
        -- Instances не заливают произвольный треугольник дёшево. Заливка иконок и
        -- так идёт через FilledRectangle-скан-лайны; сюда попадают лишь редкие
        -- акценты -- рисуем контур тремя линиями, чтобы форма была видна.
        B.Line(a, b, color, opacity, 1)
        B.Line(b, c2, color, opacity, 1)
        B.Line(c2, a, color, opacity, 1)
    end

    Engine.__novaGui = gui
    return B
end

-- Выбор бэкенда. ПО УМОЛЧАНИЮ фолбэк = retained Drawing-шим (он оптимизирован под
-- наш векторный растеризатор: тонкие линии/скан-лайны). Instance-бэкенд оказался
-- НЕ подходящим для этой задачи (иконки-полилинии -> тысячи повёрнутых Frame ->
-- кривизна и просадка FPS), поэтому он теперь ТОЛЬКО по явному флагу
-- NOVA_USE_INSTANCE. Без DI и без флагов идём в Drawing-шим.
-- Весь монтаж под одним pcall: осечка громко предупреждает и падает в шим.
local instanceInstalled = false
if needFallback and forceInstance then
    local ok, err = pcall(function()
        local b = buildInstanceBackend()
        if not b then error("buildInstanceBackend returned nil", 0) end
        local RS = svc("RunService")
        local driver = RS and (RS.Heartbeat or RS.RenderStepped)
        if not driver then error("RunService has no Heartbeat/RenderStepped", 0) end
        track(driver:Connect(function()
            if Engine.destroyed then return end
            b.__core.render()
        end))
        Engine.freeShimPool = function()
            b.__core.free()
            if Engine.__novaGui then pcall(function() Engine.__novaGui:Destroy() end)
                Engine.__novaGui = nil end
        end
        DI = b
        instanceInstalled = true
    end)
    local w = warn
    if ok and instanceInstalled then
        w("[NOVA] using Instance backend (Frame/UICorner/UIStroke)"
            .. (forceInstance and " [forced]" or ""))
    else
        instanceInstalled = false
        w("[NOVA] Instance backend unavailable (" .. tostring(err)
            .. ") -- falling back to Drawing shim")
    end
end

if needFallback and not instanceInstalled then
    if forceDrawing and typeof(DI) == "table" then
        warn("[NOVA] NOVA_USE_DRAWING=true -- forcing retained Drawing "
            .. "shim (DrawingImmediate present but ignored, for testing)")
    end
    -- ── Построение шима ────────────────────────────────────────────────────
    -- Immediate-модель: GetPaint(z):Connect(fn) регистрирует пофреймовый колбэк
    -- слоя; внутри fn глобальные DI.* рисуют в «текущий» слой. Порядок слоёв -- по
    -- z. Мы гоняем это сами через RenderStepped: каждый кадр обнуляем курсоры
    -- пулов, прогоняем колбэки слоёв по возрастанию z, затем прячем неиспользо-
    -- ванные в этом кадре объекты. ZIndex каждого примитива -- монотонный счётчик
    -- (zCursor), поэтому порядок отрисовки 1:1 совпадает с поряд��ом вызовов, как в
    -- настоящем immediate-режиме.
    local RS = svc("RunService")

    -- Поддерживает ли Drawing "Square" скругление (Rounding)? Проверяем ОДИН раз:
    -- на части сборок присвоение несуществующего поля бросает -> pcall.
    local squareRounding = pcall(function()
        local s = Drawing.new("Square"); s.Rounding = 4; s:Remove()
    end)

    -- Пул retained-объектов + ПОКАДРОВЫЙ DIFF-КЭШ. Ключевая оптимизация: запись
    -- свойства Drawing-объекта -- дорогой C++ вызов (обновляет GPU-объект). Между
    -- кадрами UI почти статичен, поэтому свойство пишется ТОЛЬКО если изменилось с
    -- прошлого кадра (сравнение по значению: Vector2/Color3/число/строка сравнимы
    -- через ~=). Это срезает ~18000 записей/кадр (2600 объектов x ~7 полей) почти
    -- до нуля на статичных кадрах -- без diff FPS на мобиле падал в пол.
    local pools = {}          -- pools[kind] = { objs={}, cache={}, n=0, cursor=0 }
    local layers = {}         -- { { z=, fn= }, ... }, отсортирован по z
    local zCursor = 0

    local function pool(kind)
        local p = pools[kind]
        if not p then
            p = { objs = {}, cache = {}, n = 0, cursor = 0 }
            pools[kind] = p
        end
        return p
    end

    -- Взять следующий объект типа kind (создать при нехватке). Возвращает объект И
    -- его кэш свойств. ZIndex (монотонный -> порядок отрисовки) и Visible тоже
    -- проходят через diff, чтобы не писать их без нужды.
    local warnedCreate = false
    local function acquire(kind)
        local p = pool(kind)
        p.cursor = p.cursor + 1
        local i = p.cursor
        local o = p.objs[i]
        local c = p.cache[i]
        if not o then
            -- Drawing.new может упасть/вернуть nil, если у экзекутора лимит на
            -- число Drawing-объектов (UI разбит на ~2600 примитивов). Тогда
            -- подставляем пустую таблицу-заглушку: слой не падает, просто этот
            -- примитив не виден. Предупреждаем ОДИН раз.
            local ok, obj = pcall(Drawing.new, kind)
            if not ok or type(obj) ~= "userdata" and type(obj) ~= "table" then
                if not warnedCreate then
                    warnedCreate = true
                    warn("[NOVA] Drawing.new(\"" .. tostring(kind)
                        .. "\") failed -- executor may cap Drawing objects; "
                        .. "some UI may be missing")
                end
                obj = {}   -- заглушка: записи свойств -- no-op, рендера нет
                -- СЧЁТЧИК ЗАГЛУШЕК: если на мобиле он большой, значит экзекутор
                -- упёрся в лимит Drawing-объектов и UI физически не может быть
                -- нарисован (заглушки не рендерятся) -> «пустой экран».
                Engine._shimStubs = (Engine._shimStubs or 0) + 1
            else
                Engine._shimMade = (Engine._shimMade or 0) + 1
            end
            o = obj
            c = {}
            p.objs[i] = o
            p.cache[i] = c
            if i > p.n then p.n = i end
        end
        zCursor = zCursor + 1
        if c.ZIndex ~= zCursor then c.ZIndex = zCursor; o.ZIndex = zCursor end
        if c.Visible ~= true then c.Visible = true; o.Visible = true end
        return o, c
    end

    -- Diff-сеттер: писать поле объекта только при изменении значения.
    local function sp(o, c, k, v)
        if c[k] ~= v then c[k] = v; o[k] = v end
    end

    local shim = {}

    -- Transparency в Drawing -- это АЛЬФА (1 = непрозрачно, 0 = невидимо), ровно
    -- как opacity у DrawingImmediate. Поэтому маппинг прямой.
    function shim.FilledRectangle(pos, size, color, opacity, rounding)
        local o, c = acquire("Square")
        sp(o, c, "Filled", true)
        sp(o, c, "Position", pos)
        sp(o, c, "Size", size)
        sp(o, c, "Color", color)
        sp(o, c, "Transparency", opacity or 1)
        if squareRounding then sp(o, c, "Rounding", rounding or 0) end
    end
    function shim.Rectangle(pos, size, color, opacity, rounding, thickness)
        local o, c = acquire("Square")
        sp(o, c, "Filled", false)
        sp(o, c, "Thickness", thickness or 1)
        sp(o, c, "Position", pos)
        sp(o, c, "Size", size)
        sp(o, c, "Color", color)
        sp(o, c, "Transparency", opacity or 1)
        if squareRounding then sp(o, c, "Rounding", rounding or 0) end
    end
    function shim.Text(pos, font, size, color, opacity, str, center)
        local o, c = acquire("Text")
        sp(o, c, "Text", str or "")
        sp(o, c, "Size", size)
        sp(o, c, "Font", font or 0)
        sp(o, c, "Color", color)
        sp(o, c, "Transparency", opacity or 1)
        sp(o, c, "Position", pos)
        sp(o, c, "Center", center or false)
        sp(o, c, "Outline", false)
    end
    function shim.OutlinedText(pos, font, size, color, opacity, ocolor, oopacity, str, center)
        local o, c = acquire("Text")
        sp(o, c, "Text", str or "")
        sp(o, c, "Size", size)
        sp(o, c, "Font", font or 0)
        sp(o, c, "Color", color)
        sp(o, c, "Transparency", opacity or 1)
        sp(o, c, "Position", pos)
        sp(o, c, "Center", center or false)
        sp(o, c, "Outline", true)
        sp(o, c, "OutlineColor", ocolor or Color3.new(0, 0, 0))
    end
    function shim.Line(p1, p2, color, opacity, thickness)
        local o, c = acquire("Line")
        sp(o, c, "From", p1)
        sp(o, c, "To", p2)
        sp(o, c, "Color", color)
        sp(o, c, "Transparency", opacity or 1)
        sp(o, c, "Thickness", thickness or 1)
    end
    function shim.Circle(center, radius, color, opacity, sides, thickness)
        local o, c = acquire("Circle")
        sp(o, c, "Filled", false)
        sp(o, c, "Radius", radius)
        sp(o, c, "NumSides", sides or 24)
        sp(o, c, "Thickness", thickness or 1)
        sp(o, c, "Position", center)
        sp(o, c, "Color", color)
        sp(o, c, "Transparency", opacity or 1)
    end
    -- ВНИМАНИЕ: у DrawingImmediate.FilledCircle порядок иной, чем у Circle --
    -- (center, radius, color, num_sides, opacity): num_sides ПЕРЕД opacity.
    function shim.FilledCircle(center, radius, color, sides, opacity)
        local o, c = acquire("Circle")
        sp(o, c, "Filled", true)
        sp(o, c, "Radius", radius)
        sp(o, c, "NumSides", sides or 250)
        sp(o, c, "Position", center)
        sp(o, c, "Color", color)
        sp(o, c, "Transparency", opacity or 1)
    end
    function shim.FilledTriangle(a, b, c2, color, opacity)
        local o, c = acquire("Triangle")
        sp(o, c, "Filled", true)
        sp(o, c, "PointA", a)
        sp(o, c, "PointB", b)
        sp(o, c, "PointC", c2)
        sp(o, c, "Color", color)
        sp(o, c, "Transparency", opacity or 1)
    end

    function shim.GetPaint(z)
        return {
            Connect = function(_, fn)
                local entry = { z = z or 0, fn = fn }
                layers[#layers + 1] = entry
                table.sort(layers, function(a, b) return a.z < b.z end)
                return {
                    Connected = true,
                    Disconnect = function(self2)
                        for i = #layers, 1, -1 do
                            if layers[i] == entry then table.remove(layers, i) end
                        end
                        if self2 then self2.Connected = false end
                    end,
                }
            end,
        }
    end

    -- Пофреймовый драйвер: сам гоняем слои (у настоящего DI это делает движок).
    -- Heartbeat (НЕ RenderStepped): RenderStepped срабатывает ДО обновления
    -- камеры -> при shift-lock/вращении retained-объекты отставали на кадр
    -- (дрожание). Heartbeat идёт после физики -> позиции стабильны. Для retained
    -- Drawing частота Heartbeat достаточна (объекты персистентны между кадрами).
    local driver = RS.Heartbeat or RS.RenderStepped
    local warnedErr = false
    track(driver:Connect(function()
        if Engine.destroyed then return end
        zCursor = 0
        for _, p in pairs(pools) do p.cursor = 0 end
        for i = 1, #layers do
            layers[i].fn()
        end
        -- Прячем объекты, не затребованные в этом кадре (Visible через diff).
        for _, p in pairs(pools) do
            for i = p.cursor + 1, p.n do
                local o, c = p.objs[i], p.cache[i]
                if o and c and c.Visible ~= false then
                    c.Visible = false; o.Visible = false
                end
            end
        end
    end))

    -- Очистка пула (retained-объекты переживают скрипт). Зовётся из unloadFx.
    Engine.freeShimPool = function()
        for _, p in pairs(pools) do
            for i = 1, p.n do
                local o = p.objs[i]
                if o then pcall(function() o:Remove() end); p.objs[i] = nil end
                p.cache[i] = nil
            end
            p.n, p.cursor = 0, 0
        end
    end

    -- Причину фиксируем ДО перезаписи DI (ниже DI = shim -> typeof(DI) станет
    -- "table" и уже не отразит исходное отсутствие). forceDrawing -> ручной форс;
    -- иначе фолбэк случился потому, что Instance-бэкенд не поднялся, а DI не было.
    local why = forceDrawing and "NOVA_USE_DRAWING=true"
        or (typeof(DI) ~= "table" and "DrawingImmediate unavailable")
        or "Instance backend unavailable"
    DI = shim
    -- warn есть не у всех экзекуторов -> безопасный фолбэк на print.
    warn("[NOVA] " .. why .. " -- using retained Drawing shim "
        .. "(square corners" .. (squareRounding and " supported" or " only") .. ")")
end

local Fonts = Drawing.Fonts
Engine.Fonts = Fonts

