local clamp, exp = math.clamp, math.exp

local function inRect(m, x, y, w, h)
    return m.X >= x and m.X <= x + w and m.Y >= y and m.Y <= y + h
end
Engine.inRect = inRect

-- Кадронезависимое сглаживание вместо твин��в: в immediate-mode нет объектов,
-- которым можно назначить твин, а TweenService работает только с Instance.
-- approach is hover/press interpolation. Callers already pass numbers
-- (`s.hover`, `x and 1 or 0`). type() on every call was leftover from a
-- boolean-openT bug that was fixed at the source.
local function approach(cur, target, dt, speed)
    return cur + (target - cur) * (1 - exp(-(speed or 14) * dt))
end
Engine.approach = approach

