-- ИЗМЕРЕНИЕ ТЕКСТА
----------------------------------------------------------------------------
-- DrawingImmediate.Text измерять не умеет. Держим один невидимый persistent
-- Drawing "Text" как линейку -- у него есть TextBounds (read-only).
-- ЗАЩИТА: раньше это был голый Drawing.new("Text") на верхнем уровне движка ->
-- если у мобильного экзекутора Drawing.Text кривой/бросает, весь бандл-IIFE падал
-- ДО построения UI, а ошибка глохла у раннера => «нет UI, пусто в логах». Теперь
-- создание под pcall; при провале measure() переходит на оценку по ширине символа.
local probe
do
    local ok, p = pcall(function()
        local t = Drawing.new("Text"); t.Visible = false; return t
    end)
    if ok then probe = p
    else warn("[NOVA] text probe unavailable (" .. tostring(p)
        .. ") -- using estimated text metrics") end
end
-- УТЕЧКА ПАМЯТИ (исправлено): measureCache кэшировал КАЖДУЮ уникальную строку
-- навсегда. Динамический текст (FPS "142.3", таймеры, пинг, координаты) плодит
-- бесконечно новые ключи -> кэш р��с��ё�� весь сеанс -> «оперативка сжирает��я».
-- Решение: ограниченный кэш с максимумом записей. При переполнении сбрасываем
-- (простой two-generation: активный + предыдущий), что даёт эффект LRU почти без
-- накладных расходов и без per-frame аллокаций.
-- Nested cache [font][size][str] -- NO concatenated key. The old
-- `font.."\0"..size.."\0"..str` allocated a string on EVERY call, including
-- hits, which is the "eats RAM every second" leak from frame 1.
local measureCache = {}
local measureCount, MEASURE_MAX = 0, 900

local function measure(str, size, font)
    if str == nil or str == "" then return Vector2.zero end
    font = font or THEME.font
    size = math.floor((size or 13) * THEME.scale + 0.5)
    local byFont = measureCache[font]
    if not byFont then
        byFont = {}
        measureCache[font] = byFont
    end
    local bySize = byFont[size]
    if not bySize then
        bySize = {}
        byFont[size] = bySize
    end
    local c = bySize[str]
    if c then return c end
    local b
    if probe then
        -- Drawing.Text.Font is DrawingFont, not a string. wrap/fit may pass
        -- nil (THEME.font is the enum) or a name leftover -- never write a string.
        if type(font) ~= "string" then
            probe.Font = font
        end
        probe.Size = size
        probe.Text = str
        b = probe.TextBounds
    end
    if not b then b = Vector2.new(math.floor(#str * size * 0.55 + 0.5), size) end
    -- Short numeric labels (FPS, timers, sliders) churn every frame --
    -- inserting them fills MEASURE_MAX then everything else misses.
    local cacheable = #str > 6 or not string.match(str, "^[%d%.%%%:%+%-]+$")
    if cacheable and measureCount < MEASURE_MAX then
        bySize[str] = b
        measureCount = measureCount + 1
    end
    return b
end
Engine.measure = measure

-- УНИВЕРСАЛЬНАЯ ОБРЕЗКА ТЕКСТА по ширине maxW: если строка влеза��т -- верн��ть как
-- есть; иначе обрезать и добавить «…». Бинарный поиск по длине -> дёшево. Нужна,
-- чтобы ярлыки элементов не налезали на значения при маленьком окне/крупном шрифте.
local function fitText(str, size, maxW, font)
    if not str or str == "" then return str end
    if maxW <= 0 then return "" end
    if measure(str, size, font).X <= maxW then return str end
    local ell = "…"
    local ellW = measure(ell, size, font).X
    if ellW >= maxW then return "" end
    local lo, hi, best = 1, #str, 0
    while lo <= hi do
        local mid = (lo + hi) // 2
        local sub = string.sub(str, 1, mid)
        if measure(sub, size, font).X + ellW <= maxW then
            best = mid; lo = mid + 1
        else
            hi = mid - 1
        end
    end
    return string.sub(str, 1, best) .. ell
end
Engine.fitText = fitText

-- ПЕРЕНОС ПО СЛОВАМ: разбивает строку на строки, влезающие в maxW (px; measure
-- уже учитывает THEME.scale). Слово длиннее с�����роки р��жется посимвольно, явные
-- \n сохраняются. Нужен, чтобы Label/Paragraph НЕ обрезались «…», а «падали
-- вниз» переносом, а секция росла под них (высоту секции считаем тем же
-- wrapText в elemHeight -> геометрия совпадает с реально нарисованным).
-- Ограниченный two-generation кеш переносов (как у measure): wrapText зовётся
-- 2x/кадр на каждый текстовый элемент (высота секции + отрисовка), а разбивка со
-- множеством measure() на слово недёшева. Ключ учитывает scale -> п��и смене кегля
-- пересчёт корректный. Результат неизменяемый (никто не мутирует список строк).
-- Nested cache [font][size][maxW][scale][str] -- no concat key (same leak as measure).
local wrapCache = {}
local wrapCount, WRAP_MAX = 0, 400
local function wrapText(str, size, maxW, font)
    if not str or str == "" then return { "" } end
    if maxW <= 0 then return { str } end
    local fontKey = font or THEME.font or 0
    local maxWi = math.floor(maxW)
    local sc = THEME.scale
    local a = wrapCache[fontKey]
    if not a then a = {}; wrapCache[fontKey] = a end
    local b = a[size]
    if not b then b = {}; a[size] = b end
    local c = b[maxWi]
    if not c then c = {}; b[maxWi] = c end
    local d = c[sc]
    if not d then d = {}; c[sc] = d end
    local hit = d[str]
    if hit then return hit end
    local lines = {}
    for rawLine in (tostring(str) .. "\n"):gmatch("(.-)\n") do
        if rawLine == "" then
            lines[#lines + 1] = ""
        else
            local cur = ""
            for word in rawLine:gmatch("%S+") do
                local try = (cur == "") and word or (cur .. " " .. word)
                if measure(try, size, font).X <= maxW then
                    cur = try
                else
                    if cur ~= "" then lines[#lines + 1] = cur; cur = "" end
                    if measure(word, size, font).X > maxW then
                        -- одно слово шире строки -> режем посимвольно
                        local piece = ""
                        for i = 1, #word do
                            local ch = string.sub(word, i, i)
                            if measure(piece .. ch, size, font).X <= maxW then
                                piece = piece .. ch
                            else
                                if piece ~= "" then lines[#lines + 1] = piece end
                                piece = ch
                            end
                        end
                        cur = piece
                    else
                        cur = word
                    end
                end
            end
            lines[#lines + 1] = cur
        end
    end
    if #lines == 0 then lines[1] = "" end
    if wrapCount < WRAP_MAX then
        d[str] = lines
        wrapCount = wrapCount + 1
    end
    return lines
end
Engine.wrapText = wrapText

