-- Сироты от предыдущих прогонов: без этого ��аждый перезапуск добавлял ещё одну
-- панель к «вееру». Вызывать ДО создания св��их объектов.
cleardrawcache()

----------------------------------------------------------------------------
-- РЕЕСТР HIT-ОБЛАСТЕЙ  (единственный ист��чник истины для ��вода)
----------------------------------------------------------------------------
-- ДВОЙНОЙ БУФЕР + ПУЛ ЗАПИСЕЙ: раньше каждый кадр аллоцировался новый frameHits{}
-- и по НОВОЙ табли��е на каждый hit() (десятки-сотни за кадр) -> постоянный GC-churn,
-- из-за которого heap экзекутора медленно полз вверх («жрёт всё больше оперативы»).
-- Теперь держим ровно два пула и переиспользуем записи, ��утируя их на месте.
local hitPoolA, hitPoolB = {}, {}
local frameHits, liveHits = hitPoolA, hitPoolB
local frameHitN, liveHitN = 0, 0
local hitSeq = 0

-- Активная область обрезки (см. раздел ОБРЕЗКА ниже). Объявлена здесь, потому
-- что hit обязан её ��чи��ывать: иначе прокрученный за край вид��ет остался бы
-- кликабельным поверх тайтлбара.
local clip = nil

-- Регистрируется во время отрисовки. scrollable=true означает, что обла��ть
-- готова принимать колесо мыши. ignoreClip=true -- для областей слоя OVERLAY
-- (открытые дропдауны): их отрисовка тоже идёт без clip, поэтому и hit не
-- должен резаться гра��ицей прокручиваемого тела карточки. Без этого пункты
-- списка ниже clip-а не регистрировались -> кликались ��олько первы��, а клик по
-- нижним попадал в элемент ПОД списком и закрывал меню (см. closeOverlaysExcept).
local function hit(key, x, y, w, h, z, scrollable, ignoreClip)
    if clip and not ignoreClip then
        local nx, ny = math.max(x, clip.x), math.max(y, clip.y)
        local nr, nb = math.min(x + w, clip.r), math.min(y + h, clip.b)
        if nr <= nx or nb <= ny then return end
        x, y, w, h = nx, ny, nr - nx, nb - ny
    end
    hitSeq += 1
    frameHitN += 1
    -- переиспользуем таблицу из пула (или доращиваем пул один раз при пике)
    local rec = frameHits[frameHitN]
    if not rec then rec = {}; frameHits[frameHitN] = rec end
    rec.key, rec.x, rec.y, rec.w, rec.h = key, x, y, w, h
    rec.z = z or Z.CONTENT
    rec.seq = hitSeq
    rec.scrollable = scrollable
end
Engine.hit = hit

-- С��ма���� верхняя область под точкой: сначала по слою, при равенстве -- по
-- порядку отрисовки (нарисованн��е позже лежит выш��).
local function pick(pt, needScroll)
    local best
    -- по liveHitN, а НЕ по #liveHits: в пуле за концом кадра лежат старые записи
    for i = 1, liveHitN do
        local r = liveHits[i]
        if (not needScroll or r.scrollable) and inRect(pt, r.x, r.y, r.w, r.h) then
            if not best or r.z > best.z or (r.z == best.z and r.seq > best.seq) then
                best = r
            end
        end
    end
    return best
end
Engine.pick = pick

-- ��писок hit-областей прош��ого кадра. Нужен для отладки и автотестов: по нему
-- ��ожно найти реальные экранные координаты виджета по его ключу.
function Engine.debugHits()
    -- срез ровно liveHitN (пул содержит хвост записей прошлых кадров)
    local out = {}
    for i = 1, liveHitN do out[i] = liveHits[i] end
    return out
end

