-- СОСТОЯНИЕ ВВОД��
----------------------------------------------------------------------------
local input = {
    mouse     = Vector2.zero,
    delta     = Vector2.zero,
    down      = false,
    hoverKey  = nil,
    activeKey = nil,   -- захват до отпускания ��нопки
    grabOff   = Vector2.zero,
}
Engine.input = input

-- Одноразовые события, которые виджет «съе��ает» на своё�� кадре.
local pendingClick = nil
local pendingRight = nil
local pendingScrollKey, pendingScrollDelta = nil, 0

function Engine.isHover(key)
    return input.hoverKey == key
end

function Engine.isActive(key)
    return input.activeKey == key and input.down
end

-- true ровно один раз на клик.
function Engine.clicked(key)
    if pendingClick == key then
        pendingClick = nil
        return true
    end
    return false
end

-- true ровно один раз на клик ПРАВОЙ кнопкой (для контекстных действий,
-- напр. свернуть секцию ПКМ).
function Engine.rightClicked(key)
    if pendingRight == key then
        pendingRight = nil
        return true
    end
    return false
end

-- Дельта колеса, тоже один раз.
function Engine.scrolled(key)
    if pendingScrollKey == key then
        local d = pendingScrollDelta
        pendingScrollKey, pendingScrollDelta = nil, 0
        return d
    end
    return 0
end

-- ОТЛОЖЕННАЯ ОТРИ��ОВКА.
-- DrawingImmediate в��утр�� одного zIndex рисует в порядке вызова, поэтому
-- открытый др��пд��ун закрасили б�� виджеты, идущие н��ж�� него по layout.
-- Геометрия и hit-области считаютс�� на месте (в основном проходе), а сама
-- отрисовка списка ��езжает в отдельный проход Z.OVERLAY поверх всего.
overlayQueue = {}

local function deferOverlay(fn)
    overlayQueue[#overlayQueue + 1] = fn
end
Engine.deferOverlay = deferOverlay

-- Долгоживущее состояние виджетов по ключу (ховер, анимации, открытость).
local ui = {}
local function stateOf(key)
    local s = ui[key]
    if not s then
        s = { hover = 0, press = 0, on = 0 }
        ui[key] = s
    end
    return s
end
Engine.stateOf = stateOf

----------------------------------------------------------------------------
-- ОБРЕЗКА (программная)
----------------------------------------------------------------------------
-- В DrawingImmediate нет scissor/clip, поэтому ��рокручиваемый список иначе
-- вылез бы за ок��о и нарисовался поверх тайтлбара. ��еализуем обрезку сами:
-- прямоугол��ники подрезаются по гр��ни��е, текст и строки отбрасываются целиком
-- (без шейдера половину глифа не срезать, а строки низкие -- разница не видна).

-- На��т��ящий стек с пересечением: вьюпорт внутри прокручиваем��го списка должен
-- обрезатьс�� и своей рамкой, и границей списка одновременно.
local clipStack = {}

-- ПУЛ clip-таблиц по ГЛУБИНЕ. Раньше pushClip аллоцировал новую таблицу на каждый
-- вызов -> при 10-20 вложениях в кадр это поток покадрового мусора для GC (одна из
-- причин периодического фриза). Обрезка строго вложенная (push/pop как стек),
-- поэтому на каждой глубине переиспользуем ОДНУ таблицу между кадрами.
local _clipPool = {}
local _clipDepth = 0

local function pushClip(x, y, w, h)
    local nx, ny, nr, nb = x, y, x + w, y + h
    if clip then
        nx, ny = math.max(nx, clip.x), math.max(ny, clip.y)
        nr, nb = math.min(nr, clip.r), math.min(nb, clip.b)
    end
    clipStack[#clipStack + 1] = clip
    _clipDepth = _clipDepth + 1
    local c = _clipPool[_clipDepth]
    if not c then c = {}; _clipPool[_clipDepth] = c end
    c.x, c.y, c.r, c.b = nx, ny, nr, nb
    clip = c
end

local function popClip()
    local n = #clipStack
    clip = clipStack[n]
    clipStack[n] = nil
    if _clipDepth > 0 then _clipDepth = _clipDepth - 1 end
end
Engine.pushClip, Engine.popClip = pushClip, popClip

-- true, если габаритный прямоугольник целиком вне обрезки
local function culled(x1, y1, x2, y2)
    if not clip then return false end
    return x2 < clip.x or x1 > clip.r or y2 < clip.y or y1 > clip.b
end
Engine.culled = culled

-- П��ресечение прямоугольника с clip. Возвращает nil, если виден не будет.
local function clipRect(x, y, w, h)
    if not clip then return x, y, w, h, false end
    local x2, y2 = x + w, y + h
    local nx, ny = math.max(x, clip.x), math.max(y, clip.y)
    local nr, nb = math.min(x2, clip.r), math.min(y2, clip.b)
    if nr <= nx or nb <= ny then return nil end
    local trimmed = (nx ~= x or ny ~= y or nr ~= x2 or nb ~= y2)
    return nx, ny, nr - nx, nb - ny, trimmed
end

local function visibleY(y, h)
    if not clip then return true end
    return y + h > clip.y and y < clip.b
end

----------------------------------------------------------------------------
-- ��РИМИТИВЫ
----------------------------------------------------------------------------
-- Engine.gAlpha (п.13): глобальный множитель прозрачности для анимации меню.
-- 1 = полностью видно, 0 = невидимо. Все прими����вы умн��жаю�� свою opacity на
-- него, поэтому одно значение красиво гасит/проявляет весь UI за раз.
Engine.gAlpha = 1
local function gA(o) return (o or 1) * Engine.gAlpha end

-- ── ОПТИМИЗАЦИЯ GC: кэш Vector2 ────────────────────────────────────────────
-- Roblox Vector2 -- иммутабельный userdata: КАЖДЫЙ Vector2.new() аллоцирует объект.
-- В горячем пути (rrect/rstroke/text/line...) это сотни-тысячи аллокаций в кадр ->
-- Luau копит мусор и раз в пару минут делает полную сборку -> фриз на пару кадров.
-- Кэшируем ТОЧНО по (x,y): при статичном UI координаты повторяются кадр-в-кадр ->
-- ~100% попаданий -> почти ноль аллокаций. Кэш вложенный (row = _v2c[x]; v = row[y])
-- -> числовые ключи, поиск БЕЗ аллокаций. Точность не теряется. Сброс целиком при
-- переполнении (анимации плодят уникальные координаты).
local _V2 = Vector2.new
local _v2c = {}
local _v2n = 0
-- Engine._v2fx: animated FX (particles/dissolve/bloom) must NOT enter the
-- cache -- unique coords fill 8000 then every later unique pixel allocates
-- forever (the leftover 2 MB/s after the dump was removed).
Engine._v2fx = false
local function v2(x, y)
    x = math.floor((x or 0) + 0.5)
    y = math.floor((y or 0) + 0.5)
    if Engine._v2fx then return _V2(x, y) end
    local row = _v2c[x]
    if not row then
        if _v2n >= 8000 then return _V2(x, y) end
        row = {}
        _v2c[x] = row
    end
    local v = row[y]
    if not v then
        v = _V2(x, y)
        if _v2n < 8000 then
            row[y] = v
            _v2n = _v2n + 1
        end
    end
    return v
end
Engine.v2 = v2

-- Скругление НЕЛЬЗЯ з��да��а��ь больше половины меньшей стороны: DI рисует дугу
-- углов радиусом `rounding`, и если он пре��ыш��ет w/2 или h/2, дуги «пер��хлёстыв��ют»
-- центр и ВЫЛЕЗАЮТ за прямоугольник -> визуально «кривые углы, выходящие за рамки»
-- (жалоба касалась не только кнопок). Клампи�� здесь ОДИН раз для всего UI.
local function clampRound(r, w, h)
    if not r or r <= 0 then return 0 end
    local m = math.min(w, h) * 0.5
    if r > m then return m end
    return r
end

local function rrect(x, y, w, h, color, opacity, rounding)
    if Engine.gAlpha <= 0 then return end
    local cx, cy, cw, ch, trimmed = clipRect(x, y, w, h)
    if not cx then return end
    -- у подрезанного прямоугольника скругление убирае��: иначе на срезанной
    -- кромке появился ��ы фальшивый за��руглённый угол
    DI.FilledRectangle(v2(cx, cy), v2(cw, ch), color,
        gA(opacity), trimmed and 0 or clampRound(rounding, cw, ch))
end

local function rstroke(x, y, w, h, color, opacity, rounding, thickness)
    if Engine.gAlpha <= 0 then return end
    -- ��амку рис��ем только целиком: обрезанная рамка выглядит как разрыв
    if clip and (y < clip.y or y + h > clip.b) then return end
    local cx, cy, cw, ch = clipRect(x, y, w, h)
    if not cx then return end
    DI.Rectangle(v2(cx, cy), v2(cw, ch), color,
        gA(opacity), clampRound(rounding, cw, ch), thickness or 1)
end

local function text(x, y, size, color, str, opacity, font, center)
    if Engine.gAlpha <= 0 then return end
    size = math.floor(size * THEME.scale + 0.5)   -- глобальный кегль (см. THEME.scale)
    if not visibleY(y, size + 4) then return end
    if clip and (y < clip.y - 2 or y + size > clip.b + 2) then return end
    -- защита от nil-строки (краш ":3280: string expected, got nil")
    DI.Text(v2(x, y), font or THEME.font, size, color, gA(opacity), tostring(str or ""), center or false)
end

local function line(x1, y1, x2, y2, color, opacity, thickness)
    if Engine.gAlpha <= 0 then return end
    if clip then
        local lo, hi = math.min(y1, y2), math.max(y1, y2)
        if hi < clip.y or lo > clip.b then return end
    end
    DI.Line(v2(x1, y1), v2(x2, y2), color, gA(opacity), thickness or 1)
end

-- ЧЁТКИЙ текст с обводкой (нативный DI.OutlinedText). Раньше «тень» под текстом
-- рисовали вторым смещённым DI.Text -> текст выглядел размытым/некачественным.
-- OutlinedText кладёт ровную обводку за один вызов -> текст остаётся резким и
-- читается н�� ��юбом фоне (н��п����. на светл��м Aqua-градиенте кнопки).
local function textOutlined(x, y, size, color, str, opacity, outlineCol, outlineOp, font, center)
    if Engine.gAlpha <= 0 then return end
    size = math.floor(size * THEME.scale + 0.5)
    if not visibleY(y, size + 4) then return end
    if clip and (y < clip.y - 2 or y + size > clip.b + 2) then return end
    DI.OutlinedText(v2(x, y), font or THEME.font, size, color, gA(opacity),
        outlineCol or COL.app, gA(outlineOp or 0.9), str, center or false)
end
Engine.textOutlined = textOutlined

-- круги отбрасываем целиком: подрезать окружность нечем
-- disc: залитый круг. РАНЬШЕ рисовался DI.FilledCircle, но на целевом билде
-- FilledCircle вырождается в треугольник (жалобы про «пирамиды» у тумблер������,
-- точек и ручек слайдеров). Рисуем как rrect со скруглением = радиусу -->
-- квадрат с радиусом в половину стороны есть круг, гладкий и без треугольников.
-- Параметр sides сохранён для совместимости си��натуры, но не используется.
local function disc(cx, cy, r, color, opacity, sides)
    if clip and (cy + r < clip.y or cy - r > clip.b) then return end
    rrect(cx - r, cy - r, r * 2, r * 2, color, opacity or 1, r)
end

local function ring(cx, cy, r, color, opacity, sides, thickness)
    if Engine.gAlpha <= 0 then return end
    if clip and (cy + r < clip.y or cy - r > clip.b) then return end
    DI.Circle(v2(cx, cy), r, color, (opacity or 1) * Engine.gAlpha, sides or 24, thickness or 1)
end
Engine.disc, Engine.ring = disc, ring

Engine.rrect, Engine.rstroke, Engine.text, Engine.line = rrect, rstroke, text, line

----------------------------------------------------------------------------
-- NOISE DISSOLVE (п.13) -- аппрокси��ация шейдера noise_mask.fsh из референса.
----------------------------------------------------------------------------
-- Настоящий пиксельный шейдер в DrawingImmediate недоступен, поэтому «растворение»
-- ри��уем СЕТКОЙ клеток: у каждой клетки сво�� псевдослучайный порог thr; клетка
-- видна (закраш��вается фоном окна, «отъедая» его), пока пр��грес�� перехода не
-- превысил её порог. Двигая порог вместе с openT, получа��м эффект сборки/распада
-- окна из шумовых квад��атиков -- ��ак в Minecraft-референсе. При openT≈1 сетка
-- пустая (ничего не перекры��ает), п��и openT→0 окно осыпается.
local function noiseAt(ix, iy)
    -- дешёвый детерминированный хеш -> [0,1); стабилен между кадрами. Luau не
    -- имеет оператора '~', поэтому XOR берём через bit32.
    local n = bit32.bxor(ix * 374761 % 2147483647, iy * 668265 % 2147483647)
    n = (n * 2246822519) % 2147483647
    return (n % 1000) / 1000
end
function Engine.drawDissolve(x, y, w, h, openT)
    local p = clamp(openT, 0, 1)
    if p >= 0.999 then return end
    local cell = 22
    local cols = math.ceil(w / cell)
    local rows = math.ceil(h / cell)
    Engine.pushClip(x, y, w, h)
    local prevA = Engine.gAlpha
    Engine.gAlpha = 1
    local acc = COL.cyan
    local prevFx = Engine._v2fx
    Engine._v2fx = true
    for cy2 = 0, rows - 1 do
        for cx2 = 0, cols - 1 do
            local dir = (cy2 / rows) * 0.55 + (1 - cx2 / cols) * 0.14
            local thr = noiseAt(cx2, cy2) * 0.60 + dir * 0.40
            if p < thr then
                local px = x + cx2 * cell
                local py = y + cy2 * cell
                local sz = v2(cell + 1, cell + 1)
                local edge = clamp((thr - p) / 0.14, 0, 1)
                DI.FilledRectangle(v2(px, py), sz, COL.app,
                    0.5 + 0.5 * edge, 0)
                if edge < 0.55 then
                    DI.FilledRectangle(v2(px, py), sz, acc,
                        (0.55 - edge) * 0.55, 0)
                end
            end
        end
    end
    Engine._v2fx = prevFx
    Engine.gAlpha = prevA
    Engine.popClip()
end

----------------------------------------------------------------------------
-- ПАРТИКЛ-СИСТЕМА (п.14) -- лёгкие плавающие частицы в фоне контента.
----------------------------------------------------------------------------
-- Лени��ая инициализация пула частиц под конкретную область (x,y,w,h). Частицы
-- ме��ленно всплывают, чуть дрейфуют по X (синусоида), мерцают прозрачностью и,
-- уходя за верх, перерождаются снизу. Рисуются акцентным цветом (COL.cyan) ->
-- автоматически переливаются вместе со схемой. Управляе��ся Engine.particlesOn.
local particles, partArea = nil, nil
Engine.particlesOn = true
-- ДЕТАЛЬНАЯ настройка частиц (правится из UI, таб Customization -> Effects).
--   count  -- сколько частиц (пул перестраивается при смене)
--   speed  -- мно��итель скорости всплытия
--   size   -- множитель радиуса/размера
--   drift  -- множитель бокового дрейфа
--   glow   -- множитель прозрачности (яркость)
--   shape  -- "dots" | "stars" | "bolts"
--   dir    -- "up" | "down"
Engine.particleCfg = {
    count = 16, speed = 1, size = 1, drift = 1, glow = 1,
    shape = "dots", dir = "up",
}
local function initParticles(w, h, n)
    particles = {}
    for i = 1, n do
        particles[i] = {
            x = math.random() * w,
            y = math.random() * h,
            r = 1 + math.random() * 2,           -- базовый радиус
            spd = 6 + math.random() * 14,        -- базовая скорость (px/с)
            amp = 4 + math.random() * 14,        -- амплитуда бокового дрейфа
            ph = math.random() * 6.28,           -- фаз�� др��йфа/мерцания
            fr = 0.4 + math.random() * 0.9,      -- частота мерцания
            rot = math.random() * 6.28,          -- поворот (для звёзд/молний)
        }
    end
end
-- Залитый треугольник с учётом gAlpha и клипа (DI.FilledTriangle сам их не знает).
local function fillTri(ax, ay, bx, by, cx, cy, col, a)
    if Engine.gAlpha <= 0 then return end
    if clip then
        local miny = math.min(ay, by, cy)
        local maxy = math.max(ay, by, cy)
        if maxy < clip.y or miny > clip.b then return end
    end
    DI.FilledTriangle(v2(ax, ay), v2(bx, by), v2(cx, cy),
        col, (a or 1) * Engine.gAlpha)
end

-- 4-конечная ЗВЕЗДА-искра как ЗАЛИТЫЙ 8-вершинный полигон (веер треугольников из
-- центра). Никаких кругов -- чистый sparkle, гладкий на любом размере.
local STAR_PTS = {
    { 0, -1 }, { 0.2, -0.2 }, { 1, 0 }, { 0.2, 0.2 },
    { 0, 1 }, { -0.2, 0.2 }, { -1, 0 }, { -0.2, -0.2 },
}
local function drawStar(px, py, r, col, a, rot)
    local c, s = math.cos(rot), math.sin(rot)
    local function P(o)
        local ox, oy = o[1] * r, o[2] * r
        return px + (ox * c - oy * s), py + (ox * s + oy * c)
    end
    local n = #STAR_PTS
    for i = 1, n do
        local x1, y1 = P(STAR_PTS[i])
        local x2, y2 = P(STAR_PTS[i % n + 1])
        fillTri(px, py, x1, y1, x2, y2, col, a)
    end
end

-- МОЛНИЯ как настоящий SVG-гли���� (Lucide "zap"): ЗАЛИТЫЙ полигон-зигзаг из двух
-- п��рекрывающихся «флажк��в��, а н�� тонкие лини��. Читается как ⚡ на любом размере.
-- Верхний ф��ажок смотрит вниз-влево, нижний -- вверх-вправо; их перекрытие в центре
-- даёт характерный излом молнии. Без свечения-кругов (жалоба на «какой-то ��руг»).
local BOLT_UP = { { 0.20, -0.95 }, { -0.52, 0.12 }, { 0.10, 0.12 } }
local BOLT_DN = { { -0.20, 0.95 }, { 0.52, -0.12 }, { -0.10, -0.12 } }
local function drawBolt(px, py, r, col, a, rot)
    local c, s = math.cos(rot), math.sin(rot)
    local function P(o)
        local ox, oy = o[1] * r, o[2] * r
        return px + (ox * c - oy * s), py + (ox * s + oy * c)
    end
    local u1x, u1y = P(BOLT_UP[1]); local u2x, u2y = P(BOLT_UP[2]); local u3x, u3y = P(BOLT_UP[3])
    local d1x, d1y = P(BOLT_DN[1]); local d2x, d2y = P(BOLT_DN[2]); local d3x, d3y = P(BOLT_DN[3])
    fillTri(u1x, u1y, u2x, u2y, u3x, u3y, col, a)
    fillTri(d1x, d1y, d2x, d2y, d3x, d3y, col, a)
end
-- ��ис����ем в области (x,y,w,h). dt -- шаг времени. Уваж��ет clip и gAlpha.
function Engine.drawParticles(x, y, w, h, dt)
    if not Engine.particlesOn then return end
    local cfg = Engine.particleCfg
    local n = math.max(1, math.floor(cfg.count or 16))
    w, h = math.floor(w + 0.5), math.floor(h + 0.5)
    if not particles or not partArea or partArea.w ~= w or partArea.h ~= h
        or partArea.n ~= n then
        initParticles(w, h, n)
        partArea = { w = w, h = h, n = n }
    end
    local t = os.clock()
    local down = (cfg.dir == "down")
    local prevFx = Engine._v2fx
    Engine._v2fx = true
    for _, p in ipairs(particles) do
        local vy = p.spd * (cfg.speed or 1) * dt
        if down then
            p.y = p.y + vy
            if p.y > h + 4 then p.y = -4; p.x = math.random() * w end
        else
            p.y = p.y - vy
            if p.y < -4 then p.y = h + 4; p.x = math.random() * w end
        end
        local dx = math.sin(t * 0.6 + p.ph) * p.amp * (cfg.drift or 1)
        local base = 0.12 + 0.14 * (0.5 + 0.5 * math.sin(t * p.fr + p.ph))
        local a = base * (cfg.glow or 1)
        local r = p.r * (cfg.size or 1)
        -- ПЛАВНОЕ ЗАТУХАНИЕ У КРАЁВ ПОЛЯ: клип прямоугольный, поэтому раньше частицы
        -- жёстко обрезались на границе (и было заметно «поздно исчезают»). Теперь
        -- гасим alpha в приграничной полосе -> частица мягко тает у любого края и не
        -- «выскакивает» резко. Плюс поле уже инсетнуто от скруглённых углов (см. вызов).
        local lx = p.x + dx
        local edge = 18
        local fade = clamp(math.min(lx, w - lx) / edge, 0, 1)
            * clamp(math.min(p.y, h - p.y) / edge, 0, 1)
        a = a * fade
        local cxp, cyp = x + lx, y + p.y
        local rot = p.rot + t * 0.5
        if a <= 0.003 then
            -- полностью прозр��чная -> не тратим примитивы (и не мигаем на границе)
        elseif cfg.shape == "stars" then
            drawStar(cxp, cyp, r * 1.6, COL.cyan, a, rot)
        elseif cfg.shape == "bolts" then
            drawBolt(cxp, cyp, r * 1.8, COL.cyan, a * 1.2, rot)
        else
            disc(cxp, cyp, r, COL.cyan, a, 10)
        end
    end
    Engine._v2fx = prevFx
end

----------------------------------------------------------------------------
-- IMAGE POOL -- persistent Drawing "Image" objects driven from immediate mode.
----------------------------------------------------------------------------
-- DrawingImmediate has no image primitive, so real raster art (SVG/PNG data
-- URLs) must live in retained Drawing objects. This pool bridges the two
-- worlds: `Engine.image(key, data, x, y, w, h, z, rounding)` positions (and
-- lazily creates) one Image per stable key each frame; `Engine.sweepImages()`
-- hides any image not touched this frame. That is exactly how a retained
-- object is scheduled from an immediate UI.
--
-- ZIndex note: Drawing objects share the paint z-space with DrawingImmediate
-- (the window shaders prove it: z=2 draws under the DI layers at z>=48). So an
-- image at z=55 lands above the content DI (Z.BODY=50) and below open overlays
-- (Z.OVERLAY=60) -- which is what a toggle knob mark wants.
local _imgPool = {}
local _imgOk = true
local _imgCount = 0
local _imgFrame = 0           -- счётчик кадров для LRU
local IMG_POOL_MAX = 64       -- потолок живых Drawing("Image") объектов

-- УТЕЧКА (профилактика): раньше пул создавал по Drawing-объекту на КАЖДЫЙ
-- уникальный key и не удалял их никогда (sweepImages только прятал). Если dev
-- использует image-иконки с динамическими ключами -> пул растёт бесконечно
-- реал��ными Drawing-объектами. Добавлен LRU: при переполнении уничтожаем самый
-- давно не использованный объект.
local function evictLRU()
    local oldestKey, oldestFrame
    for k, e in pairs(_imgPool) do
        if not oldestFrame or e.touched < oldestFrame then
            oldestFrame, oldestKey = e.touched, k
        end
    end
    if oldestKey then
        local e = _imgPool[oldestKey]
        pcall(function() if e.obj.Destroy then e.obj:Destroy() end end)
        _imgPool[oldestKey] = nil
        _imgCount = _imgCount - 1
    end
end

local function poolImage(key)
    local e = _imgPool[key]
    if e then return e end
    if not _imgOk or not Drawing then return nil end
    if _imgCount >= IMG_POOL_MAX then evictLRU() end
    local ok, obj = pcall(function() return Drawing.new("Image") end)
    if not ok or not obj then _imgOk = false; return nil end
    e = { obj = obj, data = nil, used = false, touched = _imgFrame }
    _imgPool[key] = e
    _imgCount = _imgCount + 1
    return e
end

function Engine.image(key, data, x, y, w, h, z, rounding)
    local e = poolImage(key)
    if not e then return false end
    local obj = e.obj
    -- Data is expensive to set (decodes the image), so only write it on change.
    if e.data ~= data then
        obj.Data = data
        e.data = data
    end
    obj.Position = v2(x, y)
    obj.Size     = v2(w, h)
    local rnd = rounding or 0
    if e.roundOk == nil then
        e.roundOk = pcall(function() obj.Rounding = rnd end)
        e.round = rnd
    elseif e.roundOk and e.round ~= rnd then
        e.round = rnd
        obj.Rounding = rnd
    end
    if obj.ZIndex ~= nil and e.z ~= (z or 55) then
        e.z = z or 55
        obj.ZIndex = e.z
    end
    if e.vis ~= true then
        e.vis = true
        obj.Visible = true
    end
    e.used = true
    e.touched = _imgFrame        -- LRU-метка
    return true
end

-- Hide everything not drawn this frame. Called once at the end of the frame.
function Engine.sweepImages()
    _imgFrame = _imgFrame + 1
    for _, e in pairs(_imgPool) do
        if not e.used then
            if e.vis ~= false then
                e.vis = false
                e.obj.Visible = false
            end
        end
        e.used = false
    end
end

function Engine.imagesAvailable() return _imgOk end

-- Полностью уничтожает пул image-объектов (при выгрузке библиотеки).
function Engine.freeImagePool()
    for k, e in pairs(_imgPool) do
        pcall(function() if e.obj.Destroy then e.obj:Destroy() end end)
        _imgPool[k] = nil
    end
    _imgCount = 0
end

-- base64 д����я data-URI картинок (SVG). Берём нативный эн��одер экзекутора, иначе
-- чистый Lua. SVG векторный -> Image р��сует его без ступенек на любом размере.
local _b64enc
do
    local candidates = {
        crypt and crypt.base64encode,
        crypt and crypt.base64 and crypt.base64.encode,
        (base64 and base64.encode),
        _G.base64_encode,
    }
    for _, f in ipairs(candidates) do
        if type(f) == "function" then _b64enc = f; break end
    end
    if not _b64enc then
        local B = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        _b64enc = function(data)
            return ((data:gsub(".", function(x)
                local r, b = "", x:byte()
                for i = 8, 1, -1 do r = r .. (b % 2 ^ i - b % 2 ^ (i - 1) > 0 and "1" or "0") end
                return r
            end) .. "0000"):gsub("%d%d%d?%d?%d?%d?", function(x)
                if #x < 6 then return "" end
                local c = 0
                for i = 1, 6 do c = c + (x:sub(i, i) == "1" and 2 ^ (6 - i) or 0) end
                return B:sub(c + 1, c + 1)
            end) .. ({ "", "==", "=" })[#data % 3 + 1])
        end
    end
end

local _svgCache = {}
-- Рисует SVG-строку как картинку. Кэшируем data-URI по (key,svg), потому что
-- base64 дорогой. Возвращает true, если картинку удалось поста��ить.
function Engine.svgImage(key, svg, x, y, w, h, z, rounding)
    if not _imgOk then return false end
    local ck = _svgCache[key]
    if not ck or ck.svg ~= svg then
        local ok, uri = pcall(function()
            return "data:image/svg+xml;base64," .. _b64enc(svg)
        end)
        if not ok then return false end
        ck = { svg = svg, uri = uri }
        _svgCache[key] = ck
    end
    return Engine.image(key, ck.uri, x, y, w, h, z, rounding)
end

-- «Градиентный» скруглённый прямоугольник для мелких поверхностей (шапки
-- секций, кнопки, с����тчи). ����АН��Ш�������������� рисовался горизонтальным�� полосами (banded
-- Lerp) -- отсюда ступеньки и «пиксельность», на которые жаловался юзер.
-- Теперь: ОДИН скруглённый DI-прямоугольник (углы с��лаживает сам DI) цвета-
-- середины + тонка�� светлая кромка сверху и лёгкая тень снизу. Без полос ->
-- без бандинга. Большие «настоящие» градиенты (тело вкладки, активная навигация)
-- рисуются шейдерами (novacontent/novatab), а не этим хелпером.
-- Сэмпл цвета градиента в позиции f∈[0,1]. Flow-режим удалён -> всегда СТАТИЧНЫЙ
-- линейный переход A→B. (Параметр flow сохранён для совместимости сигнатуры, но
-- игнорируется.)
local function gradSampleColor(cA, cB, f)
    return cA:Lerp(cB, f)
end
Engine.gradSampleColor = gradSampleColor

-- НАСТОЯЩИ�� градиент поло��ам�� (раньше заливалось одним средним цветом -> «весь
-- элемент один цвет»). Рисуем N полос вдоль оси (вертикаль по умолчани��, horiz=
-- ��оризонталь). Скруглённые торцы даём накладкой rrect того же цвета, чтобы держать
-- углы без клиппинга. Градиент ВСЕГДА статичный A->B (flow-режим удалён).
-- Хвостовые параметры (_t, horiz, flowTab) сохранены для совместимости вызовов.
local function gradRect(x, y, w, h, cA, cB, opacity, rounding, sheen, _t, horiz, flowTab)
    opacity = opacity or 1
    local op = math.max(0, math.min(1, opacity))
    local r = rounding or 0
    -- ПРОСТОЕ РЕШЕНИЕ: рисуем ОДИН скруглённый rrect со СРЕДНИМ цветом градиента.
    -- Полосная разбивка (arcInset + 1px torcs) создаёт видимые ступеньки на правом краю
    -- кнопок при радиусе 9px и ширине 200+px → пользователь видит «ужатый/неровный угол».
    -- Вместо сложной дуго-врезки: простой скруглённый прямоугольник DI.Rectangle —
    -- его anti-aliasing ИДЕАЛЬНО гладкий, углы симметричны слева и справа.
    -- Минус: нет «настоящего» двухцветного градиента (A→B), только средний цвет.
    -- Плюс: ноль артефактов, скругление работает.
    local midCol = cA:Lerp(cB, 0.5)
    rrect(x, y, w, h, midCol, op, r)
end
Engine.gradRect = gradRect

-- ��олоса прогресса, которая не вылеза��т за скруглённый угол контейнера:
-- собственное скругление не больше половины высоты плюс инсет от края.
local function progress(x, y, w, h, frac, color, opacity, inset)
    inset = inset or 1
    local fw = (w - inset * 2) * clamp(frac, 0, 1)
    if fw <= 0.5 then return end
    rrect(x + inset, y, fw, h, color, opacity or 1, math.min(h * 0.5, 6))
end
Engine.progress = progress

----------------------------------------------------------------------------
-- ИКОНКИ. Рисует векторную иконку из __g.NOVA_ICONS (сгенерирован
-- scripts/export-icons.ts из lib/nova/icon-data.ts -- единый ис��о��ник правды с
-- веб-репликой). Координаты примитив��в нормализован�� 0..1, здесь умножаются на
-- `size` и смещаю��ся в (x, y) -- л��вый верхний угол бокса иконки.
--
-- poly  -> ц��почка line (замыкае��ся при closed=true)
-- circle-> ring (контур)
-- dot   -> disc (залито)
-- дуги уже стесселированы в poly ещё экспортёром -- рантайм не считает sin/cos.
----------------------------------------------------------------------------
-- Достаём табл��цу иконок. Приоритет: глобал __g.NOVA_ICONS (его выставляет
-- nova_icons.lua, подключённый build.sh перед движком). Если билд её не
-- подключил, один раз пытаемся загрузить файл-��осед через readfile -- так
-- nova.lua остаёт��я самодостаточным и в дев-режиме.
local _iconsTried = false
local function getIcons()
    local icons = (__g and __g.NOVA_ICONS) or rawget(_G, "NOVA_ICONS")
    if icons or _iconsTried then return icons end
    _iconsTried = true
    if type(readfile) == "function" and type(loadstring) == "function" then
        pcall(function()
            local ok = loadstring(readfile("nova_icons.lua"))
            if ok then icons = ok() end
        end)
    end
    return icons
end

----------------------------------------------------------------------------
-- РАНТАЙМ SVG-КОМПИЛЯТОР (п.: «вставь svg с lucide.dev -> скрипт рисует»).
-- Разби��ает SVG-строку в тот же формат {w=strokeWidth, prims={...}}, что ��
-- сгенерированные иконки, поэтому дальше рисуется тем же drawIconPoly.
-- Поддержка: <path d>, <circle>, <ellipse>, <rect> (в т.ч. rx/ry), <line>,
-- <polyline>, <polygon>. Дуги (A) и безье (C/S/Q/T) стесселируются в линии.
-- Всё нормализуется по viewBox в 0..1. Результат КЭШИРУЕТСЯ по строке SVG,
-- поэтому компиляция происходит один раз, а не каждый кадр.
----------------------------------------------------------------------------
-- ВНИМАН��Е: _svgCache уже занят выше (кэш data-URI для Engine.svgImage). Здесь
-- отдельный кэш СКОМПИЛИРОВАННЫХ иконок -> своё имя, чтоб�� не путать/не затенять.
local _svgIconCache = {}     -- [svgString] = def  (ре��ультат компиляции)
local _svgIcons = {}         -- [name] = def  (зарегистрированные разработчиком)

-- Сканер чисел SVG: разделители -- пробел/запятая/знак/точка. "1-1.2" -> {1,-1.2},
-- ".5.5" -> {.5,.5}. Для lucide (ф��аги дуг разделены пробелами) этого достаточно.
local function svgScanNums(s)
    local nums, i, n = {}, 1, #s
    while i <= n do
        local c = string.sub(s, i, i)
        if string.match(c, "[%d%.%-+]") then
            local j = i
            if string.match(string.sub(s, j, j), "[%-+]") then j = j + 1 end
            while j <= n and string.match(string.sub(s, j, j), "%d") do j = j + 1 end
            if string.sub(s, j, j) == "." then
                j = j + 1
                while j <= n and string.match(string.sub(s, j, j), "%d") do j = j + 1 end
            end
            if string.match(string.sub(s, j, j), "[eE]") then
                j = j + 1
                if string.match(string.sub(s, j, j), "[%-+]") then j = j + 1 end
                while j <= n and string.match(string.sub(s, j, j), "%d") do j = j + 1 end
            end
            local v = tonumber(string.sub(s, i, j - 1))
            if v then nums[#nums + 1] = v end
            i = (j > i) and j or (i + 1)
        else
            i = i + 1
        end
    end
    return nums
end

local function svgAttr(tag, name)
    return string.match(tag, name .. '%s*=%s*"([^"]*)"')
        or string.match(tag, name .. "%s*=%s*'([^']*)'")
end

-- кубическая безье -> точки (steps сегментов)
local function bezier3(pts, x0, y0, x1, y1, x2, y2, x3, y3, steps)
    for k = 1, steps do
        local t = k / steps
        local u = 1 - t
        local a, b, c2, d = u * u * u, 3 * u * u * t, 3 * u * t * t, t * t * t
        pts[#pts + 1] = { a * x0 + b * x1 + c2 * x2 + d * x3,
                          a * y0 + b * y1 + c2 * y2 + d * y3 }
    end
end

local function bezier2(pts, x0, y0, x1, y1, x2, y2, steps)
    for k = 1, steps do
        local t = k / steps
        local u = 1 - t
        pts[#pts + 1] = { u * u * x0 + 2 * u * t * x1 + t * t * x2,
                          u * u * y0 + 2 * u * t * y1 + t * t * y2 }
    end
end

-- эллиптичес��ая дуг�� (endpoint param) -> точки. Ре��лизаци�� по спецификации SVG.
local function arcTo(pts, x0, y0, rx, ry, phi, laf, sf, x, y)
    if rx == 0 or ry == 0 then pts[#pts + 1] = { x, y }; return end
    rx, ry = math.abs(rx), math.abs(ry)
    local cosp, sinp = math.cos(phi), math.sin(phi)
    local dx, dy = (x0 - x) / 2, (y0 - y) / 2
    local x1p =  cosp * dx + sinp * dy
    local y1p = -sinp * dx + cosp * dy
    local lam = (x1p * x1p) / (rx * rx) + (y1p * y1p) / (ry * ry)
    if lam > 1 then local s = math.sqrt(lam); rx, ry = rx * s, ry * s end
    local sign = (laf ~= sf) and 1 or -1
    local num = rx * rx * ry * ry - rx * rx * y1p * y1p - ry * ry * x1p * x1p
    local den = rx * rx * y1p * y1p + ry * ry * x1p * x1p
    local co = sign * math.sqrt(math.max(0, num / den))
    local cxp =  co * rx * y1p / ry
    local cyp = -co * ry * x1p / rx
    local cx = cosp * cxp - sinp * cyp + (x0 + x) / 2
    local cy = sinp * cxp + cosp * cyp + (y0 + y) / 2
    local function ang(ux, uy, vx, vy)
        local d = math.sqrt((ux * ux + uy * uy) * (vx * vx + vy * vy))
        local c = d == 0 and 1 or math.clamp((ux * vx + uy * vy) / d, -1, 1)
        local a = math.acos(c)
        if ux * vy - uy * vx < 0 then a = -a end
        return a
    end
    local th1 = ang(1, 0, (x1p - cxp) / rx, (y1p - cyp) / ry)
    local dth = ang((x1p - cxp) / rx, (y1p - cyp) / ry, (-x1p - cxp) / rx, (-y1p - cyp) / ry)
    if sf == 0 and dth > 0 then dth = dth - 2 * math.pi
    elseif sf == 1 and dth < 0 then dth = dth + 2 * math.pi end
    local steps = math.max(4, math.floor(math.abs(dth) / (math.pi / 16)))
    for k = 1, steps do
        local th = th1 + dth * (k / steps)
        local ex = cosp * rx * math.cos(th) - sinp * ry * math.sin(th) + cx
        local ey = sinp * rx * math.cos(th) + cosp * ry * math.sin(th) + cy
        pts[#pts + 1] = { ex, ey }
    end
end

-- Разбор d="" в список полилиний {pts={{x,y}...}, closed=bool}
local function parsePath(d)
    local polys, cur = {}, nil
    local cx, cy, sx, sy = 0, 0, 0, 0
    local pcx, pcy, lastCmd = 0, 0, ""
    local function newPoly() cur = { pts = {}, closed = false }; polys[#polys + 1] = cur end
    local function push(px, py) if not cur then newPoly() end; cur.pts[#cur.pts + 1] = { px, py } end
    for cmd, argstr in string.gmatch(d, "([MmLlHhVvCcSsQqTtAaZz])([^MmLlHhVvCcSsQqTtAaZz]*)") do
        local a = svgScanNums(argstr)
        local rel = (cmd == string.lower(cmd)) and cmd ~= "Z"
        local lc = string.upper(cmd)
        if lc == "M" then
            local i = 1
            local X = rel and cx + a[i] or a[i]; local Y = rel and cy + a[i+1] or a[i+1]
            cx, cy, sx, sy = X, Y, X, Y
            newPoly(); push(cx, cy); i = i + 2
            while a[i] and a[i+1] do
                X = rel and cx + a[i] or a[i]; Y = rel and cy + a[i+1] or a[i+1]
                cx, cy = X, Y; push(cx, cy); i = i + 2
            end
        elseif lc == "L" then
            local i = 1
            while a[i] and a[i+1] do
                cx = rel and cx + a[i] or a[i]; cy = rel and cy + a[i+1] or a[i+1]
                push(cx, cy); i = i + 2
            end
        elseif lc == "H" then
            for _, v in ipairs(a) do cx = rel and cx + v or v; push(cx, cy) end
        elseif lc == "V" then
            for _, v in ipairs(a) do cy = rel and cy + v or v; push(cx, cy) end
        elseif lc == "C" then
            local i = 1
            if not cur then newPoly(); push(cx, cy) end
            while a[i+5] do
                local x1 = rel and cx + a[i] or a[i]; local y1 = rel and cy + a[i+1] or a[i+1]
                local x2 = rel and cx + a[i+2] or a[i+2]; local y2 = rel and cy + a[i+3] or a[i+3]
                local X = rel and cx + a[i+4] or a[i+4]; local Y = rel and cy + a[i+5] or a[i+5]
                bezier3(cur.pts, cx, cy, x1, y1, x2, y2, X, Y, 6)
                pcx, pcy, cx, cy = x2, y2, X, Y; i = i + 6
            end
        elseif lc == "S" then
            local i = 1
            while a[i+3] do
                local x1, y1
                if string.upper(lastCmd) == "C" or string.upper(lastCmd) == "S" then
                    x1, y1 = 2 * cx - pcx, 2 * cy - pcy
                else x1, y1 = cx, cy end
                local x2 = rel and cx + a[i] or a[i]; local y2 = rel and cy + a[i+1] or a[i+1]
                local X = rel and cx + a[i+2] or a[i+2]; local Y = rel and cy + a[i+3] or a[i+3]
                bezier3(cur.pts, cx, cy, x1, y1, x2, y2, X, Y, 6)
                pcx, pcy, cx, cy = x2, y2, X, Y; i = i + 4
            end
        elseif lc == "Q" then
            local i = 1
            while a[i+3] do
                local x1 = rel and cx + a[i] or a[i]; local y1 = rel and cy + a[i+1] or a[i+1]
                local X = rel and cx + a[i+2] or a[i+2]; local Y = rel and cy + a[i+3] or a[i+3]
                bezier2(cur.pts, cx, cy, x1, y1, X, Y, 5)
                pcx, pcy, cx, cy = x1, y1, X, Y; i = i + 4
            end
        elseif lc == "T" then
            local i = 1
            while a[i+1] do
                local x1, y1
                if string.upper(lastCmd) == "Q" or string.upper(lastCmd) == "T" then
                    x1, y1 = 2 * cx - pcx, 2 * cy - pcy
                else x1, y1 = cx, cy end
                local X = rel and cx + a[i] or a[i]; local Y = rel and cy + a[i+1] or a[i+1]
                bezier2(cur.pts, cx, cy, x1, y1, X, Y, 5)
                pcx, pcy, cx, cy = x1, y1, X, Y; i = i + 2
            end
        elseif lc == "A" then
            local i = 1
            while a[i+6] do
                local X = rel and cx + a[i+5] or a[i+5]; local Y = rel and cy + a[i+6] or a[i+6]
                arcTo(cur.pts, cx, cy, a[i], a[i+1], math.rad(a[i+2]), a[i+3], a[i+4], X, Y)
                cx, cy = X, Y; i = i + 7
            end
        elseif lc == "Z" then
            if cur then cur.closed = true end
            cx, cy = sx, sy
        end
        lastCmd = cmd
    end
    return polys
end

-- Ком��или��уе�� SVG-строку в def-иконку. opts.stroke переопределяет толщину.
function Engine.compileSVG(svg, opts)
    if type(svg) ~= "string" then return nil end
    if _svgIconCache[svg] then return _svgIconCache[svg] end
    opts = opts or {}
    -- viewBox -> нормализация. По умолчанию lucide -- "0 0 24 24".
    local vb = svgAttr(svg, "viewBox")
    local minx, miny, vbw, vbh = 0, 0, 24, 24
    if vb then
        local n = svgScanNums(vb)
        if n[3] and n[4] then minx, miny, vbw, vbh = n[1], n[2], n[3], n[4] end
    end
    local sw = tonumber(svgAttr(svg, "stroke%-width")) or 2
    -- РЕЖИМ ЗАЛИВКИ. tabler «filled»-иконки объявляют fill="currentColor" на <svg>
    -- (и рисуются СПЛОШНЫМИ формами), тогда к��к lucide -- fill="none" + обводка.
    -- rootFilled=true -> и��онка заливается; отдельные <path fill="none"> (например
    -- прозрачный фон-квадрат) при этом ПРОПУСКАЕМ -- иначе получим лишний контур.
    local rootFill = svgAttr(svg, "fill")
    local rootFilled = rootFill ~= nil and rootFill ~= "none" and rootFill ~= ""
    local def = { w = (opts.stroke or sw) / vbw, prims = {}, filled = rootFilled }
    local function normPush(prim) def.prims[#def.prims + 1] = prim end
    local function npoly(poly, fill)
        local out = {}
        for _, p in ipairs(poly.pts) do
            out[#out + 1] = { (p[1] - minx) / vbw, (p[2] - miny) / vbh }
        end
        if #out >= 2 then normPush({ t = "poly", closed = poly.closed, pts = out, fill = fill }) end
    end

    -- <path ...> с УЧЁТОМ пер-path fill. Итерируем полные теги, чтобы прочитать
    -- собственный fill каждого пути (fill="none" -> пропускаем в filled-иконке).
    local function handlePath(tag, d)
        local pf = svgAttr(tag, "fill")
        if rootFilled and pf == "none" then return end     -- прозрачный фон-путь
        local fill = rootFilled and pf ~= "none"
        for _, poly in ipairs(parsePath(d)) do npoly(poly, fill) end
    end
    for tag, d in string.gmatch(svg, '(<path[^>]-%sd%s*=%s*"([^"]*)"[^>]*>)') do
        handlePath(tag, d)
    end
    for tag, d in string.gmatch(svg, "(<path[^>]-%sd%s*=%s*'([^']*)'[^>]*>)") do
        handlePath(tag, d)
    end
    -- <circle cx cy r>
    for tag in string.gmatch(svg, "<circle[^>]*>") do
        local ccx = tonumber(svgAttr(tag, "cx")) or 0
        local ccy = tonumber(svgAttr(tag, "cy")) or 0
        local cr  = tonumber(svgAttr(tag, "r")) or 0
        if cr > 0 then
            normPush({ t = "circle", c = { (ccx - minx) / vbw, (ccy - miny) / vbh }, r = cr / vbw,
                       fill = rootFilled })
        end
    end
    -- <ellipse> -> circle если rx≈ry, иначе poly-контур
    for tag in string.gmatch(svg, "<ellipse[^>]*>") do
        local ex = tonumber(svgAttr(tag, "cx")) or 0
        local ey = tonumber(svgAttr(tag, "cy")) or 0
        local rx = tonumber(svgAttr(tag, "rx")) or 0
        local ry = tonumber(svgAttr(tag, "ry")) or 0
        if rx > 0 and ry > 0 then
            local pts = {}
            for k = 0, 40 do
                local t = k / 40 * math.pi * 2
                pts[#pts + 1] = { (ex + rx * math.cos(t) - minx) / vbw,
                                  (ey + ry * math.sin(t) - miny) / vbh }
            end
            normPush({ t = "poly", closed = true, pts = pts })
        end
    end
    -- <line x1 y1 x2 y2>
    for tag in string.gmatch(svg, "<line[^>]*>") do
        local x1 = tonumber(svgAttr(tag, "x1")) or 0
        local y1 = tonumber(svgAttr(tag, "y1")) or 0
        local x2 = tonumber(svgAttr(tag, "x2")) or 0
        local y2 = tonumber(svgAttr(tag, "y2")) or 0
        normPush({ t = "poly", closed = false, pts = {
            { (x1 - minx) / vbw, (y1 - miny) / vbh },
            { (x2 - minx) / vbw, (y2 - miny) / vbh } } })
    end
    -- <polyline> / <polygon>
    for kind, tag in string.gmatch(svg, "<(poly%a+)([^>]*)>") do
        local pstr = svgAttr(tag, "points")
        if pstr then
            local n = svgScanNums(pstr)
            local pts, i = {}, 1
            while n[i] and n[i+1] do
                pts[#pts + 1] = { (n[i] - minx) / vbw, (n[i+1] - miny) / vbh }; i = i + 2
            end
            if #pts >= 2 then
                normPush({ t = "poly", closed = (kind == "polygon"), pts = pts })
            end
        end
    end
    -- <rect x y width height rx ry>
    for tag in string.gmatch(svg, "<rect[^>]*>") do
        local rxx = tonumber(svgAttr(tag, "x")) or 0
        local ryy = tonumber(svgAttr(tag, "y")) or 0
        local rw  = tonumber(svgAttr(tag, "width")) or 0
        local rh  = tonumber(svgAttr(tag, "height")) or 0
        local crx = tonumber(svgAttr(tag, "rx")) or 0
        local cry = tonumber(svgAttr(tag, "ry")) or crx
        if crx == 0 then cry = 0 end
        if rw > 0 and rh > 0 then
            local pts = {}
            local function add(px, py) pts[#pts + 1] = { (px - minx) / vbw, (py - miny) / vbh } end
            if crx > 0 then
                crx = math.min(crx, rw / 2); cry = math.min(cry > 0 and cry or crx, rh / 2)
                local function corner(ox, oy, a0, a1)
                    for k = 0, 6 do
                        local t = a0 + (a1 - a0) * (k / 6)
                        add(ox + crx * math.cos(t), oy + cry * math.sin(t))
                    end
                end
                corner(rxx + rw - crx, ryy + cry, -math.pi/2, 0)
                corner(rxx + rw - crx, ryy + rh - cry, 0, math.pi/2)
                corner(rxx + crx, ryy + rh - cry, math.pi/2, math.pi)
                corner(rxx + crx, ryy + cry, math.pi, math.pi*1.5)
            else
                add(rxx, ryy); add(rxx + rw, ryy); add(rxx + rw, ryy + rh); add(rxx, ryy + rh)
            end
            normPush({ t = "poly", closed = true, pts = pts, fill = rootFilled })
        end
    end

    _svgIconCache[svg] = def
    return def
end

-- Регистрирует иконку п��д именем -> д��льше её можно звать как обычную (Icon="name").
-- svg -- полная SVG-строка (напр. скопированная с lucide.dev).
function Engine.registerIcon(name, svg)
    local def = Engine.compileSVG(svg)
    if def then _svgIcons[name] = def end
    return def ~= nil
end
Engine.getSvgIcon = function(name) return _svgIcons[name] end

-- Keep corners, drop collinear tessellation. Fixes "missing folder tab" /
-- crooked gear when a later stride skipped a real vertex.
local function simplifyPoly(pts, closed)
    local n = #pts
    if n <= 4 then return pts end
    local out = { pts[1] }
    for i = 2, n - 1 do
        local ax, ay = pts[i][1] - pts[i - 1][1], pts[i][2] - pts[i - 1][2]
        local bx, by = pts[i + 1][1] - pts[i][1], pts[i + 1][2] - pts[i][2]
        local al2, bl2 = ax * ax + ay * ay, bx * bx + by * by
        if al2 > 1e-10 and bl2 > 1e-10 then
            local dot = (ax * bx + ay * by) / math.sqrt(al2 * bl2)
            if dot < 0.96 then
                out[#out + 1] = pts[i]
            end
        end
    end
    out[#out + 1] = pts[n]
    if closed and #out > 2 then
        local a, b = out[1], out[#out]
        local dx, dy = a[1] - b[1], a[2] - b[2]
        if dx * dx + dy * dy < 1e-8 then out[#out] = nil end
    end
    return out
end
function Engine.simplifyIconDef(def)
    if not def or def._simp then return def end
    def._simp = true
    local prims = def.prims
    if prims then
        for i = 1, #prims do
            local p = prims[i]
            if p.t == "poly" and p.pts and #p.pts > 4 then
                p.pts = simplifyPoly(p.pts, p.closed)
            end
        end
    end
    return def
end

-- Резолвер def иконки: имя набора -> alias -> зарегистрированная -> сырой SVG.
local function resolveIconDef(name)
    if type(name) ~= "string" then return nil end
    if _svgIcons[name] then return _svgIcons[name] end
    -- сырой SVG прямо в поле Icon
    if string.find(name, "<svg", 1, true) or string.find(name, "<path", 1, true)
        or string.find(name, "d=", 1, true) then
        return Engine.compileSVG(name)
    end
    local icons = getIcons()
    if not icons then return nil end
    local def = icons[name]
    if not def and Engine._iconAlias then
        local mapped = Engine._iconAlias[name]
        if mapped then def = icons[mapped] end
    end
    return def
end
Engine.resolveIconDef = resolveIconDef

-- ЗАЛИВКА замкнутого полигона (для filled-иконок). Раньше рендерер УМЕЛ только
-- обводить контуры -> «заполненные» иконки выходили полыми/двойными. Заливаем
-- scanline-спанами через DI.FilledRectangle (FilledCircle/FilledTriangle на целевом
-- билде вырождаются -> ��пирамиды», поэтому строго прямоугольные спан��).
-- Работает и для выпу��лых, и для вогнутых форм (even-odd по пересечениям строки).
-- _fillXs -- переиспользуемый буфер пересече��ий (без GC-мусора на каждый кадр).
local _fillXs = {}
local _fillPtsBuf = {}
local function fillPolyPix(pts, n, color, opacity)
    local miny, maxy = math.huge, -math.huge
    for i = 1, n do
        local py = pts[i][2]
        if py < miny then miny = py end
        if py > maxy then maxy = py end
    end
    local y0 = math.floor(miny + 0.5)
    local y1 = math.ceil(maxy - 0.5)
    for yy = y0, y1 do
        if not (clip and (yy < clip.y or yy > clip.b)) then
            local yc = yy + 0.5
            local m = 0
            for i = 1, n do
                local a = pts[i]
                local b = pts[i % n + 1]
                local ay, by = a[2], b[2]
                if (ay <= yc and by > yc) or (by <= yc and ay > yc) then
                    local t = (yc - ay) / (by - ay)
                    m = m + 1
                    _fillXs[m] = a[1] + t * (b[1] - a[1])
                end
            end
            -- сортировка пересечений (обычно 2..4 шт -> вставками, дёшево)
            for i = 2, m do
                local v = _fillXs[i]; local j = i - 1
                while j >= 1 and _fillXs[j] > v do _fillXs[j + 1] = _fillXs[j]; j = j - 1 end
                _fillXs[j + 1] = v
            end
            for i = 1, m - 1, 2 do
                local xL = _fillXs[i]; local xR = _fillXs[i + 1]
                if xR > xL then
                    DI.FilledRectangle(v2(xL, yy), v2(xR - xL, 1),
                        color, (opacity or 1) * Engine.gAlpha, 0)
                end
            end
        end
    end
end

-- alias-ка��та (нижний регистр -> сгенерированный ключ) заполняется ниже; drawIcon
-- определён РАНЬШЕ неё, поэтому обращаемся через глобаль��ый Engine._iconAlias,
-- который присваивается там же, где объявляется ICON_ALIAS.
local function drawIconPoly(name, x, y, size, color, opacity, thickness, grad)
    -- и��я набора / alias / зарегистрированная иконка / сырой SVG-строкой
    local def = resolveIconDef(name)
    if not def then return false end
    opacity = opacity or 1
    x = math.floor((x or 0) + 0.5)
    y = math.floor((y or 0) + 0.5)
    size = math.max(2, math.floor((size or 12) + 0.5))
    if size % 2 == 1 then size = size + 1 end
    local th = thickness or math.max(1, (def.w or 0.073) * math.min(size, 16))
    th = math.min(th, 1.55)
    local sides = size < 14 and 16 or (size < 22 and 24 or 32)

    -- ДИАГОНАЛЬНЫЙ градиент иконки (референс «кристалл»): цвет берём по позиции
    -- (nx+ny)/2 -> верхний-левый край = cA, нижний-правый = cB, иконка красиво
    -- «поделена» между двумя цветами. Раньше сэмпл был только по nx (горизонталь) ->
    -- перелив читался слабо. grad.phase (Flow) плавно с��виг��ет выборку.
    -- НАСТОЯЩИЙ переливающийся градиент по иконке. Диагональная коо��дината
    -- d=(nx+ny)/2 в [0..1] задаёт положение вдоль градиента; синусоида даёт полный
    -- ход A<->B (а не просто «д��угой цвет»), а grad.phase двигает волну во времени
    -- (универсальная скорость). Без flow -- плавный статичный A->B по диагонали.
    local TAU = math.pi * 2
    local function gcol(nx, ny)
        if not grad then return color end
        local d = (nx + (ny or nx)) * 0.5
        local f
        if grad.flow then
            -- бегущая волна: 0.5 ампли��уды вокруг центра -> вся иконка проходит A..B
            f = 0.5 + 0.5 * math.sin((d - (grad.phase or 0)) * TAU)
        else
            f = d
        end
        if f < 0 then f = 0 elseif f > 1 then f = 1 end
        return grad.a:Lerp(grad.b, f)
    end

    -- Круглый стык/крышка: точка радиусом th*0.5 в вершине полилинии. БЕЗ ��её
    -- толстые отрезки на изломах давали «рваные» углы и просветы (жалоба на
    -- пиксельность/рваность иконок). Ставим только для достаточно толстых линий.
    -- Сегментов у стыка теперь АДАПТИВНО по размеру: было фиксированно 12 -> на
    -- к��упных ик��нках стык выглядел многоу��ольник��м («точки больше/угловатые»).
    -- (Равноме��ность то��ек конту��а тепер�� обес��ечивает г����нератор -> стыки ложатся
    --  ровно, без бугров.)
    -- Caps only on simple glyphs. Dense lucide strokes already overlap at
    -- joints; a disc on every tessellated vertex is the "seams / beads" on
    -- large FABs. Sidebar (size<16) skips caps entirely.
    local cap = th >= 1.6 and size >= 22
    local capR = th * 0.5
    local capSides = size < 28 and 12 or 18
    local function vcap(px, py, nx, ny)
        if cap then disc(px, py, capR, gcol(nx, ny), opacity, capSides) end
    end

    for _, p in ipairs(def.prims) do
        local t = p.t
        if t == "poly" then
            local pts = p.pts
            if p.fill and p.closed and #pts > 2 then
                local n = #pts
                for i = 1, n do
                    local q = _fillPtsBuf[i]
                    if not q then q = {}; _fillPtsBuf[i] = q end
                    q[1] = x + pts[i][1] * size
                    q[2] = y + pts[i][2] * size
                end
                fillPolyPix(_fillPtsBuf, n, gcol(0.5, 0.5), opacity)
            else
            local npts = #pts
            if npts <= 2 then
                local a, b = pts[1], pts[npts]
                local dx, dy = b[1] - a[1], b[2] - a[2]
                if dx * dx + dy * dy < 1e-4 then
                    local px = math.floor(x + a[1] * size + 0.5)
                    local py = math.floor(y + a[2] * size + 0.5)
                    local d = size >= 22 and 3 or 2
                    rrect(px - (d // 2), py - (d // 2), d, d, gcol(a[1], a[2]), opacity, 0)
                else
                    local x1, y1 = x + a[1] * size, y + a[2] * size
                    local x2, y2 = x + b[1] * size, y + b[2] * size
                    if math.abs(y1 - y2) < 0.51 then
                        local mid = math.floor((x1 + x2) * 0.5 + 0.5)
                        local half = math.max(1, math.floor(math.abs(x2 - x1) * 0.5 + 0.5))
                        local yy = math.floor((y1 + y2) * 0.5 + 0.5)
                        line(mid - half, yy, mid + half, yy, gcol(0.5, 0.5), opacity, th)
                    elseif math.abs(x1 - x2) < 0.51 then
                        local mid = math.floor((y1 + y2) * 0.5 + 0.5)
                        local half = math.max(1, math.floor(math.abs(y2 - y1) * 0.5 + 0.5))
                        local xx = math.floor((x1 + x2) * 0.5 + 0.5)
                        line(xx, mid - half, xx, mid + half, gcol(0.5, 0.5), opacity, th)
                    else
                        line(math.floor(x1 + 0.5), math.floor(y1 + 0.5),
                             math.floor(x2 + 0.5), math.floor(y2 + 0.5),
                             gcol(0.5, 0.5), opacity, th)
                    end
                end
            else
            local min2 = size >= 20 and 1.69 or 0.64
            local lx = x + pts[1][1] * size
            local ly = y + pts[1][2] * size
            for i = 2, npts do
                local px = x + pts[i][1] * size
                local py = y + pts[i][2] * size
                local ddx, ddy = px - lx, py - ly
                if i == npts or (ddx * ddx + ddy * ddy) >= min2 then
                    line(lx, ly, px, py,
                        gcol((pts[i - 1][1] + pts[i][1]) * 0.5,
                             (pts[i - 1][2] + pts[i][2]) * 0.5), opacity, th)
                    lx, ly = px, py
                end
            end
            if p.closed and npts > 2 then
                local a, b = pts[npts], pts[1]
                line(x + a[1] * size, y + a[2] * size,
                     x + b[1] * size, y + b[2] * size,
                     gcol((a[1] + b[1]) * 0.5, (a[2] + b[2]) * 0.5), opacity, th)
            end
            if cap and npts <= 8 then
                for i = 1, npts do
                    vcap(x + pts[i][1] * size, y + pts[i][2] * size, pts[i][1], pts[i][2])
                end
            end
            end
            end
        elseif t == "circle" then
            local rr = p.r * size
            if rr < 1.35 then
                -- sparkle/geometry mini-circles read as fat blobs at 13px
            elseif p.fill then
                disc(x + p.c[1] * size, y + p.c[2] * size, rr, gcol(p.c[1], p.c[2]), opacity)
            else
            ring(x + p.c[1] * size, y + p.c[2] * size, rr,
                 gcol(p.c[1], p.c[2]), opacity, sides, th)
            end
        elseif t == "dot" then
            local px = math.floor(x + p.c[1] * size + 0.5)
            local py = math.floor(y + p.c[2] * size + 0.5)
            local d = size >= 22 and 3 or 2
            rrect(px - (d // 2), py - (d // 2), d, d, gcol(p.c[1], p.c[2]), opacity, 0)
        end
    end
    return true
end

-- ЕДИНСТВЕННЫЙ путь иконок -- ВЕКТОР (drawIconPoly): линии/кольца/точки через
-- DrawingImmediate. Рас����ров��е иконки (SVG/PNG через Drawing "Image") УДАЛЕНЫ:
-- они пиксельные при масштабе, не принимают цвет (у Image нет свойства цвета)
-- и как persistent-объекты копили артефакты. Вектор рисуется каждым кадром,
-- всегда чёткий на любом размер�� и красится любым цветом (параметр color).
local function drawIcon(name, x, y, size, color, opacity, thickness, grad)
    drawIconPoly(name, x, y, size, color, opacity, thickness, grad)
end
Engine.drawIcon = drawIcon
Engine.hasIcon = function(name)
    return resolveIconDef(name) ~= nil
end

