----------------------------------------------------------------------------
-- ПОРТ И�� nova_ui: па��ам��трич��ские и соста��ные меши.
--
-- ВАЖНО: V() проецирует КАЖДУЮ вершину на единич��ую сферу -- э��о верно только
-- для платоновых тел, где все вершины равноудалены от центра. Для тора, сферы
-- и гуманоида это бы схлопнуло форму. Поэтому здесь вершины сырые, а весь набор
-- масштабируется ОДНИМ коэффици��нтом так, чтобы радиус описывающей ��феры = 1
-- (как normalize() в nova_ui). Тогда ��юбой меш ��адрируетс�� во вьюпорте
-- одинаково, а render3D/getMesh получают всё тот же формат {verts, faces}.
----------------------------------------------------------------------------
local function fitUnit(verts)
    local max = 0
    for _, v in ipairs(verts) do
        local d = math.sqrt(v.x * v.x + v.y * v.y + v.z * v.z)
        if d > max then max = d end
    end
    if max > 0 then
        for _, v in ipairs(verts) do
            v.x, v.y, v.z = v.x / max, v.y / max, v.z / max
        end
    end
    return verts
end

-- 12 треугольников на бокс, та же намотка, ��то в nova_ui.
local BOX_FACES = {
    {1,2,3},{1,3,4},{6,5,8},{6,8,7},{5,1,4},{5,4,8},
    {2,6,7},{2,7,3},{4,3,7},{4,7,8},{5,6,2},{5,2,1},
}

local function pushBox(verts, faces, cx, cy, cz, sx, sy, sz)
    local base = #verts
    local hx, hy, hz = sx / 2, sy / 2, sz / 2
    local corners = {
        {cx-hx, cy-hy, cz-hz}, {cx+hx, cy-hy, cz-hz},
        {cx+hx, cy+hy, cz-hz}, {cx-hx, cy+hy, cz-hz},
        {cx-hx, cy-hy, cz+hz}, {cx+hx, cy-hy, cz+hz},
        {cx+hx, cy+hy, cz+hz}, {cx-hx, cy+hy, cz+hz},
    }
    for _, c in ipairs(corners) do
        verts[#verts + 1] = { x = c[1], y = c[2], z = c[3] }
    end
    for _, f in ipairs(BOX_FACES) do
        faces[#faces + 1] = { f[1] + base, f[2] + base, f[3] + base }
    end
end

local function makeTorus(R, r, ringSeg, tubeSeg)
    R, r, ringSeg, tubeSeg = R or 0.72, r or 0.30, ringSeg or 14, tubeSeg or 7
    local verts, faces = {}, {}
    for i = 0, ringSeg - 1 do
        local u = (i / ringSeg) * math.pi * 2
        for j = 0, tubeSeg - 1 do
            local vv = (j / tubeSeg) * math.pi * 2
            verts[#verts + 1] = {
                x = (R + r * math.cos(vv)) * math.cos(u),
                y = r * math.sin(vv),
                z = (R + r * math.cos(vv)) * math.sin(u),
            }
        end
    end
    local function idx(i, j) return (i % ringSeg) * tubeSeg + (j % tubeSeg) + 1 end
    for i = 0, ringSeg - 1 do
        for j = 0, tubeSeg - 1 do
            local a, b, c, d = idx(i,j), idx(i+1,j), idx(i+1,j+1), idx(i,j+1)
            faces[#faces + 1] = { a, b, c }
            faces[#faces + 1] = { a, c, d }
        end
    end
    return { verts = fitUnit(verts), faces = faces }
end

local function makeSphere(rings, segs)
    rings, segs = rings or 9, segs or 14
    local verts, faces = {}, {}
    for i = 0, rings do
        local phi = (i / rings) * math.pi
        for j = 0, segs - 1 do
            local theta = (j / segs) * math.pi * 2
            verts[#verts + 1] = {
                x = math.sin(phi) * math.cos(theta),
                y = math.cos(phi),
                z = math.sin(phi) * math.sin(theta),
            }
        end
    end
    local function idx(i, j) return i * segs + (j % segs) + 1 end
    for i = 0, rings - 1 do
        for j = 0, segs - 1 do
            local a, b, c, d = idx(i,j), idx(i+1,j), idx(i+1,j+1), idx(i,j+1)
            faces[#faces + 1] = { a, b, c }
            faces[#faces + 1] = { a, c, d }
        end
    end
    return { verts = fitUnit(verts), faces = faces }
end

local function makeHumanoid()
    local verts, faces = {}, {}
    pushBox(verts, faces,  0,    1.32, 0, 0.52, 0.52, 0.52) -- голова
    pushBox(verts, faces,  0,    0.62, 0, 0.74, 0.90, 0.40) -- торс
    pushBox(verts, faces, -0.52, 0.60, 0, 0.24, 0.86, 0.24) -- ��ука L
    pushBox(verts, faces,  0.52, 0.60, 0, 0.24, 0.86, 0.24) -- рука R
    pushBox(verts, faces, -0.19,-0.32, 0, 0.28, 0.98, 0.28) -- нога L
    pushBox(verts, faces,  0.19,-0.32, 0, 0.28, 0.98, 0.28) -- нога R
    for _, v in ipairs(verts) do v.y = v.y - 0.5 end          -- центрируем
    return { verts = fitUnit(verts), faces = faces }
end

Meshes.torus    = makeTorus()
Meshes.sphere   = makeSphere()
Meshes.humanoid = makeHumanoid()

