-- Имя из UI (��Icosahedron») к ключу таблицы («icosahedron»). Б��з этого выбор
-- меша давал nil и рендер ��адал на ка��дом кадре вкладки Models.
function Engine.getMesh(name)
    if type(name) ~= "string" then return Meshes.icosahedron end
    return Meshes[name:lower()] or Meshes.icosahedron
end

local LIGHT = V(0.4, 0.7, -0.6)

----------------------------------------------------------------------------
-- 3D: РЕНДЕР
----------------------------------------------------------------------------
local function rotate(p, cx, sx, cy, sy)
    local x1 =  p.x * cy + p.z * sy
    local z1 = -p.x * sy + p.z * cy
    local y2 =  p.y * cx - z1 * sx
    local z2 =  p.y * sx + z1 * cx
    return x1, y2, z2
end

-- cam: { yaw, pitch, dist, wire, glow }
local function render3D(mesh, vx, vy, vw, vh, cam)
    -- Кривой меш не должен ронять весь кадр: паника здесь означала бы, ч��о
    -- вместе с моделью пропадёт и окно, и вкладки.
    if type(mesh) ~= "table" or not mesh.verts or not mesh.faces then
        return 0
    end

    local cx, cy = vx + vw * 0.5, vy + vh * 0.5
    local scale = math.min(vw, vh) * 0.62

    local cxr, sxr = math.cos(cam.pitch), math.sin(cam.pitch)
    local cyr, syr = math.cos(cam.yaw), math.sin(cam.yaw)

    local P = {}
    for i, v in ipairs(mesh.verts) do
        local x, y, z = rotate(v, cxr, sxr, cyr, syr)
        P[i] = { x = x, y = y, z = z }
    end

    local function proj(p)
        local pz = p.z + cam.dist
        if pz < 0.05 then pz = 0.05 end
        local s = scale / pz
        return Vector2.new(cx + p.x * s, cy - p.y * s)
    end

    local prepared = {}
    for _, f in ipairs(mesh.faces) do
        local a, b, c = P[f[1]], P[f[2]], P[f[3]]

        local ux, uy, uz = b.x - a.x, b.y - a.y, b.z - a.z
        local wx, wy, wz = c.x - a.x, c.y - a.y, c.z - a.z
        local nx = uy * wz - uz * wy
        local ny = uz * wx - ux * wz
        local nz = ux * wy - uy * wx
        local nl = math.sqrt(nx * nx + ny * ny + nz * nz)
        if nl > 1e-6 then
            nx, ny, nz = nx / nl, ny / nl, nz / nl
        end

        local front = nz <= 0
        if front or cam.glow then
            local shade = math.max(0, -(nx * LIGHT.x + ny * LIGHT.y + nz * LIGHT.z))
            prepared[#prepared + 1] = {
                a = proj(a), b = proj(b), c = proj(c),
                depth = (a.z + b.z + c.z) / 3,
                shade = shade * 0.85 + 0.15,
                front = front,
            }
        end
    end

    -- painter's algorithm: дальние гра��и раньше ближних
    table.sort(prepared, function(l, r) return l.depth > r.depth end)

    for _, t in ipairs(prepared) do
        -- Отсечение по габаритам: полигональная ��брезка треугольника здесь
        -- избыточна, а модель отмасштабирована вн��трь вьюпорт��, ��оэто��у
        -- у кра��в возможен л��шь ��и��сельный ��ыход з�� ��ран��цу.
        local minx = math.min(t.a.X, t.b.X, t.c.X)
        local maxx = math.max(t.a.X, t.b.X, t.c.X)
        local miny = math.min(t.a.Y, t.b.Y, t.c.Y)
        local maxy = math.max(t.a.Y, t.b.Y, t.c.Y)
        if not culled(minx, miny, maxx, maxy) then
            if not cam.wire then
                local base = COL.cyan
                local fill = Color3.new(base.R * t.shade, base.G * t.shade, base.B * t.shade)
                local op = cam.glow and (t.front and 0.28 or 0.12) or 1.0
                DI.FilledTriangle(t.a, t.b, t.c, fill, op)
            end
            local ecol = t.front and COL.cyan or COL.violet
            local eop = t.front and 0.9 or 0.35
            DI.Line(t.a, t.b, ecol, eop, 1)
            DI.Line(t.b, t.c, ecol, eop, 1)
            DI.Line(t.c, t.a, ecol, eop, 1)
        end
    end

    return #prepared
end
Engine.render3D = render3D

