local W = {}
Engine.W = W

-- Заголовок секции. Разделитель идёт ВЫШЕ базовой лин����и текста, а не на
-- уро��не фона: иначе линия читается как шов подложки, а не как разделитель.
function W.sectionTitle(x, y, w, label)
    local tw = measure(label, 11, Fonts.Monospace).X
    text(x, y, 11, COL.dim, label, 0.75, Fonts.Monospace)
    local lx = x + tw + 10
    if lx < x + w then
        -- Линия идёт по оп��ическому центру ЗАГЛАВНЫХ букв, а не по ц��нтру
        -- стро��и: у 11px капса высота ~8px, значит центр ≈ y+4, тогда как
        -- y+6 -- центр всей строки с учётом выносн��х элементов, и там линия
        -- визуально проваливает��я в фон. Рисуем rrect, а не line: у Line
        -- толщина растёт в обе стор��ны от оси и даёт полупиксельную размывку.
        rrect(lx, y + 4, w - (lx - x), 1, COL.text, 0.1, 0)
    end
    return y + 22
end

function W.button(key, x, y, w, h, label, dt)
    hit(key, x, y, w, h)
    local s = stateOf(key)
    s.hover = approach(s.hover, Engine.isHover(key) and 1 or 0, dt, 16)
    s.press = approach(s.press, Engine.isActive(key) and 1 or 0, dt, 26)

    -- Геометрия кнопки НЕ меняется при нажатии. ��жимать рамку -- ��ак бы��о
    -- раньше -- ��лохо по двум причинам: скругление при этом не м��сштабируется
    -- (углы «дыша��»), а тонкий stroke на дробных координатах ловит субпиксель
    -- и мерцает. Отклик д��ём светом и заливкой, плюс т����кст уезж��ет на 1px --
    -- этого достато��но для тактильного ощущения нажатия.
    local r = 6
    local p = s.press

    rrect(x, y, w, h, COL.inset, 0.5 + s.hover * 0.1 + p * 0.22, r)

    -- Внут��енняя тень с��ерху при нажатии: кнопка читается как вдавленная.
    if p > 0.01 then
        rrect(x + 1, y + 1, w - 2, 2, COL.inset, 0.5 * p, 1)
    end

    rstroke(x, y, w, h, COL.cyan, 0.12 + s.hover * 0.4 + p * 0.3, r, 1)

    -- Подсветка по нижней кромке: на ховере ра��горается, при нажатии гаснет,
    -- как будто источник ушёл под поверхность.
    local glow = s.hover * (1 - p * 0.75)
    if glow > 0.01 then
        progress(x, y + h - 2, w, 2, 1, COL.cyan, 0.1 + glow * 0.5, 6)
    end

    local tb = measure(label, 12, Fonts.Plex)
    text(x + w * 0.5 - tb.X * 0.5, y + h * 0.5 - tb.Y * 0.5 + p,
        12, COL.text, label, 0.7 + s.hover * 0.3)

    return Engine.clicked(key)
end

function W.toggle(key, x, y, w, label, value, dt)
    local h = 26
    hit(key, x, y, w, h)
    local s = stateOf(key)
    s.hover = approach(s.hover, Engine.isHover(key) and 1 or 0, dt, 16)
    s.on = approach(s.on, value and 1 or 0, dt, 18)

    local tw, th = 38, 18
    local ty = y + (h - th) * 0.5
    rrect(x, ty, tw, th, COL.inset, 0.85, th * 0.5)
    if s.on > 0.01 then
        rrect(x, ty, tw, th, COL.cyan, s.on * 0.85, th * 0.5)
    end
    local knob = x + th * 0.5 + s.on * (tw - th)
    disc(knob, ty + th * 0.5, th * 0.5 - 3,
        s.on > 0.5 and COL.panel or COL.dim, 1, 24)

    local tlx = x + tw + 12
    local tlbl = Engine.fitText and Engine.fitText(label, 13, (x + w) - tlx - 4) or label
    text(tlx, y + 5, 13, value and COL.text or COL.dim, tlbl, 0.6 + s.hover * 0.4)

    return Engine.clicked(key), y + h + 6
end

function W.slider(key, x, y, w, label, value, min, max, dt)
    local trackY = y + 22
    hit(key, x - 6, y + 14, w + 12, 20)

    local s = stateOf(key)
    local live = Engine.isHover(key) or Engine.isActive(key)
    s.hover = approach(s.hover, live and 1 or 0, dt, 16)

    -- Драг считаетс�� от СВЕЖИХ координат этого кадра, поэтому перетаскивание
    -- не ломается, если окно сдвинулось.
    local newValue = value
    if Engine.isActive(key) then
        local f = clamp((input.mouse.X - x) / math.max(w, 1), 0, 1)
        newValue = min + f * (max - min)
    end

    local frac = (newValue - min) / math.max(max - min, 1e-6)

    -- Значение спр��ва считаем ПЕРВЫМ -> знаем сколько места остаётся ярлыку.
    local vs = string.format("%.2f", newValue)
    local vw = measure(vs, 11, Fonts.Monospace).X
    -- ЯРЛЫК СЛЕВА: обрезаем по доступной ширине (w - значение - зазор), чтобы при
    -- маленьком окне/крупном шрифте текст НЕ налезал на значение (был этот баг).
    local labelMax = w - vw - 10
    local shownLabel = Engine.fitText and Engine.fitText(label, 11, labelMax, Fonts.Monospace) or label
    text(x, y, 11, COL.dim, shownLabel, 0.7, Fonts.Monospace)
    text(x + w - vw, y, 11, COL.cyan, vs, 0.85, Fonts.Monospace)

    rrect(x, trackY, w, 5, COL.inset, 0.9, 2.5)
    progress(x, trackY, w * frac + 2, 5, 1, COL.violet, 1, 0)

    local kx = x + w * frac
    local kr = 7 + s.hover * 1.5
    disc(kx, trackY + 2.5, kr, COL.text, 1, 28)
    ring(kx, trackY + 2.5, kr, COL.violet, 0.5 + s.hover * 0.5, 28, 2)

    return newValue, y + 36
end

-- Дропдаун. Спи��ок рисуется в слое OVERLAY, и КАЖ��ЫЙ ��ункт регистрирует свой
-- собственный hit-прямоугольник в том же кадре -- поэ��ому последний пункт
-- кликается ��овно так же, как первый.
function W.dropdown(key, x, y, w, options, selected, dt)
    local h = 30
    local s = stateOf(key)
    hit(key, x, y, w, h)
    s.hover = approach(s.hover, Engine.isHover(key) and 1 or 0, dt, 16)
    -- reveal ведём от s.open ВСЕГДА (а не только когда от��рыто), ч��обы сп��сок
    -- красиво ��ворачивался, а не пропадал мгновенно.
    s.reveal = approach(s.reveal or 0, s.open and 1 or 0, dt, 20)

    if Engine.clicked(key) then s.open = not s.open end

    local lift = math.max(s.hover, s.reveal)
    rrect(x, y, w, h, COL.inset, 0.55 + lift * 0.28, 7)
    rstroke(x, y, w, h, COL.cyan, 0.12 + lift * 0.4, 7, 1)
    if s.reveal > 0.01 then
        rrect(x, y + 6, 2, h - 12, COL.cyan, 0.4 + s.reveal * 0.6, 1)
    end
    text(x + 12, y + h * 0.5 - 6, 12, COL.text, tostring(selected), 0.9)

    -- Шеврон-«галочка», разворачивается вверх при раскрытии.
    local ax, ay = x + w - 15, y + h * 0.5
    local dir = 1 - s.reveal * 2
    local ac = COL.cyan
    line(ax - 4, ay - 1.6 * dir, ax, ay + 1.6 * dir, ac, 0.7 + lift * 0.3, 1.6)
    line(ax, ay + 1.6 * dir, ax + 4, ay - 1.6 * dir, ac, 0.7 + lift * 0.3, 1.6)

    local picked = nil
    if s.reveal > 0.01 then
        local ih, pad = 26, 5
        local listH = #options * ih + pad * 2
        local ly = y + h + 5

        local rows = {}
        for i, opt in ipairs(options) do
            local iy = ly + pad + (i - 1) * ih
            local ikey = key .. "/i" .. i
            -- ignoreClip=true: список рисуется в OVERLAY без clip, значит и hit
            -- не долже�� резаться границе�� тела карточк�� -- иначе кликались бы
            -- только первые пункты (см. коммент к hit()).
            hit(ikey, x, iy, w, ih, Z.OVERLAY, false, true)
            rows[i] = { y = iy, opt = opt, key = ikey }
            if Engine.clicked(ikey) then
                picked = opt
                s.open = false
            end
        end

        local grow = s.reveal
        deferOverlay(function()
            local vh = listH * grow
            rrect(x - 1, ly + 3, w + 2, vh, COL.app, 0.45 * grow, 10) -- м��гкая тень
            rrect(x, ly, w, vh, COL.panel, 0.98, 9)
            rstroke(x, ly, w, vh, COL.cyan, 0.3, 9, 1)
            for i, r in ipairs(rows) do
                if r.y + ih <= ly + vh then
                    local hov = Engine.isHover(r.key) and 1 or 0
                    local isSel = r.opt == selected
                    if hov > 0 then
                        rrect(x + 4, r.y + 1, w - 8, ih - 2, COL.cyan, 0.14, 6)
                        rrect(x + 4, r.y + 4, 2, ih - 8, COL.cyan, 0.9, 1)
                    end
                    text(x + 12, r.y + ih * 0.5 - 6, 12,
                        (isSel or hov > 0) and COL.cyan or COL.label,
                        tostring(r.opt), isSel and 1 or (0.72 + hov * 0.2))
                    if isSel then
                        disc(x + w - 13, r.y + ih * 0.5, 2.6, COL.cyan, 1, 16)
                    end
                    if i < #rows then
                        line(x + 9, r.y + ih, x + w - 9, r.y + ih, COL.faint, 0.12, 1)
                    end
                end
            end
        end)
    end

    return picked, y + h + 6
end

-- 3D-вьюпорт. Регистрируе��� себя как scrollable, поэтому колесо над ним зумит
-- м��дель и НЕ прокручивает спи��ок под ним. Драг вращает модель, потому что
-- захват достаётся самой верхней области п��д ку��сором, а не тайтл-бару.
function W.viewport(key, x, y, w, h, mesh, cam, dt)
    hit(key, x, y, w, h, Z.CONTENT, true)

    rrect(x, y, w, h, COL.inset, 0.92, 12)
    rstroke(x, y, w, h, COL.cyan, 0.18, 12, 1)

    for gx = 1, 5 do
        local gxp = x + w * gx / 6
        line(gxp, y + 6, gxp, y + h - 6, COL.cyan, 0.05, 1)
    end
    for gy = 1, 3 do
        local gyp = y + h * gy / 4
        line(x + 6, gyp, x + w - 6, gyp, COL.cyan, 0.05, 1)
    end

    if Engine.isActive(key) then
        cam.yaw += input.delta.X * 0.008
        cam.pitch = clamp(cam.pitch + input.delta.Y * 0.008, -1.4, 1.4)
        cam.spin = false
    end

    local sd = Engine.scrolled(key)
    if sd ~= 0 then
        cam.dist = clamp(cam.dist - sd * 0.25, 1.6, 9)
    end

    if cam.spin then
        cam.yaw += dt * cam.speed
    end

    -- модель обрезается рамкой вьюпорта (и, вложенно, границей списка)
    pushClip(x + 1, y + 1, w - 2, h - 2)
    local faces = render3D(mesh, x, y + 18, w, h - 40, cam)
    popClip()

    text(x + 12, y + 8, 11, COL.dim, "GEOMETRY", 0.7, Fonts.Monospace)
    text(x + 12, y + h - 20, 11, COL.dim, string.format(
        "verts %d  faces %d  %s", #mesh.verts, faces,
        cam.wire and "wire" or "solid"), 0.6, Fonts.Monospace)

    return y + h
end

----------------------------------------------------------------------------
-- NOTIFY
----------------------------------------------------------------------------
-- Тосты жив��т в св��ём слое Z.TOAST и в экранных координатах, поэтому не
-- зависят от окн�� и не могут уехать внутрь не��о.
local toasts = {}

local _toastSeq = 0
-- Глобальный выключате��ь нотификаций (Nova:SetNotificationsEnabled). Ко��да false --
-- нов��е тосты НЕ создаются вообще (тихо игнорируем вызов).
Engine.notifyEnabled = true
-- Глобальная прозрачность тостов (0..1), правится Nova:SetNotificationOpacity.
Engine.notifyOpacity = 1.0

function Engine.notify(title, body, duration, tone)
    if Engine.notifyEnabled == false then return end   -- нотификации выключены глобально
    _toastSeq = _toastSeq + 1
    toasts[#toasts + 1] = {
        id = _toastSeq,
        title = title or "Notice",
        body = body,
        life = duration or 4,
        max = duration or 4,
        tone = tone or COL.cyan,
        anim = 0,
        slide = 0,   -- отдельная пруж��нка на въе��д/высоту стопки
    }
end

-- Мгновенно у��рать все активные тосты (Nova:ClearNotifications).
function Engine.clearToasts()
    for i = #toasts, 1, -1 do toasts[i] = nil end
end

-- Флаг переливания тостов (app-чанк выставляет из Customize).
Engine.toastShimmer = true

-- Маленький к��локольчик, на��исованный ПРИМИТ��ВАМИ DrawingImmediate (линии/��уги).
-- НЕ retained-картинка: раньш�� значок был Drawing.Image с отдельным жизненным
-- циклом -> ��висел» дольше тоста. Теперь он часть immediate-отрисовки и гаснет
-- вместе с ней (п�� alpha a).
-- Колокольч��к тоста = НАСТОЯЩАЯ тонкая Lucide-иконка Bell (раньше был кустарный
-- глиф с ��олстыми стенками -- «слишком жирная», п.). Рисуем через Engine.drawIcon
-- (локальная icon() об��явлена ниже), цен���� -> угол. Толщина ~1.3px = как у Lucide.
local function bellGlyph(cx, cy, s, col, a)
    Engine.drawIcon("Bell", cx - s * 0.5, cy - s * 0.5, s, col, a, 1.3)
end

-- ПЕРЕРИСОВАННЫЙ ТОСТ: значок-колокольчик и�� DI + переливающаяся кромка/акцент.
local function drawToasts(dt, vw, vh)
    -- Масштаб тостов (п.12, UI Settings -> Notify Scale). Меняем ширину �� весь
    -- вертикальный ри��м; кегли текста тоже домножаем на ns.
    local ns = Engine.notifyScale or 1.0
    local pad, cw = 18, math.floor(300 * ns)
    local y = vh - 40
    local shimmer = Engine.toastShimmer
    local tclk = os.clock()

    for i = #toasts, 1, -1 do
        local t = toasts[i]
        t.life -= dt
        local target = t.life <= 0.35 and 0 or 1
        t.anim = approach(t.anim, target, dt, 12)

        if t.life <= 0 and t.anim < 0.02 then
            table.remove(toasts, i)
        else
            -- Глобальная прозрачность тостов домножается в общи�� alpha -> все слои
            -- (корпус/тень/текст/кромка) тускнеют согласованно.
            local a  = t.anim * (Engine.notifyOpacity or 1)
            local ez = t.anim * t.anim * (3 - 2 * t.anim)   -- геометрию ведём по anim
            local bh = math.floor((t.body and 62 or 46) * ns)
            y = y - bh
            local x = vw - cw - pad + (1 - ez) * 60
            local r = math.floor(12 * ns)
            -- Переливающийся тон: смеща��м hue вокруг базового акцента по времени.
            local tone = t.tone
            if shimmer then
                local h, s, v = t.tone:ToHSV()
                local shift = 0.05 * math.sin(tclk * 1.6 + i)
                tone = Color3.fromHSV((h + shift) % 1, s, math.min(1, v + 0.05))
            end

            -- тень (мягче и глубже -> тост «отрывается» от игр��)
            rrect(x + 3, y + 6, cw, bh, COL.app, 0.45 * a, r + 2)
            -- КОРПУС: тонированный градиент (тон -> панель), а не плоская заливка.
            -- Даёт фон/глубину, о которой просил юзер, ос��аваясь читаемым.
            gradRect(x, y, cw, bh, tone:Lerp(COL.panel, 0.82), COL.panel,
                0.98 * a, r, nil, nil, true)
            -- тёмная ��аза под зон��й текста -> ��онтраст букв поверх тонированного фона
            rrect(x + 1, y + 1, cw - 2, bh - 2, COL.panel, 0.28 * a, r - 1)
            -- Кромка тона + мягкий «дышащий» блеск альфы (без бегущей полосы).
            local edgeA = 0.34
            if shimmer then edgeA = 0.26 + 0.18 * (0.5 + 0.5 * math.sin(tclk * 2.2 + i)) end
            rstroke(x, y, cw, bh, tone, edgeA * a, r, 1.2)
            -- верхний стеклянный блик (полоса, а не 1px)
            rrect(x + r * 0.5, y, cw - r, bh * 0.34, COL.text, 0.05 * a, r)

            -- Бейдж: свечение тона + диск + коло��ольчик. Свечение = «фон» под иконкой.
            local bxr = math.floor(15 * ns)
            local bcx, bcy = x + 14 + bxr, y + bh * 0.5
            rrect(bcx - bxr - 4, bcy - bxr - 4, (bxr + 4) * 2, (bxr + 4) * 2, tone, 0.1 * a, bxr + 4)
            gradRect(bcx - bxr, bcy - bxr, bxr * 2, bxr * 2, tone:Lerp(COL.text, 0.15),
                tone:Lerp(COL.panel, 0.4), 0.28 * a, bxr)
            rstroke(bcx - bxr, bcy - bxr, bxr * 2, bxr * 2, tone, 0.6 * a, bxr, 1.4)
            bellGlyph(bcx, bcy, 15 * ns, tone, 0.98 * a)

            -- текст (к��гли домножены на ns)
            local tx = x + 14 + bxr * 2 + 10
            text(tx, y + (t.body and 12 * ns or bh * 0.5 - 7 * ns), 13 * ns, COL.text, t.title, a)
            if t.body then
                text(tx, y + 30 * ns, 11 * ns, COL.dim, t.body, 0.72 * a)
            end

            -- таймер-пр��гресс
            local th, ins = 3, 8
            local frac = clamp(t.life / t.max, 0, 1)
            rrect(x + ins, y + bh - th - 4, cw - ins * 2, th, COL.trackOff, 0.5 * a, th * 0.5)
            local fw = (cw - ins * 2) * frac
            if fw > 1 then
                rrect(x + ins, y + bh - th - 4, fw, th, tone, 0.9 * a, th * 0.5)
            end

            y = y - 12
        end
    end
end

----------------------------------------------------------------------------
-- РОУТЕР ВВ��ДА
----------------------------------------------------------------------------
-- Одна точка входа. Захват означает, что до отпускания кнопки все перемещения
-- уходят одному владельцу: поэтому drag окна ��е крадёт вращение модели, а
-- слайдер не теряет курсор при выходе за свой прямоугольник.

local function closeOverlaysExcept(key)
    for k, s in pairs(ui) do
        -- ВАЖНО: закрываем ТОЛЬКО настоящие оверлеи-дропдауны, у которых `.open` ==
        -- булев true. Поле имени `open` ТАКЖЕ используют НАВ-ГРУППЫ сайдбара, но там
        -- это ЧИСЛО анимации (0..1). Раньше проверка `if s.open then` считала 1.0
        -- truthy и присваивала navgrp `.open = false` при ЛЮБОМ клике -> либо краш в
        -- approach (false-cur), либо (после защиты approach) число становилось 0 и
        -- группа схлопывалась н�� любой клик, а вкладки переставали открываться
        -- (пункты кликаются только при gOpen>0.5). Строгое `== true` трогает лишь
        -- булевы дропдауны и не задевает числовую ани����цию групп.
        if s.open == true then
            -- открытым остаётся только тот дропдаун, к которому относится клик
            if not (key and (k == key or string.sub(key, 1, #k + 1) == k .. "/")) then
                s.open = false
            end
        end
    end
end

TC(UIS.InputBegan):Connect(function(io)
    -- Тач зеркалим как ЛКМ: на мобиле нет мыши, поэтому и весь UI, и плавающие
    -- мобильные кнопки должны реагировать на касание. Для Touch коо��динату берём ��з
    -- io.Position (GetMouseLocation на первом кадре касания может отставать).
    local isTouch = io.UserInputType == Enum.UserInputType.Touch
    if not isTouch and io.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
    local m = isTouch and Vector2.new(io.Position.X, io.Position.Y) or UIS:GetMouseLocation()
    input.mouse, input.down = m, true
    input.justPressed = true              -- фронт нажатия для мобильного с��оя (сбрасывается в кадре)

    local target = pick(m)

    -- ОТМЕНА Ф��КУСА ИНПУТА КЛИКОМ ВНЕ (п.7). Клики обрабатыва��тся отложенно в
    -- отрисовке, поэтому раньше фокус текстового поля НИКОГДА не снимался при
    -- клике мимо. Зд��сь pick(m) доступен сразу: если клик НЕ по сфокусированному
    -- полю -- снимаем фокус (и коммитим значение через onDone, если з��дан).
    local tf = Engine.textFocus
    if tf then
        local fkey = tf.key or tf.hitKey
        if not target or target.key ~= fkey then
            Engine.textFocus = nil
            if tf.settings and tf.settings.Callback then
                pcall(tf.settings.Callback, tf.state.text)
            end
        end
    end

    if not target then
        closeOverlaysExcept(nil)
        input.activeKey = nil
        return
    end

    input.activeKey = target.key
    input.grabOff = m - Vector2.new(target.x, target.y)
    pendingClick = target.key
    closeOverlaysExcept(target.key)
end)

-- Правая кнопка: одноразовый pendingRight на элементе под ку��с��ром.
TC(UIS.InputBegan):Connect(function(io)
    if io.UserInputType ~= Enum.UserInputType.MouseButton2 then return end
    if not Engine.visible then return end
    local target = pick(UIS:GetMouseLocation())
    if target then pendingRight = target.key end
end)

-- Клавиатура: нужна билде��-API для Keybind-элементов. Держим последнюю нажатую
-- клавишу и «слушатель» захвата (к��гда пользователь переназначает бинд), плюс
-- набор зажатых клави��, чтобы биндам мо��но было опрашивать состояние.
input.keysDown = {}
Engine.keyListener = nil       -- function(keyCode) | nil -- когда != nil, ловим след. клавишу

-- МАСТЕР-ВИДИМОСТЬ. Гейтит слои glass/body/overlay (тосты и клав��ату�����ный хук
-- живу�� всегда, чтобы UI можно было снова отк��ыть биндом). Плавный fade че�����з
-- Engine.uiAlpha читают слои при отрисовке.
Engine.visible = true
Engine.uiAlpha = 1
-- Анимация открытия/закрытия (п.13). openT ходит 0..1: 0 = за��рыто, 1 = открыто.
-- visible -- целевое состояние, openT догоняет ег�� с эластичным easing. Пока
-- openT > 0 мы ПРОДОЛЖАЕМ рисовать, применяя fade+scale+noise-dissolve, поэтому
-- закрытие тож�� анимируется (раньше просто исчеза��о).
Engine.openT = 1
function Engine.setVisible(v)
