end
function Engine.toggle()
    Engine.visible = not Engine.visible
end
-- easeOutBack -- лёгкий «overshoot» на открытии для пр��ятного о��скока
local function easeOutBack(t)
    local c1, c3 = 1.70158, 2.70158
    local x = t - 1
    return 1 + c3 * x * x * x + c1 * x * x
end
Engine.easeOutBack = easeOutBack
TC(UIS.InputBegan):Connect(function(io, gpe)
    if io.UserInputType ~= Enum.UserInputType.Keyboard then return end
    input.keysDown[io.KeyCode] = true
    input.lastKey = io.KeyCode
    -- ЗАХВАТ переназначен��я ловим ВСЕГДА (даже при gpe): у Drawing-UI нет
    -- настоящего тек��тбокса, а gpe у некоторых экзекуторов приходит true и
    -- раньше глотал перепривязку -- отсюда «кейбинды не работают».
    if Engine.keyListener then
        local cb = Engine.keyListener
        Engine.keyListener = nil
        pcall(cb, io.KeyCode)
        return
    end
    -- Клавиша открытия/зак��ытия меню (WindowFunctions:SetToggleKey). Держим
    -- ОТДЕЛЬНО от пользовательских биндов, чтобы не кон��ликт��вать.
    if Engine.toggleKey and io.KeyCode == Engine.toggleKey then
        Engine.toggle()
        return
    end
    -- Обычное нажатие -> биндовые колбэки.
    if Engine.onKey then Engine.onKey(io.KeyCode) end
end)
TC(UIS.InputEnded):Connect(function(io)
    if io.UserInputType == Enum.UserInputType.Keyboard then
        input.keysDown[io.KeyCode] = nil
        for _, el in ipairs(Engine.keybindEls or {}) do
