end)

TC(UIS.InputChanged):Connect(function(io)
    -- Движение пальца -> обновляем позицию «курсора», чтобы драг мобильных кнопок и
    -- слайдеров работал под касанием.
    if io.UserInputType == Enum.UserInputType.Touch then
        input.mouse = Vector2.new(io.Position.X, io.Position.Y)
        return
    end
    if io.UserInputType == Enum.UserInputType.MouseWheel then
        -- Колесо ��ходит ТОЛЬКО верхней scrollable-области под курсором.
        local target = pick(UIS:GetMouseLocation(), true)
        if target then
            pendingScrollKey = target.key
            pendingScrollDelta = io.Position.Z
        end
    end
end)

-- «Курсор над ��кном?» -- по ЖИВОМУ экранному rect окна (WIN.pos..WIN.pos+size),
-- он же двигается при драге, так что зона всегда точная.
function Engine.pointerInWindow(m)
    m = m or UIS:GetMouseLocation()
    local p, s = WIN.pos, WIN.size
    return m.X >= p.X and m.X <= p.X + s.X
       and m.Y >= p.Y and m.Y <= p.Y + s.Y
end

-- СЪЕДАНИЕ КОЛЕСА. У Drawing-UI нет реального GuiObject, поэтому колесо иначе
-- доходит до дефолтной камер�� и «зумит игру, когда я скроллю меню» (п.3). CAS с
-- высоким приоритетом ловит MouseWheel и возвращает Sink, ПОКА курсор над
-- открытым окном; ин��че Pass -> в игре зум работает как обычно. Приоритет выше
-- дефолтной камеры (Enum.ContextActionPriority.High.Value).
local WHEEL_ACTION = "NovaWheelSink"
local function wheelSink(_, state, _)
    if Engine.visible and Engine.pointerInWindow() then
        return Enum.ContextActionResult.Sink
    end
    return Enum.ContextActionResult.Pass
end
CAS:BindActionAtPriority(
    WHEEL_ACTION, wheelSink, false,
    Enum.ContextActionPriority.High.Value,
    Enum.UserInputType.MouseWheel
)

-- СЪЕДАНИЕ КЛАВИАТУРЫ ПРИ ВВОДЕ (п. Search bar). У Drawing-UI нет настоящего
-- TextBox, поэтому клавиши доходили и до игры -> «когда печатаю в поиск,
-- срабатывают игровые нажатия». Пока сфокусировано текстовое поле
-- (Engine.textFocus), высокоприоритетный CAS-экшен ловит ВСЕ клавиши и возвращает
-- Sink -> игра их не видит. Наши UIS.InputBegan-хуки при этом продолжают получать
-- события (Sink режет только нижний приоритет и дефолтные обработчики игры),
-- поэтому набор текста работает. Как только фокус снят -> Pass, игра снова видит
-- клавиатуру.
local KEY_ACTION = "NovaKeySink"
local function keySink(_, _, _)
    if Engine.textFocus ~= nil then
        return Enum.ContextActionResult.Sink
    end
    return Enum.ContextActionResult.Pass
end
local keys = {}
for _, k in ipairs(Enum.KeyCode:GetEnumItems()) do keys[#keys + 1] = k end
CAS:BindActionAtPriority(
    KEY_ACTION, keySink, false,
    Enum.ContextActionPriority.High.Value + 1,
    table.unpack(keys)
)

TC(UIS.InputEnded):Connect(function(io)
    if io.UserInputType ~= Enum.UserInputType.MouseButton1
        and io.UserInputType ~= Enum.UserInputType.Touch then return end
    input.down = false
    input.activeKey = nil
    input.released = true                 -- фронт отпускан��я для мобильного слоя
end)

