-- ФОН ОКНА: два шейдера + прим��тивы как деградация
----------------------------------------------------------------------------
-- Основной путь -- HLSL: тело окна (`nova`) и полоса тайтлбара (`novahead`).
-- Шейдер дел��ет то, чего примитивами не сделать вовсе: плавный гради��нт без
-- п��лос, aurora, мягкое св��чение по кромке и настоящее скругление формы.
--
-- Оба шейдера получа���т ОДИН И ТОТ ЖЕ прямоугольн��к окна. Это не небрежность:
-- `novahead` кра��ит только верхнюю долю HEADF и режет остальное по альфе,
-- поэтому его верхние углы скруглены той же sdRoundBox, что и у тела. Полоса
-- собственного р��змера дала б�� квадратные углы поверх скруглённых.
--
-- ZIndex ниже слоя Z.GLASS: шейдеры -- это фон, поверх них рисует DI.
--
-- Примитивный путь ниже сохранён целиком и включается сам, если шейдер не
-- соб��ался. Ограничение того пути: обрезка ПРЯМОУГОЛЬНАЯ, скруглённого clip
-- нет, поэтому градиент рисуется полос��ми только в средней зоне [y+r, y+h-r],
-- ��де боковые грани��ы -- ровные вертикальн��е линии, а верхние и нижние r
-- пикселей закрывают отдельные скруглённые «шапки».
local fxBody, fxHead
local fxTab
-- TWO independent accents:
--   curAccent = the general UI accent (content field, sliders, tab highlight).
--   curChrome = the WINDOW CHROME accent (novaglass body glow + novahead bar).
-- The user likes the chrome's default look and wants to recolour it SEPARATELY
-- from everything else, so the chrome shaders read curChrome, not curAccent.
local curAccent = COL.cyan
local curChrome = COL.cyan
-- DI content-field config. mode/shimmer/alpha are all read LIVE by the DI
-- renderer each frame -- none are baked into a shader, so nothing recompiles
-- while a slider is dragged.
local gradCfg = { alpha = 0.85, mode = 0, shimmer = 1.0 }
-- Content region left/top in LOCAL window px (sidebar width / titlebar height);
-- off-screen until the app reports the real layout via Engine.setContentHole.
local holeL, holeT = 99999, 99999
-- Chrome-shader rebuilds are DEFERRED to pointer-release: baking a literal
-- (chrome accent / hole position) recompiles the shader, and doing that every
-- frame while dragging the picker is what tanked FPS. Setters flag this;
-- applyGradFx commits it once the mouse is up.
local fxDirty = false
local function markFxDirty() fxDirty = true end

-- Values baked into novaglass: chrome accent tint + content-hole rect. One
-- object, so dragging the window leaves no translucent trail.
local function glassVars()
    return {
        ACOLR = curChrome.R, ACOLG = curChrome.G, ACOLB = curChrome.B,
        HOLEL = holeL, HOLET = holeT,   -- числа; подст��новка форматирует через %.6f
    }
end

-- Values baked into novahead (titlebar): height fraction + chrome accent.
local function headVars()
    return {
        HEADF = WIN.title / math.max(WIN.size.Y, 1),
        ACOLR = curChrome.R, ACOLG = curChrome.G, ACOLB = curChrome.B,
