-- Content-field config from Customize. alpha/mode/shimmer are ALL read live by
-- the DI renderer every frame -- nothing is baked into a shader, so none of
-- these ever trigger a recompile (this is why the sliders stay smooth).
function Engine.setGradientConfig(alpha, mode, shimmer)
    if alpha ~= nil then gradCfg.alpha = alpha end
    if mode ~= nil then gradCfg.mode = mode end
    if shimmer ~= nil then gradCfg.shimmer = shimmer end
