-- Явная выгрузка. Drawing-��бъекты пережи��ают завершение скрипта, п��э��ому без
-- этого (или без cleardrawcache при следующем старте) панели накапливаются.
function Engine.unloadFx()
    if fxBody then fxBody:destroy(); fxBody = nil end
    if fxHead then fxHead:destroy(); fxHead = nil end
    if fxTab then fxTab:destroy(); fxTab = nil end
