local glassPaint = DI.GetPaint(Z.GLASS)
TC(glassPaint):Connect(function()
    if Engine.destroyed then return end

    -- ПЕРЕТАСКИВАНИЕ ОКНА применяем ЗДЕСЬ -- glassPaint (Z.GLASS) рисуется ПЕРВЫМ в
    -- кадре, раньше bodyPaint (Z.BODY, где идёт onDraw с DI). Если двигать WIN.pos
    -- внутри onDraw, то фоновый ШЕЙДЕР этого кадра берёт позицию ДО дельты, а DI --
    -- ПОСЛЕ -> фон на кадр отстаёт от рамки и визуально «растяги��ается» в сторону
    -- перетаскивания. Применяя дельту в самом раннем пасе, гарантируем, что и
    -- шейдер, и DI используют ОДНУ позицию (glassPaint вызывается один раз/кадр).
    -- isActive/delta валидны -- ��ит-зоны заявлены в прошлом кадре.
    if Engine.isActive("win/drag") or Engine.isActive("win/dragL") then
        local d = Engine.input.delta
        if d.X ~= 0 or d.Y ~= 0 then
            WIN.pos = WIN.pos + d
            Engine.winMoved = true   -- юзер сам двигал окно -> прекращаем автоцентр
        end
    end

    -- UI ПОЛНОСТЬЮ закрыт (openT<=0) -> прячем фоновые шейдеры. Во время анимации
    -- (openT в (0,1)) НЕ прячем -- фон едет/сжимается вместе с контентом, поэтому
    -- закры��ие кр��сиво «уносит» и подложку, а не оставляет её висеть.
    local ot = Engine.openT or 1
    if ot <= 0.001 then
        if fxBody then fxBody:hide() end
        if fxHead then fxHead:hide() end
        return
    end
    local x, y = WIN.pos.X, WIN.pos.Y
    local w, h = WIN.size.X, WIN.size.Y
    -- Анимация открытия/закрытия: ТОЛЬКО СДВ��Г по Y (позиция дёшева). Масштаб
    -- шейдера ЗАПРЕЩЁН -- изменение w/h каждый кадр триггерит sizeStale/aspectStale
    -- в setRect и пересобирает GPU-текстуру покадрово => обвал FPS (та жалоба).
    -- Поэтому размер держим постоянным, а «сжатие» имитируем только на контенте.
    local oy = Engine.animOffsetY or 0
    y = y + oy
    local r = WIN.radius
    local t = os.clock()

    ------------------------------------------------------------------
    -- ПУТЬ 1: шейдер. ��он рисует GPU, здесь остаётся только вне��ний
    -- контур -- он гасит пиксели карты вплотную к кромке и даёт панели
    -- край. Всё о��тальное (гр��диент, aurora, свечение, скругл��ние)
    -- уже ��нутри шейдера, дублировать примитивами нельзя: получится
    -- грязь поверх чистой картинки.
    ------------------------------------------------------------------
    if fxBody then
        -- К��ИТИЧНО: зан��во ПОКАЗЫ��АЕМ шейдер��. При скрытии UI выше вызывается
        -- fxBody:hide()/fxHead:hide() (Visible=false). Раньше в этой ветке был
        -- только setRect БЕЗ show(), поэтому после «закрыл-открыл UI» шейдер окна
        -- (тело + тайтлбар) оставался невидимым навсегда -- ровно та жалоба
        -- «шейде�� исчеза��т после переоткрытия».
        fxBody:show()
        if fxHead then fxHead:show() end
        -- Position и Size пишутся ВМЕС��Е -- иначе вернётся тот самый баг
        -- с растягиванием узора. Размер окна постоянен, поэтому пересборки
        -- нет: при драге это две ��аписи св��йств.
        fxBody:setRect(x, y, w, h)
        if fxHead then fxHead:setRect(x, y, w, h) end

        -- НЕ ри���уем DI-контур п��верх шейдера. DI-о��водка ��круглённого
        -- прямоугольника тесселируется экзекутором грубо, и её ломаные углы
        -- лож��лись поверх ГЛАДКОГО силуэта шейдера (aa-feather из panelLocal) --
        -- это и есть «пиксельные закругления». Кромку целиком даёт сам
        -- novaglass: внутренний rim (exp(-edge)) + сглаженное покрытие aa.
        return
    end

    ------------------------------------------------------------------
    -- ФОН ОКНА (единственный путь -- шейдеры выключены).
    ------------------------------------------------------------------
    -- Раньше здесь рисовался градиентный ф��н окна (GLASS_TOP->GLASS_BOT + св��чения
    -- + боковые violet-полосы). Пользователь его не любит («не подходит по дизайну»),
    -- а сайдбар/топбар/контент тепер�� и так рисуют СВОИ фоны и ��амощают всё окно со
    -- скруглением своих внешних углов. Поэтому backdrop сведён к минимуму:
    --   1) сплошная тёмная скруглённая подложка -- гарантирует силуэт окна и
    --      отсутствие щелей на стыках панелей во время драга;
    --   2) один аккуратный акцентный ко��тур с лёг��им «дыханием» а��ьфы -- от��еляет
    --      окно о�� игры без тёмного ореола-тени (которого примитивами не сделать).
    -- Никакого гра��иента-заливки, колец и боковых полос -> чисто и по дизайну.
    -- ВНЕШНИЙ КОНТУР рисуем НЕ здесь (Z.BODY), а в самом конце кадра (onDraw),
