    -- Непрозрачность подложки = contentOpacity: сайдбар/топбар рисуют СВОИ
    -- ���епрозра��ные фоны поверх (COL.inset,1), поэтому полупрозрачной остаётся
    -- только ЗОНА КОНТЕНТА -> при contentOpacity<1 сквозь фон контента видно игру
    -- (жалоба). При 1.0 -- как раньше (полностью непрозрачно).
    local cOp = Engine.contentOpacity or 1
    DI.FilledRectangle(v2(x, y), v2(w, h), COL.inset, cOp, r)
end)

local bodyPaint = DI.GetPaint(Z.BODY)
TC(bodyPaint):Connect(function()
    if Engine.destroyed then return end        -- после Unload() -- полный стоп
    local now = os.clock()
    local dt = now - lastClock
    lastClock = now
    if dt > 0 then
        Engine.fps = Engine.fps + (1 / dt - Engine.fps) * 0.1
    end
    if dt > 0.1 then dt = 0.1 end
    Engine.dt = dt

    -- История FPS для мини-спарклайна в футере (п.6). Кольцевой буфер на 32
    -- точки, обновляется примерно раз в 0.1с, чтобы график был плавным.
    Engine.startTime = Engine.startTime or now
    Engine.fpsHist = Engine.fpsHist or {}
    Engine._fpsAcc = (Engine._fpsAcc or 0) + dt
    if Engine._fpsAcc >= 0.1 then
        Engine._fpsAcc = 0
        local h = Engine.fpsHist
        h[#h + 1] = Engine.fps
        if #h > 32 then table.remove(h, 1) end
    end

    local m = UIS:GetMouseLocation()
    input.delta = m - lastMouse
    lastMouse = m
    input.mouse = m

    -- Плавный UI Scale: подтягиваем размер окна к ц��ли каждый кадр (см. applyUiScale).
    if Engine.updateUiScale then Engine.updateUiScale(dt) end

    -- ДИАГНОСТИКА РАСКЛАДКИ (мобилка «нет UI»): печатаем реальные числа на кадрах
    -- 1/30/90, чтобы поймать значения ПОСЛЕ появления камеры. Так видно, окно
    -- off-screen / нулевого размера / невидимо, или же координаты корректны, но
