-- Пространствен��ый градиент иконок accentA->accentB ПОПЕРЁК иконки. Flow-режим
-- удалён -> фаза статична (0). Включается тумблером Gradient Icons; иначе nil ->
-- иконка рисуется плоским цветом.
-- Переиспользуемая scratch-таблица: iconGrad зовётся на КАЖДУЮ иконку каждый кадр,
-- поэтому не аллоцируем новую таблицу (иначе GC-мусор на сотнях иконок). Значение
-- потребляется синхронно в drawIcon в том же вызове -> переиспользование безопасно.
local _iconGradScratch = { flow = true }
local function iconGrad(c)
    if not Engine.accentA or c ~= COL.cyan then return nil end
    if not Engine.iconGrad then return nil end
    -- Фаза от УНИВЕРСАЛЬНЫХ часов градиента -> иконки переливаются A<->B той же
    -- скоростью Gradient Speed, что и фон. flow=true -> движущаяся диагональная
    -- волна по ВСЕЙ иконке (а не просто «поделить по позиции», что читалось как
    -- смена цвета). accentB держим всегда (даже если основной градиент выключен).
    _iconGradScratch.a = Engine.accentA
    _iconGradScratch.b = Engine.accentB
    _iconGradScratch.phase = (Engine.gradClock and Engine.gradClock() or 0) * 0.35
    return _iconGradScratch
end

local function icon(name, cx, cy, s, c, o)
    local key = ICON_ALIAS[name] or name
    s = math.max(2, math.floor((s or 13) + 0.5))
    if s % 2 == 1 then s = s + 1 end
    local th = s <= 16 and 1.2 or 1.45
    drawIcon(key, math.floor(cx - s * 0.5 + 0.5), math.floor(cy - s * 0.5 + 0.5),
        s, c, o or 1, th, iconGrad(c))
end

