-- Карта таб -> группа (для крошек «Группа / Таб��). Заполняется из ПОСТРОЕННОЙ
-- билдер-модели в sidebar() (NAV_GROUP[tab.name] = tab.group). Захардкоженный
-- фолбэк-NAV (демо-прототип Syllinse/Aura) удалён.
local NAV_GROUP = {}


