    navCollapsed = {}, drawerOpen = false }

-- УНИВЕРСАЛЬНЫЙ ПОИСК. Нормализуем строку: нижний регистр + убираем ВСЕ
-- пробелы, чтобы "Silent Aim" находилось по "silentaim", "silent", "aim" и т.д.
local function normSearch(s)
    return (tostring(s or ""):lower():gsub("%s+", ""))
end
-- Имя элемента для поиска (Toggle/Button -> Name, Label -> Text, и т.��.).
local function elemName(el)
    local st = el.settings or {}
    return st.Name or st.Title or st.Text or ""
end
-- Совпадает ли вкладка с запросом: по и��ени вкладки ИЛИ по имени любой секции /
-- элемента внутри неё.
local function tabMatches(tab, nq)
    if nq == "" then return true end
    if normSearch(tab.name):find(nq, 1, true) then return true end
    for _, sec in ipairs(tab.sections or {}) do
        if normSearch(sec.title):find(nq, 1, true) then return true end
        for _, el in ipairs(sec.elements or {}) do
            if normSearch(elemName(el)):find(nq, 1, true) then return true end
        end
    end
    return false
end
-- Виден ли конкретный элемент при активном поиске (для фильтра контента).
local function elemMatches(el, nq, secTitleMatch)
    if nq == "" then return true end
    if secTitleMatch then return true end
    return normSearch(elemName(el)):find(nq, 1, true) ~= nil
end
Engine.normSearch = normSearch

