-- Quality preset: 0 Low / 1 Medium / 2 High. Controls tessellation only.
-- Visual toggles (grid, particles, bg FX) stay in Effects -- this is not a
-- second copy of those switches.
function Engine.applyQuality(q)
    q = math.floor(tonumber(q) or 1)
    if q < 0 then q = 0 elseif q > 2 then q = 2 end
    app.custom.quality = q
    Engine.quality = q
    Engine.iconQuality = q
    Engine.ringSegs = (q <= 0 and 10) or (q == 1 and 20) or 36
    Engine.fxBands = (q <= 0 and 6) or (q == 1 and 12) or 20
    Engine.bloomSteps = (q <= 0 and 4) or (q == 1 and 8) or 14
end
Engine.applyQuality(app.custom.quality or 1)

-- ЕДИНЫЕ «ЧАСЫ ГРАДИЕНТА»: одна фаза вре��ени, умноженная на УНИВЕРСАЛЬНУЮ скорость
-- gradSpeed. ВСЕ анимации градиентов (фон контента, перелив акцента, градиен��
-- иконок) читают её -> один слайдер Gradient Speed управляет всем сразу. Фаза
-- накапливается вручную (�� не os.clock()*speed), чтобы смена скорости не давала
-- скачок фазы. 0 -> заморозка.
Engine._gradPhase = 0
Engine._gradLast = os.clock()
function Engine.gradClock()
    return Engine._gradPhase or 0
end
function Engine.tickGradClock(dt)
    Engine._gradPhase = (Engine._gradPhase or 0) + (dt or 0.016) * (Engine.gradSpeed or 1)
end

-- Синхрон��зиро��ать Engine.particleCfg из app.custom (вы��ывает��я при старте и и��
-- колбэков UI). Один источник правды -> частицы всегда отражают настройки.
function Engine.syncParticleCfg()
    local c = Engine.particleCfg
    -- PERF: 26 -> 16 частиц по умолчанию. Каждая частица = disc (rrect) каждый
    -- кадр; звёзды/молнии - до 8 треугольников КАЖДАЯ. 16 точек визуально тот же
    -- «сноп», примитивов на ~40% меньше. Пользователь может поднять в Effects.
    c.count = app.custom.partCount or 16
    c.speed = app.custom.partSpeed or 1
    c.size  = app.custom.partSize or 1
    c.drift = app.custom.partDrift or 1
    c.glow  = app.custom.partGlow or 1
    c.shape = app.custom.partShape or "dots"
    c.dir   = app.custom.partDir or "up"
end
Engine.syncParticleCfg()

