-- Запекаем цвет в фоновый градиент-шейдер (дорого -> только по смене цвета,
-- НЕ каждый кадр). Все��да чистый A (flow/whole-режимы удалены).
local function bakeAccentShader()
    if not Engine.fxAccent then return end
    Engine.fxAccent(Engine.accentA)
end
Engine.bakeAccentShader = bakeAccentShader
local function applyAccent(r, g, b)
    local c = Color3.fromRGB(r, g, b)
    Engine.accentA = c
    COL.cyan = c
    COL.violet = c
    bakeAccentShader()
end
-- Второй цвет градиента (B). Хранится вс��гда, даже при выключенном градиенте.
local function applyAccent2(r, g, b)
    Engine.accentB = Color3.fromRGB(r, g, b)
    bakeAccentShader()
end
-- Покадровое обновление акцента. Flow/Whole-режимы УДАЛЕНЫ: градиент теперь всегда
-- СТАТИЧНЫЙ A→B. COL.cyan/violet держ��м на A (плоский акцент для одноцветных мест);
-- градиентные поверхности сами сэмплируют A→B через gradRect. Функция оставлена
-- (вызывается из рендер-лупа), ��о больш�� не анимирует а��цент.
local function updateAccentGrad(dt)
    Engine.accentFlowOn = false
    COL.cyan = Engine.accentA
    COL.violet = Engine.accentA
end
Engine.updateAccentGrad = updateAccentGrad
-- Публичная пересборка акцента из текущего состояния (для тумблеров в Effects,
-- которые не имеют доступа к локальным applyAccent/applyAccent2).
function Engine.applyAccentPublic()
    local a, b = app.custom.accent, app.custom.accent2
    applyAccent(a.r, a.g, a.b)
    applyAccent2(b.r, b.g, b.b)
end
