        app.custom.accent.b):ToHSV()
    app.custom.hue, app.custom.sat, app.custom.val = h, s, v
    local h2, s2, v2 = Color3.fromRGB(app.custom.accent2.r, app.custom.accent2.g,
        app.custom.accent2.b):ToHSV()
    app.custom.hue2, app.custom.sat2, app.custom.val2 = h2, s2, v2
end

-- Эталонные (нейтральные) значения поверхностей -- снимок ДО тонировки, чтобы
-- каждый повторный applyChrome смешивал от чистой базы, а не ��акапливал от��енок.
local BASE_SURF = {}
for _, k in ipairs({ "inset", "app", "panel", "navOn", "search", "user", "track", "trackOff" }) do
    BASE_SURF[k] = COL[k]
end

-- ЦВЕТ Х��ОМА (п.10). ��аньше хром красил ТОЛЬКО рамочные шейдеры (fxChrome), а
-- ���е��ции/фон контента/зона табов оставались фиксированно-тёмными -> «HUD влияет
-- только на полоску с fps». Теперь applyChrome ДОПОЛНИТЕЛЬНО подмешивает
-- chrome-от��енок во все нейтральные пове��хн��сти COL: пане��и секций, фон
-- контента (app), сайдбар/топ��ар (inset), навигацию, жёлоба и т.д. Каж��ая
-- поверхность тонируется от своего ЭТАЛОН�� (BASE_SURF) с ��ндивидуальной сил��й,
-- чтобы иерархия глубины (тёмный фон < панель) сохранялась. Виджеты читают COL
-- каждый кад��, так что смена мгновенная.
local function applyChrome(r, g, b)
    local c = Color3.fromRGB(r, g, b)
    if Engine.fxChrome then Engine.fxChrome(c) end
    -- сила п��дмеса для ка��дой поверхности (мягко: это ТОНИРОВКА, не заливка)
    local MIX = {
        inset = 0.10, app = 0.08, panel = 0.14, navOn = 0.18,
        search = 0.12, user = 0.12, track = 0.14, trackOff = 0.12,
    }
    for k, amt in pairs(MIX) do
        COL[k] = BASE_SURF[k]:Lerp(c, amt)
    end
end
applyChrome(app.custom.chrome.r, app.custom.chrome.g, app.custom.chrome.b)
do
    local h, s, v = Color3.fromRGB(app.custom.chrome.r, app.custom.chrome.g,
        app.custom.chrome.b):ToHSV()
    app.custom.chromeHue, app.custom.chromeSat, app.custom.chromeVal = h, s, v
end

-- Применяем выбранный шрифт (THEME.font чит��ется measure()/text() каждый кадр).
local function applyFont(idx)
    local fc = FONT_CHOICES[idx]
    if fc then THEME.font = fc.font end
end

-- Глобальный масштаб ��егля (THEME.scale читает��я measure()/text() каждый ка��р).
-- Дополнительно мягко ра��тим шаг строк M.row, чтобы при крупном шрифте (1.35)
-- строки не наезжали, но интерфейс не «раз��увался» линейно (коэф. 0.6).
local M_ROW_BASE = M.row
local function applyFontScale(v)
    THEME.scale = v
    M.row = math.floor(M_ROW_BASE * (1 + (v - 1) * 0.6))
end

-- UI Scale (п.12): единый множитель для fontScale. Отдельный слайдер в UI
-- Settings; перемножается с базовым fontScale, чтобы «��р��пный шрифт» �� «крупный
-- UI» с��ладывались предсказуемо, а не конфликтовали.
-- UI Scale (п.2): теперь ��еняе�� РЕАЛЬН��Й РАЗМЕР окна, а не шрифт. Вся раскладка
-- в корневом рендере бе��ётся из WIN.size кажд��й кадр, FX-шейдеры то��е читают
-- WIN.size -> достаточно переписать WIN.size = базовый * v, и окно (и шрифты,
-- т.к. текст масштаб��рует���� по геометрии секций) плавно растёт/сжима����тся.
-- baseSize фиксируем один раз как эталон. Text Scale остался отдельным слайдером
-- (fontScale) -- масштабирует только кегль внутри неизменной раскладки.
Engine.WIN_BASE = Engine.WIN_BASE or WIN.size
-- UI Scale теперь ПЛАВНЫЙ: с��айдер задаёт цель (uiScaleTarget), а размер окна
-- каждый кадр подтя��ивается к ней в Engine.updateUiScale() -> нет резкого скачка.
Engine.uiScaleTarget = app.custom.uiScale or 1
Engine.uiScaleCur = Engine.uiScaleTarget
local function applyUiScale(v)
    app.custom.uiScale = v
    Engine.uiScaleTarget = v
end
Engine.setUiScale = applyUiScale   -- публ��чный доступ (WindowFunctions:SetScale)

-- AUTO-RESCALE: множитель под разрешение экрана. Эталон = FullHD (1920x1080),
-- где ручные настройки «в самый раз» -> на 1080p фактор ровно 1.0. Берём МЕНЬШЕЕ
-- из отношений сторон к эталону, чтобы окно не переполняло мелкие экраны. На
-- тач-устройствах без клавиатуры (телефон/планшет) добавляем запас, чтобы попадать
-- пальцем. Результат кэшируем в Engine.autoScaleFactor (для UI).
Engine.autoRescale = app.custom.autoRescale ~= false
Engine.fontScaleCur = app.custom.fontScale or 1
-- Игнор «масштабных» ключей при загрузке конфигов. Мобильные (тач без клавиатуры)
-- по умолчанию ВКЛ -> чужой конфиг с desktop-масштабом не ломает мобильный вид.
if Engine.ignoreConfigScale == nil then
    Engine.ignoreConfigScale = (UIS.TouchEnabled and not UIS.KeyboardEnabled) or false
end
local function deviceFactor()
    if not Engine.autoRescale then return 1 end
    -- Workspace/CurrentCamera могут быть nil на раннем кадре -> безопасно падаем на
    -- этало�� 1920x1080 (фактор 1.0), а не крашимся.
    local cam = WS and WS.CurrentCamera
    local vp = (cam and cam.ViewportSize) or Vector2.new(1920, 1080)
    local w, h = vp.X, vp.Y
    if w < 1 or h < 1 then return 1 end
    local f = math.min(w / 1920, h / 1080)
    local touch = UIS.TouchEnabled and not UIS.KeyboardEnabled
    if touch then f = f * 1.35 end
    return clamp(f, 0.7, 2.0)
end
Engine.deviceFactor = deviceFactor

-- Вызываетс�� в начале кадра. Экспоненциальное приближение (framerate-independent).
-- Масштабирует И окно (WIN.size), И к��гль (THEME.scale через applyFontScale) на
-- df -> при auto-rescale текст и раскладка растут согласованно.
function Engine.updateUiScale(dt)
    local vp = Engine.viewport()
    if not Engine.visible and (Engine.openT or 0) <= 0
        and math.abs((Engine.uiScaleCur or 1) - (Engine.uiScaleTarget or 1)) < 0.0005
        and Engine._lastVpX == vp.X and Engine._lastVpY == vp.Y then
        return
    end
    Engine._lastVpX, Engine._lastVpY = vp.X, vp.Y
    local df = deviceFactor()
    local k = math.min(1, (dt or 0.016) * 12)

    -- FIT-CLAMP (фикс «окно больше экрана и уезжает за край» на мобиле): каким бы
    -- ни был df, окно НЕ может быть больше вьюпорта. Считаем максимальный масштаб,
    -- при котором WIN_BASE ещё влезает (минус поля), и не даём итоговому масштабу
    -- его превысить. Раньше df от эталона 1920x1080 + тач-множитель 1.35 раздувал
    -- десктопный WIN_BASE (1033x677) до 1395x914 на вьюпорте 740x360 -> центр
    -- давал отрицательный pos, и весь UI оказывался за левым-верхним углом.
    local base = Engine.WIN_BASE
    local margin = 8
    local fitX = (vp.X - margin * 2) / base.X
    local fitY = (vp.Y - margin * 2) / base.Y
    local fit = math.min(fitX, fitY)
    if fit < 0.2 then fit = 0.2 end                 -- совсем крошечный вьюпорт: не в ноль
    Engine.fitScale = fit

    -- SHEET: десктопная композиция (сайдбар 215 + две колонки) на этом вьюпорте
    -- даёт колонку < 200px или ширину < 720. Не ужимаем открытку 1033x677 —
    -- окно почти на весь экран, нав уходит в drawer, контент в одну колонку.
    -- Порог геометрический, не TouchEnabled.
    local deskCol = ((base.X * fit - 215) - 19 * 2 - 16) * 0.5
    local sheet = vp.X < 720 or deskCol < 200
    Engine.sheet = sheet
    if sheet then
        Engine.drawerW = math.min(268, math.floor((vp.X - 16) * 0.78))
        if Engine.drawerW < 168 then
            Engine.drawerW = math.max(148, math.floor(vp.X - 20))
        end
        Engine._gs = Engine._gs or game:GetService("GuiService")
        local top = margin + Engine._gs:GetGuiInset().Y
        local bot = 12
        local s = clamp(Engine.uiScaleTarget or 1, 0.92, 1)
        local availW = math.max(120, vp.X - margin * 2)
        local availH = math.max(120, vp.Y - top - bot)
        local nx = math.floor(availW * s + 0.5)
        local ny = math.floor(availH * s + 0.5)
        if nx > vp.X then nx = math.floor(vp.X) end
        if ny > vp.Y then ny = math.floor(vp.Y) end
        if WIN.size.X ~= nx or WIN.size.Y ~= ny then
            WIN.size = Vector2.new(nx, ny)
        end
        local px, py
        if not Engine.winMoved then
            px = math.max(0, math.floor((vp.X - nx) * 0.5 + 0.5))
            py = math.max(0, math.floor(top + (availH - ny) * 0.5 + 0.5))
        else
            px = clamp(WIN.pos.X, 0, math.max(0, vp.X - 80))
            py = clamp(WIN.pos.Y, 0, math.max(0, vp.Y - 60))
        end
        if WIN.pos.X ~= px or WIN.pos.Y ~= py then
            WIN.pos = Vector2.new(px, py)
        end
        -- Кегль остаётся пользовательским. Старый fit (0.36) ужимал текст до ~4px,
        -- а иконки и пилюли оставались десктопными.
        Engine.uiScaleCur = Engine.uiScaleTarget or 1
        Engine.autoScaleFactor = 1
        if Engine.autoRescale then
            local ftgt = app.custom.fontScale or 1
            local fcur = Engine.fontScaleCur or 1
            if math.abs(fcur - ftgt) < 0.0005 then fcur = ftgt else fcur = fcur + (ftgt - fcur) * k end
            if math.abs(fcur - (Engine.fontScaleCur or -1)) > 1e-4 then
                Engine.fontScaleCur = fcur
                applyFontScale(fcur)
            end
        end
        return
    end

    -- Итоговый целевой масштаб окна = желаемый (df * пользовательский), но не больше
    -- того, что влезает в экран. На десктопе fit обычно > df -> ничего не меняется.
    local desired = (Engine.uiScaleTarget or 1) * df
    local tgt = math.min(desired, fit)
    Engine.autoScaleFactor = tgt                    -- диагностика печатает реальный масштаб

    -- окно (плавно к tgt)
    local cur = Engine.uiScaleCur or 1
    if math.abs(cur - tgt) < 0.0005 then cur = tgt else cur = cur + (tgt - cur) * k end
    Engine.uiScaleCur = cur
    local nx = math.floor(base.X * cur + 0.5)
    local ny = math.floor(base.Y * cur + 0.5)
    if nx > vp.X then nx = math.floor(vp.X) end
    if ny > vp.Y then ny = math.floor(vp.Y) end
    -- Only allocate when the pixel size actually changes. Previous code
    -- built 2-3 Vector2 every frame (open OR closed) -- continuous leak.
    if WIN.size.X ~= nx or WIN.size.Y ~= ny then
        WIN.size = Vector2.new(nx, ny)
    end

    local px, py
    if not Engine.winMoved then
        px = math.max(0, math.floor((vp.X - nx) * 0.5 + 0.5))
        py = math.max(0, math.floor((vp.Y - ny) * 0.5 + 0.5))
    else
        px = clamp(WIN.pos.X, -nx + 80, vp.X - 80)
        py = clamp(WIN.pos.Y, 0, math.max(0, vp.Y - 60))
    end
    if WIN.pos.X ~= px or WIN.pos.Y ~= py then
        WIN.pos = Vector2.new(px, py)
    end

    -- кегль (только когда auto-rescale активен; иначе THEME.scale держит слайдер
    -- Text Size без на��его вмешательства -> ручной режим не конфликтует).
    -- Следуем ФАКТИЧЕСКОМУ масштабу окна (cur/uiScaleTarget), а не «сырому» df ->
    -- если окно ужато под экран, текст ужимается синхронно, а не вылезает за рамку.
    if Engine.autoRescale then
        local effFactor = cur / (Engine.uiScaleTarget or 1)
        local fcur = Engine.fontScaleCur or 1
        local ftgt = (app.custom.fontScale or 1) * effFactor
        if math.abs(fcur - ftgt) < 0.0005 then fcur = ftgt else fcur = fcur + (ftgt - fcur) * k end
        if math.abs(fcur - (Engine.fontScaleCur or -1)) > 1e-4 then
            Engine.fontScaleCur = fcur
            applyFontScale(fcur)
        end
    end
end

-- Notify Scale (п.12): читается drawToasts каждый кадр через Engine.notifyScale.
local function applyNotifyScale(v)
    app.custom.notifyScale = v
    Engine.notifyScale = v
end

-- Применяем стартовые шрифт и мас��таб (иначе дефолты из app.custom не вступа��и
-- в си���у, пока пользователь не трогал слайдеры в Customize).
applyFont(app.custom.fontIdx)
applyFontScale(app.custom.fontScale)
applyNotifyScale(app.custom.notifyScale)

----------------------------------------------------------------------------
-- СНИ��ОК ТЕМЫ UI (��ля конфи��ов, п. «сохранять ли цветовую гамму»). Определён
-- ЗДЕСЬ, потому что все apply*-хуки и app.custom/THEME в этой области видимости.
-- captureTheme -> сериализуемая таблица (цвета как {r,g,b}); applyTheme(t) ->
-- пишет в app.custom и ПРИМЕНЯЕТ во все подсистемы (+ пересобирает HSV-зеркала
-- пикеров и engine-флаги), чтобы загрузка конфига мгновенно меняла вид.
local THEME_KEYS = {
    "accentGrad", "accentSlot", "iconGrad", "iconGradSpeed", "navGroups",
    "fontIdx", "fontScale", "notifyDur", "notifyAccent", "notifyShimmer",
    "notifyEnabled", "notifyOpacity", "gradMode", "gradAlpha", "gradShimmer",
    "gradSpeed", "contentOpacity", "uiScale", "notifyScale", "autoRescale", "searchPos",
    "mobileBtn", "mobileScale", "keybindScale", "mobileOpacity",
    "keybindList", "keybindListAll", "keybindListIcons", "keybindListOpacity",
    "keybindListScale", "keybindFabLabels", "mobileGrad", "kbListGrad", "sectionGrid",
    "quality",
}
-- «Масштабные» ключи: их применение п��опускается при загрузке конфига, если
-- включён Engine.ignoreConfigScale (по умо��чанию ВКЛ на мо��иле) -> конфиг не
-- перебивает под��бранный под устройство масштаб.
local SCALE_KEYS = { fontScale = true, uiScale = true, notifyScale = true, autoRescale = true }
function Engine.captureTheme()
    local cu = app.custom
    local t = {
        accent  = { cu.accent.r, cu.accent.g, cu.accent.b },
        accent2 = { cu.accent2.r, cu.accent2.g, cu.accent2.b },
        chrome  = { cu.chrome.r, cu.chrome.g, cu.chrome.b },
    }
    for _, k in ipairs(THEME_KEYS) do t[k] = cu[k] end
    -- Раскладка мобильных FAB (видимость + ОТНОСИТЕЛЬНАЯ позиция) -> запоминается
    -- между сессиями и корректно ложится на любое разрешение. Хук определён позже
    -- (там, где живут mob/keybindEls), поэтому зовём через Engine.* поздним связыванием.
    if Engine.captureMobileLayout then t.mobileLayout = Engine.captureMobileLayout() end
    return t
end
function Engine.applyTheme(t)
    if type(t) ~= "table" then return end
    local cu = app.custom
    local function setC(dst, v)
        if type(v) == "table" and #v >= 3 then dst.r, dst.g, dst.b = v[1], v[2], v[3] end
    end
    setC(cu.accent, t.accent); setC(cu.accent2, t.accent2); setC(cu.chrome, t.chrome)
    local skipScale = Engine.ignoreConfigScale
    for _, k in ipairs(THEME_KEYS) do
        if t[k] ~= nil and not (skipScale and SCALE_KEYS[k]) then cu[k] = t[k] end
    end
    -- применяем во все подсистемы
    applyAccent(cu.accent.r, cu.accent.g, cu.accent.b)
    applyAccent2(cu.accent2.r, cu.accent2.g, cu.accent2.b)
    applyChrome(cu.chrome.r, cu.chrome.g, cu.chrome.b)
    applyFont(cu.fontIdx)
    -- масштабы применяем ТОЛЬКО если конфиг-скейлы не игнорируются (иначе оставляем
    -- текущий подобранный под устройство масштаб нетронутым).
    if not skipScale then
        applyFontScale(cu.fontScale)
        applyNotifyScale(cu.notifyScale or 1)
        applyUiScale(cu.uiScale or 1)
        Engine.autoRescale = cu.autoRescale ~= false
    end
    if Engine.setGradientConfig then
        Engine.setGradientConfig(cu.gradAlpha, cu.gradMode, cu.gradShimmer)
    end
    -- мобильная р��складка (видимость + относительные позиции FAB) -- НЕ гейтится
    -- скейлом: это layout, а не масштаб.
    if t.mobileLayout and Engine.applyMobileLayout then
        Engine.applyMobileLayout(t.mobileLayout)
    end
    Engine.toastShimmer = cu.notifyShimmer
    Engine.iconGrad = cu.iconGrad
    Engine.applyQuality(cu.quality or 1)
    Engine.notifyEnabled = cu.notifyEnabled ~= false
    Engine.notifyOpacity = cu.notifyOpacity or 1
    Engine.contentOpacity = cu.contentOpacity or 1
    -- iconGradSpeed БОЛЬШЕ не самостоятелен: скорость иконок = ун��версальный gradSpeed.
    Engine.gradSpeed = cu.gradSpeed or 1
    Engine.iconGradSpeed = cu.gradSpeed or 1
    -- HSV-зе��кала пикеров (иначе пикеры покажут старые H/S/V)
    local h, s, v = Color3.fromRGB(cu.accent.r, cu.accent.g, cu.accent.b):ToHSV()
    cu.hue, cu.sat, cu.val = h, s, v
    local h2, s2, v2 = Color3.fromRGB(cu.accent2.r, cu.accent2.g, cu.accent2.b):ToHSV()
    cu.hue2, cu.sat2, cu.val2 = h2, s2, v2
    local ch, cs, cv = Color3.fromRGB(cu.chrome.r, cu.chrome.g, cu.chrome.b):ToHSV()
    cu.chromeHue, cu.chromeSat, cu.chromeVal = ch, cs, cv
end

----------------------------------------------------------------------------
-- ФОН КОНТЕНТА (DI, а не шейде��).
----------------------------------------------------------------------------
-- Почему DI, а не novacontent: шейдер лежал ПОД слоем DI, не реагировал на
-- opacity/mode/shimmer (жалобы), не адаптировался под скруглённый правый край
-- окна (квадратный r=0) и пропадал после с��рытия UI. DI-��он детерминирован:
-- реальная прозрачность (сквозь низкую ��льфу видно игру), 4 различимых режима,
-- живой shimmer, и правый край скруглён радиусом окна.
--   alpha  -- app.custom.gradAlpha (0.2..1): основная непрозрач��ость фона.
--   mode   -- app.custom.gradMode (0 bloom | 1 aurora | 2 sweep | 3 pulse).
--   shim   -- app.custom.gradShimmer (0..1.5): сила движущегося ��лика.
-- Скруглени�� правого-нижнего угла контента, УСТОЙЧИВОЕ к клипу.
-- ПОЧЕМУ отдельная функция: rrect под клипом принудительно теряет скругление
-- (см. `trimmed and 0` в rrect) -> прежняя «выр����ка» рисовала КВАДРАТНЫЙ угол,
-- который торчал за скруглённый силуэт окна (жалоба «выпирает уголок»).
-- РЕШЕНИЕ: рисуем disc с центром, ВДВИНУТЫМ на r внутрь -> его bbox целиком
-- внутри клипа контента -> disc НЕ подрезается -> остаётся настоящим кругом.
-- 1) заливаем угловой бокс цветом рамки окна (стираем квадратный угол),
-- 2) возвращаем дугу четвертью круга базового цвета.
local function carveWinCorner(cx, cw, fy, fh, r, baseAlpha)
    if not r or r <= 0 then return end
    local x0, y0 = cx + cw - r, fy + fh - r       -- верхний-левый пиксель бокса
    rrect(x0, y0, r, r, COL.app, 1, 0)            -- р��мка окна в углу
    Engine.disc(x0, y0, r, COL.app, baseAlpha)    -- дуга (нижне-правый квад��ант круга)
end

-- ��аливка СПЛОШ��ОГО прямоугольника с выбранными скруглёнными углами, устойчивая
-- к клипу. Нужна, потому что rrect под клипом теряет скругление (trimmed -> 0) и
-- углы окна у сплошных панелей (сайдбар/топбар) выходили КВАДРАТНЫМИ и торчали за
-- скруглённый силуэт. Здесь углы собираем ��з прямых полос + угловых КРУГОВ (disc
-- с центром, вдвинутым внутрь на R -> его bbox внутри клипа -> круг не режется).
-- Сливер вне дуги НЕ закрашивается -> там честно остаётся прозрачность/силуэт.
-- corners = { tl=bool, tr=bool, bl=bool, br=bool }.
local function fillRoundedPanel(x, y, w, h, color, alpha, R, corners)
    R = math.max(0, math.min(R or 0, w * 0.5, h * 0.5))
    if R <= 0 then rrect(x, y, w, h, color, alpha, 0); return end
    local tl = corners.tl and R or 0
    local tr = corners.tr and R or 0
    local bl = corners.bl and R or 0
    local br = corners.br and R or 0
    -- средняя вертикальная зона (между верхней и нижней кромками) -- це��иком
    rrect(x, y + math.max(tl, tr), w, h - math.max(tl, tr) - math.max(bl, br),
        color, alpha, 0)
    -- верхняя кромка: полоса, вырезающая только скруглённые углы
    local topInsetL, topInsetR = tl, tr
    rrect(x + topInsetL, y, w - topInsetL - topInsetR, math.max(tl, tr), color, alpha, 0)
    -- нижняя кромка
    local botH = math.max(bl, br)
    rrect(x + bl, y + h - botH, w - bl - br, botH, color, alpha, 0)
    -- углов��е ��уги (нижний/верхний квадрант нуж��ого круга)
    if tl > 0 then Engine.disc(x + R, y + R, R, color, alpha) end
    if tr > 0 then Engine.disc(x + w - R, y + R, R, color, alpha) end
    if bl > 0 then Engine.disc(x + R, y + h - R, R, color, alpha) end
    if br > 0 then Engine.disc(x + w - R, y + h - R, R, color, alpha) end
end
Engine.fillRoundedPanel = fillRoundedPanel

local function drawContentBg(cx, fy, cw, fh, winR)
    local cu = app.custom
    local alpha = cu.gradAlpha or 0.85
    local mode = cu.gradMode or 0
    local shim = cu.gradShimmer or 1.0
    local acc = COL.cyan
    -- ДВА цвета градие��та (жалоба «переливается ОДНИМ цветом, а не плавным
    -- градиентом»). accA/accB -- реальные два а��цента. Если они почти совпадают
    -- (второй цвет не задан) -> выводим па��тнёра сдвигом hue, чтобы фон ВСЕГДА был
    -- двухтональным, а не однотонным мерцанием.
    local accA = Engine.accentA or acc
    local accB = Engine.accentB or acc
    do
        local dr, dg, db = accA.R - accB.R, accA.G - accB.G, accA.B - accB.B
        if (dr * dr + dg * dg + db * db) < 0.0025 then
            local hh, ss, vv = accA:ToHSV()
            accB = Color3.fromHSV((hh + 0.14) % 1, math.max(ss, 0.5), math.min(1, vv + 0.06))
        end
    end
    -- УНИВЕРСАЛЬНЫЕ часы градиента: одна фаза * gradSpeed управляет ВСЕЙ анимацией
    -- градиентов (не только фоном). 0 -> статичный фон.
    local t = Engine.gradClock()

    -- Клип по прямоугольнику контента, чтобы блики не вылезали.
    Engine.pushClip(cx, fy, cw, fh)

    -- База тела окна: непрозрачность = contentOpacity (ОТДЕЛЬНАЯ настройка, не путать
    -- с gradAlpha, который управляет лишь ЯРКОСТЬЮ бликов-градиента). Чем ниже
    -- contentOpacity -> тем сильнее сквозь UI видно игру (DI рисует поверх кадра игры
    -- с альфа-смешением). Скругление ТОЛЬКО правого-нижнего угла (см. ниже).
    local cOp = Engine.contentOpacity or 1
    local bleedL = Engine.sheet and 0 or winR
    rrect(cx - bleedL, fy - winR, cw + bleedL, fh + winR, COL.app, cOp, Engine.sheet and 0 or winR)

    -- Фоновый градиент можно ВЫКЛЮЧИТЬ (жалоба «к Background градиент не
    -- применяется» -> теперь это явный тумблер). При выкле остаётся только тёмная
    -- база + скруглённый угол ниже; анимированные слои и shimmer пропускаются.
    -- Режим «None» (gradMode=0) = то же самое, но выбором в пикере Background.
    if cu.bgGradient == false or mode < 0.5 then
        carveWinCorner(cx, cw, fy, fh, winR, cOp)
    if Engine.sheet and winR > 0 then
        local xL, yL = cx + winR, fy + fh - winR
        rrect(cx, yL, winR, winR, COL.app, 1, 0)
        Engine.disc(xL, yL, winR, COL.app, cOp)
    end
        Engine.popClip()
        return
    end

    local prevFx = Engine._v2fx
    Engine._v2fx = true

    do
        local bands = Engine.fxBands or 12
        local tq = math.floor((t or 0) * 10 + 0.5)
        local cache = Engine._bgBand
        if not cache or cache.tq ~= tq or cache.n ~= bands
            or cache.accA ~= accA or cache.accB ~= accB or cache.alpha ~= alpha then
            cache = { tq = tq, n = bands, accA = accA, accB = accB, alpha = alpha, col = {}, al = {} }
            for i = 0, bands - 1 do
                local vf = i / math.max(1, bands - 1)
                local gpos = 0.5 + 0.5 * math.sin(vf * 2.2 + t * 0.6)
                local tone = accA:Lerp(accB, gpos)
                cache.col[i] = COL.app:Lerp(tone, 0.14 + 0.5 * (1 - vf))
                cache.al[i] = alpha * (0.34 + 0.42 * (1 - vf))
            end
            Engine._bgBand = cache
        end
        local bh = fh / bands
        for i = 0, bands - 1 do
            rrect(cx, fy + i * bh, cw, bh + 1, cache.col[i], cache.al[i], 0)
        end
    end

    if mode < 1.5 then
        local function bloom(bx, by, rad, str, bc)
            local steps = Engine.bloomSteps or 8
            for i = steps, 1, -1 do
                local f = i / steps
                local rr = rad * f
                local a = alpha * str * math.exp(-f * f * 3.2) * 0.18
                rrect(bx - rr, by - rr, rr * 2, rr * 2, bc, a, rr)
            end
        end
        local big = math.min(cw, fh)
        bloom(cx + cw * (0.78 + 0.05 * math.sin(t * 0.35)),
              fy + fh * (0.16 + 0.04 * math.cos(t * 0.30)), big * 1.05, 1.0, accA)
        bloom(cx + cw * (0.20 + 0.05 * math.cos(t * 0.42)),
              fy + fh * (0.86 + 0.03 * math.sin(t * 0.38)), big * 0.85, 0.7, accB)

    elseif mode < 2.5 then
        -- AURORA: вертикальные световые «шторы», как северное сияние -- дрейфуют
        -- по горизонтали, ме��цают по высоте. Раньше были плоские горизонтальные
        -- полосы (читались как обычный градиент). Каждая штора -- вертикальный
        -- стек, суживающийся книзу, с волнистой яркостью и лёгким высветлением к
        -- верху -> получатся текстура «занавеса», а не ровная заливка.
        local curtains = 5
        local vsteps = 12
        local vh = fh / vsteps
        for c = 1, curtains do
            local ph = t * (0.12 + c * 0.02) + c * 1.7
            local ccx = cx + cw * (0.5 + 0.44 * math.sin(ph))
            local halfW0 = cw * (0.09 + 0.03 * math.sin(ph * 1.3 + 1.0))
            for i = 0, vsteps - 1 do
                local vf = i / vsteps                       -- 0 верх .. 1 низ
                local wob = 0.5 + 0.5 * math.sin(vf * 5.0 + ph * 2.2)
                local a = alpha * (0.05 + 0.28 * (1 - vf)) * wob
                local halfW = halfW0 * (1.0 - vf * 0.55)
                -- цвет шторы берём из пары accA<->accB по её индексу -> занавесы
                -- разных оттенков, а не одного.
                local cbase = accA:Lerp(accB, (c - 1) / math.max(1, curtains - 1))
                local tone = cbase:Lerp(Color3.new(1, 1, 1), 0.25 * (1 - vf))
                rrect(ccx - halfW, fy + i * vh, halfW * 2, vh + 1, tone, a, 0)
            end
        end

    elseif mode < 3.5 then
        -- SWEEP: полоса света, идущая слева-направо, ПОТОМ справа-налево (пинг-понг),
        -- а не по циклу в одну сторону. Треугольная волна tri: 0->1->0.
        local cols = 24
        local bw = cw / cols
        local phase = (t * 0.22) % 2.0
        local tri = (phase < 1.0) and phase or (2.0 - phase)  -- 0..1..0
        local head = 0.15 + tri * 0.70                        -- ходит в [0.15,0.85]
        for i = 0, cols - 1 do
            local f = i / cols
            local g = math.exp(-(((f - head) * 5.0) ^ 2))
            local aa = alpha * (0.05 + 0.85 * g)
            rrect(cx + i * bw, fy, bw + 1, fh, accA:Lerp(accB, f), aa, 0)  -- цвет по позиции
        end

    else
        -- PULSE: концентрические кольца из центра, дышащие во времени.
        local ccx, ccy = cx + cw * 0.5, fy + fh * 0.5
        local maxr = math.max(cw, fh) * 0.75
        local rings = 7
        for i = rings, 1, -1 do
            local base = (i / rings)
            local puls = 0.5 + 0.5 * math.sin(t * 1.6 - i * 0.9)
            local rr = maxr * base
            local aa = alpha * (0.07 + 0.26 * puls) * (1 - base * 0.5)
            -- кольца чередуют оттенок из пары -> двухцветная пульсация.
            rstroke(ccx - rr, ccy - rr, rr * 2, rr * 2,
                accA:Lerp(accB, i / rings), aa, rr, 2 + 2 * puls)
        end
    end

    -- Общий движущийся блик (shimmer): мягкая диагональная волна поверх режима.
    if shim > 0.01 then
        local cols = 16
        local bw = cw / cols
        for i = 0, cols - 1 do
            local f = i / cols
            local s = 0.5 + 0.5 * math.sin(f * 5.0 - t * 2.0)
            rrect(cx + i * bw, fy, bw + 1, fh, COL.text,
                alpha * shim * 0.03 * s, 0)
        end
    end

    -- Вырезка правого-нижнего угла. baseAlpha = contentOpacity (НЕ gradAlpha!):
    -- раньше дуга рисовалась с непрозрачностью градиента, отличной от базы фона ->
    -- в правом-нижнем углу проступал «странный круг» иной прозрачности (жалоба).
    -- Теперь дуга совпадает с базой -> шов не виден, угол просто скруглён.
    carveWinCorner(cx, cw, fy, fh, winR, cOp)
    if Engine.sheet and winR > 0 then
        local xL, yL = cx + winR, fy + fh - winR
        rrect(cx, yL, winR, winR, COL.app, 1, 0)
        Engine.disc(xL, yL, winR, COL.app, cOp)
    end

    Engine._v2fx = prevFx
    Engine.popClip()
end
Engine.drawContentBg = drawContentBg

-- Состояние 3D-сцены страницы Render (порт из nova_ui). Камера в том же
-- формате, что ждёт render3D/W.viewport: yaw/pitch/dist + spin/speed + wire/glow.
app.scene = {
    mesh = "Icosahedron",
    cam  = {
        yaw = 0.6, pitch = -0.35, dist = 3.2,
        spin = true, speed = 0.6, wire = false, glow = true,
    },
}

----------------------------------------------------------------------------
-- КОНТРОЛЫ
----------------------------------------------------------------------------
-- ��умблер-пилюля. `tone` разный по замеру референса: у пер��ключателя самого
-- модуля он ЗЕЛЁНЫЙ, у настроек внутри карточки -- малиновый.
-- ТУМБЛЕР. Ручка -- НАСТОЯЩАЯ КАРТИНКА circle-dashed (векторный SVG через
-- Drawing Image), а не полилиния/треугольник: SVG рисуется без ступенек на
-- любом масштабе. Если у экзекут��ра нет Image -- аккуратный fallback-��иск
-- (тоже без треугольников).
-- Тумблер-пилюля. Увеличен до 46x24 (легче попадать, в т.ч. на мобильных).
-- noHit=true -> только РИСУЕТ по состоянию (клик ловит вызывающая сторона по
-- всей строке); hoverK -> ключ, чей hover подсвечивает ручку (обычно ключ ст��оки).
local function pill(key, x, y, value, dt, tone, noHit, hoverK)
    local w, h = 46, 24
    if not noHit then hit(key, x, y, w, h) end
    local s = stateOf(key)
    s.on = approach(s.on, value and 1 or 0, dt, 18)
    local hovSrc = hoverK or key
    s.hover = approach(s.hover, Engine.isHover(hovSrc) and 1 or 0, dt, 16)

    local accent = tone or COL.cyan
    local trackC = COL.trackOff:Lerp(accent, s.on)
    rrect(x, y, w, h, trackC, 0.55 + s.on * 0.42 + s.hover * 0.06, h * 0.5)
    rstroke(x, y, w, h, accent, 0.14 + s.on * 0.4, h * 0.5, 1)

    -- Ручка -- круглый rrect (не disc: FilledCircle тут вырождается в т��еугольник).
    local kr = 9
    local kx = x + 3 + kr + s.on * (w - (kr + 3) * 2)
    local ky = y + h * 0.5
    rrect(kx - kr + 1, ky - kr + 1.5, kr * 2, kr * 2, COL.app, 0.30, kr)
    rrect(kx - kr, ky - kr, kr * 2, kr * 2, COL.text, 1, kr)
    local mColor = value and accent or COL.trackOff
    local dr = 3
    rrect(kx - dr, ky - dr, dr * 2, dr * 2, mColor, 0.9, dr)
    return (not noHit) and Engine.clicked(key) or false
end

-- Строка «подпись слева -- значение справа». Возвращает следующий y.
local function rowLabel(x, y, label, dim)
    text(x, y + M.row * 0.5 - 6, 12, dim and COL.dim or COL.label, label, 0.95)
end

-- АВТО-РАСКЛАДКА СТРОКИ ЭЛЕМЕНТА (общая для slider/dropdown/input/keybind/...).
-- Если подпись длинная и контрол шириной ctrlW не влезает рядом -> пере��одим на
-- ДВУХЭТАЖНУЮ раскладку: ��одпись сверху, контрол снизу во всю ширину строки.
-- Иначе -- обычная строка (контрол с��рава). Это чинит наложение контрол�� на
-- текст (особе��но на малом масштабе и при длинных именах).
-- Возвращает: stacked, ctrlCy (верт. центр области ко��трола), rowH (высота
-- строки -> renderer вернёт y+rowH), ctrlX, ctrlAvailW.
local function rowLayout(x, y, w, name, ctrlW)
    local labelW = measure(name or "", 12).X
    local avail = w - 28                 -- поля по 14 слева/справа
    -- ЗАЗОР 24px (было 12): при borderline-длине подписи контрол вставал вплотную и
    -- визуально «заходил на текст». Теперь при нехватке комфортного зазора элемент
    -- ��ходит на ДВУХЭТАЖНУЮ раскладку (как старый слайдер «умно шёл ниже»).
    if avail - labelW - 24 >= ctrlW then
        local rowH = Engine.sheet and math.max(M.row, 44) or M.row
        return false, y + rowH * 0.5, rowH, x + w - 14 - ctrlW, ctrlW
    end
    local topH = Engine.sheet and 22 or 20
    local bodyH = Engine.sheet and 40 or 30
    local rowH = topH + bodyH
    return true, y + topH + bodyH * 0.5, rowH, x + 14, avail
end

local function rowToggle(key, x, y, w, r, dt)
    rowLabel(x + 14, y, r.label)
    if pill(key, x + w - 14 - 46, y + M.row * 0.5 - 12, r.value, dt, COL.cyan) then
        r.value = not r.value
    end
    return y + M.row
end

local function rowDropdown(key, x, y, w, r, dt)
    rowLabel(x + 14, y, r.label)

    local cw = 130
    local cx = x + w - 14 - cw
    local cy = y + M.row * 0.5 - 11
    hit(key, cx, cy, cw, 22)
    local s = stateOf(key)
    s.hover = approach(s.hover, Engine.isHover(key) and 1 or 0, dt, 16)
    if Engine.clicked(key) then s.open = not s.open end
    s.reveal = approach(s.reveal or 0, s.open and 1 or 0, dt, 20)

    -- Знач��ние ����ижато к ше��рон�� справа, как в референсе.
    local vw = measure(r.value, 12, Fonts.Plex).X
    local maxV = cw - 20
    text(cx + cw - 18 - math.min(vw, maxV), cy + 5, 12, COL.dim, r.value,
        0.85 + s.hover * 0.15)
    icon("chevron", cx + cw - 7, cy + 11, 9, COL.dim, 0.8 + s.hover * 0.2)

    -- Открытый списо�� уезжает в overlay-проход: иначе его закрасят строки,
    -- которые идут ниже по layout внутри того же zIndex.
    if (s.reveal or 0) > 0.01 then
        local ih, ly = 26, cy + 26
        local rows = {}
        for i, opt in ipairs(r.opts) do
            local iy = ly + (i - 1) * ih
            local ik = key .. "/i" .. i
            -- ignoreClip=true: без это��о пункты ниже тела карточки не
            -- регистрировались и кликались лишь первые (а к��ик по нижним
            -- проваливался в элемент под спис��ом и закрывал меню).
            hit(ik, cx, iy, cw, ih, Z.OVERLAY, false, true)
            rows[i] = { y = iy, opt = opt, key = ik }
            if Engine.clicked(ik) then
                r.value = opt
                s.open = false
            end
        end
        local grow, listH = s.reveal, #r.opts * ih + 8
        deferOverlay(function()
            local vh = listH * grow
            rrect(cx - 1, ly - 1, cw + 2, vh, COL.app, 0.4 * grow, 9) -- тень
            rrect(cx, ly - 4, cw, vh, COL.panel, 0.98, 9)
            rstroke(cx, ly - 4, cw, vh, COL.cyan, 0.3, 9, 1)
            for i, rw in ipairs(rows) do
                if rw.y + ih <= ly - 4 + vh then
                    local hov = Engine.isHover(rw.key) and 1 or 0
                    local sel = rw.opt == r.value
                    if hov > 0 then
                        rrect(cx + 4, rw.y, cw - 8, ih, COL.cyan, 0.14, 6)
                        rrect(cx + 4, rw.y + 3, 2, ih - 6, COL.cyan, 0.9, 1)
                    end
                    text(cx + 11, rw.y + 7, 12,
                        (sel or hov > 0) and COL.cyan or COL.label,
                        rw.opt, sel and 1 or (0.78 + hov * 0.18))
                    if sel then
                        Engine.disc(cx + cw - 11, rw.y + ih * 0.5, 2.4, COL.cyan, 1, 16)
                    end
                    if i < #rows then
                        line(cx + 8, rw.y + ih, cx + cw - 8, rw.y + ih, COL.faint, 0.1, 1)
                    end
                end
            end
        end)
    end
    return y + M.row
end

local function rowSlider(key, x, y, w, r, dt)
    rowLabel(x + 14, y, r.label)

    -- Справа нал��во: бокс значения, зат��м жё��об. Так в референсе.
    local boxW = r.unit and 74 or 46
    local boxX = x + w - 14 - boxW
    local boxY = y + M.row * 0.5 - 10
    rrect(boxX, boxY, boxW, 20, COL.track, 1, 5)
    local val = string.format("%.2f", r.value) .. (r.unit or "")
    local vw = measure(val, 11, Fonts.Plex).X
    text(boxX + boxW * 0.5 - vw * 0.5, boxY + 5, 11, COL.label, val, 0.95)

    local tw, th = 74, 8
    local tx = boxX - 10 - tw
    local ty = y + M.row * 0.5 - th * 0.5
    hit(key, tx - 4, ty - 8, tw + 8, th + 16)

    local s = stateOf(key)
    s.hover = approach(s.hover, Engine.isHover(key) and 1 or 0, dt, 16)
    if Engine.isActive(key) then
        local f = clamp((Engine.input.mouse.X - tx) / tw, 0, 1)
        r.value = r.min + f * (r.max - r.min)
    end

    local frac = clamp((r.value - r.min) / math.max(r.max - r.min, 1e-6), 0, 1)
    rrect(tx, ty, tw, th, COL.trackOff, 1, th * 0.5)
    if frac > 0.001 then
        rrect(tx, ty, math.max(tw * frac, th), th, COL.cyan, 1, th * 0.5)
    end
    disc(tx + fit(tw * frac, 7, tw - 7), ty + th * 0.5, 7 + s.hover, COL.text, 1, 20)
    return y + M.row
end

----------------------------------------------------------------------------
-- КА��ТОЧКА МОДУЛЯ
----------------------------------------------------------------------------
local function card(id, x, y, w, mod, dt)
    local headH = mod.desc and 52 or 40
    local s = stateOf(id .. "/card")
    s.open = s.open == nil and true or s.open
    s.reveal = approach(s.reveal or 1, s.open and 1 or 0, dt, 18)

    local bodyH = 0
    if s.reveal > 0.01 then bodyH = #mod.rows * M.row * s.reveal end
    local h = headH + bodyH + 8

    rrect(x, y, w, h, COL.panel, 1, M.cardR)

    -- Шапка: имя, описание, шев��он �� тумблер модуля (зелёный по замеру).
    text(x + 14, y + 12, 13, COL.text, mod.name, 1)
    if mod.desc then
        text(x + 14, y + 31, 10.5, COL.faint, mod.desc, 1)
    end

    local tgKey = id .. "/on"
    if pill(tgKey, x + w - 14 - 46, y + 9, mod.on, dt, COL.good) then
        mod.on = not mod.on
    end

    local chKey = id .. "/fold"
    local chx, chy = x + w - 14 - 36 - 20, y + 21
    hit(chKey, chx - 9, chy - 9, 18, 18)
    if Engine.clicked(chKey) then s.open = not s.open end
    icon("chevron", chx, chy - 1 + (1 - s.reveal) * 2, 9, COL.dim,
        Engine.isHover(chKey) and 1 or 0.7)

    -- Тело: строк���� контролов. Об��езаем по раскрытию, чтобы при сворачивании
    -- строки не вылезали за скру��ление к��рточки.
    if bodyH > 1 then
        Engine.pushClip(x, y + headH, w, bodyH)
        local ry = y + headH
        for i, r in ipairs(mod.rows) do
            local key = id .. "/r" .. i
            if r.kind == "toggle" then
                ry = rowToggle(key, x, ry, w, r, dt)
            elseif r.kind == "dropdown" then
                ry = rowDropdown(key, x, ry, w, r, dt)
            else
                ry = rowSlider(key, x, ry, w, r, dt)
            end
        end
        Engine.popClip()
    end

    return y + h + 14
end

----------------------------------------------------------------------------
-- САЙДБАР
----------------------------------------------------------------------------
    -- Переиспользуемое п��ле поиска (п.6): рисуется в произвольном прямоугольнике
    -- -> один и тот же виджет обслуживает и сайдбар, и топбар. Пишет в общий
    -- Engine.searchInput, поэтому фильтр навигации рабо��ает независимо от места.
    local function drawSearchField(sx, sy, sw, sh, dt)
        hit("side/search", sx, sy, sw, sh, Z.BODY)
        local ss = stateOf("side/search")
        ss.hover = approach(ss.hover, Engine.isHover("side/search") and 1 or 0, dt, 16)
        Engine.searchInput = Engine.searchInput
            or { settings = {}, state = { text = "" }, isSearch = true, hitKey = "side/search" }
        local focused = Engine.textFocus == Engine.searchInput
        if Engine.clicked("side/search") then
            Engine.textFocus = focused and nil or Engine.searchInput
        end
        app.query = Engine.searchInput.state.text
        rrect(sx, sy, sw, sh, COL.search, 1, 8)
        rstroke(sx, sy, sw, sh, COL.cyan, focused and 0.45 or (0.05 + ss.hover * 0.06), 8, 1)
        icon("search", sx + 14, sy + sh * 0.5, 12, focused and COL.cyan or COL.dim,
            focused and 0.95 or 0.7)
        local caret = focused and (math.floor(os.clock() * 2) % 2 == 0 and "|" or "") or ""
        local ty = sy + sh * 0.5 - 6
        if app.query ~= "" then
            text(sx + 26, ty, 11.5, COL.text, app.query .. caret, 0.95)
        else
            text(sx + 26, ty, 11.5, COL.dim, focused and caret or "Search...", 0.55)
        end
    end

    -- Рисует настраиваемый ASCII-логоти�� в верхней зоне сайдбара. Возвра��ает
    -- ВЫСОТУ занятого блока -> сайдб��р кладёт под него разделитель и н��в��гацию.
    local function drawLogo(x, y, w, dt)
        local LG = Engine.logo
        if not LG.glyphs then LG.glyphs = LOGO_GLYPHS end
        if not LG.name or LG.name == "" then LG.name = "Syllinse" end
        local pad = 12
        -- Бренд-иконка над вордмарком УБРАНА (по просьбе -- «лишнее и не красиво»).
        -- Оставляем неб��льшой верхний отступ, чтобы ворд��арк не прилипал к самому
        -- верху сайдбара (тот же воздух сверху, что был с иконкой).
        local px, pw, py = x + pad, w - pad * 2, y + 26
        local grad = app.custom.accentGrad
        local cA = Engine.accentA or COL.cyan
        local cB = Engine.accentB or COL.cyan
        local gsc = Engine.gradSampleColor
        local clk = os.clock()
        local name = LG.name or "NOVA"
        local glyphs = LG.glyphs

        -- Проверяем, что для КАЖДОЙ буквы есть битмап; иначе -> текстовый откат.
        local haveAll = glyphs ~= nil
        if haveAll then
            for i = 1, #name do
                if not glyphs[name:sub(i, i):upper()] then haveAll = false; break end
            end
        end

        if haveAll and #name > 0 then
            -- ===== ПИ��СЕЛЬНЫЙ ВОРДМАРК: связные наклонные штрихи =====
            local ROWS = 5
            local letterCols, gap = {}, 1            -- gap в ячейках между буквами
            local totalCols = 0
            for i = 1, #name do
                local g = glyphs[name:sub(i, i):upper()]
                local cols = #(g[1])
                letterCols[i] = { g = g, cols = cols }
                totalCols = totalCols + cols + (i < #name and gap or 0)
            end
            -- Наклон (курсив): верхние ряды сдвинуты вправо. Резервируем место под наклон.
            local slant = 0.30                       -- сдвиг на ряд в долях ячейки
            local cell = math.floor(math.min((pw * 0.90) / (totalCols + (ROWS - 1) * slant), 8))
            cell = math.max(cell, 3)
            local slantStep = cell * slant
            local artW = totalCols * cell + (ROWS - 1) * slantStep
            local artH = ROWS * cell
            local ax = px + (pw - artW) * 0.5
            local rnd = math.max(1, math.floor(cell * 0.42))  -- скругление концов штрихов

            -- Плавный (без шва) перелив: треугольная волна вместо (gx+flow)%1, которая
            -- давала РЕЗКИЙ скачок цвета на месте обмотки 1->0. tri идёт A->B->A гладко.
            local phase = grad and (clk * (LG.speed or 1) * 0.5) or 0
            local function gcol(gx)
                if not grad then return cA end
                local t = (gx * 0.85 + phase) % 1
                local tri = (t < 0.5) and (t * 2) or ((1 - t) * 2)   -- 0..1..0
                return gsc(cA, cB, tri)
            end

            -- Рисуем ПО РЯДАМ, сливая соседние «X» в один скруглённый штрих (связный
            -- вид). dot = cell целиком (без зазора) -> вертикально ряды стыкуются в
            -- сплошные штрихи. Каждый ряд сдвинут по наклону.
            local baseCol = ax
            for r = 0, ROWS - 1 do
                local rowShift = (ROWS - 1 - r) * slantStep
                local cx = baseCol
                for i = 1, #name do
                    local L = letterCols[i]
                    local rowStr = L.g[r + 1]
                    local c = 0
                    while c < L.cols do
                        if rowStr:sub(c + 1, c + 1) ~= " " then
                            local runStart = c
                            while c < L.cols and rowStr:sub(c + 1, c + 1) ~= " " do
                                c = c + 1
                            end
                            local runLen = c - runStart
                            local sx = cx + runStart * cell + rowShift
                            local gx = (sx + runLen * cell * 0.5 - ax) / math.max(artW, 1)
                            rrect(sx, py + r * cell, runLen * cell, cell,
                                gcol(gx), 1, rnd)
                        else
                            c = c + 1
                        end
                    end
                    cx = cx + (L.cols + gap) * cell
                end
            end
            local ly = py + artH

            -- Тонкая акцентная черта под вордмарком -- завязка бренд-блока. Ширина
            -- = 44% ширины вордмарка, по центру; заливка тем же градиентом акцента,
            -- поэтому «переливае��ся» в такт ло���отипу.
            local ulW = math.floor(artW * 0.44)
            local ulX = px + (pw - ulW) * 0.5
            local ulY = ly + 8
            if grad then
                Engine.gradRect(ulX, ulY, ulW, 2, cA, cB, 0.9, 1, 0, nil, true)
            else
                rrect(ulX, ulY, ulW, 2, cA, 0.9, 1)
            end
            ly = ulY + 2

            -- Подзаголовок ОБЫЧНЫМ шрифтом (меняется вместе с Font).
            local tag = LG.tagline or ""
            if tag ~= "" then
                local ts = 10
                local tw = measure(tag, ts).X
                text(px + (pw - tw) * 0.5, ly + 8, ts, COL.dim, tag, 0.9)
                ly = ly + 8 + measure(tag, ts).Y
            end
            return (ly + 14) - y
        end

        -- ===== ОТКАТ: текстовый в��рдмарк (буквы без битмапа) =====
        local nameBase = 22
        local nameW = measure(name, nameBase).X
        text(px + (pw - nameW) * 0.5, py, nameBase, cA, name, 1)
        local tag = LG.tagline or ""
        local ly = py + measure(name, nameBase).Y + 5
        if tag ~= "" then
            local tw = measure(tag, 10).X
            text(px + (pw - tw) * 0.5, ly, 10, COL.dim, tag, 0.9)
            ly = ly + measure(tag, 10).Y
        end
        return (ly + 14) - y
    end

    local function sidebar(x, y, h, dt, sideW)
    local w = sideW or M.side
    -- ФОН САЙДБАРА. Ск��угление ЛЕВЫХ углов окна держит сам сайдбар. Раньше
    -- использовался приём «rrect с выносом за clip», но под клипом rrect ТЕРЯЕТ
    -- скругление (trimmed->0) -> левые углы выходили КВАДРАТНЫМИ и торчали за
    -- скруглённый силуэт окна. Теперь через fillRoundedPanel: настоящие
    -- скруглённые top-left/bottom-left, правый край прямой (��тык с контентом).
    local R = WIN.radius
    Engine.pushClip(x, y, w, h)
    fillRoundedPanel(x, y, w, h, COL.inset, 1, R, { tl = true, bl = true })
    Engine.popClip()

    -- Логотип по центру верхней зоны; высота блока -> позиция разделителя/нав.
    -- Зона перетаскивания окна охв��тывает ВЕСЬ блок логотип�� (drag за шапку).
    -- ��ельту применяет onDraw в начале кадра -> нет рассинхрона фон/рамка.
    local logoH = drawLogo(x, y, w, dt)
    hit("win/dragL", x, y, w, logoH, Z.BODY)
    line(x + 1, y + logoH + 1, x + w - 1, y + logoH + 1, COL.text, 0.06, 1)

    -- Источник вкладок: строго из построенной билдер-модели. Фолбэк-NAV удалён --
    -- сайдбар рисуется только когда окно собрано (см. гвард в onDraw).
    local navSrc = {}
    if Engine.model and Engine.model.hasBuilt then
        -- Строим список из билдер-модели, ВСТАВЛЯЯ заголовок группы при каждой
        -- смене tab.group (п.1). Так группы, заданные через :Tab{Group=...},
        -- ��еально видн�� и сворачиваемы в сайдб��ре, а не только в крошках.
        navSrc = {}
        local lastG
        -- Разделение на группы можно о��ключить в UI Settings (app.custom.navGroups).
        -- То��да за���оловки НЕ вставляются -> плоский список ��кладок, как раньше.
        local useGroups = app.custom.navGroups ~= false
        for _, tab in ipairs(Engine.model.tabs) do
            local g = tab.group
            if useGroups and g and g ~= lastG then
                navSrc[#navSrc + 1] = { group = g }
                lastG = g
            end
            navSrc[#navSrc + 1] = { id = tab.name, ic = tab.icon, group = useGroups and g or nil }
            NAV_GROUP[tab.name] = g or NAV_GROUP[tab.name]
        end
    end

    -- Фильтр по строке поиска: нормализуем (регистр + пробелы) и совпадаем по
    -- имени вкладки ��ЛИ по любому имени секции/элемента внутри (см. tabMatches).
    local nq = Engine.normSearch(app.query or "")
    if nq ~= "" then
        local byName = Engine.model and Engine.model.tabByName
        local filtered = {}
        for _, item in ipairs(navSrc) do
            if item.id then     -- только реальные пункты; заголовки групп отбрасываем
                local tab = byName and byName[item.id]
                local ok
                if tab then
                    ok = tabMatches(tab, nq)
                else
                    ok = Engine.normSearch(item.id):find(nq, 1, true) ~= nil
                end
                if ok then filtered[#filtered + 1] = item end
            end
        end
        navSrc = filtered
    end

    local iy = y + logoH + 14   -- навигация начинается ��од блоком л��готипа
    if nq ~= "" and #navSrc == 0 then
        text(x + 12, iy, 11, COL.faint, "No results", 0.7)
    end
    -- gOpen = АНИМИРОВАННАЯ доля раскрытия ТЕКУЩЕЙ группы (0..1). Раньше пункты
    -- свёрнутой группы исчезали МГНОВЕННО -> все вкладки ниже прыгали вверх, из-за
    -- чего их hover/active пересчитывался и «анимировались все группы разом» (баг).
    -- Теперь ��ысота каждого пункта умножается на gOpen свое�� группы -> плавное
    -- сворачивание без скачка раскладки.
    local gOpen = 1
    for _, item in ipairs(navSrc) do
        -- ЗАГОЛОВОК ГРУППЫ = запись с .group И БЕЗ .id. У пунктов .group тоже есть
        -- (для свора��ивания), поэтому обяза��ельно проверяем отсутствие .id, иначе
        -- каждый пункт ошибочно рисуется как заголовок (был именно этот баг).
        if item.group and not item.id then
            -- Заголо��ок-кно��ка с шевроном: клик сворачивает/разворачивает группу.
            -- При поиске (nq~="") группы не сворачиваем -- показываем все совпадения.
            local gkey = "navgrp/" .. item.group
            local collapsed = (nq == "") and app.navCollapsed[item.group] or false
            local gh = Engine.sheet and 40 or 30
            hit(gkey, x + 8, iy, w - 16, gh, Z.BODY)
            local gs = stateOf(gkey)
            gs.hover = approach(gs.hover, Engine.isHover(gkey) and 1 or 0, dt, 16)
            if Engine.clicked(gkey) and nq == "" then
                app.navCollapsed[item.group] = not app.navCollapsed[item.group]
                collapsed = app.navCollapsed[item.group]
            end
            -- ВА��НО: `open` инициализируем СРАЗУ в целевое значение (0/1), а не в 1.
            -- Иначе п��и первом появлении КАЖДАЯ уже-свёрнутая группа проигрывала бы
            -- фальш-анимацию 1->0 -> выглядело как «анимируются все группы разом».
            -- Теперь двигается только та группа, чей collapsed реально изменился.
            if gs.open == nil then gs.open = collapsed and 0 or 1 end
            gs.open = approach(gs.open, collapsed and 0 or 1, dt, 16)
            gOpen = gs.open   -- ведёт высоту пунктов ЭТОЙ группы до следующего заголовка

            -- фон-подсве��ка на ховере
            if gs.hover > 0.01 then
                rrect(x + 8, iy, w - 16, gh, COL.navOn, gs.hover * 0.3, 8)
            end
            -- ���еврон (вниз=р���скрыто -> вправо=свёрнуто), крупнее и ��р��е
            local chvx, chvy = x + 18, iy + gh * 0.5
            local rot = -(1 - gs.open) * (math.pi * 0.5)
            local function rp(px, py)
                return chvx + (px * math.cos(rot) - py * math.sin(rot)),
                       chvy + (px * math.sin(rot) + py * math.cos(rot))
            end
            local ss2 = 4
            local a1x, a1y = rp(-ss2, -ss2 * 0.5)
            local b1x, b1y = rp(0, ss2 * 0.5)
            local d1x, d1y = rp(ss2, -ss2 * 0.5)
            Engine.line(a1x, a1y, b1x, b1y, COL.cyan, 1, 2)
            Engine.line(b1x, b1y, d1x, d1y, COL.cyan, 1, 2)
            -- название группы: крупное, обычный регистр, яркое (не капс, п.-)
            text(x + 32, iy + gh * 0.5 - 7, 13.5, COL.text, item.group, 1)
            iy = iy + gh + 2
        elseif gOpen <= 0.001 then
            -- ��руппа полностью свёрнута -- пункт не занимает места и не кликается
        else
            local key = "nav/" .. item.id
            local active = app.nav == item.id
            -- Анимирова��ная высота пункта: полная высота * gOpen. При gOpen<1 пункт
            -- «схлопывается» плавно, а не исчеза��т мгновенно.
            local fullH = Engine.sheet and 44 or M.navH
            local rowH = fullH * gOpen
            local a = gOpen                       -- прозра��ность содержимого
            -- hit-зону даём только когда пункт достаточно раскрыт (не ловим клики
            -- по «схлопывающейся» полоске)
            if gOpen > 0.5 then hit(key, x + 8, iy, w - 16, rowH) end
            local s = stateOf(key)
            s.hover = approach(s.hover, (gOpen > 0.5 and Engine.isHover(key)) and 1 or 0, dt, 16)
            s.on = approach(s.on, active and 1 or 0, dt, 18)
            if gOpen > 0.5 and Engine.clicked(key) then
                app.nav = item.id
                app.scrollY = 0
                if Engine.sheet then app.drawerOpen = false end
            end

            -- Ховер: ровная подсветка. Активная вкладка: гладкий акцентный гр��диент.
            -- Высота/прозрачность масштабируются на gOpen (a) -> плавный коллапс.
            local drawH = rowH
            if s.hover > 0.01 and s.on < 0.5 then
                rrect(x + 8, iy, w - 16, drawH, COL.navOn, s.hover * 0.35 * a, M.navR)
            end
            if s.on > 0.01 then
                -- горизонтальный статичный акцентный градиент A->B на активной вкладке
                local gA2 = COL.navOn:Lerp(Engine.accentA or COL.cyan, 0.30)
                local gB2 = COL.navOn:Lerp(Engine.accentB or COL.cyan, 0.30)
                Engine.gradRect(x + 8, iy, w - 16, drawH, gA2, gB2,
                    s.on * 0.96 * a, M.navR, 0, nil, true)
                Engine.rstroke(x + 8, iy, w - 16, drawH, COL.cyan,
                    0.30 * s.on * a, M.navR, 1)
            end
            -- содержимое рисуем только когда пункт достаточно раскрыт (иначе текст
            -- «сплющивается» и выглядит грязно)
            if a > 0.35 then
                local c = active and COL.text or COL.dim
                local ca = (0.8 + s.on * 0.2) * a
                icon(item.ic, x + 26, iy + drawH * 0.5, Engine.sheet and 16 or 13, c, ca)
                text(x + 40, iy + drawH * 0.5 - 6, 12, c, fitText(item.id, 12, math.max(24, w - 56)),
                    (0.8 + s.on * 0.2 + s.hover * 0.1) * a)
            end
            iy = iy + rowH + 3 * a
        end
    end

    ------------------------------------------------------------------
    -- Низ сайдбара: поиск (если позиция = sidebar) + брендовый футер.
    ------------------------------------------------------------------
    local sw = w - 16

    -- ФУТЕР-ВИДЖЕТ СТАТИС��ИКИ (п.6). Вместо брендовой плашки «Nova UI» -- ��ивая
    -- полезная сводка: крупный FPS + мини-спарклайн истории кадров + ап����йм
    -- сессии. Высота фикс. -> позиция ��оиска с��итается ОТ ВЕРХА футера, поэтому
    -- поиск всегда подстраивается под него (раньше оба были з��хардкожены и не
    -- согла��ованы).
    local fh = 52
    local fy = y + h - fh - 10
    rrect(x + 8, fy, sw, fh, COL.user, 1, 12)
    rstroke(x + 8, fy, sw, fh, COL.cyan, 0.10, 12, 1)

    -- FPS (крупно) + подпи��ь
    local fpsN = floor(Engine.fps + 0.5)
    local fpsTxt = tostring(fpsN)
    text(x + 18, fy + 9, 20, COL.text, fpsTxt, 1)
    local nw = measure("888", 20, Fonts.Plex).X
    text(x + 18 + nw + 5, fy + 17, 9, COL.faint, "FPS", 1)

    -- аптайм сессии (mm:ss) под FPS
    local up = math.floor(os.clock() - (Engine.startTime or os.clock()))
    local ups = string.format("%d:%02d", math.floor(up / 60), up % 60)
    text(x + 18, fy + 32, 9.5, COL.dim, "session " .. ups, 0.85)

    -- мини-спарклайн FPS справа
    local hist = Engine.fpsHist or {}
    if #hist >= 2 then
        local spW, spH = 66, 24
        local spX = x + 8 + sw - spW - 12
        local spY = fy + fh * 0.5 - spH * 0.5
        local mx = 1
        for _, v in ipairs(hist) do if v > mx then mx = v end end
        mx = math.max(mx, 60)
        local prevX, prevY
        for i, v in ipairs(hist) do
            local px = spX + (spW) * ((i - 1) / (#hist - 1))
            local py = spY + spH - (clamp(v / mx, 0, 1) * spH)
            if prevX then Engine.line(prevX, prevY, px, py, COL.cyan, 0.75, 1.4) end
            prevX, prevY = px, py
        end
        -- точка на конце
        disc(prevX, prevY, 2, COL.cyan, 0.95, 12)
    end

    -- Поиск в сайдбаре: НАД футером с отступом (позиция = "sidebar", п.6).
    if (app.custom and app.custom.searchPos or "sidebar") == "sidebar" then
        drawSearchField(x + 8, fy - 40, sw, 30, dt)
    end
end

----------------------------------------------------------------------------
-- ВЕРХНЯЯ ПАНЕЛЬ (крошки) -- она же зона перетаскивания окна
----------------------------------------------------------------------------
local function topbar(x, y, w, dt)
    -- ФОН ТОПБАРА (DI). Титлбар рисуем сами. Скругляем ТОЛЬКО правый-верхний угол
    -- окна (левый край стыкуется с сайдбаром, низ -- с контентом). Раньше приём
    -- extend-past-clip давал КВАДРАТНЫЙ ��г��л (rrect под клипом теряет скругление),
    -- он торчал за силуэт окна. Теперь fillRoundedPanel -> настоящий top-right.
    local R = WIN.radius
    local cy = y + M.top * 0.5
    Engine.pushClip(x, y, w, M.top)
    fillRoundedPanel(x, y, w, M.top, COL.inset, 1, R, Engine.sheet and { tl = true, tr = true } or { tr = true })
    -- едва заметный вертикальный высвет сверху убран (создавал визуальную полосу/
    -- «кривой оттенок» на фоне заголовков табов/групп). fillRoundedPanel даёт
    -- ровную заливку без артефактов.
    Engine.popClip()
    -- нижняя раз��елительная линия с л����гким акцентным подтоном
    line(x, y + M.top - 0.5, x + w, y + M.top - 0.5, COL.cyan, 0.08, 1)

    -- Только ЗАЯВЛЯЕМ хит-зону перетаскивания; дельту ��рименяет onDraw в начале кадра.
    hit("win/drag", x, y, w, M.top, Z.BODY)

    local lead = 0
    if Engine.sheet then
        lead = 44
        hit("nav/drawer", x, y, 44, M.top, Z.BODY)
        if Engine.clicked("nav/drawer") then
            app.drawerOpen = not app.drawerOpen
        end
        local hx, hy = x + 22, cy
        if app.drawerOpen then
            line(hx - 6, hy - 6, hx + 6, hy + 6, COL.text, 0.95, 1.6)
            line(hx - 6, hy + 6, hx + 6, hy - 6, COL.text, 0.95, 1.6)
        else
            line(hx - 8, hy - 5, hx + 8, hy - 5, COL.text, 0.9, 1.6)
            line(hx - 8, hy, hx + 8, hy, COL.text, 0.9, 1.6)
            line(hx - 8, hy + 5, hx + 8, hy + 5, COL.text, 0.9, 1.6)
        end
    end

    -- ИКОНКА активной вкладки -- из построенной модели (фолбэк-NAV удалён).
    local navIc
    if Engine.model and Engine.model.hasBuilt then
        local t = Engine.model.tabByName and Engine.model.tabByName[app.nav]
        navIc = t and t.icon or nil
    end
    navIc = navIc or "layers"

    -- Крошки: «Группа / [иконка] Таб». БЕЗ выделения-чипа (пользователю не нрави��ось
    -- «выделение секции»): активный таб подчёркиваем тонкой АКЦЕНТНОЙ ЛИНИЕЙ под
    -- текстом -- аккуратнее сплошной плашки.
    local bx = x + M.pad + (lead or 0)
    local grp = NAV_GROUP[app.nav] or "Misc"
    text(bx, cy - 6, 12, COL.dim, grp, 0.8)
    local aw = measure(grp, 12, Fonts.Plex).X
    -- Разделитель "/" и увеличенные ��азоры: р��ньше иконка стояла вплотную к "/"
    -- (icon() центрирует по icX, а отступ считался как от левого края) -> почти
    -- соприкас��лись. Теперь считаем ЯВНО: зазор "/"->иконка и иконка->текст.
    local slashX = bx + aw + 12
    text(slashX, cy - 7, 13, COL.faint, "/", 0.6)
    local slashW = measure("/", 13, Fonts.Plex).X

    local icSize = 13
    local icX  = slashX + slashW + 14 + icSize * 0.5   -- ЦЕНТР иконки (14px от "/")
    icon(navIc, icX, cy, icSize, COL.text, 0.95)
    local txX  = icX + icSize * 0.5 + 8                -- текст в 8px от правого края и��онки
    local searchW = 0
    if (app.custom and app.custom.searchPos) == "topbar" then
        searchW = Engine.sheet and math.min(140, math.floor(w * 0.38)) or 190
    end
    local rightLimit = x + w - M.pad - (searchW > 0 and (searchW + 8) or 0)
    local nameMax = math.max(24, rightLimit - txX)
    local shownNav = fitText(app.nav, 12, nameMax, Fonts.Plex)
    local nameW = measure(shownNav, 12, Fonts.Plex).X
    text(txX, cy - 6, 12, COL.text, shownNav, 1)
    -- подчёркивание по ��ири��е имени таба, акцентным градиентом
    local ulY = cy + 9
    if app.custom and app.custom.accentGrad then
        Engine.gradRect(txX, ulY, nameW, 2, Engine.accentA or COL.cyan,
            Engine.accentB or COL.cyan, 0.9, 1, 0, nil, true)
    else
        rrect(txX, ulY, nameW, 2, COL.cyan, 0.9, 1)
    end

    -- П��иск в ТОПБАРЕ (позиция "topbar"): компактное поле справа. FPS-счётчик у��ран.
    if searchW > 0 then
        drawSearchField(x + w - searchW - M.pad, cy - 13, searchW, 26, dt)
    end
end

----------------------------------------------------------------------------
-- СТРАНИЦА RENDER -- 3D-СЦЕНА (порт из nova_ui)
----------------------------------------------------------------------------
-- Слева больш��й вьюпорт (орбита мыш��ю, зум колесом, авто-спин), сп��ава карточка
-- контролов: выбор меша, spin/wireframe/glow и скорость вращения. Использует
-- Engine.W.viewport + W.dropdown + getMesh -- ничего нового рисовать не нужно,
-- только собрать layout под метрики аппа. НЕ участвует в вертикальном скролле
-- (сцена фиксирована в области контента), поэтому рисуется вне card-петли.
local W = Engine.W

-- Деф��лт камеры для кнопки Reset View (совпадает с app.scene.cam).
local SCENE_DEFAULT = {
    yaw = 0.6, pitch = -0.35, dist = 3.2,
    spin = true, speed = 0.6, wire = false, glow = true,
}

-- Мелки�� HUD-чип поверх вьюп��рта: подпис�� + значение, моно-цифры.
local function hudChip(x, y, label, value, tone, liveDot)
    local lw = measure(label, 10, Fonts.Plex).X
    local vw = measure(value, 10, Fonts.PlexMono or Fonts.Plex).X
    local dotw = liveDot and 10 or 0
    local w = 14 + dotw + lw + 6 + vw
    rrect(x, y, w, 20, COL.inset, 0.6, 6)
    local tx = x + 8
    if liveDot then
        disc(tx + 2, y + 10, 2.5, tone or COL.cyan, 1, 12)
        tx = tx + dotw
    end
    text(tx, y + 5, 10, COL.faint, label, 1)
    text(tx + lw + 6, y + 5, 10, COL.text, value, 1, Fonts.PlexMono or Fonts.Plex)
    return w
end

-- Метрика-плашка (VERTS / TRIS) в нижн��й панели.
local function statBox(x, y, w, label, value)
    rrect(x, y, w, 34, COL.inset, 0.5, 6)
    text(x + 8, y + 5, 9, COL.faint, label, 1)
    text(x + 8, y + 17, 13, COL.text, value, 1, Fonts.PlexMono or Fonts.Plex)
end

-- Сегментный тумблер: скруглённая кнопка с точкой-индикатором и подписью.
-- Возвращает true при клике. Ширина считается по тексту.
local function segToggle(key, x, y, label, value, dt, iconId)
    local lw = measure(label, 12).X
    local w = 30 + lw + 12
    hit(key, x, y, w, 30)
    local tone = value and COL.cyan or COL.dim
    rrect(x, y, w, 30, value and COL.cyan or COL.inset,
        value and 0.14 or 0.5, 8)
    if value then
        rstroke(x, y, w, 30, COL.cyan, 0.45, 8, 1)
    end
    -- иконка Lucide ��мес��о точки-индикатора (drawIcon сам откатится на вектор)
    Engine.drawIcon(iconId or "Render", x + 8, y + 8, 14, tone, value and 1 or 0.6)
    text(x + 30, y + 9, 12, value and COL.text or COL.dim, label, 1)
    return Engine.clicked(key), w
end

-- Высота wideSlider (совпадает с draw). НОВЫЙ дизайн (жалоба «непонятно, к чему
-- слайдер»): подпись и значение ВСЕГДА в одной строке (значение справа), жёлоб
-- вплотную под ними, и увеличенный НИЖНИЙ отступ -> соседние слайдеры визуально
-- разделены «воздухом», сразу видно границы одного контрола. Ничего не «падает»
-- под подпись, поэтому не остаётся висящих одиноких строк.
-- Возвраты: totalH (с нижним воздухом), rowH (строка подпись/значение), gap.
local WSL_ROW  = 11     -- кегль строки подпись/значение
local WSL_GAP  = 3      -- зазор строка->жёлоб (вплотную)
local WSL_TRK  = 8      -- толщина жёлоба
local WSL_AIR  = 8      -- нижний «воздух» между слайдерами (было 16 -> слишком много)
local function wideSliderH(w, label, value, suffix)
    local sc = (THEME and THEME.scale) or 1
    local rowH   = math.floor(WSL_ROW * sc) + 3
    local gap    = math.floor(WSL_GAP * sc)
    local trkReg = WSL_TRK + 6                         -- жёлоб + свес ручки
    local air    = math.floor(WSL_AIR * sc)
    return rowH + gap + trkReg + air, rowH, gap
end

-- Широкий слайдер: подпись слева + значение справа в ОДНОЙ строке, жёлоб вплотную
-- под ними. Возвращает новое значение.
local function wideSlider(key, x, y, w, label, value, vmin, vmax, suffix, dt)
    local sc = (THEME and THEME.scale) or 1
    local lblSz, valSz = WSL_ROW, 10.5
    local _, rowH, gap = wideSliderH(w, label, value, suffix)
    local vtxt = string.format("%.2f%s", value, suffix or "")
    local vfont = Fonts.PlexMono or Fonts.Plex
    local vw = measure(vtxt, valSz, vfont).X + 12
    local ph = math.floor(valSz * sc) + 6

    -- строка: подпись слева (обрезаем, чтобы не залезть под бокс значения),
    -- бокс значения справа. Обе на одной базо��ой линии.
    local labelMaxW = math.max(20, w - vw - 10)
    text(x, y + 1, lblSz, COL.label, fitText(label or "", lblSz, labelMaxW), 0.95)
    local vbx, vby = x + w - vw, y - 1
    rrect(vbx, vby, vw, ph, COL.track, 1, 5)
    text(vbx + 6, vby + 2, valSz, COL.label, vtxt, 0.95, vfont)

    -- жёлоб вплотную под строкой
    local ty = y + rowH + gap + 5                 -- +5 = верхний свес ручки
    local th = WSL_TRK
    hit(key, x - 2, ty - 8, w + 4, th + 16)
    local out = value
    if Engine.isActive(key) then
        local f = clamp((Engine.input.mouse.X - x) / w, 0, 1)
        out = vmin + f * (vmax - vmin)
    end
    local frac = clamp((value - vmin) / (vmax - vmin), 0, 1)
    rrect(x, ty, w, th, COL.trackOff, 1, th * 0.5)
    if frac > 0.001 then
        rrect(x, ty, math.max(w * frac, th), th, COL.cyan, 1, th * 0.5)
    end
    -- Ручка -- скруглённая вертикальная «пилюля» (rrect), НЕ disc: FilledCircle на
    -- части э��зе��уторов вырождается в треугольник (жалоба юзера). Пилюля надёжна.
    local hx = x + fit(w * frac, 6, w - 6)
    local hw, hh = 6, th + 10
    rrect(hx - hw * 0.5, ty + th * 0.5 - hh * 0.5, hw, hh, COL.text, 1, hw * 0.5)
    rstroke(hx - hw * 0.5, ty + th * 0.5 - hh * 0.5, hw, hh, COL.cyan, 0.5, hw * 0.5, 1)
    return out
end

local function modelsPage(cx, fy, cw, fh, dt)
    -- Only the active Geometry tab reaches here via CustomPage.
    if not Engine.visible then return fy end
    local scene = app.scene
    local cam = scene.cam
    local pad = M.pad
    -- МАСШТАБ UI: раньше нижняя панель имела фиксированные размеры (122px высота,
    -- 210px колонка, отступы 12/30/48), а шрифты/слайдеры растут с THEME.scale ->
    -- при крупном скейле ��онтент вылезал за панель и за рамки UI (жалоба). Тепе��ь
    -- вся ����еометрия панели масштабируется вместе со шрифтом.
    local sc = (THEME and THEME.scale) or 1
    local function S(v) return math.floor(v * sc) end

    -- FPS -- экспоненциальное сглаживание, как HUD-счётчик.
    scene._fps = scene._fps or 60
    if dt > 0 then scene._fps = scene._fps + (1 / dt - scene._fps) * 0.1 end

    -- РАСКЛАДКА: вьюпорт сверху во всю ширину, панель Geometry снизу горизонтально.
    -- Высота панели = max(база, реальная высота двух слайдеров + отступы), чтобы
    -- Spin Speed/Distance гарантированно помещались при любом скейле/ширине.
    local vx = cx + pad
    local vw = cw - pad * 2
    local gap = 12
    -- п��икидываем ширину колонки слайдеров (правая треть) для расчёта их высоты
    local c3wEst = math.max(vw * 0.34, 120)
    local slPairH = wideSliderH(c3wEst, "Spin Speed", cam.speed, "x")
        + wideSliderH(c3wEst, "Distance", cam.dist, "") + S(30)
    local panelH = math.max(S(122), slPairH)
    local vy = fy + 12
    local vh = fh - panelH - gap - 24

    local mesh = Engine.getMesh(scene.mesh)
    W.viewport("scene/view", vx, vy, vw, vh, mesh, cam, dt)

    -- HUD-чипы (FPS live + DIST) в правом верхнем углу вьюпорта.
    -- Рисуе�� справа на��ево: ширину чипа считаем той ��е формулой, ч��о в hudChip,
    -- НЕ рисуя фантомный чип (иначе он появлялся бы ���� углу эк��ана).
    local monoF = Fonts.PlexMono or Fonts.Plex
    local function chipW(label, value, liveDot)
        local dotw = liveDot and 10 or 0
        return 14 + dotw + measure(label, 10, Fonts.Plex).X + 6 + measure(value, 10, monoF).X
    end
    local distV = string.format("%.1f", cam.dist)
    local fpsTxt = tostring(math.floor(scene._fps + 0.5))
    local dw = chipW("DIST", distV, false)
    local fw = chipW("FPS", fpsTxt, true)
    hudChip(vx + vw - 10 - dw, vy + 10, "DIST", distV, COL.cyan, false)
    hudChip(vx + vw - 10 - dw - 6 - fw, vy + 10, "FPS", fpsTxt, COL.cyan, true)

    -- Reset View -- правый нижний угол вьюпорта (иконка + подпись).
    local rvw = measure("Reset View", 10.5).X + 30
    local rvx, rvy = vx + vw - 10 - rvw, vy + vh - 10 - 22
    hit("scene/reset", rvx, rvy, rvw, 22)
    if Engine.clicked("scene/reset") then
        for k, v in pairs(SCENE_DEFAULT) do cam[k] = v end
    end
    rrect(rvx, rvy, rvw, 22, COL.inset, 0.75, 6)
    rstroke(rvx, rvy, rvw, 22, COL.cyan, 0.2, 6, 1)
    Engine.drawIcon("Reset", rvx + 8, rvy + 5, 12, COL.dim, 1)
    text(rvx + 24, rvy + 5, 10.5, COL.dim, "Reset View", 1)

    -- НИЖНЯЯ ПАНЕЛЬ
    local py = vy + vh + gap
    rrect(vx, py, vw, panelH, COL.panel, 0.92, M.cardR)

    -- Колонка 1: заголовок + модель + метрики. Все отступы через S() -> тянутся
    -- вместе со скейлом, пан��ль больше не переполняется по вертикали.
    local c1x = vx + S(16)
    local c1w = S(210)
    text(c1x, py + S(12), 13, COL.text, "Geometry", 1)
    text(c1x, py + S(30), 10.5, COL.faint, "Orbit with drag, zoom with wheel.", 1)
    local picked = W.dropdown("scene/mesh", c1x, py + S(48), c1w, Engine.MeshOrder, scene.mesh, dt)
    if picked then scene.mesh = picked end
    local sbY = py + panelH - S(44)
    statBox(c1x, sbY, c1w * 0.5 - 4, "VERTS", tostring(#mesh.verts))
    statBox(c1x + c1w * 0.5 + 4, sbY, c1w * 0.5 - 4, "TRIS", tostring(#mesh.faces))

    -- Разделители-колонки.
    local divA = c1x + c1w + S(18)
    line(divA, py + 14, divA, py + panelH - 14, COL.text, 0.06, 1)

    -- Колонка 2: Display -- три сегментных тумблера (горизонтально).
    local c2x = divA + S(18)
    text(c2x, py + S(12), 10, COL.faint, "DISPLAY", 1)
    local ty = py + S(30)
    local cl1, w1 = segToggle("scene/spin", c2x, ty, "Auto Spin", cam.spin, dt, "Spin")
    if cl1 then cam.spin = not cam.spin end
    local tx2 = c2x + w1 + 8
    local cl2, w2 = segToggle("scene/wire", tx2, ty, "Wireframe", cam.wire, dt, "Wireframe")
    if cl2 then cam.wire = not cam.wire end
    local tx3 = tx2 + w2 + 8
    local cl3, w3 = segToggle("scene/glow", tx3, ty, "Glow", cam.glow, dt, "Glow")
    if cl3 then cam.glow = not cam.glow end
    local c2right = tx3 + w3

    local divB = c2right + S(18)
    line(divB, py + 14, divB, py + panelH - 14, COL.text, 0.06, 1)

    -- Колонка 3: слайдеры (тянутся до правого края панели). Вертикальный шаг берём
    -- из wideSliderH -> при узкой колонк�� значение падает под подпись, а второй
    -- с��айдер сдвигается ��овно на реальную высоту первого. Больше не наезжают и не
    -- выходят за панель ни при мелком, ни при крупном скейле.
    local c3x = divB + S(18)
    local c3w = (vx + vw - S(16)) - c3x
    local slY = py + S(18)
    local h1 = wideSliderH(c3w, "Spin Speed", cam.speed, "x")
    cam.speed = wideSlider("scene/speed", c3x, slY, c3w, "Spin Speed", cam.speed, 0, 3, "x", dt)
    cam.dist  = wideSlider("scene/dist",  c3x, slY + h1 + S(6), c3w, "Distance", cam.dist, 1.6, 9, "", dt)

    return fy + fh
end

----------------------------------------------------------------------------
-- УНИВЕРСАЛЬНЫЙ ТАБ CUSTOMIZE
----------------------------------------------------------------------------
-- Не к��рточки/секции (��то НЕ страница модулей), а собственные крупные панели с
-- градиентн��ми шапками -- уникальный дизайн, ка�� и просил пользователь. Меняет
-- буквально всё: акцент (пресеты + RGB), шрифт, и полностью Notify (текст,
-- длительнос��ь, тон) с кнопкой отправки тестового тоста.

-- Панель с градиентной шапкой. В��звращает Y начала вну��реннего контента.
local function panel(x, y, w, headH, title, sub, iconId)
    -- Тело панели рисует вызывающий код; здесь -- тольк�� градиентная шапка
    -- (демонстрация того самого градиента) и заголо��ок.
    local gTop = COL.panel:Lerp(COL.cyan, 0.16)
    local gBot = COL.panel:Lerp(COL.cyan, 0.02)
    gradRect(x, y, w, headH, gTop, gBot, 1, M.cardR, 0.6, os.clock())
    rstroke(x, y, w, headH, COL.cyan, 0.22, M.cardR, 1)
    -- Иконка в скруглённом бейдже -- тот же стиль, что в билдер-секциях (п.12),
    -- чтобы Customise и UI Settings выглядели одинаково.
    local tx = x + 16
    if iconId then
        local bsz = 30
        local bx, by = x + 12, y + headH * 0.5 - bsz * 0.5
        rrect(bx, by, bsz, bsz, COL.cyan, 0.14, 9)
        drawIcon(iconId, bx + bsz * 0.5 - 8, by + bsz * 0.5 - 8, 16, COL.cyan, 0.95)
        tx = bx + bsz + 12
    end
    text(tx, y + 9, 13, COL.text, title, 1)
    if sub then text(tx, y + 26, 10.5, COL.dim, sub, 0.85) end
    return y + headH + 12
end

-- Слайдер одного цветового канала (жёлоб окрашен в цвет канала).
local function chanSlider(key, x, y, w, label, value, tone, dt)
    text(x, y, 11, COL.label, label, 0.9)
    local vtxt = tostring(floor(value + 0.5))
    text(x + w - measure(vtxt, 11).X, y, 11, COL.dim, vtxt, 0.9)
    local ty = y + 18
    local th = 6
    -- зона захвата шире жёлоба (п.7): ловим и удержание, и одиночный клик
    hit(key, x - 6, ty - 12, w + 12, th + 24, Z.CONTENT)
    local out = value
    if Engine.isActive(key) or Engine.clicked(key) then
        out = clamp((Engine.input.mouse.X - x) / w, 0, 1) * 255
    end
    local frac = clamp(value / 255, 0, 1)
    rrect(x, ty, w, th, COL.trackOff, 1, th * 0.5)
    if frac > 0.001 then rrect(x, ty, math.max(w * frac, th), th, tone, 1, th * 0.5) end
    disc(x + fit(w * frac, 6, w - 6), ty + th * 0.5, 6.5, COL.text, 1, 20)
    return out
end

-- HSV-ПИКЕР. SV-квадрат + верти��альная hue-��олоса.
-- ВСЁ ри��уется примити��ами DrawingImmediate (полосами), Н�� шейдером: шейдер
-- всегда лежит ПОД DI-слоем и его заливка панели скрывает -> «палитра пустая».
-- Полосы же рисуются тем же DI, что и панель, ��оэтому цвета видны всегда.
-- X квадрата -> saturation, Y -> value. Пишет прямо в app.custom (hue/sat/val).
local function hidePickerFxIfIdle() end  -- совместимость: шейдеров у пикера б��льше нет
Engine.hidePickerFxIfIdle = hidePickerFxIfIdle

-- Обобщённый HSV-пикер. st = { hue, sat, val } (0..1). Возвращает (Color3, changed).
-- Рисуется примитивами DI, поэто��у виден всегда. Универсален: и Customize, и
-- builder-Colorpicker использ��ют его.
-- ВВОД палитры -- ОБЯЗАТЕЛЬНО в ГЛАВНОМ проходе (не в deferOverlay!). Регистрирует
-- hit-об��асти SV-квадрата и hue-полосы, чтобы они попали в liveHits ДО снапшота.
-- Иначе pick() и�� не видит -> клик по палитре «проваливается» -> colorpicker
-- закрывается на любой клик и цвет не меняется (именно этот баг и чи����м).
local function colorFieldHit(key, sx, sy, ssz, hueX, hueW, st)
    local before = st.hue .. "," .. st.sat .. "," .. st.val
    local skey = key .. "/sv"
    hit(skey, sx, sy, ssz, ssz, Z.OVERLAY, false, true)
    if Engine.isActive(skey) then
        st.sat = clamp((Engine.input.mouse.X - sx) / ssz, 0, 1)
        st.val = 1 - clamp((Engine.input.mouse.Y - sy) / ssz, 0, 1)
    end
    local hkey = key .. "/hue"
    hit(hkey, hueX, sy, hueW, ssz, Z.OVERLAY, false, true)
    if Engine.isActive(hkey) then
        st.hue = clamp((Engine.input.mouse.Y - sy) / ssz, 0, 1)
    end
    local changed = (st.hue .. "," .. st.sat .. "," .. st.val) ~= before
    return Color3.fromHSV(st.hue, st.sat, st.val), changed
end

-- ОТРИСОВКА палитры -- в deferOverlay (поверх соседних строк). Только визуал.
local function colorField(key, sx, sy, ssz, hueX, hueW, st)
    -- SV-квадрат. Поло���� ПОПИКСЕЛЬНЫЕ (bands ~= ssz), и��аче градиент выглядит
    -- «рван��м»/ступен��атым (жалоба). bw держим с нахлё��том +1, чтобы не бы��о
    -- зазоров между полосами.
    -- Нахлёст (+1.2) закрывает зазоры МЕЖДУ полосами, но ширину/высоту ПОСЛЕДНЕЙ
    -- полосы клампуем к краю: иначе она вылезал�� на 1.2px за границу и торч��ла
    -- тонкой полоской чистого оттенка справа/снизу (замеченный шов).
    local hueC = Color3.fromHSV(st.hue, 1, 1)
    local bands = math.max(64, math.floor(ssz))
    local bw = ssz / bands
    local white = Color3.new(1, 1, 1)
    for i = 0, bands - 1 do
        local f = (i + 0.5) / bands
        local w = math.min(bw + 1.2, ssz - i * bw)
        rrect(sx + i * bw, sy, w, ssz, white:Lerp(hueC, f), 1, 0)
    end
    -- Затемнение св��рху вниз -> value.
    for i = 0, bands - 1 do
        local f = (i + 0.5) / bands
        local h = math.min(bw + 1.2, ssz - i * bw)
        rrect(sx, sy + i * bw, ssz, h, Color3.new(0, 0, 0), f * f * 0.98, 0)
    end
    -- hue-полоса (радуга).
    local hbands = math.max(48, math.floor(ssz))
    local hbw = ssz / hbands
    for i = 0, hbands - 1 do
        local f = (i + 0.5) / hbands
        local h = math.min(hbw + 1.2, ssz - i * hbw)
        rrect(hueX, sy + i * hbw, hueW, h, Color3.fromHSV(f, 1, 1), 1, 0)
    end

    rstroke(sx, sy, ssz, ssz, COL.text, 0.16, 4, 1)
    rstroke(hueX, sy, hueW, ssz, COL.text, 0.16, 4, 1)

    -- Маркеры выбора (кольца с большим чи��лом сегм��нтов -> гладкие).
    local mx = sx + st.sat * ssz
    local my = sy + (1 - st.val) * ssz
    local hy = sy + st.hue * ssz
    ring(mx, my, 6, Color3.new(0, 0, 0), 0.7, 48, 2.5)
    ring(mx, my, 6, Color3.new(1, 1, 1), 0.95, 48, 1.5)
    rstroke(hueX - 2, hy - 3, hueW + 4, 6, Color3.new(1, 1, 1), 0.95, 3, 1.5)
    rstroke(hueX - 2, hy - 3, hueW + 4, 6, Color3.new(0, 0, 0), 0.5, 3, 0.75)
end

-- Крупная кнопка с градиентной заливкой в акценте.
local function bigButton(key, x, y, w, h, label, iconId, dt, tip)
    hit(key, x, y, w, h)
    local s = stateOf(key)
    s.hover = approach(s.hover, Engine.isHover(key) and 1 or 0, dt, 16)
    s.press = approach(s.press, Engine.isActive(key) and 1 or 0, dt, 20)

    local clickedNow = Engine.clicked(key)
    -- АНИМАЦИЯ НАЖАТИЯ (сдержанная): короткая вспышка s.flash 1->0 поверх всей
    -- кнопки + лё��кий «утоп» через s.press. Прежний ripple (расширяющийся диск +
    -- кольцо) убран -- он был слишком крупным и не вписы��ался.
    if clickedNow then s.flash = 1 end
    if s.flash and s.flash > 0 then
        s.flash = approach(s.flash, 0, dt, 9)
        if s.flash < 0.01 then s.flash = 0 end
    end

    -- Горизонтальный акцентный градиент A->B, стеклянная плёнка, чёткий текст.
    local r = 9
    local hov, prs = s.hover, s.press
    -- лёгкий «утоп» на нажатии (симметр��чный, скругление не искажается)
    local sq = prs * 1.2
    local bx, by, bw, bh = x + sq, y + sq, w - sq * 2, h - sq * 2
    -- мягкий ореол на ховере
    if hov > 0.01 then
        rrect(bx - 2, by - 2, bw + 4, bh + 4, COL.cyan, 0.12 * hov, r + 2)
    end
    -- база: горизонтальный акц��нтный градиент A->B.
    local cA = Engine.accentA or COL.cyan
    local cB = Engine.accentB or COL.cyan
    local baseA = (0.92 + hov * 0.06) - prs * 0.04
    gradRect(bx, by, bw, bh, cA, cB, baseA, r, 0, nil, true)
    -- стеклянная плёнка сверху (объём без искажения оттенка)
    rrect(bx, by, bw, bh * 0.42, COL.text, 0.06 + hov * 0.05, r)

    -- вспышка нажатия: ровная светлая заливка, быстро гаснет
    if s.flash and s.flash > 0 then
        rrect(bx, by, bw, bh, COL.text, 0.18 * s.flash, r)
    end
    if prs > 0.01 then rrect(bx, by, bw, bh, COL.text, 0.05 * prs, r) end
    -- Оутлайн убран (просьба юзера): вместо рамки — только тонкий верхний блик выше,
    -- граница кнопки читается за счёт градиента и тени.

    local lw = measure(label, 12.5).X
    local ix = bx + bw * 0.5 - (lw + (iconId and 22 or 0)) * 0.5
    local ty = by + bh * 0.5 - 7
    local iy2 = by + bh * 0.5 - 8
    if iconId then
        drawIcon(iconId, ix, iy2, 16, COL.text, 1)
        ix = ix + 22
    end
    -- Текст БЕЗ тёмной обводки (просьба юзера: оутлайн не со��етался с UI). Чистый
    -- foreground; читаемо��ть на градиенте держит стеклянная плёнка сверху корпуса.
    text(ix, ty, 12.5, COL.text, label, 1)
    if tip and Engine.isHover(key) then Engine.setTooltip(tip) end
    return clickedNow
end

local function customPage(cx, fy, cw, dt)
    local pad = M.pad
    local x = cx + pad
    local w = cw - pad * 2 - 4
    local y = fy + 14 - app.scrollY
    local cu = app.custom

    -- Масштаб-за��исимые ��лоты, чтобы панели АВТОМАТИЧЕСКИ подстраивались под
    -- крупный шрифт (1.35) и ко��тент не вылезал з�� ����н. gsc -- мягкий коэф.
    local gsc = 1 + ((THEME and THEME.scale or 1) - 1) * 0.6
    local RH  = math.floor(28 * gsc)                                -- слот toggle-строки
    local BTNH = math.floor(34 * gsc)                               -- высота крупной кнопки
    local floorv = math.floor

    ------------------------------------------------------------------
    -- Заголовок страницы
    ------------------------------------------------------------------
    text(x, y, 20, COL.text, "Customization", 1)
    text(x, y + 26, 11.5, COL.dim,
        "Universal theme editor -- colors, font and notifications.", 0.85)
    y = y + 54

    ------------------------------------------------------------------
    -- ПАНЕЛЬ 1: Accent Color -- НАСТОЯЩИЙ HSV-��ИКЕР (без треугольников)
    ------------------------------------------------------------------
    -- Геометрия считается ДО фона, чтобы высота панели подстроилась под контент.
    local hdrH = 48
    local sqSize = floorv(118 * gsc)
    local hueW = 20
    local acc = cu.accent
    local sqX = x + 14
    local hueX = sqX + sqSize + 12
    local pvX = hueX + hueW + 18
    local pvW = w - (pvX - x) - 14
    local sw2 = floorv(22 * gsc)
    local perRow = math.max(1, floorv((pvW + 8) / (sw2 + 8)))
    local swRows = math.ceil(#ACCENTS / perRow)
    -- правый столбец: слоты A/B (44) + тумблер (26) + сегмент режима (24, если grad)
    -- + превью (16) + подпись схем (16) + сетка. Отступы по 8/10.
    local modeH = 24 + 8
    local rightH = 44 + 8 + 26 + 8 + modeH + 16 + 12 + 16 + swRows * (sw2 + 8)
    local p1h = hdrH + math.max(sqSize, rightH) + 14

    rrect(x, y, w, p1h, COL.panel, 0.96, M.cardR)
    local iy = panel(x, y, w, hdrH, "Accent & Gradient",
        "Pick colour A, or turn on Gradient and set A and B.", "palette")
    local sqY = iy

    -- HSV-пикер правит ВЫБРАННЫЙ слот (A или B). Прокидываем прокси с HSV с��ота,
    -- потом переносим результат обратно -- ровно тот же приём, что у HUD-пикера.
    local slot = cu.accentSlot or 1
    local proxy = (slot == 1)
        and { hue = cu.hue, sat = cu.sat, val = cu.val }
        or  { hue = cu.hue2, sat = cu.sat2, val = cu.val2 }
    -- ВВОД в главном проходе (colorFieldHit возвращает цвет + changed), ОТРИСОВКА
    -- отдельно (colorField -- только визуал, ничего не возвращает). Раньше здесь
    -- стоял ТОЛЬКО colorField -> pickChanged всегда nil и hit-области не
    -- регистрировались -> палитра в Customize не реагировала (чиним это).
    local pickedC, pickChanged = colorFieldHit("cust/sv", sqX, sqY, sqSize, hueX, hueW, proxy)
    colorField("cust/sv", sqX, sqY, sqSize, hueX, hueW, proxy)
    if slot == 1 then cu.hue, cu.sat, cu.val = proxy.hue, proxy.sat, proxy.val
    else cu.hue2, cu.sat2, cu.val2 = proxy.hue, proxy.sat, proxy.val end
    if pickChanged then
        -- A и B НЕЗАВИСИМЫ: правим ��олько выбранный слот, второй не трогаем, чтобы
        -- цвет B сох��анялся при переключении режима/выключе��ии градиента.
        local pr, pg, pb = floor(pickedC.R * 255 + 0.5), floor(pickedC.G * 255 + 0.5), floor(pickedC.B * 255 + 0.5)
        if slot == 1 then
            acc.r, acc.g, acc.b = pr, pg, pb
            applyAccent(acc.r, acc.g, acc.b)
        else
            cu.accent2.r, cu.accent2.g, cu.accent2.b = pr, pg, pb
            applyAccent2(pr, pg, pb)
        end
    end

    local c1 = Color3.fromRGB(acc.r, acc.g, acc.b)
    local c2 = Color3.fromRGB(cu.accent2.r, cu.accent2.g, cu.accent2.b)

    -- ── СЛОТЫ A / B ────────────���─��─��────────────────────────────────
    local slotW = (pvW - 10) * 0.5
    local slotH = 44
    for si = 1, 2 do
        local sc = (si == 1) and acc or cu.accent2
        local sx2 = pvX + (si - 1) * (slotW + 10)
        local skey = "cust/slot" .. si
        hit(skey, sx2, sqY, slotW, slotH)
        rrect(sx2, sqY, slotW, slotH, Color3.fromRGB(sc.r, sc.g, sc.b), 1, 9)
        local onLight = (sc.r * 0.299 + sc.g * 0.587 + sc.b * 0.114) > 150
        local tcol = onLight and COL.app or COL.text
        text(sx2 + 10, sqY + 7, 12.5, tcol, si == 1 and "A" or "B", 1)
        local hx = string.format("#%02X%02X%02X", floor(sc.r), floor(sc.g), floor(sc.b))
        text(sx2 + 10, sqY + slotH - 17, 10, tcol, hx, 0.9)
        -- слот B слегка притушён (0.75), пока градиент выключен -- он ХР��НИТСЯ, но
        -- сейчас не влияет на вид. Не «unused» и без сб��оса цвета.
        if si == 2 and not cu.accentGrad then
            rrect(sx2, sqY, slotW, slotH, COL.app, 0.32, 9)
        end
        -- рамка выбора: активный слот пикера
        if (cu.accentSlot or 1) == si then
            rstroke(sx2 - 1.5, sqY - 1.5, slotW + 3, slotH + 3, COL.cyan, 0.95, 10, 2)
        elseif Engine.isHover(skey) then
            rstroke(sx2, sqY, slotW, slotH, COL.text, 0.3, 9, 1)
        end
        if Engine.clicked(skey) then
            cu.accentSlot = si
            -- выбор слота B при выключенном градиенте авто-включает градиент, чтобы
            -- редактирование B было видно (но цвет B при этом НЕ сбрасывается).
            if si == 2 and not cu.accentGrad then
                cu.accentGrad = true; bakeAccentShader()
            end
        end
    end

    -- ── ТУМБЛЕР Г��АДИЕНТА ───────────────────────────────────────────
    local gy = sqY + slotH + 8
    local gkey = "cust/gradtog"
    hit(gkey, pvX, gy, pvW, 26)
    local gon = cu.accentGrad
    rrect(pvX, gy, pvW, 26, gon and COL.cyan or COL.inset, gon and 0.2 or 0.5, 7)
    rstroke(pvX, gy, pvW, 26, gon and COL.cyan or COL.text, gon and 0.5 or 0.14, 7, 1)
    text(pvX + 10, gy + 7, 11.5, gon and COL.cyan or COL.label, "Gradient  A -> B", 1)
    local stTxt = gon and "ON" or "OFF"
    local stw = measure(stTxt, 10, Fonts.Plex).X
    text(pvX + pvW - stw - 10, gy + 8, 10, gon and COL.cyan or COL.dim, stTxt, 0.95)
    if Engine.clicked(gkey) then
        -- переключаем ТОЛЬКО флаг: цвета A и B сохраняются в любом состояни��.
        cu.accentGrad = not cu.accentGrad
        bakeAccentShader()
        Engine.notify("Customization", cu.accentGrad and "Gradient enabled" or "Solid accent", 2)
    end

    -- ── ПРЕВЬЮ (горизонтальный статичный градиент A->B) ─────────────
    -- Flow/Whole сегмент-контрол удалён: г��адиент теперь всегда статичный.
    local py = gy + 26 + 8
    Engine.gradRect(pvX, py, pvW, 16, c1, gon and c2 or c1, 1, 6, 0)
    rstroke(pvX, py, pvW, 16, COL.text, 0.14, 6, 1)

    -- ── ПРЕСЕТ-СХЕМЫ ────────────────────────────────────────────────
    local schY = py + 16 + 12
    text(pvX, schY - 2, 10, COL.dim, "SCHEMES", 0.8)
    local gridY = schY + 16
    for i, p in ipairs(ACCENTS) do
        local col = (i - 1) % perRow
        local rowi = floor((i - 1) / perRow)
        local ex = pvX + col * (sw2 + 8)
        local ey = gridY + rowi * (sw2 + 8)
        local skey = "cust/sw" .. i
        hit(skey, ex, ey, sw2, sw2)
        -- диагональный дуэт c -> c2 (одноцветные схемы вы��лядят сплошными)
        Engine.gradRect(ex, ey, sw2, sw2, p.c, p.c2 or p.c, 1, 6, 0.4)
        local sel = floor(acc.r) == floor(p.c.R * 255 + 0.5)
            and floor(acc.g) == floor(p.c.G * 255 + 0.5)
            and floor(acc.b) == floor(p.c.B * 255 + 0.5)
        if sel or Engine.isHover(skey) then
            rstroke(ex - 1.5, ey - 1.5, sw2 + 3, sw2 + 3, COL.text,
                sel and 0.9 or 0.4, 7, 1.5)
        end
        if Engine.isHover(skey) then Engine.setTooltip(p.name) end
        if Engine.clicked(skey) then
            local pc2 = p.c2 or p.c
            local isGrad = not (floor(p.c.R * 255) == floor(pc2.R * 255)
                and floor(p.c.G * 255) == floor(pc2.G * 255)
                and floor(p.c.B * 255) == floor(pc2.B * 255))
            acc.r, acc.g, acc.b = floor(p.c.R * 255 + 0.5),
                floor(p.c.G * 255 + 0.5), floor(p.c.B * 255 + 0.5)
            cu.accent2.r, cu.accent2.g, cu.accent2.b =
                floor(pc2.R * 255 + 0.5), floor(pc2.G * 255 + 0.5), floor(pc2.B * 255 + 0.5)
            local h, s, v = p.c:ToHSV(); cu.hue, cu.sat, cu.val = h, s, v
            local h2, s2, v2 = pc2:ToHSV(); cu.hue2, cu.sat2, cu.val2 = h2, s2, v2
            cu.accentGrad = isGrad          -- схема-градиент включает режим, сплошная -- выключает
            applyAccent(acc.r, acc.g, acc.b)
            applyAccent2(cu.accent2.r, cu.accent2.g, cu.accent2.b)
            Engine.notify("Customization", p.name .. " scheme applied", 2.5)
        end
    end
    y = y + p1h + 16

    ------------------------------------------------------------------
    -- ПАНЕЛЬ 1b: Window / HUD Color -- ТАКОЙ ЖЕ HSV-пикер, что и у Accent, но
    -- пишет в cu.chrome (независимо от accent). Геометрия зерка��ит панель 1,
    -- поэ��ому ничего не съезжает и не вылезает за края при любом масштабе.
    ------------------------------------------------------------------
    local chH = cu.chrome
    local csqX = x + 14
    local chueX = csqX + sqSize + 12
    local cpvX = chueX + hueW + 18
    local cpvW = w - (cpvX - x) - 14
    local cSwRows = math.ceil(#ACCENTS / perRow)
    local cRightH = 56 + cSwRows * (sw2 + 8)
    local p1bh = hdrH + math.max(sqSize, cRightH) + 14

    rrect(x, y, w, p1bh, COL.panel, 0.96, M.cardR)
    iy = panel(x, y, w, hdrH, "Window / HUD Color",
        "Recolors the window frame and titlebar. Independent of the accent.",
        "monitor")
    local csqY = iy

    -- HSV-п����кер через общий colorField. Он читает/пишет .hue/.sat/.val, поэтому
    -- прокидываем прокси с chrome-HSV, затем ��ереносим результат в cu.chrome*.
    local cProxy = { hue = cu.chromeHue, sat = cu.chromeSat, val = cu.chromeVal }
    -- ВВОД + ОТРИСОВКА раздельно (та же причина, что и у accent-пикера выше).
    local cPicked, cChanged = colorFieldHit("cust/chsv", csqX, csqY, sqSize, chueX, hueW, cProxy)
    colorField("cust/chsv", csqX, csqY, sqSize, chueX, hueW, cProxy)
    cu.chromeHue, cu.chromeSat, cu.chromeVal = cProxy.hue, cProxy.sat, cProxy.val
    if cChanged then
        chH.r = floor(cPicked.R * 255 + 0.5)
        chH.g = floor(cPicked.G * 255 + 0.5)
        chH.b = floor(cPicked.B * 255 + 0.5)
        applyChrome(chH.r, chH.g, chH.b)
    end

    -- превью + hex справа (та же раскладка, что у accent -> ровно, без съезда)
    rrect(cpvX, csqY, cpvW, 44, Color3.fromRGB(chH.r, chH.g, chH.b), 1, 9)
    rstroke(cpvX, csqY, cpvW, 44, COL.text, 0.16, 9, 1)
    local chex = string.format("#%02X%02X%02X", floor(chH.r), floor(chH.g), floor(chH.b))
    local chexOn = (chH.r * 0.299 + chH.g * 0.587 + chH.b * 0.114) > 150
    text(cpvX + cpvW * 0.5 - measure(chex, 12).X * 0.5, csqY + 15, 12,
        chexOn and COL.app or COL.text, chex, 1)

    -- пресеты-����вотчи под прев����
    for i, p in ipairs(ACCENTS) do
        local col = (i - 1) % perRow
        local rowi = floor((i - 1) / perRow)
        local ex = cpvX + col * (sw2 + 8)
        local ey = csqY + 56 + rowi * (sw2 + 8)
        local skey = "cust/chsw" .. i
        hit(skey, ex, ey, sw2, sw2)
        rrect(ex, ey, sw2, sw2, p.c, 1, 6)
        local sel = floor(chH.r) == floor(p.c.R * 255 + 0.5)
            and floor(chH.g) == floor(p.c.G * 255 + 0.5)
            and floor(chH.b) == floor(p.c.B * 255 + 0.5)
        if sel or Engine.isHover(skey) then
            rstroke(ex - 1.5, ey - 1.5, sw2 + 3, sw2 + 3, COL.text,
                sel and 0.9 or 0.4, 7, 1.5)
        end
        if Engine.clicked(skey) then
            chH.r, chH.g, chH.b = floor(p.c.R * 255 + 0.5),
                floor(p.c.G * 255 + 0.5), floor(p.c.B * 255 + 0.5)
            local h, s, v = p.c:ToHSV()
            cu.chromeHue, cu.chromeSat, cu.chromeVal = h, s, v
            applyChrome(chH.r, chH.g, chH.b)
            Engine.notify("Customization", p.name .. " window color applied", 2.5)
        end
    end
    y = y + p1bh + 16

    ------------------------------------------------------------------
    -- ПАНЕЛЬ 2: Interface Font (+ размер шрифта)
    ------------------------------------------------------------------
    local fBtnH = floorv(40 * gsc)
    -- высота слайдера Font Size через wideSliderH (может ��асти при узк��й ширине)
    local hFs = wideSliderH(w - 28, "Font Size", cu.fontScale, "x")
    local p2h = 48 + fBtnH + 16 + hFs + 12
    rrect(x, y, w, p2h, COL.panel, 0.96, M.cardR)
    iy = panel(x, y, w, 48, "Interface Font",
        "Family and global size, applied instantly.", "font")
    local fbw = (w - 28 - 3 * 10) / 4
    for i, fc in ipairs(FONT_CHOICES) do
        local fx = x + 14 + (i - 1) * (fbw + 10)
        local fkey = "cust/font" .. i
        local active = cu.fontIdx == i
        hit(fkey, fx, iy, fbw, fBtnH)
        local fs = stateOf(fkey)
        fs.hover = approach(fs.hover, Engine.isHover(fkey) and 1 or 0, dt, 16)
        if active then
            gradRect(fx, iy, fbw, fBtnH, COL.panel:Lerp(COL.cyan, 0.30),
                COL.panel:Lerp(COL.cyan, 0.05), 1, 8, 0)
            rstroke(fx, iy, fbw, fBtnH, COL.cyan, 0.45, 8, 1)
        else
            rrect(fx, iy, fbw, fBtnH, COL.inset, 0.5 + fs.hover * 0.2, 8)
        end
        -- ��мя рисуем ЭТИМ шрифтом -- сразу видно, как он выглядит
        local nm = fc.name
        local nmw = measure(nm, 12, fc.font).X
        text(fx + fbw * 0.5 - nmw * 0.5, iy + fBtnH * 0.5 - 8, 12,
            active and COL.text or COL.label, nm, active and 1 or 0.8, fc.font)
        if Engine.clicked(fkey) then
            cu.fontIdx = i
            applyFont(i)
        end
    end
    -- слайдер размера шрифта (0.85x..1.6x); THEME.scale множит весь текст
    local newScale = wideSlider("cust/fscale", x + 14, iy + fBtnH + 20, w - 28,
        "Font Size", cu.fontScale, 0.85, 1.6, "x", dt)
    if math.abs(newScale - cu.fontScale) > 1e-4 then
        cu.fontScale = newScale
        applyFontScale(newScale)
    end
    y = y + p2h + 16

    -- (Панель Notifications перенесена в таб UI Settings, п.9 -- убрана о��сюда,
    --  чтобы настройки тостов не дублировались, п.3.)

    ------------------------------------------------------------------
    -- ПАНЕЛЬ 4: Background (DI-градиент: текстура + shimmer + opacity)
    ------------------------------------------------------------------
    local modeBtnH = floorv(38 * gsc)
    -- Высоты трёх слайдеров считаем ЗАРАНЕЕ через wideSliderH (у него значение
    -- может уходить под подпись при узкой ширине) -> панель точно вмещает их при
    -- любом скейле, слайдеры не наезжают. Слайдеры: Shimmer, Gradient Opacity,
    -- Content Opacity.
    local sw = w - 28
    local hSh = wideSliderH(sw, "Shimmer", cu.gradShimmer, "")
    local hGa = wideSliderH(sw, "Gradient Opacity", cu.gradAlpha, "")
    local hCo = wideSliderH(sw, "Content Opacity", cu.contentOpacity or 1, "")
    local p4h = 48 + 12 + modeBtnH + 16 + hSh + hGa + hCo + 4
    rrect(x, y, w, p4h, COL.panel, 0.96, M.cardR)
    iy = panel(x, y, w, 48, "Background",
        "Animated translucent field behind the content.", "image")

    -- выбор текстуры/движения
    local tRowY = iy
    local GMODES = { "None", "Bloom", "Aurora", "Sweep", "Pulse" }
    local gbw = (w - 28 - 4 * 10) / 5
    for i, nm in ipairs(GMODES) do
        local gx = x + 14 + (i - 1) * (gbw + 10)
        local gkey = "cust/gmode" .. i
        local active = cu.gradMode == (i - 1)
        hit(gkey, gx, tRowY, gbw, modeBtnH)
        local gs = stateOf(gkey)
        gs.hover = approach(gs.hover, Engine.isHover(gkey) and 1 or 0, dt, 16)
        if active then
            gradRect(gx, tRowY, gbw, modeBtnH, COL.panel:Lerp(COL.cyan, 0.30),
                COL.panel:Lerp(COL.cyan, 0.05), 1, 8, 0)
            rstroke(gx, tRowY, gbw, modeBtnH, COL.cyan, 0.45, 8, 1)
        else
            rrect(gx, tRowY, gbw, modeBtnH, COL.inset, 0.5 + gs.hover * 0.2, 8)
        end
        local nmw = measure(nm, 11.5).X
        text(gx + gbw * 0.5 - nmw * 0.5, tRowY + modeBtnH * 0.5 - 7, 11.5,
            active and COL.text or COL.label, nm, active and 1 or 0.85)
        if Engine.clicked(gkey) then
            cu.gradMode = i - 1
            Engine.setGradientConfig(nil, cu.gradMode, nil)
        end
    end

    -- Три слайдера подряд, вертикальный шаг = реальная высота каждого (wideSliderH).
    -- DI читает cu.* вживую каждый кадр -> слайдеры мгновенные, без пересборки.
    local slX = x + 14
    local shY = tRowY + modeBtnH + 20

    -- Shimmer -- сила перелива градиента.
    local gsh = wideSlider("cust/gshim", slX, shY, sw, "Shimmer", cu.gradShimmer, 0, 1.5, "", dt)
    if math.abs(gsh - cu.gradShimmer) > 1e-4 then cu.gradShimmer = gsh end

    -- Gradient Opacity -- ЯРКОСТЬ бликов-градиента (не путать с прозрачностью фона).
    local gaY = shY + hSh
    local ga = wideSlider("cust/galpha", slX, gaY, sw, "Gradient Opacity", cu.gradAlpha, 0.05, 1.0, "", dt)
    if math.abs(ga - cu.gradAlpha) > 1e-4 then cu.gradAlpha = ga end

    -- Content Opacity -- ОТДЕЛЬНАЯ настройка: непрозрачность всего фона контента.
    -- <1 -> сквозь UI просвечивает игра (жалоба «Opacity влиял лишь на градиент»).
    local coY = gaY + hGa
    local co = wideSlider("cust/copacity", slX, coY, sw, "Content Opacity",
        cu.contentOpacity or 1, 0.1, 1.0, "", dt)
    if math.abs(co - (cu.contentOpacity or 1)) > 1e-4 then
        cu.contentOpacity = co
        Engine.contentOpacity = co
    end
    y = y + p4h + 16

    -- ��озвращаем нижнюю кромку С учётом смещения скролла (как ветка карточек):
    -- корневой ра����чё�� contentH с��м вычита��т (fy - scrollY), и scrollY сокращается.
    return y
end

----------------------------------------------------------------------------
-- СТРАНИЦА CONFIGS (п.8): менеджер конфигов со списком, [ACTIVE], Load, Delete
----------------------------------------------------------------------------
-- Полностраничный сп��сок по референсу: шапка «Configs Manager» + поле ��мени +
-- Save Config, ниже -- строки с именем файла, метк��й [ACTIVE] у загруженн��го и
-- кнопка��и Load / Delete. Данные берём из живого Nova API (RefreshConfigList /
-- activeConfig). Использует те же local-хелперы (rrect/text/hit/clicked), что и
-- customPage, поэтому визуально совпадает с остальным UI. Строится каждый кадр.
local cfgName = { state = { text = "" }, hitKey = "cfg/name", settings = {} }

-- Детерминированная иконка по имени конфига -> спи��ок выглядит разнообразно, но
-- у одного и того же конфига иконка не «прыгает» между кадрами. Берём только
-- иконки, реально существующие в набор�� (nova_icons.lua).
local CFG_ICONS = { "Save", "Sword", "Crosshair", "Target", "Glow",
                    "Droplet", "Bolt", "Gear", "Image", "Layout", "Eye" }
local function configIcon(name)
    local h = 0
    for i = 1, #name do h = (h * 31 + name:byte(i)) % 2147483647 end
    return CFG_ICONS[(h % #CFG_ICONS) + 1]
end

local function configPage(cx, fy, cw, dt)
    local Nova = Engine.Nova
    local x = cx + M.pad
    local w = cw - M.pad * 2
    local y = fy - app.scrollY + M.pad

    local list = Nova:RefreshConfigList()

    -- ── ГЕРОЙ-ШАПКА (п.4): градиентная панель с иконкой-бейджем, заголовком,
    -- счётчиком конфигов и к��асивой строкой ввода/сохранения ──
    local headH = 126
    -- гр��диентная подложка (��кцент вверх�� -> па��ель вн��зу)
    Engine.gradRect(x, y, w, headH, COL.panel:Lerp(COL.cyan, 0.16),
        COL.panel, 0.98, M.cardR, 0)
    rstroke(x, y, w, headH, COL.cyan, 0.12, M.cardR, 1)

    -- иконка-б��йдж (папка) в скруглённ��м ква��рате
    local bsz = 42
    rrect(x + 16, y + 16, bsz, bsz, COL.cyan, 0.16, 12)
    rstroke(x + 16, y + 16, bsz, bsz, COL.cyan, 0.4, 12, 1)
    icon("folder", x + 16 + bsz * 0.5, y + 16 + bsz * 0.5, 20, COL.cyan, 0.95)

    text(x + 70, y + 20, 16, COL.text, "Configs Manager", 1)
    text(x + 70, y + 42, 10.5, COL.faint, "Save, load and manage your presets", 0.9)
    -- счётч��к-пилюля справа
    local cnt = #list .. (#list == 1 and " config" or " configs")
    local cntw = measure(cnt, 10).X
    rrect(x + w - cntw - 34, y + 22, cntw + 20, 22, COL.cyan, 0.14, 11)
    text(x + w - cntw - 24, y + 27, 10, COL.cyan, cnt, 0.95)

    -- ��оле имени
    local inW = w - 32 - 148
    local inX, inY = x + 16, y + 74
    hit("cfg/name", inX, inY, inW, 38, Z.BODY)
    local focused = Engine.textFocus == cfgName
    if Engine.clicked("cfg/name") then
        Engine.textFocus = focused and nil or cfgName
    end
    rrect(inX, inY, inW, 38, COL.search, 1, 9)
    rstroke(inX, inY, inW, 38, COL.cyan, focused and 0.5 or 0.06, 9, 1)
    icon("folder", inX + 16, inY + 19, 12, focused and COL.cyan or COL.dim, 0.7)
    local caret = focused and (math.floor(os.clock() * 2) % 2 == 0 and "|" or "") or ""
    if cfgName.state.text ~= "" then
        text(inX + 30, inY + 12, 12, COL.text, cfgName.state.text .. caret, 1)
    else
        text(inX + 30, inY + 12, 12, COL.dim, focused and caret or "Config name...", 0.6)
    end

    -- кнопка Save Config (акцентная, с иконкой)
    local sbX, sbW = inX + inW + 12, 136
    hit("cfg/save", sbX, inY, sbW, 38, Z.BODY)
    local shov = stateOf("cfg/save")
    shov.hover = approach(shov.hover, Engine.isHover("cfg/save") and 1 or 0, dt, 16)
    Engine.gradRect(sbX, inY, sbW, 38, COL.cyan,
        COL.cyan:Lerp(Color3.new(0,0,0), 0.15), 0.9 + shov.hover * 0.1, 9, 0)
    icon("check", sbX + 22, inY + 19, 13, COL.app, 0.95)
    local slbl = "Save Config"
    local slw = measure(slbl, 12, Fonts.Plex).X
    text(sbX + 34 + (sbW - 34) * 0.5 - slw * 0.5, inY + 12, 12, COL.app, slbl, 1)
    if Engine.clicked("cfg/save") then
        local nm = cfgName.state.text
        if nm ~= "" then
            Nova:SaveConfig(nm)
            Nova.activeConfig = nm
            Engine.notify("Configs", "Saved " .. nm, 2)
        end
    end

    y = y + headH + 14

    -- ── КАРТА «SAVE LOCATION» (раньше путь б��л просто брошен текстом в шапку) ──
    do
        local lh = 40
        rrect(x, y, w, lh, COL.panel, 0.85, 10)
        rstroke(x, y, w, lh, COL.cyan, 0.06, 10, 1)
        rrect(x + 10, y + lh * 0.5 - 13, 26, 26, COL.cyan, 0.14, 8)
        icon("folder", x + 10 + 13, y + lh * 0.5, 13, COL.cyan, 0.9)
        text(x + 46, y + 8, 9, COL.faint, "SAVE LOCATION", 0.75)
        text(x + 46, y + 21, 11, COL.text, Nova:GetFolderPath() .. "/", 0.95, Fonts.Monospace)
        y = y + lh + 12
    end

    -- ── НАСТРОЙКИ МЕНЕДЖЕРА (крупные строки-переключатели) ──
    -- Крупная строка: ��аголовок + описание слева, большой (мобилопригодный) свитч
    -- справа. Кликабельна ВСЯ строка. Тултип с расширенным пояснением на ховере.
    -- Возвращает НОВОЕ зна��ение (коррек��ный toggle -- прежний and/or-тернар не мог
    -- переключить из true в false, отсюда «тумблеры не работают»).
    local function settingRow(sy, title, desc, value, tkey, tip)
        local rh = 54                       -- выше -> описание не жмётся к заголовку
        hit(tkey, x, sy, w, rh, Z.CONTENT)
        local st2 = stateOf(tkey)
        local hov = Engine.isHover(tkey)
        st2.hover = approach(st2.hover, hov and 1 or 0, dt, 14)
        st2.on = approach(st2.on, value and 1 or 0, dt, 16)
        rrect(x, sy, w, rh, COL.panel, 0.88 + st2.hover * 0.08, 10)
        rstroke(x, sy, w, rh, COL.cyan, 0.05 + st2.on * 0.22, 10, 1)
        -- заголовок крупнее, описание ЗА��ЕТНО крупнее и контрастне�� (было 9.5/faint
        -- 0.8 -> «плохо видно»). Оставляем место справа под свитч (не залазим).
        text(x + 14, sy + 10, 13, value and COL.text or COL.label, title, 1)
        text(x + 14, sy + 30, 11, COL.dim, desc, 0.95)
        -- большой свитч
        local sw2, sh2 = 46, 24
        local swx, swy = x + w - sw2 - 14, sy + rh * 0.5 - sh2 * 0.5
        rrect(swx, swy, sw2, sh2, COL.inset:Lerp(COL.cyan, st2.on * 0.75), 1, sh2 * 0.5)
        rstroke(swx, swy, sw2, sh2, COL.cyan, 0.14 + st2.on * 0.3, sh2 * 0.5, 1)
        local knr = sh2 - 6
        local kn = swx + 3 + (sw2 - knr - 6) * st2.on
        rrect(kn, swy + 3, knr, knr, COL.text, 0.95, knr * 0.5)
        if hov and tip then Engine.setTooltip(tip) end
        if Engine.clicked(tkey) then return not value end
        return value
    end

    local n1 = settingRow(y, "Save UI theme",
        "Store colors, fonts, gradient & scale in the config", Nova:GetSaveUI(),
        "cfg/set/saveui", "When on, saving also writes the current appearance so loading restores it.")
    if n1 ~= Nova:GetSaveUI() then Nova:SetSaveUI(n1) end
    y = y + 54 + 8

    local n2 = settingRow(y, "Apply UI on load",
        "Restore saved appearance when a config is loaded", Nova:GetApplyUIOnLoad(),
        "cfg/set/applyui", "Turn off to load only feature values and keep your current look.")
    if n2 ~= Nova:GetApplyUIOnLoad() then Nova:SetApplyUIOnLoad(n2) end
    y = y + 54 + 8

    -- Игнор масштабных ключей кон��ига: защищает подобранный под экран/устройство
    -- масштаб от перезаписи чужим (desktop) конфигом. По умолчанию ВКЛ на мобиле.
    local nSc = settingRow(y, "Keep my scale",
        "Ignore UI/Text/Notify scale stored in configs", Nova:GetIgnoreConfigScale(),
        "cfg/set/ignorescale", "Recommended on phones: loading a config won't shrink or blow up the UI to a desktop scale.")
    if nSc ~= Nova:GetIgnoreConfigScale() then Nova:SetIgnoreConfigScale(nSc) end
    y = y + 54 + 8

    local n3 = settingRow(y, "AutoLoad on startup",
        "Load the AUTO-marked config automatically next launch", Nova:GetAutoLoadEnabled(),
        "cfg/set/autoload", "Uses the config you mark with the power icon below.")
    if n3 ~= Nova:GetAutoLoadEnabled() then Nova:SetAutoLoadEnabled(n3) end
    y = y + 54 + 8

    -- Авто-сохранение AUTO-конфига + его область (UI only / Everything) сегментом.
    local n4 = settingRow(y, "Auto-save changes",
        "Continuously save changes into the AUTO config", Nova:GetAutoSave(),
        "cfg/set/autosave", "When on, edits are written to the AUTO-marked config as you make them.")
    if n4 ~= Nova:GetAutoSave() then Nova:SetAutoSave(n4) end
    y = y + 54 + 8

    do  -- сегмент области авто-сохранения
        local rh = 40
        rrect(x, y, w, rh, COL.panel, 0.85, 10)
        text(x + 14, y + rh * 0.5 - 6, 11.5, COL.label, "Auto-save scope", 1)
        local segW, segH = 190, 26
        local segX, segY = x + w - segW - 12, y + rh * 0.5 - segH * 0.5
        rrect(segX, segY, segW, segH, COL.inset, 0.8, 8)
        local scope = Nova:GetAutoSaveScope()
        local opts = { { id = "ui", lbl = "UI only" }, { id = "all", lbl = "Everything" } }
        local hw = segW / 2
        for i, o in ipairs(opts) do
            local ox = segX + (i - 1) * hw
            local sel = (scope == o.id)
            local sk = "cfg/scope/" .. o.id
            hit(sk, ox, segY, hw, segH, Z.CONTENT)
            if sel then rrect(ox + 2, segY + 2, hw - 4, segH - 4, COL.cyan, 0.85, 6) end
            local lw = measure(o.lbl, 10.5).X
            text(ox + hw * 0.5 - lw * 0.5, segY + segH * 0.5 - 6, 10.5,
                sel and COL.app or COL.dim, o.lbl, 1)
            if Engine.clicked(sk) then Nova:SetAutoSaveScope(o.id) end
        end
        y = y + rh + 12
    end

    -- ── Список конфигов ──
    if #list == 0 then
        -- Пустое состояние: иконка + два центрированных текста, вертикально
        -- сбалансированы (иконка / заголовок / подсказка равномерно по высоте).
        local eh = 110
        rrect(x, y, w, eh, COL.panel, 0.55, M.cardR)
        rstroke(x, y, w, eh, COL.cyan, 0.06, M.cardR, 1)
        local cxm = x + w * 0.5
        rrect(cxm - 20, y + 16, 40, 40, COL.cyan, 0.1, 12)
        icon("folder", cxm, y + 36, 20, COL.dim, 0.7)
        local ph = "No saved configs yet"
        text(cxm - measure(ph, 12).X * 0.5, y + 64, 12, COL.label, ph, 0.9)
        local ph2 = "Type a name above and hit Save Config"
        text(cxm - measure(ph2, 10).X * 0.5, y + 84, 10, COL.faint, ph2, 0.7)
        y = y + eh
    else
        local rowH = 56
        for _, name in ipairs(list) do
            local active = (Nova.activeConfig == name)
            local rkey = "cfg/row/" .. name
            hit(rkey, x, y, w, rowH, Z.BODY)     -- ловим ховер для подсветки
            local rh = stateOf(rkey)
            rh.hover = approach(rh.hover, Engine.isHover(rkey) and 1 or 0, dt, 14)

            -- фон ряда: активный ярче + акцентная кромка, ховер чуть подсвечивает
            rrect(x, y, w, rowH, COL.panel, (active and 0.98 or 0.88) + rh.hover * 0.08, M.cardR)
            if active then
                -- активный маркируем ТОЛЬКО акцентной обводкой (риску слева убрали:
                -- вместе с обводкой давала «полоску слева», выглядело лишним).
                rstroke(x, y, w, rowH, COL.cyan, 0.6, M.cardR, 1.4)
            end

            -- иконка-бейдж файла: РАЗНАЯ для каждого конфига (детерминированно по
            -- имени) -> список не выглядит монотонным «одна и та же иконка».
            local bsz = 34
            local bx, by = x + 16, y + rowH * 0.5 - bsz * 0.5
            rrect(bx, by, bsz, bsz, active and COL.cyan or COL.inset, active and 0.16 or 0.6, 9)
            icon(configIcon(name), bx + bsz * 0.5, by + bsz * 0.5, 15,
                active and COL.cyan or COL.dim, 0.9)

            -- имя + подпись + бейджи (ACTIVE / AUTO / UI)
            local tx = bx + bsz + 12
            text(tx, y + rowH * 0.5 - 13, 13, COL.text, name, 1)
            text(tx, y + rowH * 0.5 + 3, 9.5, COL.faint, name .. ".json", 0.7)
            -- ряд бейджей справа от имени. КРОМКА = осветлённый тон (не тёмная
            -- линия): раньше рамка была плотнее заливки -> читалась тёмным контуром
            -- вокруг светлого фона («края темн��е градиента»). Теперь край-блик.
            local badgeX = tx + measure(name, 13).X + 10
            -- Бейджи КРУПНЕЕ (текст 9->11, выс��та 15->19) -- раньше «тупо не видно».
            -- Текст центрируем по высоте бейджа через measure().Y, а не magic +3.
            local function badge(lbl, col)
                local fs = 11
                local bh = 19
                local tsz = measure(lbl, fs)
                local bw = tsz.X + 16
                local by0 = y + rowH * 0.5 - bh * 0.5
                rrect(badgeX, by0, bw, bh, col, 0.22, 8)
                rstroke(badgeX, by0, bw, bh, col:Lerp(COL.text, 0.45), 0.3, 8, 1)
                text(badgeX + 8, by0 + bh * 0.5 - tsz.Y * 0.5, fs, col:Lerp(COL.text, 0.3), lbl, 1)
                badgeX = badgeX + bw + 6
            end
            if active then badge("ACTIVE", COL.cyan) end
            if Nova:GetAutoLoad() == name then badge("AUTO", COL.warn or COL.cyan) end
            -- метка «меняет UI» -> конфиг содержит тему
            if Nova:ConfigHasUI(name) then badge("UI", COL.mag or COL.cyan) end

            -- Кнопки справа: [Delete][Load] + квадратные [AutoLoad][Overwrite].
            local delW, ldW, gap, sq = 82, 74, 8, 30
            local delX = x + w - 14 - delW
            local ldX = delX - gap - ldW
            local ovX = ldX - gap - sq            -- Overwrite (перез��пись)
            local alX = ovX - gap - sq            -- AutoLoad (сделать авто��агрузкой)
            local btnY, btnH = y + rowH * 0.5 - 15, 30
            local dkey, lkey = "cfg/del/" .. name, "cfg/load/" .. name
            local okey, akey = "cfg/ovr/" .. name, "cfg/auto/" .. name

            -- квадратная кнопка-иконка (хелпер) + тултип на ховере
            local function sqBtn(sx, ic, col, sk, active2, tip)
                hit(sk, sx, btnY, sq, btnH, Z.CONTENT)
                local h2 = stateOf(sk)
                local hv = Engine.isHover(sk)
                h2.hover = approach(h2.hover, hv and 1 or 0, dt, 16)
                -- активная кнопка (нап��. текущий AUTO) заполнена ярче, чем «покоя»
                local baseF = active2 and 0.28 or 0.1
                rrect(sx, btnY, sq, btnH, col, baseF + h2.hover * 0.2, 8)
                rstroke(sx, btnY, sq, btnH, col:Lerp(COL.text, 0.4),
                    0.22 + h2.hover * 0.28, 8, 1)
                icon(ic, sx + sq * 0.5, btnY + btnH * 0.5, 13, col, 0.95)
                if hv and tip then Engine.setTooltip(tip) end
                return Engine.clicked(sk)
            end

            -- AutoLoad: назначить конфиг автозагружаемым ИЛИ снять (toggle).
            -- РАНЬШЕ было `isAuto and nil or name` -> классическая Lua-лову��ка:
            -- при isAuto=true это ВСЕГДА возвращало name (never nil), поэтому AUTO
            -- нельзя было выключить и кнопка «мигала». Теперь явный if.
            local isAuto = (Nova:GetAutoLoad() == name)
            local aCol = isAuto and (COL.warn or COL.cyan) or COL.dim
            if sqBtn(alX, "power", aCol, akey, isAuto,
                    isAuto and "Clear AutoLoad" or "Set as AutoLoad config") then
                if isAuto then Nova:SetAutoLoad(nil) else Nova:SetAutoLoad(name) end
                Engine.notify("Configs", isAuto and "AutoLoad cleared"
                    or ("AutoLoad: " .. name), 2)
            end
            -- Overwrite: перезаписать существующий конфиг текущими настройками
            if sqBtn(ovX, "save", COL.cyan, okey, false, "Overwrite with current settings") then
                Nova:OverwriteConfig(name)   -- сам обновляет кэш меты
                Engine.notify("Configs", "Overwritten " .. name, 2)
            end

            hit(lkey, ldX, btnY, ldW, btnH, Z.CONTENT)
            local lh = stateOf(lkey)
            lh.hover = approach(lh.hover, Engine.isHover(lkey) and 1 or 0, dt, 16)
            rrect(ldX, btnY, ldW, btnH, COL.cyan, (active and 0.14 or 0.1) + lh.hover * 0.18, 8)
            rstroke(ldX, btnY, ldW, btnH, COL.cyan, 0.3 + lh.hover * 0.3, 8, 1)
            icon("download", ldX + 16, btnY + btnH * 0.5, 12, COL.cyan, 0.95)
            text(ldX + 30, btnY + btnH * 0.5 - 6, 11.5, COL.cyan, "Load", 1)
            if Engine.clicked(lkey) then
                local ok = Nova:LoadConfig(name)
                Engine.notify("Configs", ok and ("Loaded " .. name) or "Load failed", 2)
            end

            hit(dkey, delX, btnY, delW, btnH, Z.CONTENT)
            local dh = stateOf(dkey)
            dh.hover = approach(dh.hover, Engine.isHover(dkey) and 1 or 0, dt, 16)
            rrect(delX, btnY, delW, btnH, COL.danger, 0.16 + dh.hover * 0.22, 8)
            rstroke(delX, btnY, delW, btnH, COL.danger, 0.3 + dh.hover * 0.3, 8, 1)
            icon("trash", delX + 16, btnY + btnH * 0.5, 12, COL.danger, 0.95)
            text(delX + 30, btnY + btnH * 0.5 - 6, 11.5, COL.danger, "Delete", 1)
            if Engine.clicked(dkey) then
                Nova:DeleteConfig(name)
                Engine.notify("Configs", "Deleted " .. name, 2)
            end

            y = y + rowH + 8
        end
    end

    return y
end

----------------------------------------------------------------------------
-- BUILDER API (MacLib-совместимый) + retained-модель + рендер модели
----------------------------------------------------------------------------
-- Nova -- immediate-mode движок, а MacLib -- retained (создал Instance -> ж��вёт).
-- Чтобы дать ТОТ ЖЕ порядок вызовов (Window/TabGroup/Tab/Section/э��ементы,
-- Settings+Flag, методы :Update.../:Get...), билдер строит retained-МОД��ЛЬ ��з
-- деск��ипторов, а рендер каждый к��др обходит её и рисует существующими
-- виджетами, ��авор��чивая ввод обратно в состояние и колбэки.

local Nova = { Flags = {} }
Engine.Nova = Nova

local model = { tabs = {}, hasBuilt = false, window = nil, activeTab = nil }
Engine.model = model

local _uid = 0
local function uid(p) _uid = _uid + 1; return (p or "el") .. _uid end

-- keycode -> символ для текстовых полей (буквы/цифры/пробе��).
local DIGIT = { Zero="0",One="1",Two="2",Three="3",Four="4",
    Five="5",Six="6",Seven="7",Eight="8",Nine="9",
    -- для ручного ввода в сл��йдер (п.13): точка, запятая и минус. Запятая н��жна
    -- для локалей, где десятичный разд��литель "," (парсер ниже конвертит в ".").
    Period=".", KeypadPeriod=".", Comma=",", Minus="-", KeypadMinus="-",
    KeypadZero="0",KeypadOne="1",KeypadTwo="2",KeypadThree="3",KeypadFour="4",
    KeypadFive="5",KeypadSix="6",KeypadSeven="7",KeypadEight="8",KeypadNine="9" }
local function keyChar(kc)
    local n = kc.Name
    if #n == 1 and n:match("%a") then
        local shift = UIS:IsKeyDown(Enum.KeyCode.LeftShift)
            or UIS:IsKeyDown(Enum.KeyCode.RightShift)
        return shift and n or n:lower()
    end
    return DIGIT[n]
end

-- Фокус текстового поля + маршрутизация клавиш из клавиатурного хука.
Engine.textFocus = nil
-- Состоян��е авто-повтора Backspace (зажатие). Универсально: основано на опросе
-- «клавиша зажата» в рендер-лупе, а не на OS-key-repeat -> работает одинаково для
-- всех экзекуторов и способов ввода.
local _bkHeld = false      -- была ли backspace зажата в прошлом кадре
local _bkTimer = 0         -- накопитель времени зажатия
local BK_DELAY = 0.35      -- задержка до старта а��то-повтора, сек
local BK_RATE = 0.035      -- интерва�� между удалениями при зажатии, сек

local function deleteBack(el)
    if #el.state.text > 0 then
        el.state.text = el.state.text:sub(1, -2)
        if el.settings.OnChanged then pcall(el.settings.OnChanged, el.state.text) end
        return true
    end
    return false
end

function Engine.onKey(kc)
    local f = Engine.textFocus
    if not f then return end
    local el = f
    if kc == Enum.KeyCode.Backspace then
        deleteBack(el)
        -- сброс таймера -> первое удаление сразу, авто-повтор ��ерез BK_DELAY
        _bkHeld = true
        _bkTimer = 0
        return
    elseif kc == Enum.KeyCode.Return then
        Engine.textFocus = nil
        if el.settings.Callback then pcall(el.settings.Callback, el.state.text) end
        return
    elseif kc == Enum.KeyCode.Space then
        el.state.text = el.state.text .. " "
    else
        local ch = keyChar(kc)
        if ch then el.state.text = el.state.text .. ch end
    end
    if el.settings.OnChanged then pcall(el.settings.OnChanged, el.state.text) end
end

-- Вызывается каждый кадр (bodyPaint). Реализ��ет авто-повтор Backspace при
-- зажа��ии: держим -> после BK_DELAY удаляем по одному символу каждые BK_RATE.
-- Опр��с keysDown делает поведение универсальным (в ��.ч. для мобильных/сенсорных
-- клавиатур, к��торые держат состояние клавиши).
function Engine.updateTextRepeat(dt)
    local el = Engine.textFocus
    local down = el ~= nil and UIS:IsKeyDown(Enum.KeyCode.Backspace)
    if not down then
        _bkHeld = false
        _bkTimer = 0
        return
    end
    _bkTimer = _bkTimer + (dt or 0.016)
    if _bkTimer >= BK_DELAY then
        -- в фазе авто-повт��ра: удаляем с частотой BK_RATE (может >1 за кадр при лагах)
        while _bkTimer >= BK_DELAY + BK_RATE do
            if not deleteBack(el) then break end
            _bkTimer = _bkTimer - BK_RATE
        end
    end
end

-- keybind: имя клавиши коротко (RightControl -> RCtrl и т.п.).
local KEYSHORT = { RightControl="RCtrl", LeftControl="LCtrl", RightShift="RShift",
    LeftShift="LShift", RightAlt="RAlt", LeftAlt="LAlt", Return="Enter",
    Backspace="Bksp", Unknown="None" }
local function keyName(kc)
    if not kc then return "None" end
    return KEYSHORT[kc.Name] or kc.Name
end

-- Оповещение биндов о нажат��и (Engine.onKey уже дергается хуком; сюда шлём из
-- keyListener-ветки только текст, а биндовые колбэки держ��м отдельным списком).
-- keybind registry is owned by Engine so the inline UI chunk shares the same table.
local baseOnKey = Engine.onKey
local function keybindAllowed(s, kc)
    local list = s and s.Blacklist
    if type(list) ~= "table" then return true end
    for _, bad in ipairs(list) do
        if bad == kc or (typeof(bad) == "EnumItem" and bad.Name == kc.Name) then
            return false
        end
    end
    return true
end
Engine.onKey = function(kc)
    baseOnKey(kc)
    if Engine.textFocus then return end
    for _, el in ipairs(Engine.keybindEls or {}) do
        local s = el.settings
        local bound = el.state.key
        local same = bound == kc or (bound and kc and bound.Name == kc.Name)
        if same and keybindAllowed(s, kc) and s.Callback then
            pcall(s.Callback, kc)
        end
    end
end
Engine.onDraw(function(dt)
    if Engine.textFocus then return end
    for _, el in ipairs(Engine.keybindEls or {}) do
        local s, kc = el.settings, el.state.key
        if kc and Engine.input and Engine.input.keysDown[kc]
            and keybindAllowed(s, kc) and s.onBindHeld then
            el._held = true
            pcall(s.onBindHeld, true, kc, dt or 0.016)
        elseif el._held then
            el._held = false
            if s.onBindHeld then pcall(s.onBindHeld, false, kc, 0) end
        end
    end
end)

