-- МОБИЛЬНЫЕ ПЛАВАЮЩИЕ ���НОПКИ (Mobile Button + Keybind FAB)
----------------------------------------------------------------------------
-- Плавающая «пилюля» открывает/закрывает меню (центр-сверху, перетаскиваемая), и
-- по одному FAB на каждый Keybind, которому включили показ («+» в строке бинда).
-- Рисуются на сло�� Z.MOBILE (НЕ гейтится Engine.visible) -> видны и при закрытом
-- окне, иначе на ��обиле мен��� нечем открыть. Свой tap/drag поверх Engine.input.
local minput = Engine.input
local mob = { st = {}, dragOwner = nil, pos = {}, toggleAnim = 0 }
Engine.mobileState = mob

-- Показывать ли плавающие кнопки: nil -> авто по устройству; true/false -> форс.
local function mobileEnabled()
    local v = app.custom.mobileBtn
    if v == nil then return Engine.isMobile() end
    return v and true or false
end
Engine.mobileEnabled = mobileEnabled
local function resetMobilePos() mob.pos = {} end
Engine.resetMobilePos = resetMobilePos

-- tap/drag одной кнопки. Возвращает tapped(bool) + state (для анима��ии нажатия).
-- Порог 40px^2 отделяет тап от перетаскивани�� -> случайный сдвиг не считается тапом.
local function fabInput(id, x, y, w, h, mode)
    -- mode: "tap" -> без перетаскивания (Mobile Button); "holddrag" -> тап = нажатие,
    -- удержание ~0.16с включает перетаскивание (Mobile Keybind); nil/"drag" -> тащим
    -- сразу при сдвиге. Возвращает tapped(bool) + state.
    mode = mode or "drag"
    local m = minput.mouse
    local st = mob.st[id]; if not st then st = {}; mob.st[id] = st end
    local inside = m and m.X >= x and m.X <= x + w and m.Y >= y and m.Y <= y + h
    if minput.justPressed and inside and not mob.dragOwner then
        mob.dragOwner = id
        st.gx, st.gy = m.X - x, m.Y - y
        st.px, st.py = m.X, m.Y
        st.moved = false
        st.hold = 0
        st.armed = false
        -- Тот же тап синхронно прошёл через pick() и мог «схватить» контрол окна под
        -- кнопкой (если пилюля/FAB наложились на окно). Отпускаем его -> нет двойной
        -- реакции (кнопка + слайдер под ней).
        minput.activeKey = nil
    end
    local tapped = false
    if mob.dragOwner == id then
        if m then
            local dx, dy = m.X - st.px, m.Y - st.py
            if dx * dx + dy * dy > 64 then st.moved = true end
            st.hold = (st.hold or 0) + (Engine.dt or 0.016)
            -- решаем, «вооружён» ли drag
            if mode == "tap" then
                st.armed = false
            elseif mode == "holddrag" then
                -- перетаскивание включается ТОЛЬКО после удержания -> короткий тап
                -- всегда остаётся нажатием, даже если палец чуть дёрнулся.
                if (st.hold or 0) >= 0.16 then st.armed = true end
            else
                if st.moved then st.armed = true end
            end
            if st.armed then
                -- мутируем существующую таблицу (не аллоцируем новую каждый кадр)
                local p = mob.pos[id]
                if p then p.x, p.y = m.X - st.gx, m.Y - st.gy
                else mob.pos[id] = { x = m.X - st.gx, y = m.Y - st.gy } end
            end
        end
        if minput.released or not minput.down then
            -- тап засчитываем, если drag не активировался и палец почти не двигался
            if not st.armed and not st.moved then tapped = true; st.pop = 1 end
            mob.dragOwner = nil
            st.hold = 0
        end
    end
    st.press = approach(st.press or 0, (mob.dragOwner == id) and 1 or 0, Engine.dt or 0.016, 20)
    -- «захвачено» (для подсветки, что кнопка перешла в режим перетаскивания)
    st.grab = approach(st.grab or 0, (st.armed and mob.dragOwner == id) and 1 or 0, Engine.dt or 0.016, 16)
    -- pop = одноразовый пружинный отскок после тапа (гаснет к 0) -> MacLib-bounce
    st.pop = approach(st.pop or 0, 0, Engine.dt or 0.016, 11)
    return tapped, st
end

-- Пружинные easing'и (MacLib-стиль): backOut даёт «отскок» в конце (overshoot).
local function backOut(t)
    if t <= 0 then return 0 end
    if t >= 1 then return 1 end
    local c1 = 1.70158; local c3 = c1 + 1; local u = t - 1
    return 1 + c3 * u * u * u + c1 * u * u
end
local function smooth01(t) return t * t * (3 - 2 * t) end

-- Плавно переливающий��я акцент (accentA<->accentB) на общих gradClock-часах ->
-- синхронно с остальными градиентами UI, скорость = Gradient Speed. phase сдвигает
-- фазу (разные элементы переливаются не в унисон). Да��е при одном акценте добавляем
-- лё��кий яркостный пульс, чтобы перелив был виден.
local function flowT(phase)
    local t = (Engine.gradClock and Engine.gradClock() or os.clock())
    return 0.5 + 0.5 * math.sin(t * 1.1 + (phase or 0))
end
local function flowAccent(phase)
    local a = Engine.accentA or COL.cyan
    local b = Engine.accentB or a
    local base = a:Lerp(b, flowT(phase))
    return base:Lerp(Color3.new(1, 1, 1), 0.10 * flowT((phase or 0) + 1.7))
end
-- Статический акцент (без перелива) -- когда градиент элемента выключен в Effects.
local function staticAccent() return Engine.accentA or COL.cyan end
-- Акцент мобильных кнопок (Mobile Button + keybind-FAB): перелив гейтится
-- Effects->Mobile Gradient. Выкл -> ровный accent A (одинаковые стопы = плоско).
local function fabAccent(phase)
    if app.custom.mobileGrad == false then return staticAccent() end
    return flowAccent(phase)
end
-- Акцент Keybind List HUD: перелив гейтится Effects->Keybind List Gradient.
local function kbAccent(phase)
    if app.custom.kbListGrad == false then return staticAccent() end
    return flowAccent(phase)
end

-- ── ДЕКОР-ХЕЛПЕРЫ моб��льных кнопок (общие для Button/FAB и превью) ────────────
-- Тонкая тех-сетка ВНУТРИ прямоугольника: отступ = радиус, чтобы линии не вылезали
-- за скруглённые углы (без clip-стека). Даёт «панель приборов», а не пустую заливку.
local function gridRect(x, y, w, h, r, col, op)
    if op <= 0.01 then return end
    local pad = math.max(2, r * 0.65)
    local gx, gy = x + pad, y + pad
    local gw, gh = w - pad * 2, h - pad * 2
    if gw <= 4 or gh <= 4 then return end
    local step = math.max(6, gw / 4)
    local vx = gx + step
    while vx < gx + gw - 0.5 do line(vx, gy, vx, gy + gh, col, op, 1); vx = vx + step end
    local vy = gy + step
    while vy < gy + gh - 0.5 do line(gx, vy, gx + gw, vy, col, op, 1); vy = vy + step end
end
-- Та же сетка, но обрезанная по КРУГУ (хорда: half = sqrt(R^2 - d^2)) -> заполняет
-- диск FAB ровными линиями без выхода за кромку. rg = радиус клипа (чуть меньше кольца).
local function gridCircle(cx, cy, rg, col, op)
    if op <= 0.01 or rg < 6 then return end
    local step = math.max(6, rg * 0.45)
    local d = -math.floor(rg / step) * step
    while d <= rg do
        local half = math.sqrt(math.max(0, rg * rg - d * d)) - 1
        if half > 1 then
            line(cx - half, cy + d, cx + half, cy + d, col, op, 1)  -- горизонталь
            line(cx + d, cy - half, cx + d, cy + half, col, op, 1)  -- верти��аль
        end
        d = d + step
    end
end
-- HUD-«уголки�� (L-скобки) по углам квадрата -> техно-акцент, кнопка не «пустая».
local function cornerBrackets(x, y, w, h, r, col, op)
    if op <= 0.01 then return end
    local m = math.max(3, r * 0.5)
    local len = math.max(5, w * 0.17)
    local t = 1.6
    local L = { { x + m, y + m, 1, 1 }, { x + w - m, y + m, -1, 1 },
                { x + m, y + h - m, 1, -1 }, { x + w - m, y + h - m, -1, -1 } }
    for _, c in ipairs(L) do
        local px, py, sx, sy = c[1], c[2], c[3], c[4]
        line(px, py, px + len * sx, py, col, op, t)
        line(px, py, px, py + len * sy, col, op, t)
    end
end
-- Подпись имени бинда -- «медаль-риббон»: компактный бейдж с переливающейся
-- гра��иент-заливкой (flowAccent), НАЛЕЗАЮЩИЙ на низ диска (как лент��чка на медали).
-- Тёмный текст на ярком градиенте -> высокий контраст, читается частью кнопки, а не
-- «просто слово рядом». Без коннектора/точки (прошлый вариант не нравился).
local function fabLabel(cx, discBottom, sc, alpha, name)
    local ns = 10 * sc
    local tw = measure(name, ns).X
    local padx = 9 * sc
    local pw = tw + padx * 2
    local ph = math.floor(18 * sc)
    local py = discBottom - ph * 0.42        -- налезает на диск снизу
    local px = cx - pw * 0.5
    -- тень-подложка бейджа
    rrect(px, py + 1, pw, ph, COL.app, 0.4 * alpha, ph * 0.5)
    -- переливающаяся градиент-заливка (плоская, если Mobile Gradient выключен)
    Engine.gradRect(px, py, pw, ph, fabAccent(0), fabAccent(1.4),
        0.95 * alpha, ph * 0.5, nil, nil, true)
    -- тёмный тек��т по центру (контраст на ярком ��радиенте)
    text(cx - tw * 0.5, py + ph * 0.5 - ns * 0.5, ns, COL.app, name, alpha)
end

-- ─��� MOBILE BUTTON (тумблер меню) ──────────────────────────���──────────────────
-- Новый дизайн (жалобы: пикселизация градиента, лишний текст «NOVA», «пилюля»):
-- компактная КВАДРАТНАЯ иконка-кнопка (squircle) БЕЗ подписей. Только нативные
-- rrect-заливки (гладкие скругления, без страйп-градиента = без пикселизации) +
-- один глиф-логотип, морфящий в «×» при открытом меню. Возвращает w,h (квадрат).
local function toggleSize(sc)
    local d = math.floor(52 * sc)
    return d, d
end
-- Новый корпус: квадратный «тех-модуль». БЕЗ верхней стеклянной плё��ки (жалоба на
-- «закруглённый прямоугольник сверху»), почти НЕПРОЗРАЧНЫЙ, с тонкой сеткой внутри,
-- HUD-уголками и акцент-кольцом. Нажатие = равномерный scale-down без искажен��й.
local function drawTogglePill(x, y, sc, alpha, openT, press)
    press, openT = press or 0, openT or 0
    local d = math.floor(52 * sc)
    local scl = 1 - 0.06 * press
    local bd = d * scl
    local cx, cy = x + d * 0.5, y + d * 0.5
    local bx, by = cx - bd * 0.5, cy - bd * 0.5
    local r = math.floor(bd * 0.28)
    local q = Engine.quality or 1
    local acc = (q >= 1) and fabAccent(0) or staticAccent()
    rrect(bx + 2, by + 4, bd, bd, COL.app, 0.4 * alpha, r)
    rrect(bx, by, bd, bd, COL.panel, 0.6 * alpha, r)
    rrect(bx, by, bd, bd, acc, 0.06 * alpha, r)
    if q >= 2 then
        gridRect(bx, by, bd, bd, r, acc, 0.12 * alpha)
    end
    if openT > 0.01 then rrect(bx, by, bd, bd, acc, 0.16 * openT * alpha, r) end
    if q >= 1 then
        cornerBrackets(bx, by, bd, bd, r, acc, (0.55 + 0.4 * openT + 0.35 * press) * alpha)
    end
    rstroke(bx, by, bd, bd, acc, (0.7 + 0.25 * press + 0.2 * openT) * alpha, r, 1.8)
    local gsz = math.floor(bd * 0.46)
    local a1, a2 = (1 - openT) * alpha, openT * alpha
    if a1 > 0.02 then drawIcon(Engine.logoIcon or "sparkles", cx - gsz * 0.5, cy - gsz * 0.5, gsz, acc, a1) end
    if a2 > 0.02 then drawIcon("close", cx - gsz * 0.5, cy - gsz * 0.5, gsz, acc, a2) end
    return d, d
end

-- ── MOBILE KEYBIND FAB ───────────────────────────────────────────────────────
-- Круглый д��ск действия. Изменения по фидбеку: КРУПНЕЕ (58 базовых), СВОЙ масштаб
-- (sc уже содержит keybindScale), БЕЗ текста эмулируемой клавиши и без иконки-
-- клавиатуры (мобиле не нужно зна��ь клавишу). В центре -- иконка бинда, а если её
-- нет -- монограмма (первая буква имени). Имя выводится пилюлей п��д диском.
-- Габарит = диаметр (квадрат для hit-теста), подпись в hit не входит.
local function keyFabSize(sc)
    local d = math.floor(66 * sc)
    return d, d
end
-- press=утоп(0..1), grab=перетаскивание(0..1), pop=пружина после тапа(0..1),
-- appear=пружина появления/исчезновения (backOut, может >1 на овершуте).
-- Дизайн: КРУПНЕЕ (66), плотный диск + тех-сетка (обрезана по кругу), двойное
-- акцент-кольцо, HUD-лейбл имени. Нажатие = ripple-кольцо, расходящееся наружу
-- (вместо простого «утопа») + короткая вспышка -> тап читается как настоящий клик.
local function drawKeyFab(x, y, sc, alpha, name, iconId, press, grab, pop, appear)
    press, grab, pop = press or 0, grab or 0, pop or 0
    appear = appear == nil and 1 or appear
    local d = math.floor(66 * sc)
    -- НОВАЯ анимация нажатия: bounce -- горб 0->1->0 по мере затухания pop (1->0),
    -- даёт пружинный «поп» (кнопка коротко подрастает и оседает), а не унылый утоп.
    local bounce = math.sin((1 - pop) * math.pi)
    local scl = appear * (1 + 0.14 * bounce - 0.05 * press) + grab * 0.05
    local bd = d * scl
    if alpha <= 0.01 or bd < 2 then return d, d end
    -- центр фиксирован -> масштабируем ВОКРУГ центра (пружина не «прыгает» позицией)
    local cx, cy = x + d * 0.5, y + d * 0.5
    local r = bd * 0.5
    local q = Engine.quality or 1
    local segs = Engine.ringSegs or 20
    local acc = (q >= 1) and fabAccent(0.6) or staticAccent()
    if bounce > 0.01 then
        disc(cx, cy, r * (1.05 + 0.35 * bounce), acc, 0.28 * bounce * alpha)
    end
    if grab > 0.01 then
        local pr = (4 + 2.5 * (0.5 + 0.5 * math.sin(os.clock() * 6))) * sc
        disc(cx, cy, r + pr, acc, 0.12 * grab * alpha)
    end
    disc(cx, cy + 2, r, COL.app, 0.4 * alpha)
    disc(cx, cy, r, COL.panel, 0.6 * alpha)
    disc(cx, cy, r, acc, 0.06 * alpha)
    if q >= 2 then
        gridCircle(cx, cy, r * 0.88, acc, 0.12 * alpha)
    end
    local flash = bounce * 0.16 + press * 0.1
    if flash > 0.01 then disc(cx, cy, r, acc, flash * alpha) end
    ring(cx, cy, r, acc, (0.75 + 0.2 * grab) * alpha, segs, 1.8)
    if q >= 2 then
        ring(cx, cy, r - 3, acc, 0.14 * alpha, segs, 1)
    end
    if iconId then
        local isz = bd * 0.42
        drawIcon(iconId, cx - isz * 0.5, cy - isz * 0.5, isz, COL.text, 0.98 * alpha)
    else
        local mono = (name and name ~= "") and name:sub(1, 1):upper() or "*"
        local msz = 22 * sc * scl
        local mw = measure(mono, msz).X
        text(cx - mw * 0.5, cy - msz * 0.55, msz, COL.text, mono, alpha)
    end
    -- бейдж-риббон имени, налезающий на низ ��иска. По умолчанию ВЫКЛ
    -- (app.custom.keybindFabLabels=false) -- включается в Mobile Buttons.
    if name and name ~= "" and appear > 0.4 and app.custom.keybindFabLabels then
        fabLabel(cx, cy + r, sc, alpha, name)
    end
    return d, d
end
Engine.drawTogglePillPreview = drawTogglePill   -- превью в UI Settings
Engine.drawKeyFabPreview = drawKeyFab
Engine.gridRect = gridRect                      -- фон-сетка превью

-- ЖИВОЙ мобильный слой (регистрируется в always-on Z.MOBILE).
local function drawMobileLayer(dt)
    if not mobileEnabled() then return end
    local vp = Engine.viewport()
    -- ДВА независимых масштаба: Mobile Button (mobileScale) и keybind-FAB (keybindScale).
    local scT = clamp((app.custom.mobileScale or 1) * (Engine.autoScaleFactor or 1), 0.6, 2.2)
    local scK = clamp((app.custom.keybindScale or 1) * (Engine.autoScaleFactor or 1), 0.55, 2.6)
    local alpha = clamp(app.custom.mobileOpacity or 1, 0.15, 1)
    mob.toggleAnim = approach(mob.toggleAnim, Engine.visible and 1 or 0, dt, 14)

    -- Mobile Button: дефолт центр-сверху; кламп в экран (не потерять за краем).
    local tw, th = toggleSize(scT)
    if Engine.sheet then
        mob.pos.toggle = mob.pos.toggle or {}
        mob.pos.toggle.x = vp.X * 0.5 - tw * 0.5
        mob.pos.toggle.y = vp.Y - th - 20
    elseif not mob.pos.toggle then
        mob.pos.toggle = { x = vp.X * 0.5 - tw * 0.5, y = math.floor(vp.Y * 0.05) }
    end
    mob.pos.toggle.x = clamp(mob.pos.toggle.x, 4, math.max(4, vp.X - tw - 4))
    mob.pos.toggle.y = clamp(mob.pos.toggle.y, 4, math.max(4, vp.Y - th - 4))
    local tx, ty = mob.pos.toggle.x, mob.pos.toggle.y
    -- Mobile Button = БЕЗ перетаскивания (mode="tap"): всегда фиксирован сверху-центр.
    local tapped, tst = fabInput("toggle", tx, ty, tw, th, "tap")
    if tapped then Engine.toggle() end
    drawTogglePill(tx, ty, scT, alpha, mob.toggleAnim, tst.press)

    -- keybind-FAB'ы: круглые, tap=нажатие / hold=перетаскивание, пружинное
    -- появление/исчезновение (backOut) + pop-отскок после тапа (MacLib-стиль).
    mob.fabAnim = mob.fabAnim or {}
    local dsize = keyFabSize(scK)
    local stackUp = Engine.sheet
    local stackY = stackUp and (ty - dsize - math.floor(16 * scK)) or (ty + th + math.floor(20 * scK))
    for i, el in ipairs(Engine.keybindEls or {}) do
        local fid = el.mobileFlag or ("kb" .. i)   -- стабильный id (для персиста позиции)
        local want = el.state.fab and 1 or 0
        local av = approach(mob.fabAnim[fid] or 0, want, dt, 15)
        mob.fabAnim[fid] = av
        if av > 0.004 then
            local name = el.settings.Name or "Bind"
            local iconId = el.settings.Icon           -- иконка бинда (если ��адана)
            -- дефолт: стопкой под Mobile Button (учёт диаметра + подписи снизу)
            if not mob.pos[fid] then
                if stackUp then
                    mob.pos[fid] = { x = math.max(4, vp.X - dsize - 12), y = stackY }
                else
                    mob.pos[fid] = { x = tx + (tw - dsize) * 0.5, y = stackY }
                end
            end
            if stackUp then
                stackY = stackY - dsize - math.floor(16 * scK)
            else
                stackY = stackY + dsize + math.floor(34 * scK)
            end
            mob.pos[fid].x = clamp(mob.pos[fid].x, 4, math.max(4, vp.X - dsize - 4))
            mob.pos[fid].y = clamp(mob.pos[fid].y, 4, math.max(4, vp.Y - dsize - 4))
            local fx, fy = mob.pos[fid].x, mob.pos[fid].y
            local press, grab, pop = 0, 0, 0
            -- ввод регистрируем только для АКТИВНЫХ FAB (не для гаснущих)
            if el.state.fab then
                local ft, fst = fabInput(fid, fx, fy, dsize, dsize, "holddrag")
                if ft then
                    if el.settings.Callback then pcall(el.settings.Callback, el.state.key) end
                    if el.settings.onBindHeld then pcall(el.settings.onBindHeld, true, el.state.key, 0.016) end
                end
                press, grab, pop = fst.press, fst.grab or 0, fst.pop or 0
            end
            drawKeyFab(fx, fy, scK, alpha * smooth01(av), name, iconId, press, grab, pop, backOut(av))
        end
    end
end
Engine.onMobilePaint(drawMobileLayer)

-- ── KEYBIND LIST HUD (для ПК) ────────────────────────────────────────────────
-- Всегда-на-экране список забинженных клавиш (кроме UI-бинда). Рисуется через
-- onMobilePaint (он вызывается каждый кадр независимо от того, открыто ли меню).
-- Перетаскивается мышью (fabInput), позиция персистится в mob.pos["kbdlist"].
local klAnim = 0
-- Размер коробки списка (нужен и для позиционирования/перетаскивания, и для paint).
local function kbListSize(sc, rows)
    local pad = math.floor(14 * sc)
    local headH = math.floor(30 * sc)
    local rowH = math.floor(24 * sc)
    local ns, ks = 12.5 * sc, 11 * sc
    -- ШИРЕ: базовая ширина с запасом под заголовок+иконку, и больше воздуха между
    -- именем функции и кэпом клавиши (было те��но).
    local contentW = measure("Keybinds", 11.5 * sc).X + math.floor(56 * sc)
    for _, rw in ipairs(rows) do
        local capW = measure(rw.key, ks).X + math.floor(16 * sc)
        local w = measure(rw.name, ns).X + math.floor(52 * sc) + capW
        if w > contentW then contentW = w end
    end
    contentW = math.max(contentW, math.floor(184 * sc))   -- нижняя гран��ца ширины
    local nRows = math.max(1, #rows)
    local boxW = contentW + pad * 2
    -- НИЖНИЙ ОТСТУП увеличен: раньше HUD-уголки (boxH-8) наезжали на последнюю
    -- строку («контейнер почти выходит за уголки») -> даём телу дышать.
    local boxH = headH + nRows * rowH + math.floor(18 * sc)
    return boxW, boxH, headH, rowH, pad, ns, ks
end
-- Отрисовка коробки по готовым строкам (переиспользуется в живом превью настроек).
-- Дизайн под ре��еренс «HotKeys»: НЕПРОЗРАЧНАЯ шапка (обычная панель) со скруглением
-- только СВЕРХУ + СТЕКЛЯННОЕ тело (полупрозрачное) со скруглением и HUD-уголками
-- только СНИЗУ. На стыке -- пере��ивающийся градиент-бар (flowAccent).
local function paintKbList(x, y, sc, alpha, rows, opacity)
    opacity = opacity or 1
    local a = alpha * opacity
    local boxW, boxH, headH, rowH, pad, ns, ks = kbListSize(sc, rows)
    local r = math.floor(10 * sc)
    local acc = kbAccent(0)

    -- ТЕНЬ всей коробки
    rrect(x + 2, y + 4, boxW, boxH, COL.app, 0.4 * a, r)
    -- ТЕЛО (стекло): полупрозрачное; нижние углы скруглены, верхние перекроет шапка
    rrect(x, y + headH, boxW, boxH - headH, COL.app, 0.55 * a, r)
    rrect(x, y + headH, boxW, boxH - headH, acc, 0.04 * a, r)     -- лёгкий тон стекла
    rrect(x, y + headH, boxW, r, COL.app, 0.55 * a, 0)           -- плоский верх тела
    -- ШАПКА: непрозрачная панель; низ выпрямляем полосой -> скругление только сверху
    rrect(x, y, boxW, headH, COL.panel, 0.98 * a, r)
    rrect(x, y + headH - r, boxW, r, COL.panel, 0.98 * a, 0)
    -- бейдж-иконка + заголовок
    local bd = math.floor(headH * 0.56)
    local bcx = x + pad + bd * 0.5
    local bcy = y + headH * 0.5
    rrect(bcx - bd * 0.5, bcy - bd * 0.5, bd, bd, acc, 0.18 * a, math.floor(bd * 0.3))
    drawIcon("dialpad", bcx - bd * 0.32, bcy - bd * 0.32, bd * 0.64, acc, 0.95 * a)
    text(bcx + bd * 0.5 + 6 * sc, bcy - 11.5 * sc * 0.5, 11.5 * sc, COL.text, "Keybinds", 0.95 * a)
    -- переливающийся градиент-бар на стыке шап��и и ��ела
    Engine.gradRect(x, y + headH - 1, boxW, math.max(2, math.floor(2 * sc)),
        kbAccent(0), kbAccent(1.6), 0.9 * a, 0, nil, nil, true)
    -- HUD-уголки ТОЛЬКО снизу (стеклянные скобки)
    local m = math.floor(8 * sc)
    local len = math.max(8, boxW * 0.06)
    local by2 = y + boxH - m
    line(x + m, by2, x + m + len, by2, acc, 0.7 * a, 1.6)
    line(x + m, by2, x + m, by2 - len, acc, 0.7 * a, 1.6)
    line(x + boxW - m, by2, x + boxW - m - len, by2, acc, 0.7 * a, 1.6)
    line(x + boxW - m, by2, x + boxW - m, by2 - len, acc, 0.7 * a, 1.6)
    -- тонкая рамка всей коробки
    rstroke(x, y, boxW, boxH, acc, 0.22 * a, r, 1.2)

    -- СТРОКИ
    if #rows == 0 then
        local msg = "No binds"
        local mw = measure(msg, ns).X
        -- «No binds» центрируем по ТЕЛУ и опускаем чуть ниже (просьба).
        local by0 = y + headH
        text(x + (boxW - mw) * 0.5, by0 + (boxH - headH - ns) * 0.5 + math.floor(3 * sc),
            ns, COL.faint, msg, 0.7 * a)
    else
        for i, rw in ipairs(rows) do
            local ry = y + headH + math.floor(6 * sc) + (i - 1) * rowH
            local tcy = ry + rowH * 0.5
            local active = rw.active == true
            -- ПОДСВЕТКА АКТИВНЫХ функций: залитая акцентом полоса на всю ширину строки
            -- + акцент-точка слева. Неактивные -- обычные (не «висят» как раньше).
            if active then
                local hy = tcy - rowH * 0.5 + math.floor(1 * sc)
                rrect(x + math.floor(6 * sc), hy, boxW - math.floor(12 * sc), rowH - math.floor(2 * sc),
                    acc, 0.14 * a, 6)
                disc(x + pad + math.floor(3 * sc), tcy, math.floor(2.5 * sc), acc, 0.95 * a)
            end
            local nx = x + pad + (active and math.floor(11 * sc) or 0)
            if rw.icon and app.custom.keybindListIcons ~= false then
                drawIcon(rw.icon, nx, tcy - 7 * sc, 14 * sc,
                    active and acc or COL.label, (active and 0.98 or 0.85) * a)
                nx = nx + math.floor(19 * sc)
            end
            text(nx, tcy - ns * 0.5, ns, active and COL.text or COL.label, rw.name,
                (active and 1 or 0.9) * a)
            -- кэп клавиши справа. Незабин��енные ("None") -- приглушённый плоский кэп.
            local capW = measure(rw.key, ks).X + math.floor(16 * sc)
            local ch = math.floor(19 * sc)
            local cx2 = x + boxW - pad - capW
            if not rw.bound then
                rrect(cx2, tcy - ch * 0.5, capW, ch, COL.inset, 0.6 * a, 5)
                rstroke(cx2, tcy - ch * 0.5, capW, ch, COL.line, 0.4 * a, 5, 1)
                local kw = measure(rw.key, ks).X
                text(cx2 + (capW - kw) * 0.5, tcy - ks * 0.5, ks, COL.faint, rw.key, 0.7 * a)
            else
                -- активный кэп -- залит акцентом (тёмный текст), иначе тон-обводка.
                if active then
                    rrect(cx2, tcy - ch * 0.5, capW, ch, acc, 0.9 * a, 5)
                else
                    rrect(cx2, tcy - ch * 0.5, capW, ch, COL.inset, 0.92 * a, 5)
                    rstroke(cx2, tcy - ch * 0.5, capW, ch, acc, 0.3 * a, 5, 1)
                end
                local kw = measure(rw.key, ks).X
                text(cx2 + (capW - kw) * 0.5, tcy - ks * 0.5, ks,
                    active and COL.app or acc, rw.key, 0.95 * a)
            end
        end
    end
    return boxW, boxH
end
Engine.kbListPaint = paintKbList

-- ЕДИНЫЙ сборщик строк списка (HUD + превью настроек одинаковы).
-- Логика показа (по решению пользователя):
--   keybindListAll = false (по умолч.): ТОЛЬКО АКТИВНЫ�� (включённые) функции.
--   keybindListAll = true: ВСЕ ЗАБИНЖЕННЫЕ функции (у которых есть клавиша),
--       не исключённые вручную; активные -> подсвечены.
-- Исключения:
--   HideFromList -> элемент никогда не в списке (UI-бинды, напр. Menu Toggle).
--   el.state.ignored -> пользователь скрыл конкретный кейбинд кнопкой «ignore».
-- active: el.settings.Active() (предикат состояния функции), иначе el.state.active.
local function kbActive(el)
    local A = el.settings.Active
    if type(A) == "function" then local ok, v = pcall(A); if ok then return v == true end end
    return el.state.active == true
end
function Engine.kbListRows()
    local rows = {}
    local showAll = app.custom.keybindListAll == true
    for _, el in ipairs(Engine.keybindEls or {}) do
        if not el.settings.HideFromList and not el.state.ignored then
            local bound = el.state.key ~= nil
            local active = kbActive(el)
            -- Unbound entries never belong in the HUD, even when their feature is on.
            local include = bound and (showAll or active)
            if include then
                rows[#rows + 1] = {
                    name   = el.settings.ListName or el.settings.Name or "Bind",
                    icon   = el.settings.Icon,
                    bound  = bound,
                    active = active,
                    key    = bound and keyName(el.state.key) or "None",
                }
            end
        end
    end
    return rows
end

local function drawKeybindList(dt)
    klAnim = approach(klAnim, app.custom.keybindList and 1 or 0, dt, 14)
    if klAnim < 0.01 then return end
    local alpha = smooth01(klAnim)
    local op = clamp(app.custom.keybindListOpacity or 1, 0.2, 1)

    local rows = Engine.kbListRows()
    -- масштаб = авто-скейл * пользовательский Keybind List Scale.
    local sc = clamp(Engine.autoScaleFactor or 1, 0.8, 1.6) * (app.custom.keybindListScale or 1)
    local boxW, boxH = kbListSize(sc, rows)
    local vp = Engine.viewport()
    if not mob.pos.kbdlist then
        mob.pos.kbdlist = { x = math.floor(16 * sc), y = math.floor(vp.Y * 0.28) }
    end
    mob.pos.kbdlist.x = clamp(mob.pos.kbdlist.x, 4, math.max(4, vp.X - boxW - 4))
    mob.pos.kbdlist.y = clamp(mob.pos.kbdlist.y, 4, math.max(4, vp.Y - boxH - 4))
    fabInput("kbdlist", mob.pos.kbdlist.x, mob.pos.kbdlist.y, boxW, boxH, "drag")
    -- слайд-появление слева
    local x = mob.pos.kbdlist.x - (1 - alpha) * math.floor(16 * sc)
    paintKbList(x, mob.pos.kbdlist.y, sc, alpha, rows, op)
end
Engine.onMobilePaint(drawKeybindList)

-- ── ПЕРСИСТ мобильной раскла��ки (дл�� конфигов) ──────────────────────────────
-- Видимость FAB + ОТНОСИТЕЛЬНАЯ позиция (доля вьюпорта) по стабильному flag ->
-- восстановление корректно на любом разрешении. Ключи по el.mobileFlag.
function Engine.captureMobileLayout()
    local vp = Engine.viewport()
    local vx, vy = math.max(1, vp.X), math.max(1, vp.Y)
    local out = {}
    for _, el in ipairs(Engine.keybindEls or {}) do
        local fid = el.mobileFlag
        if fid then
            local rec = { fab = el.state.fab and true or false }
            local p = mob.pos[fid]
            if p then rec.xr = p.x / vx; rec.yr = p.y / vy end
            out[fid] = rec
        end
    end
    -- позиция Keybind List HUD (относительная)
    if mob.pos.kbdlist then
        out._klist = { xr = mob.pos.kbdlist.x / vx, yr = mob.pos.kbdlist.y / vy }
    end
    return out
end
function Engine.applyMobileLayout(layout)
    if type(layout) ~= "table" then return end
    local vp = Engine.viewport()
    for _, el in ipairs(Engine.keybindEls or {}) do
        local fid = el.mobileFlag
        local rec = fid and layout[fid]
        if rec then
            -- Old configs saved fab=true for every Mobile bind. Do not
            -- restore that -- user opts in with + . Keep position only.
            if rec.xr and rec.yr then
                mob.pos[fid] = { x = rec.xr * vp.X, y = rec.yr * vp.Y }
            end
        end
    end
    if type(layout._klist) == "table" and layout._klist.xr then
        mob.pos.kbdlist = { x = layout._klist.xr * vp.X, y = layout._klist.yr * vp.Y }
    end
end

----------------------------------------------------------------------------
-- РЕНДЕР ЭЛЕМЕНТОВ МОДЕЛИ (каждый воз��ращает следующий y)
----------------------------------------------------------------------------
local elDraw = {}

-- Высота одной текстовой строки при кегле size (measure учитывает THEME.scale).
local function lineH(size)
    return math.floor((size or 12) * ((THEME and THEME.scale) or 1) + 0.5) + 6
end

-- ЕДИНЫЕ размеры «стоечного» слайдера (подпись сверху, контрол строкой ниже).
-- Draw И elemHeight берут ИХ ЖЕ -> высота секции точно совпадает с нарисованным
-- (иначе низ секции обрезал контрол ��ри крупном/мелком скейле).
local function sliderMetrics()
    local sc = (THEME and THEME.scale) or 1
    local f = 1 + (sc - 1) * 0.6
    local topH = math.floor(20 * f)
    local bodyH = math.floor(30 * f)
    if Engine.sheet then
        topH = math.max(topH, 22)
        bodyH = math.max(bodyH, 40)
    end
    return topH, bodyH, topH + bodyH
end

-- Метрики Label/Paragraph с ПЕРЕНОСОМ по сл��вам -> и draw, и elemHeight считают
-- одинаково, поэтому секция РАСТЁТ ровно под перенесённый т��кст (без обрезки).
local function labelMetrics(el, w)
    local str = (el.settings and el.settings.Text) or (el.state and el.state.text) or ""
    local sub = el.state and el.state.sub
    local sz = sub and 10.5 or 12
    local lines = wrapText(str, sz, w - 28)
    local lh = lineH(sz)
    return lines, sz, sub, lh, 6 + #lines * lh + 4
end

local function paraMetrics(el, w)
    local head = (el.settings and (el.settings.Title or el.settings.Header)) or ""
    local body = (el.settings and (el.settings.Description or el.settings.Body)) or ""
    local hLines = wrapText(head, 12.5, w - 28)
    local bLines = wrapText(body, 11, w - 28)
    local hh, bh = lineH(12.5), lineH(11)
    return hLines, bLines, hh, bh, 4 + #hLines * hh + 2 + #bLines * bh + 6
end

local function headerMetrics(el, w)
    local str = (el.settings and el.settings.Text) or (el.state and el.state.text) or ""
    local lines = wrapText(str, 13, w - 34)
    local lh = lineH(13)
    return lines, lh, 4 + #lines * lh + 10
end

elDraw.Label = function(el, x, y, w, dt)
    local lines, sz, sub, lh = labelMetrics(el, w)
    local col = sub and COL.faint or COL.label
    local a = sub and 0.75 or 0.9
    local yy = y + 6
    for _, ln in ipairs(lines) do
        text(x + 14, yy, sz, col, ln, a)
        yy = yy + lh
    end
    return yy + 4
end

-- Header — заголовок подгруппы: текст + разделительная линия.
elDraw.Header = function(el, x, y, w, dt)
    local lines, lh, total = headerMetrics(el, w)
    local yy = y + 6
    for _, ln in ipairs(lines) do
        text(x + 14, yy, 13, COL.text, ln, 1)
        yy = yy + lh
    end
    -- Одна тонкая линия без stroke — раньше две rrect создавали обводку.
    local lineY = yy + 3
    rrect(x + 14, lineY, w - 28, 1, COL.text, 0.15, 0)
    return y + total
end

-- Spacer -- пустой зазор фиксированной высоты (Size опционально), п.11.
elDraw.Spacer = function(el, x, y, w, dt)
    return y + ((el.settings and el.settings.Size) or 12)
end

elDraw.Paragraph = function(el, x, y, w, dt)
    -- MacLib именует поля Header/Body; поддерживаем и Title/Description. Обе части
    -- переносятся по словам -> длинный текст не обрезается, а секция растёт.
    local hLines, bLines, hh, bh = paraMetrics(el, w)
    local yy = y + 4
    for _, ln in ipairs(hLines) do
        text(x + 14, yy, 12.5, COL.text, ln, 1)
        yy = yy + hh
    end
    yy = yy + 2
    for _, ln in ipairs(bLines) do
        text(x + 14, yy, 11, COL.dim, ln, 0.85)
        yy = yy + bh
    end
    return yy + 6
end

-- DIVIDER (редиз��йн): не «просто полоска». Линии з��тухают от краёв к центру
-- (несколько сегментов с нарастающей прозрачностью -> эффект градиента без
-- шейдера), а в центре -- акцентный ромб-узел с мягким свечением. Если задан
-- Text -- вместо ромба рисуем подпись по центру, а линии обрываются �� неё.
elDraw.Divider = function(el, x, y, w, dt)
    local s = el.settings or {}
    local cx = math.floor(x + w * 0.5 + 0.5)
    local cy = math.floor(y + 8 + 0.5)
    local lx, rx = math.floor(x + 14 + 0.5), math.floor(x + w - 14 + 0.5)
    local label = s.Text or s.Name

    -- рисуем половину линии из N сегментов: alpha максимальна у края, гаснет к центру
    local function halfLine(x1, x2, dir)
        local segs = 7
        local total = math.abs(x2 - x1)
        local sw = total / segs
        for i = 0, segs - 1 do
            local t = i / (segs - 1)                    -- 0 у центра .. 1 у края
            local a = 0.02 + 0.11 * t                   -- к краю ярче
            local sx = x1 + dir * (i * sw)
            line(sx, cy, sx + dir * sw, cy, COL.text, a, 1)
        end
    end

    if label and label ~= "" then
        local fs = 11
        local lw = measure(label, fs).X
        local gap = lw * 0.5 + 10
        halfLine(lx, cx - gap, 1)                       -- ле��ая линия до подписи
        halfLine(rx, cx + gap, -1)                      -- правая линия до подписи
        text(cx - lw * 0.5, cy - fs * 0.5, fs, COL.dim, label, 0.8)
        return y + 24
    end

    -- без подписи: две затухающие полулинии + централ��ный УЗЕЛ. Раньше узе�� был
    -- ромбом из 4 тонких линий -> на изломах «рвался»/пикселил (жалоба). Теперь
    -- крист��льно-чистый узел БЕЗ линий: мягкое свечение + сплош����я точка-ядро +
    -- тонкое кольцо-ореол (всё это гладкие примитивы disc/ring).
    halfLine(lx, cx - 8, 1)
    halfLine(rx, cx + 8, -1)
    local d = 4.6
    Engine.disc(cx, cy, 6.2, COL.cyan, 0.12)
    Engine.line(cx, cy - d, cx + d, cy, COL.cyan, 0.95, 1.7)
    Engine.line(cx + d, cy, cx, cy + d, COL.cyan, 0.95, 1.7)
    Engine.line(cx, cy + d, cx - d, cy, COL.cyan, 0.95, 1.7)
    Engine.line(cx - d, cy, cx, cy - d, COL.cyan, 0.95, 1.7)
    Engine.disc(cx, cy, 2.15, COL.cyan, 1)
    return y + 20
end

elDraw.Button = function(el, x, y, w, dt)
    local k = el.key
    local tip = el.settings.Tooltip or el.settings.Description
    local bh = Engine.sheet and 40 or 32
    local row = Engine.sheet and 48 or 40
    if bigButton(k, x + 12, y + (row - bh) * 0.5, w - 24, bh, el.settings.Name or "Button",
        el.settings.Icon, dt, tip) then
        if el.settings.Callback then pcall(el.settings.Callback) end
    end
    return y + row
end

elDraw.Toggle = function(el, x, y, w, dt)
    local s = el.settings
    local desc = s.Description
    local name = s.Name or "Toggle"
    local stacked, ctrlCy, rowH, ctrlX = rowLayout(x, y, w, name, 46)
    local extra = (Engine.sheet and desc and desc ~= "") and 16 or 0
    hit(el.key, x + 8, y, w - 16, rowH + extra, Z.CONTENT)
    local hov = Engine.isHover(el.key)
    local labelMax = stacked and (w - 28) or math.max(24, ctrlX - x - 22)
    if stacked then
        text(x + 14, y + 4, 12, COL.label, fitText(name, 12, labelMax), 0.95)
    elseif desc and desc ~= "" and not Engine.sheet then
        text(x + 14, y + rowH * 0.5 - 12, 12, COL.label, fitText(name, 12, labelMax), 0.95)
        text(x + 14, y + rowH * 0.5 + 3, 9.5, COL.faint, fitText(desc, 9.5, labelMax), 0.8)
    else
        text(x + 14, y + rowH * 0.5 - 6, 12, COL.label, fitText(name, 12, labelMax), 0.95)
    end
    if extra > 0 then
        text(x + 14, y + rowH - 2, 9.5, COL.faint, fitText(desc, 9.5, w - 28), 0.8)
    end
    local tip = s.Tooltip or desc
    if tip and hov then Engine.setTooltip(tip) end
    local col = el.state.color or COL.cyan
    local px = stacked and (x + w - 14 - 46) or ctrlX
    pill(el.key .. "/vis", px, ctrlCy - 12, el.state.on, dt, col, true, el.key)
    if Engine.clicked(el.key) then
        el.state.on = not el.state.on
        if s.Callback then pcall(s.Callback, el.state.on) end
    end
    return y + rowH + extra
end

elDraw.Slider = function(el, x, y, w, dt)
    local s = el.settings
    local boxW = s.Suffix and 74 or 52
    -- ВСЕГДА ДВУХЭТАЖНО (по просьбе): подпись сверху -- контрол строкой НИЖЕ во всю
    -- ширину. Это поведение «старого слайдера», который надёжно уход��л под ��екст и
    -- никогда не наезжал на него -- при любом скейле и любой длине названия.
    -- (Раньше rowLayout иногда оставлял контрол в той же ��троке -> при длинных
    --  именах/крупном скейле трек «заходил за текст».)
    -- Стоечная раскладка ч��рез ЕДИНЫЕ метрики (совпадает с elemHeight -> секция
    -- растёт под слайдер и не обрезает его при любом скейле).
    local topH, bodyH, rowH = sliderMetrics()
    local ctrlCy = y + topH + bodyH * 0.5   -- вертикальный центр контрол-ст��оки
    local ctrlX = x + 14
    local ctrlAvailW = w - 28
    -- подпись во всю ширину верхней строки -> обрезаем по ширине, чтобы длинное имя
    -- не улезало под правое поле.
    text(x + 14, y + 5, 12, COL.label, fitText(s.Name or "Slider", 12, ctrlAvailW), 0.95)
    local rightEdge = ctrlX + ctrlAvailW
    local boxX = rightEdge - boxW
    local boxY = ctrlCy - 10
    local rounding = s.Rounding or 0

    -- РУЧНОЙ ВВОД ЗНАЧЕНИЯ (п.13). Value-box сам по себе -- текст-поле: клик по
    -- нему фокусирует �� даёт печатать число, Enter/клик-вне коммитят его
    -- (парсим, клампим в [Min,Max], зовём Callback). Пока НЕ сфокусирован --
    -- показывает ж��вое значен��е слайдера. Буфер (state.buf) отдельн�� от
    -- state.value, чтобы перетаскивание ручки и печать не дра��ись.
    el.valueField = el.valueField or {
        state = { text = "" },
        hitKey = el.key .. "/box",   -- чтобы blur-по-клику-вне (п.7) у��навал это поле
        settings = {
            -- коммит введённого те��ста в значение слайдера
            Callback = function(txt)
                -- запят��ю -> точку, зате�� разр��шаем ".5" и "0.5" (ведущая точка).
                local norm = (txt or ""):gsub(",", ".")
                local n = tonumber(norm:match("%-?%d*%.?%d+"))
                if n then
                    n = clamp(n, s.Minimum, s.Maximum)
                    if s.Increment then n = floor(n / s.Increment + 0.5) * s.Increment end
                    el.state.value = n
                    if s.Callback then pcall(s.Callback, n) end
                end
                el.valueField.editing = false
            end,
        },
    }
    local vf = el.valueField
    local editing = Engine.textFocus == vf
    local boxKey = el.key .. "/box"
    hit(boxKey, boxX, boxY, boxW, 20, Z.BODY)
    if Engine.clicked(boxKey) and not editing then
        vf.editing = true
        vf.state.text = ""            -- начинаем с пустого -> печатаем новое число
        Engine.textFocus = vf
    end

    rrect(boxX, boxY, boxW, 20, COL.track, 1, 5)
    if editing then rstroke(boxX, boxY, boxW, 20, COL.cyan, 0.6, 5, 1) end

    local shown
    if editing then
        local caret = (math.floor(os.clock() * 2) % 2 == 0) and "|" or ""
        shown = (vf.state.text ~= "" and vf.state.text or "") .. caret
    else
        shown = rounding > 0 and string.format("%." .. rounding .. "f", el.state.value)
            or tostring(floor(el.state.value + 0.5))
    end
    local val = shown .. (editing and "" or (s.Suffix or ""))
    local vw = measure(val, 11).X
    text(boxX + boxW * 0.5 - vw * 0.5, boxY + 5, 11,
        editing and COL.text or COL.label, val, 0.95)

    -- трек занимает всё место слева от бокса (в двухэтажном режиме -- шире)
    local th = 8
    local tx = ctrlX
    local tw = math.max(40, (boxX - 10) - tx)
    local ty = ctrlCy - th * 0.5

    -- ЗОНА ЗАХВАТА (п.7). Раньше hit был тонк��й по��оской вокруг 8px-жёлоба, и
    -- поймать драг было почти невозможно -> «ползунок не двигается». Теперь
    -- ловим захват по всей высоте области контрола и по всей ширине жёлоба.
    local trackKey = el.key .. "/track"
    hit(trackKey, tx - 6, ctrlCy - M.row * 0.5, tw + 20, M.row, Z.CONTENT)
    local st = stateOf(trackKey)
    st.hover = approach(st.hover, Engine.isHover(trackKey) and 1 or 0, dt, 16)
    if Engine.isActive(trackKey) or Engine.clicked(trackKey) then
        local f = clamp((Engine.input.mouse.X - tx) / tw, 0, 1)
        local nv = s.Minimum + f * (s.Maximum - s.Minimum)
        if s.Increment then nv = floor(nv / s.Increment + 0.5) * s.Increment end
        if nv ~= el.state.value then
            el.state.value = nv
            if s.Callback then pcall(s.Callback, nv) end
        end
    end
    local frac = clamp((el.state.value - s.Minimum) / math.max(s.Maximum - s.Minimum, 1e-6), 0, 1)
    rrect(tx, ty, tw, th, COL.trackOff, 1, th * 0.5)
    if frac > 0.001 then rrect(tx, ty, math.max(tw * frac, th), th, COL.cyan, 1, th * 0.5) end
    -- Ручка -- скруглённая ��илюля (rrect), не disc (FilledCircle -> треугольник
    -- на части экзекуторов).
    local hx = tx + fit(tw * frac, 5, tw - 5)
    local hw, hh = 6, th + 10 + st.hover * 2
    rrect(hx - hw * 0.5, ty + th * 0.5 - hh * 0.5, hw, hh, COL.text, 1, hw * 0.5)
    rstroke(hx - hw * 0.5, ty + th * 0.5 - hh * 0.5, hw, hh, COL.cyan, 0.5, hw * 0.5, 1)
    return y + rowH
end

-- SCALE SLIDER: специальный слайдер для пар��метров, которые МЕНЯЮТ РАСКЛАДКУ на
-- лету (UI Scale и т.п.). У обычного слайдера значение каждый кадр вычисляется как
-- (mouseX - trackX)/trackW; но ко��да callback пересчитывает масштаб окна, trackX/
-- trackW смещаются -> дробь скачет -> ручку «дёргает» и зна��ение не встаёт куда
-- надо. Здесь используется ОТНОСИТЕЛЬНЫЙ драг: в момент захвата запоми��аем разницу
-- м��жду fraction курсора и fraction значения (grabOffset); далее ведём значение ��о
-- (fracCursor - grabOffset). Мелкие сдвиги т��ека компе��сируют��я -> НЕТ джиттера.
-- ZOOM-GAUGE (нестандартный UI Scale). Вместо обыч��ого трек+кругляш -- гребёнка
-- насечек, высота которых РАСТЁТ слева направо (визуально «масштаб увеличивается»),
-- по бокам степпе��ы [-]/[+], справа чип с процентами. Перетаскивание -- ПО ДЕЛЬТЕ
-- курсора (value += dx * span/stripW), а ��е по абсолютной позиции -> при рескейле
-- всего окна планка сдвигается, но значение НЕ дёргается (нет джиттера вообще).
local function setScaleValue(el, nv)
    local s = el.settings
    if s.Increment then nv = floor(nv / s.Increment + 0.5) * s.Increment end
    nv = clamp(nv, s.Minimum or 0.8, s.Maximum or 1.4)
    -- о��ругление до разумной точности (убираем накопление float)
    nv = floor(nv * 1000 + 0.5) / 1000
    if nv ~= el.state.value then
        el.state.value = nv
        if s.Callback then pcall(s.Callback, nv) end
    end
end

elDraw.ScaleSlider = function(el, x, y, w, dt)
    local s = el.settings
    -- ДВУХСТРОЧНАЯ раскладка в едином языке со слайдерами: ВЕРХНЯЯ строка = подпись
    -- слева + чип «200%» справа (шапка -- сразу ясно, к чему слайдер); НИЖНЯЯ строка
    -- = гребёнка-«зум» со степ��ерами [-]/[+] по краям. Раньше чип/индикатор висели на
    -- строке гребёнки далеко от подписи -> «непонятн��, что за слайдер» (жалоба).
    local topH, bodyH = sliderMetrics()
    rowLabel(x + 14, y + math.floor((topH - M.row) * 0.5), s.Name or "Scale")
    local minV, maxV = s.Minimum or 0.8, s.Maximum or 1.4
    local incr = s.Increment or 0.05
    local span = math.max(maxV - minV, 1e-6)
    local cy = y + topH + bodyH * 0.5
    local val = el.state.value

    -- ---- раскладка: чип значения ушёл на ВЕРХНЮЮ строку (к подписи), а на нижней
    -- строке степперы стоят по краям и гребёнка т��нется во всю ширину между ними.
    -- Так «к чему слайдер» читается сразу: подпись+значение = одна шапка.
    local chipW = 52
    local chipX = x + w - 14 - chipW
    local chipY = y + math.floor((topH - 20) * 0.5)   -- верхняя строка, у подписи
    local btn = 18
    -- Планка НЕ тянется во всю ширину (была слишком длинной). Ограничиваем её
    -- максимумом и центрируем группу [-][гребёнка][+] по строк�� -> компактно.
    local avail = w - 28 - (btn + 10) * 2             -- место под гребёнку ��ежду кнопками
    local stripW = math.max(40, math.min(avail, 168)) -- жёсткий кап ширины
    local groupW = (btn + 10) + stripW + (10 + btn)
    local gx = x + (w - groupW) * 0.5                  -- центрируем группу
    local minusX = gx
    local stripX = minusX + btn + 10
    local stripRight = stripX + stripW
    local plusX = stripRight + 10
    local byB = cy - btn * 0.5

    -- ---- степперы [-] / [+] ----
    local function stepBtn(bx, key, sign, label)
        hit(key, bx, byB, btn, btn, Z.CONTENT)
        local bs = stateOf(key)
        bs.hover = approach(bs.hover, Engine.isHover(key) and 1 or 0, dt, 16)
        local enabled = (sign < 0 and val > minV + 1e-4) or (sign > 0 and val < maxV - 1e-4)
        rrect(bx, byB, btn, btn, COL.track, 0.9, 5)
        rstroke(bx, byB, btn, btn, COL.cyan, (0.2 + bs.hover * 0.4) * (enabled and 1 or 0.3), 5, 1)
        local c = enabled and COL.text or COL.faint
        -- рисуем +/- линиями (чёткие, независимо от шрифта)
        line(bx + 5, cy, bx + btn - 5, cy, c, enabled and 0.9 or 0.4, 1.6)
        if sign > 0 then line(bx + btn * 0.5, byB + 5, bx + btn * 0.5, byB + btn - 5, c, 0.9, 1.6) end
        if enabled and Engine.clicked(key) then setScaleValue(el, val + sign * incr) end
    end
    stepBtn(minusX, el.key .. "/dec", -1)
    stepBtn(plusX, el.key .. "/inc", 1)

    -- ---- греб��нка насечек ----
    local stripKey = el.key .. "/strip"
    hit(stripKey, stripX - 4, cy - M.row * 0.5, stripW + 8, M.row, Z.CONTENT)
    local st = stateOf(stripKey)
    st.hover = approach(st.hover, Engine.isHover(stripKey) and 1 or 0, dt, 16)

    -- перетаскивание ПО ДЕЛЬТЕ (иммунно к рескейлу планки).
    -- РАНЬШЕ: каждый кадр setScaleValue снапил val к Increment ОТ уже снапнутого
    -- знач��ния, ��оэтому суб-инкрементный сдвиг курсора (медленное движ��ние)
    -- терялся -> «нужно сильно вертеть мышкой». ТЕПЕРЬ ведём НЕСНАПНУТЫЙ
    -- аккумулятор st.raw и снапим только при коммите -> плавно и точно ловит
    -- даже малые ��вижения. Чувствительность 1.35x (диапазон трека ш��ре планки).
    local active = Engine.isActive(stripKey)
    if Engine.clicked(stripKey) then
        st.lastX = Engine.input.mouse.X
        st.raw = val
    end
    if active then
        local mx = Engine.input.mouse.X
        local dx = mx - (st.lastX or mx)
        st.lastX = mx
        if dx ~= 0 then
            st.raw = clamp((st.raw or val) + dx * (span / stripW) * 1.35, minV, maxV)
            setScaleValue(el, st.raw)   -- снап только для итогового значения
            val = el.state.value
        end
    elseif Engine.clicked(stripKey) then
        -- чистый клик без движения -> прыжок к насечке под курсором
        local f = clamp((Engine.input.mouse.X - stripX) / stripW, 0, 1)
        setScaleValue(el, minV + f * span)
        st.raw = el.state.value
        val = el.state.value
    end

    local frac = clamp((val - minV) / span, 0, 1)
    -- ПЛОТНАЯ шкала: крупные насечки на каждый Increment + 4 тонкие минорные между
    -- ними -> нет огромных пустых промежутков (жалоба). Ширина насечек фикс. в
    -- пикселях, а шаг = равномерная доля ширины -> одинаково на любом разрешен��и.
    local majors = math.max(1, floor(span / incr + 0.5))   -- число интервалов
    local SUB = 4                                          -- минорных на и��тервал
    local total = majors * SUB
    for i = 0, total do
        local t = i / total
        local tx = stripX + t * stripW
        local isMajor = (i % SUB == 0)
        local hh = (isMajor and 6 or 3) + t * (isMajor and 12 or 6)  -- рост слева->направо
        local on = t <= frac + 1e-3
        local col = on and COL.cyan or COL.trackOff
        local a = (on and 0.9 or 0.45) * (isMajor and 1 or 0.55)
        rrect(tx - (isMajor and 1 or 0.5), cy - hh * 0.5, isMajor and 2 or 1, hh, col, a, 1)
    end
    -- светящийся индикатор текущей насечки
    local ix = stripX + frac * stripW
    local ih = 5 + frac * 12
    Engine.disc(ix, cy - ih * 0.5 - 4, 3 + st.hover, COL.cyan, 0.9)
    line(ix, cy - ih * 0.5, ix, cy + ih * 0.5, COL.text, 0.95, 2)

    -- ---- чип с процента��и: теперь РЕДАКТИРУЕМЫЙ (��ак value-box обычного слайдера) ----
    -- Клик по чипу -> фокус, печатаем число В ПРОЦЕНТАХ (напр. 120), Enter/клик-вне
    -- коммитит value = n/100 с клампом. Тот же механизм valueField + Engine.textFocus.
    el.valueField = el.valueField or {
        state = { text = "" },
        hitKey = el.key .. "/chip",
        settings = {
            Callback = function(txt)
                local norm = (txt or ""):gsub("%%", ""):gsub(",", ".")
                local n = tonumber(norm:match("%-?%d*%.?%d+"))
                if n then setScaleValue(el, n / 100) end   -- ввод в процентах
                el.valueField.editing = false
            end,
        },
    }
    local vf = el.valueField
    local editing = Engine.textFocus == vf
    local chipKey = el.key .. "/chip"
    hit(chipKey, chipX, chipY, chipW, 20, Z.CONTENT)
    if Engine.clicked(chipKey) and not editing then
        vf.editing = true
        vf.state.text = ""
        Engine.textFocus = vf
    end
    rrect(chipX, chipY, chipW, 20, COL.track, 1, 6)
    rstroke(chipX, chipY, chipW, 20, COL.cyan, editing and 0.6 or 0.22, 6, 1)
    local pct
    if editing then
        local caret = (math.floor(os.clock() * 2) % 2 == 0) and "|" or ""
        pct = (vf.state.text ~= "" and vf.state.text or "") .. caret
    else
        pct = tostring(floor(val * 100 + 0.5)) .. "%"
    end
    local pw = measure(pct, 11).X
    text(chipX + chipW * 0.5 - pw * 0.5, chipY + 4, 11, editing and COL.text or COL.label, pct, 0.95)

    if not active then st.lastX = nil end
    return y + topH + bodyH
end

elDraw.Input = function(el, x, y, w, dt)
    local s = el.settings
    local name = s.Name or "Input"
    local bw = 150
    local stacked, ctrlCy, rowH, ctrlX, ctrlAvail = rowLayout(x, y, w, name, bw)
    if stacked then
        text(x + 14, y + 4, 12, COL.label, fitText(name, 12, w - 28), 0.95)
        bw = math.max(40, ctrlAvail)
    else
        text(x + 14, y + rowH * 0.5 - 6, 12, COL.label, fitText(name, 12, math.max(24, ctrlX - x - 22)), 0.95)
    end
    local boxH = Engine.sheet and 32 or 22
    local bx = ctrlX
    local by = ctrlCy - boxH * 0.5
    hit(el.key, bx, by, bw, boxH)
    local focused = Engine.textFocus == el
    if Engine.clicked(el.key) then Engine.textFocus = el end
    rrect(bx, by, bw, boxH, COL.inset, focused and 0.9 or 0.6, 6)
    rstroke(bx, by, bw, boxH, COL.cyan, focused and 0.5 or 0.12, 6, 1)
    local shown = el.state.text
    local ty = by + math.floor((boxH - 12) * 0.5)
    if shown == "" and not focused then
        text(bx + 8, ty, 11.5, COL.faint, s.Placeholder or "", 0.7)
    else
        local caret = focused and (math.floor(os.clock() * 2) % 2 == 0 and "|" or "") or ""
        text(bx + 8, ty, 11.5, COL.text, shown .. caret, 0.95)
    end
    return y + rowH
end

elDraw.Keybind = function(el, x, y, w, dt)
    local s = el.settings
    local rowH = Engine.sheet and math.max(M.row, 44) or M.row
    local btnH = Engine.sheet and 32 or 22
    text(x + 14, y + rowH * 0.5 - 6, 12, COL.label,
        fitText(s.Name or "Keybind", 12, math.max(24, w - 28 - 150)), 0.95)
    local by = y + rowH * 0.5 - btnH * 0.5

    -- МОБИЛЬНЫЙ режим (как в MacLib): key-capture бесполезен без клавиатуры, поэтому
    -- показываем компактный переключатель [+]/[−] -> добавить/убрать плавающую
    -- keybind-кнопку (FAB) на экране. Слева от него -- маленький кэп текущей клавиши.
    if Engine.mobileEnabled() then
        local btn = btnH
        local px = x + w - 14 - btn
        local capW = 54
        local capX = px - 8 - capW
        -- NoMobileButton: для UI-бинда (Menu Toggle) плавающая кнопка не имеет
        -- смысла -- у нас уже есть отдельная Mobile Button. Прячем «+» и держим
        -- FAB выключенным, пока��ываем только справочный кэп клавиши.
        if s.NoMobileButton then
            el.state.fab = false
            local resetKey = el.key .. "/reset/mobile"
            local resetX = capX - btn - 6
            hit(resetKey, resetX, by, btn, btn, Z.CONTENT + 2)
            if Engine.clicked(resetKey) then
                el.state.key = nil
                if s.onBinded then pcall(s.onBinded, nil) end
            end
            rrect(resetX, by, btn, btn, COL.inset, 0.5, 6)
            drawIcon("x", resetX + 4, by + 4, 14, COL.dim, 0.95)
            local kb = keyName(el.state.key)
            local kw = measure(kb, 11).X
            rrect(capX, by, capW + btn + 8, btn, COL.inset, 0.5, 6)
            text(capX + (capW + btn + 8) * 0.5 - kw * 0.5, by + 5, 11, COL.dim, kb, 0.9)
            return y + rowH
        end
        -- кэп клавиши (справочно; на мобиле привязать нельзя, но конфиг/ПК могли задать)
        local resetKey = el.key .. "/reset/mobile"
        local resetX = capX - btn - 6
        hit(resetKey, resetX, by, btn, btn, Z.CONTENT + 2)
        if Engine.clicked(resetKey) then
            el.state.key = nil
            if el.settings.onBinded then pcall(el.settings.onBinded, nil) end
        end
        rrect(resetX, by, btn, btn, COL.inset, 0.5, 6)
        drawIcon("x", resetX + 4, by + 4, 14, COL.dim, 0.95)
        rrect(capX, by, capW, btn, COL.inset, 0.5, 6)
        local kb = keyName(el.state.key)
        local kw = measure(kb, 11).X
        text(capX + capW * 0.5 - kw * 0.5, by + 5, 11, COL.dim, kb, 0.9)
        -- переключатель FAB
        local on = el.state.fab and true or false
        local pk = el.key .. "/fab"
        hit(pk, px, by, btn, btn)
        if Engine.clicked(pk) then
            el.state.fab = not on
            if el.settings.onBinded then pcall(el.settings.onBinded, el.state.key) end
        end
        rrect(px, by, btn, btn, on and COL.panel or COL.inset, 0.9, 6)
        rstroke(px, by, btn, btn, COL.cyan, on and 0.6 or 0.18, 6, 1)
        local cx = math.floor(px + btn * 0.5 + 0.5)
        local cy = math.floor(by + btn * 0.5 + 0.5)
        line(cx - 5, cy, cx + 5, cy, COL.cyan, 0.95, 1.6)
        if not on then line(cx, cy - 5, cx, cy + 5, COL.cyan, 0.95, 1.6) end
        return y + rowH
    end

    -- ДЕСКТОП: обычный key-capture.
    local bw = 90
    local bx = x + w - 14 - bw

    -- Reset ПЕРВАЯ кнопка слева от bind-box с hover/click анимацией.
    -- Ignore вторая справа от reset.
    if not s.HideFromList then
        local rb = 22
        local rx = bx - 8 - rb
        local rk = el.key .. "/reset"
        hit(rk, rx, by, rb, rb, Z.CONTENT + 2)
        local rst = stateOf(rk)
        rst.hover = approach(rst.hover, Engine.isHover(rk) and 1 or 0, dt, 8)
        rst.press = approach(rst.press, Engine.isActive(rk) and 1 or 0, dt, 12)
        if Engine.clicked(rk) then
            el.state.key = nil
            el.state.listening = false
            if s.onBinded then pcall(s.onBinded, nil) end
        end
        local hl = 0.6 + rst.hover * 0.15 - rst.press * 0.2
        rrect(rx, by, rb, rb, COL.inset, hl, 6)
        rstroke(rx, by, rb, rb, COL.cyan, 0.18 + rst.hover * 0.12, 6, 1)
        drawIcon("x", rx + 4, by + 4, 14, COL.dim, 0.7 + rst.hover * 0.25)
        
        local ib = 22
        local ix = rx - 4 - ib
        local ik = el.key .. "/ignore"
        hit(ik, ix, by, ib, ib)
        local ist = stateOf(ik)
        ist.hover = approach(ist.hover, Engine.isHover(ik) and 1 or 0, dt, 8)
        if Engine.clicked(ik) then el.state.ignored = not el.state.ignored end
        local ign = el.state.ignored == true
        rrect(ix, by, ib, ib, ign and COL.inset or COL.panel, 0.9, 6)
        rstroke(ix, by, ib, ib, COL.cyan, ign and 0.18 or (0.5 + ist.hover * 0.15), 6, 1)
        drawIcon(ign and "eye-off" or "eye", ix + ib * 0.5 - 7, by + ib * 0.5 - 7, 14,
            ign and COL.dim or COL.cyan, 0.95)
    end

    hit(el.key, bx, by, bw, 22)
    local listening = el.state.listening
    if Engine.clicked(el.key) then
        el.state.listening = true
        Engine.keyListener = function(kc)
            el.state.listening = false
            -- Escape/Backspace -> очистить бинд (н�� назна��ать эти к��ави��и).
            if kc == Enum.KeyCode.Escape then return end
            if kc == Enum.KeyCode.Backspace then
                el.state.key = nil
                if s.onBinded then pcall(s.onBinded, nil) end
                return
            end
            if s.Blacklist then
                for _, bad in ipairs(s.Blacklist) do
                    if bad == kc or (typeof(bad) == "EnumItem" and bad.Name == kc.Name) then
                        return
                    end
                end
            end
            el.state.key = kc
            if s.onBinded then pcall(s.onBinded, kc) end
            -- НЕ вызываем s.Callback здесь! Раньше при��воение бинда СРАЗУ дёргало
            -- ко��бэк (для UI-тумблера -> Engine.toggle), поэтому меню исчезало
            -- прямо в момент перепривязки, и назначенная клавиша считалась «уже
            -- н��жатой» (п.16). Колбэк должен срабатывать ТОЛЬКО на реальном
            -- нажатии клавиши позже -- это делает Engine.onKey по keybindEls.
        end
    end
    rrect(bx, by, bw, 22, COL.inset, 0.6, 6)
    rstroke(bx, by, bw, 22, COL.cyan, listening and 0.6 or 0.12, 6, 1)
    local label = listening and "..." or keyName(el.state.key)
    local lw = measure(label, 11.5).X
    text(bx + bw * 0.5 - lw * 0.5, by + 5, 11.5,
        listening and COL.cyan or COL.label, label, 0.95)
    return y + rowH
end

elDraw.Dropdown = function(el, x, y, w, dt)
    local s = el.settings
    local cw = 150
    -- авто-раскладка: длинна�� подпись -> контрол уезжа��т на второй этаж во всю ширину
    local stacked, ctrlCy, rowH, ctrlX, ctrlAvailW = rowLayout(x, y, w, s.Name or "Dropdown", cw)
    if stacked then
        text(x + 14, y + 5, 12, COL.label, s.Name or "Dropdown", 0.95)
        cw = ctrlAvailW
    else
        rowLabel(x + 14, y, s.Name or "Dropdown")
    end
    local cx = ctrlX
    local cy = ctrlCy - 11
    el._rowH = rowH               -- для return в конце
    hit(el.key, cx, cy, cw, 22)
    local st = stateOf(el.key)
    st.hover = approach(st.hover, Engine.isHover(el.key) and 1 or 0, dt, 16)
    if Engine.clicked(el.key) then st.open = not st.open end
    st.reveal = approach(st.reveal or 0, st.open and 1 or 0, dt, 20)

    -- Отображаемое значение. Для multi НЕ вываливаем весь список за рамку:
    -- показываем сколько ��лезает, а остаток сворачивае�� в «+N» (как просил юзер).
    local maxV = cw - 26   -- слева пад��инг 8 + справа ��еврон 16 + запас
    local shownVal
    if s.Multi then
        -- собираем выбранные В ПОРЯДК�� Options (ст��бильно, без прыжков)
        local sel = {}
        for _, opt in ipairs(s.Options or {}) do
            if el.state.multi[opt] then sel[#sel + 1] = opt end
        end
        if #sel == 0 then
            shownVal = "None"
        else
            -- до��авляем имена пока влезают; остальное -> "+N"
            local shown, count = "", 0
            for i, name in ipairs(sel) do
                local trial = (shown == "" and name) or (shown .. ", " .. name)
                local extra = (#sel - i)   -- сколько останется после этого
                local suffix = extra > 0 and ("  +" .. (extra)) or ""
                if measure(trial .. suffix, 12).X <= maxV or count == 0 then
                    shown = trial
                    count = i
                else
                    break
                end
            end
            local rest = #sel - count
            shownVal = shown .. (rest > 0 and ("  +" .. rest) or "")
        end
    else
        shownVal = el.state.value or "None"
    end
    rrect(cx, cy, cw, 22, COL.inset, 0.55 + st.hover * 0.2, 6)
    rstroke(cx, cy, cw, 22, COL.cyan, 0.1 + st.reveal * 0.4, 6, 1)
    local hasSel = s.Multi and shownVal ~= "None" or (not s.Multi and el.state.value)
    text(cx + 8, cy + 5, 12, hasSel and COL.label or COL.dim, shownVal,
        0.85 + st.hover * 0.15)
    icon("chevron", cx + cw - 8, cy + 11, 9, COL.cyan, 0.8)

    if (st.reveal or 0) > 0.01 then
        local ih = 26
        -- SEARCH BAR (s.Search): текст-поле поверх списка, фильтрует оп��ии вжи��ую.
        -- Отдельное focus-поле на el.searchField; печат�� допи��ывает state.text
        -- (общий механизм Engine.textFocus), читаем query каждый кадр.
        local searchH = s.Search and 30 or 0
        local ly = cy + 26 + searchH        -- список начинается ниже поиска
        el.searchField = el.searchField or {
            state = { text = "" }, hitKey = el.key .. "/search", settings = {},
        }
        local sf = el.searchField
        local searching = Engine.textFocus == sf
        local query = s.Search and sf.state.text:lower() or ""
        local sKey = el.key .. "/search"
        if searchH > 0 then
            hit(sKey, cx, cy + 26, cw, searchH - 4, Z.OVERLAY, false, true)
            if Engine.clicked(sKey) and not searching then Engine.textFocus = sf end
        end
        -- отфильтр��ванные опции (подстрока, без регистра)
        local filtered = {}
        for _, opt in ipairs(s.Options or {}) do
            if query == "" or tostring(opt):lower():find(query, 1, true) then
                filtered[#filtered + 1] = opt
            end
        end

        local rows = {}
        for i, opt in ipairs(filtered) do
            local iy = ly + (i - 1) * ih
            local ik = el.key .. "/i" .. i
            hit(ik, cx, iy, cw, ih, Z.OVERLAY, false, true)  -- ignoreClip: см. hit()
            rows[i] = { y = iy, opt = opt, key = ik }
            if Engine.clicked(ik) then
                if s.Multi then
                    el.state.multi[opt] = not el.state.multi[opt]
                    if s.Callback then pcall(s.Callback, el.state.multi) end
                else
                    el.state.value = opt
                    st.open = false
                    Engine.textFocus = nil
                    if s.Callback then pcall(s.Callback, opt) end
                end
            end
        end
        local grow = st.reveal
        local listH = math.max(#filtered, 1) * ih + 8
        deferOverlay(function()
            local vh = (searchH + listH) * grow
            rrect(cx - 1, cy + 25, cw + 2, vh, COL.app, 0.4 * grow, 9)
            rrect(cx, cy + 22, cw, vh, COL.panel, 0.98, 9)
            rstroke(cx, cy + 22, cw, vh, COL.cyan, 0.3, 9, 1)
            -- строка по����ка. Прозрачность умножаем на grow (=st.reveal), поэтому
            -- при закрытии она ПЛАВНО гасн��т вмест�� с панелью, а не пропадает резко.
            if searchH > 0 then
                local siy = cy + 26
                local g = grow
                rrect(cx + 4, siy, cw - 8, searchH - 6, COL.inset, 0.7 * g, 6)
                rstroke(cx + 4, siy, cw - 8, searchH - 6, COL.cyan, (searching and 0.5 or 0.15) * g, 6, 1)
                icon("search", cx + 14, siy + (searchH - 6) * 0.5, 11, COL.cyan, 0.8 * g)
                local caret = (searching and math.floor(os.clock() * 2) % 2 == 0) and "|" or ""
                local qt = sf.state.text
                local ph = (qt == "" and not searching) and "Search..." or (qt .. caret)
                text(cx + 26, siy + 5, 11.5,
                    (qt == "" and not searching) and COL.dim or COL.text, ph, 0.9 * g)
            end
            local bottom = cy + 22 + vh
            for i, rw in ipairs(rows) do
                if rw.y + ih <= bottom then
                    local hov = Engine.isHover(rw.key) and 1 or 0
                    local sel = s.Multi and el.state.multi[rw.opt] or (rw.opt == el.state.value)
                    if sel then
                        rrect(cx + 4, rw.y + 2, cw - 8, ih - 4, COL.cyan, 0.16, 7)
                        rstroke(cx + 4, rw.y + 2, cw - 8, ih - 4, COL.cyan, 0.4, 7, 1)
                    elseif hov > 0 then
                        rrect(cx + 4, rw.y + 2, cw - 8, ih - 4, COL.text, 0.06 * hov, 7)
                    end
                    text(cx + 12, rw.y + 7, 12,
                        (sel or hov > 0) and COL.text or COL.label, rw.opt,
                        sel and 1 or (0.78 + hov * 0.18))
                    if sel then
                        icon("check", cx + cw - 14, rw.y + ih * 0.5, 12, COL.cyan, 1)
                    end
                end
            end
            -- пусто после фильтра
            if #rows == 0 then
                text(cx + 12, ly + 7, 12, COL.dim, "No matches", 0.7)
            end
        end)
    end
    return y + (el._rowH or M.row)
end

elDraw.Colorpicker = function(el, x, y, w, dt)
    local s = el.settings
    rowLabel(x + 14, y, s.Name or "Color")
    local sw = 36
    local sx = x + w - 14 - sw
    local sy = y + M.row * 0.5 - 10
    hit(el.key, sx, sy, sw, 20)
    local st = stateOf(el.key)
    if Engine.clicked(el.key) then st.open = not st.open end
    st.reveal = approach(st.reveal or 0, st.open and 1 or 0, dt, 18)
    local c = el.state.color
    -- HSV-состояние поповера инициализируем из текущего ��в��та один раз.
    if not el.state.hsv then
        local h, sv, v = c:ToHSV()
        el.state.hsv = { hue = h, sat = sv, val = v }
    end
    rrect(sx, sy, sw, 20, c, 1, 5)
    rstroke(sx, sy, sw, 20, COL.text, 0.2, 5, 1)

    if (st.reveal or 0) > 0.01 then
        -- Поповер с ПАЛИТРОЙ: SV-квадрат + hue-полоса + превью/hex.
        local pw, ph = 226, 150
        local px = fit(sx + sw - pw, x + 8, x + w - pw - 8)
        local py = sy + 24
        local sq = 110
        local sqx, sqy = px + 14, py + 14
        local hueX = sqx + sq + 12
        local hueW = 18
        -- ВВОД -- в ГЛАВНОМ проходе (только когда попап раскрыт), чтобы hit-области
        -- палитры попали в liveHits и pick() их находил (иначе клик закрывал попап).
        if (st.reveal or 0) > 0.6 then
            local nc, ch = colorFieldHit(el.key .. "/pick", sqx, sqy, sq, hueX, hueW, el.state.hsv)
            if ch then
                el.state.color = nc
                if s.Callback then pcall(s.Callback, nc, el.state.alpha) end
            end
        end
        -- ОТРИСОВКА -- отложенно, поверх соседних строк.
        deferOverlay(function()
            local grow = st.reveal
            if grow < 0.6 then
                rrect(px, py, pw, ph * grow, COL.panel, 0.98, 10)
                rstroke(px, py, pw, ph * grow, COL.cyan, 0.3, 10, 1)
                return
            end
            rrect(px, py, pw, ph, COL.panel, 0.98, 10)
            rstroke(px, py, pw, ph, COL.cyan, 0.3, 10, 1)
            colorField(el.key .. "/pick", sqx, sqy, sq, hueX, hueW, el.state.hsv)
            -- превью + hex справа
            local pvx = hueX + hueW + 12
            local pvw = px + pw - 14 - pvx
            rrect(pvx, sqy, pvw, 34, el.state.color, 1, 7)
            rstroke(pvx, sqy, pvw, 34, COL.text, 0.16, 7, 1)
            local cc = el.state.color
            local hx = string.format("#%02X%02X%02X",
                floor(cc.R*255+0.5), floor(cc.G*255+0.5), floor(cc.B*255+0.5))
            text(pvx + pvw * 0.5 - measure(hx, 11).X * 0.5, sqy + 42, 11, COL.label, hx, 0.95)
        end)
    end
    return y + M.row
end

elDraw.Custom = function(el, x, y, w, dt)
    local h = el.settings.Height or 40
    if el.settings.Draw then pcall(el.settings.Draw, x, y, w, h, dt) end
    return y + h
end

-- Высота элемента (для авто-высоты секции). Держим в синхроне с elDraw.
-- Базовые высоты (при scale=1). Row-элементы читают M.row ЖИВЬЁМ, чтобы п��и
-- смене THEME.scale (см. applyFontScale) шаг стро�� рос вместе с кегл��м и текст
-- не на��зжал. Не-row высоты ма��штабируем тем же мягким коэффициентом.
local elHeightBase = {
    Divider = 16, Button = 40,
}
-- Slider больше НЕ row-эле��ент: он стоечный (подпись сверху, контрол ниже) ->
-- считаем его высоту через sliderMetrics (совпадает с elDraw.Slider).
local ROW_KINDS = {
    Toggle = true, Input = true, Keybind = true,
    Dropdown = true, Colorpicker = true,
}
-- w = ширина, на которой элемент реально рисуется (= ширина секции). Нужна для
-- перен��симого текста (Label/Header/Paragraph) и стоечного слайдера -> высота
-- секции точно совпадает с нарисованным, ничего не обрезается.
local function elemHeight(el, w)
    w = w or (M and M.contentW) or 300
    if el.kind == "Custom" then return el.settings.Height or 40 end
    if el.kind == "Spacer" then return (el.settings and el.settings.Size) or 12 end
    if el.kind == "Slider" or el.kind == "ScaleSlider" then
        local _, _, rowH = sliderMetrics()
        return rowH
    end
    if el.kind == "Label" then
        local _, _, _, _, total = labelMetrics(el, w)
        return total
    end
    if el.kind == "Header" then
        local _, _, total = headerMetrics(el, w)
        return total
    end
    if el.kind == "Paragraph" then
        local _, _, _, _, total = paraMetrics(el, w)
        return total
    end
    if el.kind == "Divider" then
        local s = el.settings or {}
        return (s.Text or s.Name) and 24 or 20
    end
    if el.kind == "Button" then
        if Engine.sheet then return 48 end
    end
    if el.kind == "Toggle" or el.kind == "Input" or el.kind == "Dropdown" then
        local ctrlW = (el.kind == "Toggle") and 46 or 150
        local name = el.settings and el.settings.Name or ""
        local _, _, rowH = rowLayout(0, 0, w, name, ctrlW)
        if el.kind == "Toggle" and Engine.sheet then
            local desc = el.settings and el.settings.Description
            if desc and desc ~= "" then rowH = rowH + 16 end
        end
        return rowH
    end
    if el.kind == "Keybind" and Engine.sheet then
        return math.max(M.row, 44)
    end
    if ROW_KINDS[el.kind] then return M.row end
    local base = elHeightBase[el.kind]
    if base then
        local sc = (THEME and THEME.scale) or 1
        return math.floor(base * (1 + (sc - 1) * 0.6))
    end
    return M.row
end

----------------------------------------------------------------------------
-- РЕНДЕР СЕКЦИИ (титульная панел�� с элементами) И ВКЛАДКИ
----------------------------------------------------------------------------
-- PERF: общая функция вместо создания closure каждый кадр для каждой секции.
local function rotatedPoint(cx, cy, dist, angle)
    local rad = math.rad(angle)
    return cx + dist * math.cos(rad), cy + dist * math.sin(rad)
end

-- PERF: переиспользуемый буфер для shown-списка вместо аллокации каждый кадр.
local shownBuffer = {}
local function drawBuiltSection(sec, x, y, w, dt, nq)
    nq = nq or ""
    local headH = Engine.sheet and 44 or 34
    local secTitleMatch = nq ~= "" and (normSearch(sec.title):find(nq, 1, true) ~= nil)

    -- При активном поиске секция без совпадений (в заголовке или элементах)
    -- полностью пропускается.
    if nq ~= "" and not secTitleMatch then
        local any = false
        for _, el in ipairs(sec.elements) do
            if el.visible ~= false and normSearch(elemName(el)):find(nq, 1, true) then any = true; break end
        end
        if not any then return y end
    end

    -- Считаем высоту тела только по ВИДИМЫМ (с учётом фильтра) элементам.
    for i = 1, #shownBuffer do shownBuffer[i] = nil end
    local fullBody = 0
    for _, el in ipairs(sec.elements) do
        if el.visible ~= false and elemMatches(el, nq, secTitleMatch) then
            shownBuffer[#shownBuffer + 1] = el
            fullBody = fullBody + elemHeight(el, w)
        end
    end

    -- СВОРАЧИВАНИЕ: ЛКМ или ПКМ п�� ш��пке. При активном поиске с��кция всегда
    -- раскрыта, чтобы результаты были видны.
    local hkey = "sec/" .. (sec.title or tostring(sec))
    hit(hkey, x, y, w, headH)
    local hhover = approach(stateOf(hkey).h or 0, Engine.isHover(hkey) and 1 or 0, dt, 16)
    stateOf(hkey).h = hhover
    if Engine.clicked(hkey) or Engine.rightClicked(hkey) then sec.collapsed = not sec.collapsed end
    local wantOpen = (nq ~= "") or (not sec.collapsed)
    sec.open = approach(sec.open or 1, wantOpen and 1 or 0, dt, 16)
    local ez = sec.open * sec.open * (3 - 2 * sec.open)   -- smoothstep

    local bodyH = (fullBody + 10) * ez
    local h = headH + bodyH
    rrect(x, y, w, h, COL.panel, 1, M.cardR)

        -- PERF: статичная сетка во всю секцию. Раньше была переливающаяся анимация
        -- с sin() и десятками rrect — отключена для FPS. Теперь простой фон-паттерн.
        local sectionGrid = app.custom.sectionGrid ~= false
        if sectionGrid and bodyH > 6 then
            local gstep = 64
            for gx = x + gstep, x + w - 1, gstep do
                rrect(gx, y + headH, 1, h - headH, COL.cyan, 0.02 * ez, 0)
            end
            for gy = y + headH + gstep, y + h - 2, gstep do
                rrect(x + 1, gy, w - 2, 1, COL.cyan, 0.015 * ez, 0)
            end
        end

    -- Шапка: ровная заливка + п��дсветка при наведении (сигнал «кликабельно»).
    rrect(x, y, w, headH, COL.panel:Lerp(COL.cyan, 0.05 + hhover * 0.12), 1, M.cardR)

    local cy2 = y + headH * 0.5

    -- КНОПКА-ШЕВРОН ��лева: симметричный «v» (открыто) -> «>» (свёрнуто),
    -- вращается вокруг СВОЕГО ВИ��УАЛЬНОГО ЦЕНТРА (раньш�� pivot был выше centroid
    -- галочки -> кнопка казалась кривой, п.4). Точки центрированы по вертик��ли.
    local cxr = x + 17
    rrect(cxr - 9, cy2 - 9, 18, 18, COL.cyan, 0.10 + hhover * 0.12, 9)
    local rot = -(1 - ez) * (math.pi * 0.5)
    local cos_r, sin_r = math.cos(rot), math.sin(rot)
    local s = 3.6
    local px, py = -s, -s * 0.42
    local ax, ay = cxr + (px * cos_r - py * sin_r), cy2 + (px * sin_r + py * cos_r)
    px, py = 0, s * 0.42
    local bx2, by2 = cxr + (px * cos_r - py * sin_r), cy2 + (px * sin_r + py * cos_r)
    px, py = s, -s * 0.42
    local dx, dy = cxr + (px * cos_r - py * sin_r), cy2 + (px * sin_r + py * cos_r)
    Engine.line(ax, ay, bx2, by2, COL.cyan, 0.95, 1.7)
    Engine.line(bx2, by2, dx, dy, COL.cyan, 0.95, 1.7)

    -- ИКОНКА СЕКЦИИ (если задана) -> потом название (icon-first, п.11). Шеврон-
    -- бэйдж занимает x+8..x+26, поэтому иконку СДВИГАЕМ дальше (центр x+44, бэйдж
    -- x+34..x+54) -- раньш�� они налезали друг на друга (п.5). Без иконки текст
    -- идёт сразу после шеврона.
    local tx = x + 36
    if sec.icon then
        local isz, ix0 = 20, x + 44
        rrect(ix0 - isz * 0.5, cy2 - isz * 0.5, isz, isz, COL.cyan, 0.12, 6)
        icon(sec.icon, ix0, cy2, 13, COL.cyan, 0.95)
        tx = x + 62
    end
    text(tx, cy2 - 7, 12.5, COL.text, sec.title or "Section", 1)

    if bodyH > 6 then rrect(x + 8, y + headH, w - 16, 1, COL.text, 0.06 * ez, 0) end
    rstroke(x, y, w, h, COL.text, 0.05, M.cardR, 1)

    if ez > 0.04 then
        Engine.pushClip(x, y + headH, w, bodyH)
        local ry = y + headH + 4
        for _, el in ipairs(shownBuffer) do
            local fn = elDraw[el.kind]
            if fn then ry = fn(el, x, ry, w, dt) end
        end
        Engine.popClip()
    end
    return y + h + 14
end

-- Полноши��и��ный рендер вкладк��: левая/правая колонки секций (MacLib-раскладка).
local function drawBuiltTab(tab, cx, fy, cw, fh, dt)
    if tab.fullPage then
        -- Полностраничный контент сам возвращает нижнюю кромку (для скро��ла),
        -- ��ибо fy, если страница нескроллируемая (например 3D-сцена).
        local r = tab.fullPage(cx, fy, cw, fh, dt)
        return type(r) == "number" and r or fy
    end
    local pad = M.pad
    local nq = Engine.normSearch(app.query or "")
    if Engine.sheet then
        local colW = math.max(40, cw - pad * 2)
        local x0 = cx + pad
        local y = fy + 10 - app.scrollY
        for _, sec in ipairs(tab.sections) do
            y = drawBuiltSection(sec, x0, y, colW, dt, nq)
        end
        return y
    end
    local gap = 16
    local colW = (cw - pad * 2 - gap) * 0.5
    local leftX = cx + pad
    local rightX = leftX + colW + gap
    local ly = fy + 14 - app.scrollY
    local ry = fy + 14 - app.scrollY
    for _, sec in ipairs(tab.sections) do
        if sec.side == "Right" then
            ry = drawBuiltSection(sec, rightX, ry, colW, dt, nq)
        else
            ly = drawBuiltSection(sec, leftX, ly, colW, dt, nq)
        end
    end
    return math.max(ly, ry)
end
Engine.drawBuiltTab = drawBuiltTab

----------------------------------------------------------------------------
-- BUILDER: Window -> TabGroup -> Tab -> Section -> элементы
----------------------------------------------------------------------------
-- Определяем MacLib-совме��тимый Class хендла по доступным геттерам (у нас нет
-- отдельного поля kind на F). Порядок важен: Toggle раньше Slider (у Toggle
-- ес��ь GetState и нет GetValue), Colorpicker раньше остальных (GetColor).
local function inferClass(h)
    if h.Class then return h.Class end
    if h.GetState   then return "Toggle" end
    if h.GetColor   then return "Colorpicker" end
    if h.GetKeybind then return "Keybind" end
    if h.GetText    then return "Input" end
    if h.GetValue   then
        return (h.Settings and h.Settings.Options) and "Dropdown" or "Slider"
    end
    return "Button"
end

local function bindFlag(flag, ctrl)
    if flag then
        -- проставляем .Class один раз при регистрации -> GetOptions/итерация
        -- реестра дают el.Class как в MacLib, без правки каждого фабричного метода.
        if not ctrl.Class then ctrl.Class = inferClass(ctrl) end
        Nova.Flags[flag] = ctrl
        if ctrl.Settings and ctrl.Settings.ForceAutoLoad then
            local original = ctrl.Settings.Callback
            ctrl.Settings.Callback = function(...)
                if original then original(...) end
                if Nova.FALSave then pcall(Nova.FALSave, Nova, flag, ctrl) end
            end
            if ctrl.Class == "Keybind" then
                local oldBind = ctrl.Settings.onBinded
                ctrl.Settings.onBinded = function(bind)
                    if oldBind then oldBind(bind) end
                    if Nova.FALSave then pcall(Nova.FALSave, Nova, flag, ctrl) end
                end
            end
            if Nova.FALLoad then
                task.defer(function() pcall(Nova.FALLoad, Nova, flag, ctrl) end)
            end
        end
    end
end

-- MacLib-совместимое глобальное API опций: Nova.Options -- та же таблица флагов
-- (flag -> handle элемента). Nova:GetOption(flag) достаёт handle по флагу.
Nova.Options = Nova.Flags
function Nova:GetOption(flag) return Nova.Flags[flag] end
function Nova:GetFlags() return Nova.Flags end
-- Быстрый доступ к «значению» флага независимо от типа элемента.
function Nova:GetFlagValue(flag)
    local h = Nova.Flags[flag]
    if not h then return nil end
    if h.GetState then return h:GetState() end
    if h.GetValue then return h:GetValue() end
    if h.GetText then return h:GetText() end
    if h.GetColor then return h:GetColor() end
    if h.GetKeybind then return h:GetKeybind() end
    return nil
end

-- Глобальные MacLib-хелперы для мобильной кнопки Keybind (по flag).
function Nova:ShowKeybindButton(flag, state)
    local h = Nova.Flags[flag]
    if h and h.SetMobileButtonVisibility then h:SetMobileButtonVisibility(state ~= false) end
end
Nova.SetMobileKeybindVisible = Nova.ShowKeybindButton
function Nova:SimulateKeybindPress(flag)
    local h = Nova.Flags[flag]
    if h and h.Settings and h.Settings.Callback then
        pcall(h.Settings.Callback, h.GetKeybind and h:GetKeybind() or nil)
    end
end
function Nova:StyleKeybindButton(flag, props)
    local h = Nova.Flags[flag]
    if not h or not props then return end
    if props.Image and h.SetMobileImage then h:SetMobileImage(props.Image) end
    if props.Visible ~= nil and h.SetMobileButtonVisibility then h:SetMobileButtonVisibility(props.Visible) end
    -- размер/прозрачность FAB храним в настройках элемента -> читает мобильный слой.
    h.Settings.MobileButtonSize = props.Size or h.Settings.MobileButtonSize
    h.Settings.MobileButtonTransparency = props.BackgroundTransparency or h.Settings.MobileButtonTransparency
end

--==========================================================================--
-- ПРОДВИНУТЫЕ API (перенос из MacLib, адаптировано под immediate-mode).
-- NOVA рисует всё через DrawingImmediate -> у элементов НЕТ Instance-дерева.
-- Поэтому Instance-ориентированные части MacLib (RegisterElement с Frame,
-- StyleElement по потомкам) портированы в DI-��квиваленты, а не буквально.
--==========================================================================--

-- Универсальный сеттер значения по Class (имена сеттеров у нас Update*/Set*).
local function setFlagByClass(h, v)
    local c = h.Class or inferClass(h)
    if c == "Toggle" and h.UpdateState then h:UpdateState(v); return true end
    if (c == "Slider" or c == "ScaleSlider") and h.UpdateValue then h:UpdateValue(v); return true end
    if c == "Input" and h.SetText then h:SetText(v); return true end
    if c == "Keybind" and h.SetKeybind then h:SetKeybind(v); return true end
    if c == "Dropdown" and h.SetValue then h:SetValue(v); return true end
    if c == "Colorpicker" and h.SetColor then
        if type(v) == "table" and not (typeof and typeof(v) == "Color3") then
            if v.color then h:SetColor(v.color) end
            if v.alpha ~= nil and h.SetAlpha then h:SetAlpha(v.alpha) end
        else
            h:SetColor(v)
        end
        return true
    end
    -- запасной путь: пробуем любой изве��тный сеттер
    if h.UpdateState then h:UpdateState(v); return true end
    if h.UpdateValue then h:UpdateValue(v); return true end
    if h.SetValue then h:SetValue(v); return true end
    if h.SetText then h:SetText(v); return true end
    if h.SetColor then h:SetColor(v); return true end
    if h.SetKeybind then h:SetKeybind(v); return true end
    return false
end

-- Установить значение одного флага (уважает silent -> без Callback).
function Nova:SetFlagValue(flag, v, silent)
    local h = Nova.Flags[flag]; if not h then return false end
    if silent and h.Settings then
        local cb = h.Settings.Callback
        h.Settings.Callback = nil
        local ok = setFlagByClass(h, v)
        h.Settings.Callback = cb
        return ok
    end
    return setFlagByClass(h, v)
end

-- BatchSet({ flag = value, ... }, silent?) -- много значений за раз.
function Nova:BatchSet(map, silent)
    if type(map) ~= "table" then return end
    for flag, v in pairs(map) do Nova:SetFlagValue(flag, v, silent) end
end

-- GetOptions() -- безопасная копия реестра для итерации.
function Nova:GetOptions()
    local copy = {}
    for k, v in pairs(Nova.Flags) do copy[k] = v end
    return copy
end
Nova.GetFlagsCopy = Nova.GetOptions

-- RemoveOption(flag) -- убрать эл���мент из реестра, скрыть его UI и снять
-- вс�� подписки WatchOption для этого флага.
function Nova:RemoveOption(flag)
    local h = Nova.Flags[flag]; if not h then return false end
    if h.SetVisibility then pcall(h.SetVisibility, h, false) end
    if h._el then h._el.visible = false; h._el.removed = true end
    Nova.Flags[flag] = nil
    Nova._watchers[flag] = nil
    Nova._watchLast[flag] = nil
    return true
end

-- ----- WatchOption: подписка на изменение значения без замены Callback -----
-- В immediate-mode нет единой точки set (знач��ние меняют и юзер, и код), поэтому
-- ��овим изменения ПОЛЛИНГОМ раз в кадр: сравниваем текущее значение с прошлым.
Nova._watchers  = Nova._watchers or {}
Nova._watchLast = Nova._watchLast or {}

local function valEq(a, b)
    if a == b then return true end
    if typeof and typeof(a) == "Color3" and typeof(b) == "Color3" then
        return math.abs(a.R - b.R) < 1e-4 and math.abs(a.G - b.G) < 1e-4
            and math.abs(a.B - b.B) < 1e-4
    end
    if type(a) == "table" and type(b) == "table" then
        for k, v in pairs(a) do if b[k] ~= v then return false end end
        for k, v in pairs(b) do if a[k] ~= v then return false end end
        return true
    end
    return false
end

function Nova:WatchOption(flag, cb)
    if type(cb) ~= "function" then return function() end end
    Nova._watchers[flag] = Nova._watchers[flag] or {}
    table.insert(Nova._watchers[flag], cb)
    Nova._watchLast[flag] = Nova:GetFlagValue(flag)   -- базлайн -> не стреляем сразу
    return function()                                  -- функция отписки
        local list = Nova._watchers[flag]; if not list then return end
        for i = #list, 1, -1 do if list[i] == cb then table.remove(list, i) end end
        if #list == 0 then Nova._watchers[flag] = nil end
    end
end

function Nova:_pollWatchers()
    for flag, list in pairs(Nova._watchers) do
        if list[1] then
            local cur = Nova:GetFlagValue(flag)
            if not valEq(cur, Nova._watchLast[flag]) then
                Nova._watchLast[flag] = cur
                local h = Nova.Flags[flag]
                local alpha = (h and h.GetAlpha) and h:GetAlpha() or nil
                for i = 1, #list do pcall(list[i], cur, alpha) end
            end
        end
    end
end
Engine.onDraw(function() Nova:_pollWatchers() end)

-- SetNotifyScale(v) -- масштаб тостов; drawToasts читает Engine.notifyScale
-- каждый кадр, поэтому уже видимые уведомления твинятся в реальном ��ремени.
function Nova:SetNotifyScale(v)
    v = tonumber(v) or 1
    Engine.notifyScale = v
    if app and app.custom then app.custom.notifyScale = v end
    return v
end

-- ----- Extend / Hook: расширение самого объекта Nova -----
function Nova:Extend(name, fn)
    if type(name) == "string" and type(fn) == "function" then Nova[name] = fn end
end

function Nova:Hook(name, hookFn)
    local orig = Nova[name]
    if type(orig) ~= "function" or type(hookFn) ~= "function" then return false end
    Nova[name] = function(self, ...) return hookFn(orig, self, ...) end
    return true
end

-- ----- Section-ра����ирения (PatchSection/ExtendSection) -----
-- Хранилище методов, которые подмешиваются в КАЖДУЮ секцию при её создании
-- в билдере (см. Nova:Window). Работает для секций, созданны�� ПОСЛЕ регистрации
-- (обычный паттерн MacLib: регистрируешь до построения UI).
Nova._sectionExt = Nova._sectionExt or {}
function Nova:PatchSection(name, fn)
    if type(name) == "string" and type(fn) == "function" then
        Nova._sectionExt[name] = fn
    end
end
Nova.ExtendSection = Nova.PatchSection

-- ----- RegisterElement (DI-эквивалент) -----
-- MacLib-версия строит Instance в Frame секции. У нас Frame'ов нет, поэт��му
-- кастомный элемент = DI-функция отрисовки + собственное состояние. def:
--   { Height=число, Class=строка?, Default=любое,
--     Draw = function(px,py,pw,ph,dt, api, settings, state) ... end }
-- api = { Get(), Set(v) }. Флагованный элемент участвует в Save/Load через
-- GetValue/SetValue (как обычные элементы).
Nova._customEls = Nova._customEls or {}
function Nova:RegisterElement(typeName, def)
    if type(typeName) ~= "string" or type(def) ~= "table" then return false end
    Nova._customEls[typeName] = def
    -- авто-патч: section:<typeName>(settings, flag)
    Nova:PatchSection(typeName, function(sectionSelf, settings, flag)
        settings = settings or {}
        local state = { value = (settings.Default ~= nil) and settings.Default or def.Default }
        local api = {}
        function api.Get() return state.value end
        function api.Set(_, v)
            state.value = v
            if settings.Callback then pcall(settings.Callback, v) end
        end
        local handle = sectionSelf:CreateCustomElement({
            Height = settings.Height or def.Height or 44,
            Draw = function(px, py, pw, ph, dt)
                if def.Draw then
                    pcall(def.Draw, px, py, pw, ph, dt, api, settings, state)
                end
            end,
        })
        local F = handle or {}
        F.Settings = settings
        F.Class = def.Class or typeName
        function F:GetValue() return state.value end
        function F:SetValue(v) api.Set(nil, v) end
        function F:SetVisibility(vis) if F._el then F._el.visible = vis end end
        if flag then Nova.Flags[flag] = F end
        return F
    end)
    return true
end

-- CreateCustomElement на уровне Nova -> совместимость с MacLib-вызовом
-- (section передаётся первым аргументом).
function Nova:CreateCustomElement(section, typeName, settings, flag)
    local patch = Nova._sectionExt[typeName]
    if patch then return patch(section, settings, flag) end
    return section:CreateCustomElement(settings)
end

-- AddPlugin(callback, section) -- отдаём секцию плагину в отдельном потоке.
function Nova:AddPlugin(callback, section)
    if type(callback) ~= "function" then return end
    task.spawn(function() pcall(callback, section) end)
end

-- StyleElement(flag, props) -- в DI нет дерева Instance, поэтому применяем
-- ОСМЫСЛЕННЫЕ для DI свойства (цвет у Colorpicker), остальное складываем в
-- h._style для чтения кастомными Draw'ами.
function Nova:StyleElement(flag, props)
    local h = Nova.Flags[flag]
    if not h or type(props) ~= "table" then return false end
    if props.Color and h.SetColor then pcall(h.SetColor, h, props.Color) end
    h._style = h._style or {}
    for k, v in pairs(props) do h._style[k] = v end
    return true
end

-- ----- Preloader: асинхронная загрузка плагинов/расширений -----
Nova._loaded      = Nova._loaded or {}
Nova._loadWaiters = Nova._loadWaiters or {}

function Nova:OnLoad(name, cb)
    if type(cb) ~= "function" then return end
    if Nova._loaded[name] ~= nil then pcall(cb, Nova._loaded[name]); return end
    Nova._loadWaiters[name] = Nova._loadWaiters[name] or {}
    table.insert(Nova._loadWaiters[name], cb)
end

function Nova:IsLoaded(name) return Nova._loaded[name] ~= nil end

function Nova:Preloader(module, opts)
    local onLoad, onError, name, win
    if type(opts) == "function" then
        onLoad = opts                                  -- старый API (только callback)
    elseif type(opts) == "table" then
        onLoad, onError = opts.onLoad, opts.onError
        name, win = opts.Name, opts.Window
    end
    task.spawn(function()
        local element
        local ok, err = pcall(function()
            if type(module) == "function" then
                element = module({
                    Nova = Nova, MacLib = Nova, Options = Nova.Flags,
                    Window = win, Name = name,
                })
            else
                element = module                       -- уже вызванный результат/таблица
            end
        end)
        if not ok then
            if onError then pcall(onError, err) else warn("[NOVA] Preloader:", err) end
            return
        end
        if name then
            Nova._loaded[name] = (element ~= nil) and element or true
            local waiters = Nova._loadWaiters[name]
            if waiters then
                for _, cb in ipairs(waiters) do pcall(cb, element) end
                Nova._loadWaiters[name] = nil
            end
        end
        if onLoad then pcall(onLoad, element) end
    end)
end

function Nova:Window(Settings)
    Settings = Settings or {}
    -- УТЕЧКА (исправлено): по��торный вызов :Window() (скрипт перезапустили без
    -- рестарта экзекутора) РАНЬШЕ накапл��вал старые вкладки/кейбинды/флаги в
    -- модуль-таблицах (model.tabs, keybindEls, Nova.Flags) -> он�� жили вечно.
    -- Чистим с��стояние с��орки перед новым построением UI.
    for k in pairs(model.tabs) do model.tabs[k] = nil end
    if model.tabByName then for k in pairs(model.tabByName) do model.tabByName[k] = nil end end
    for k in pairs(Engine.keybindEls or {}) do Engine.keybindEls[k] = nil end
    for k in pairs(Nova.Flags) do Nova.Flags[k] = nil end
    app.nav = nil

    model.window = Settings
    model.hasBuilt = true
    -- клавиша перек��ючения меню из настроек окна (если задана)
    Engine.toggleKey = Settings.ToggleKey or Settings.Keybind or Engine.toggleKey
    local WindowFunctions = { Settings = Settings }

    function WindowFunctions:UpdateTitle(t) Settings.Title = t end
    function WindowFunctions:UpdateSubtitle(t) Settings.Subtitle = t end
    function WindowFunctions:SelectTab(name)
        -- было: индексировали model.tabs по имени (числовой массив) -> всегда nil.
        -- tabByName -- корректная мапа имя->таб.
        if model.tabByName and model.tabByName[name] then app.nav = name end
    end

    -- === Управление окном (MacLib-совме��тимо + расширения Nova) ===
    -- Показать/спрятать/переключить меню (та же анимация noise-dissolve).
    function WindowFunctions:Show() Engine.setVisible(true) end
    function WindowFunctions:Hide() Engine.setVisible(false) end
    function WindowFunctions:SetVisible(v) Engine.setVisible(v and true or false) end
    function WindowFunctions:Toggle() Engine.toggle() end
    function WindowFunctions:IsOpen() return Engine.visible and true or false end
    -- Клавиша открытия/закрыт��я меню на лету.
    function WindowFunctions:SetToggleKey(key)
        Settings.ToggleKey = key
        Engine.toggleKey = key
    end
    WindowFunctions.SetKeybind = WindowFunctions.SetToggleKey
    -- Колбэк на закрытие/выгрузку (MacLib :OnClose аналог).
    function WindowFunctions:OnClose(fn) Engine.onClose = fn end
    -- П��лная выгрузка библиотеки: гасит рендер, чистит хуки/коннекты.
    function WindowFunctions:Unload()
        if Engine.onClose then pcall(Engine.onClose) end
        if Engine.unloadFx then pcall(Engine.unloadFx) end
        Engine.setVisible(false)
        Engine.destroyed = true
    end
    WindowFunctions.Destroy = WindowFunctions.Unload
    -- Список имён ��кладок (для про��раммной навигации).
    function WindowFunctions:GetTabs()
        local names = {}
        for _, t in ipairs(model.tabs) do names[#names + 1] = t.name end
        return names
    end
    function WindowFunctions:GetActiveTab() return app.nav end
    -- Уведо��ление прямо из хендл�� окна (удобный шорткат).
    function WindowFunctions:Notify(s) return Nova:Notify(s) end

    -- === Масштаб / размер (MacLib-совместимо) ===
    function WindowFunctions:SetScale(v)
        v = math.clamp(tonumber(v) or 1, 0.8, 1.4)
        if Engine.setUiScale then Engine.setUiScale(v) end
        return v
    end
    function WindowFunctions:GetScale() return Engine.uiScaleTarget or 1 end
    function WindowFunctions:GetSize()
        local s = Engine.WIN and Engine.WIN.size
        return s and { X = s.X, Y = s.Y } or { X = 0, Y = 0 }
    end
    -- === Нотификации на уровне окна (шорткаты глобальных ме��одов) ===
    function WindowFunctions:SetNotificationsState(v) return Nova:SetNotificationsEnabled(v) end
    function WindowFunctions:GetNotificationsState() return Nova:NotificationsEnabled() end
    function WindowFunctions:SetNotificationOpacity(o) return Nova:SetNotificationOpacity(o) end
    -- MacLib называет колбэк выгрузки onUnloaded; держим как алиас OnClose.
    function WindowFunctions:onUnloaded(fn) Engine.onClose = fn end

    function WindowFunctions:TabGroup()
        local TabGroupFunctions = {}
        function TabGroupFunctions:Tab(TabSettings)
            TabSettings = TabSettings or {}
            local tab = {
                name = TabSettings.Name or ("Tab" .. (#model.tabs + 1)),
                icon = TabSettings.Icon or TabSettings.Image or "folder",
                group = TabSettings.Group,        -- имя группы для сайдбара (п.1)
                sections = {},
                fullPage = nil,
            }
            model.tabs[#model.tabs + 1] = tab
            model.tabByName = model.tabByName or {}
            model.tabByName[tab.name] = tab
            if #model.tabs == 1 then app.nav = tab.name end

            local TabFunctions = {}
            -- Расширение Nova: полностраничный кастомный контент (для Render/Customize).
            function TabFunctions:CustomPage(fn) tab.fullPage = fn end

            -- СИСТЕМНЫЕ ВСТАВКИ библиотечного контента в пользовательский таб:
            -- InsertUI      -- все секции настроек UI (Scale/Notify/Behaviour/
            --                  Keybind List/Effects/Particles/Mobile) в ЭТОТ таб.
            -- InsertGeometry -- полностраничная 3D-сцена «Geometry» (демо-фича).
            -- Билдеры (Engine.buildUISettings / Engine.buildGeometry) объявлены в
            -- этом же чанке ниже -> к моменту вызова из демо всё определено.
            function TabFunctions:InsertUI()
                if Engine.buildUISettings then Engine.buildUISettings(self) end
                return self
            end
            function TabFunctions:InsertGeometry()
                if Engine.buildGeometry then Engine.buildGeometry(self) end
                return self
            end
            -- InsertConfigSection / InsertCustomizationSection -- полностраничные
            -- библиотечные страницы (менеджер конфигов и редактор темы). configPage/
            -- customPage -- локальные функции библиотеки, поэтому внешний скрипт не
            -- может дотянуться до них напрямую -> отдаём через публичные методы.
            function TabFunctions:InsertConfigSection()
                self:CustomPage(function(cx, fy, cw, fh, dt) return configPage(cx, fy, cw, dt) end)
                return self
            end
            function TabFunctions:InsertCustomizationSection()
                self:CustomPage(function(cx, fy, cw, fh, dt) return customPage(cx, fy, cw, dt) end)
                return self
            end

            function TabFunctions:Section(SectionSettings)
                SectionSettings = SectionSettings or {}
                local sec = {
                    title = SectionSettings.Name or SectionSettings.Title or "Section",
                    side = SectionSettings.Side or "Left",
                    icon = SectionSettings.Icon,     -- опциональная икон��а слева от н��звания
                    elements = {},
                }
                tab.sections[#tab.sections + 1] = sec
                local SectionFunctions = {}

                local function add(kind, settings, state)
                    local el = { kind = kind, key = uid(kind), settings = settings or {}, state = state or {} }
                    sec.elements[#sec.elements + 1] = el
                    return el
                end

                -- ЖИВЫЕ MacLib-СВОЙСТВА. MacLib выставляет у хендла поля .State/.Value/
                -- .Text/.Bind/.Color/.Alpha, отражающие ТЕКУЩЕЕ значение. У нас данные
                -- лежат в el.state, поэтому даём их через метатаблицу (__index читает
                -- живьём). Методы остаются прямыми ключами F и разрешаются раньше
                -- __index -- метатаблица срабатывает лишь для отсутствующих ключей.
                local function liveProps(F, el, class, map)
                    F.Class = class
                    local mt = { __index = function(_, k)
                        local src = map[k]
                        if src == nil then return nil end
                        if type(src) == "function" then return src(el) end
                        return el.state[src]
                    end }
                    return setmetatable(F, mt)
                end

                -- Label -> теперь возвращает handle с MacLib-методами (п.11),
                -- оставаясь совместимым (цепочка через SectionFunctions больше не
                -- нужна: MacLib возвращает handle, а не секцию).
                function SectionFunctions:Label(s)
                    s = s or {}
                    local el = add("Label", s, { text = s.Text or s.Name or "" })
                    local F = { Settings = s }
                    function F:UpdateName(n) s.Text = n; el.state.text = n end
                    F.SetText = F.UpdateName
                    function F:SetVisibility(v) el.visible = v end
                    return F
                end
                -- SubLabel -- мелкий приглушённый текст (MacLib). Рисуется как Label,
                -- но поме��аем tiny -> elDraw.Label уменьшит кегль/яркость.
                function SectionFunctions:SubLabel(s)
                    s = s or {}
                    local el = add("Label", s, { text = s.Text or s.Name or "", sub = true })
                    local F = { Settings = s }
                    function F:UpdateName(n) s.Text = n; el.state.text = n end
                    function F:SetVisibility(v) el.visible = v end
                    return F
                end
                -- Header -- жирный заголовок-разделитель внутри секции (MacLib).
                function SectionFunctions:Header(s)
                    s = s or {}
                    local el = add("Header", s, { text = s.Text or s.Name or "" })
                    local F = { Settings = s }
                    function F:UpdateName(n) s.Text = n; el.state.text = n end
                    function F:SetVisibility(v) el.visible = v end
                    return F
                end
                function SectionFunctions:Paragraph(s)
                    local el = add("Paragraph", s)
                    local F = { Settings = s }
                    function F:UpdateHeader(n) s.Title = n end
                    function F:UpdateBody(n) s.Description = n end
                    function F:SetVisibility(v) el.visible = v end
                    return F
                end
                -- Divider: опциональный Text -> подпись по центру (иначе ромб-узел).
                function SectionFunctions:Divider(s)
                    if type(s) == "string" then s = { Text = s } end
                    local el = add("Divider", s or {})
                    local F = { Settings = el.settings }
                    function F:UpdateName(n) el.settings.Text = n end
                    F.SetText = F.UpdateName
                    function F:SetVisibility(v) el.visible = v end
                    function F:Remove() el.visible = false end
                    return F
                end
                -- Spacer -- пустой верт��кальный зазор (MacLib).
                function SectionFunctions:Spacer(s)
                    local el = add("Spacer", s or {})
                    local F = {}
                    function F:SetVisibility(v) el.visible = v end
                    function F:Remove() el.visible = false end
                    return F
                end

                function SectionFunctions:Button(s, flag)
                    local el = add("Button", s)
                    local F = { Settings = s, Class = "Button" }
                    function F:UpdateName(n) s.Name = n end
                    function F:UpdateDescription(n) s.Description = n end
                    function F:SetCallback(fn) s.Callback = fn end
                    function F:SetVisibility(v) el.visible = v end
                    bindFlag(flag, F)
                    return F
                end

                function SectionFunctions:Toggle(s, flag)
                    s = s or {}
                    local el = add("Toggle", s, { on = s.Default and true or false, color = s.Color })
                    if s.Default and s.Callback then pcall(s.Callback, true) end
                    local F = { Settings = s }
                    function F:GetState() return el.state.on end
                    function F:UpdateState(v) el.state.on = v and true or false; if s.Callback then pcall(s.Callback, el.state.on) end end
                    -- Set/SetValue -- ТИХАЯ установка сост��яния (без колбэка): для
                    -- внешней синхронизации UI (напр. кейбинд переключил функцию ->
                    -- тумблер отражает это, не вызывая колбэк повторно и без рекурсии).
                    function F:Set(v) el.state.on = v and true or false end
                    F.SetValue = F.Set
                    function F:Toggle() F:UpdateState(not el.state.on) end
                    function F:SetCallback(fn) s.Callback = fn end
                    function F:UpdateName(n) s.Name = n end
                    function F:SetColor(c) el.state.color = c end
                    function F:SetEnabledColor(c) s.EnabledColor = c; el.state.color = c end
                    function F:SetDisabledColor(c) s.DisabledColor = c end
                    function F:SetVisibility(v) el.visible = v end
                    liveProps(F, el, "Toggle", { State = "on" })
                    bindFlag(flag, F)
                    return F
                end

                function SectionFunctions:Slider(s, flag)
                    s = s or {}
                    s.Minimum = s.Minimum or 0
                    s.Maximum = s.Maximum or 100
                    local el = add("Slider", s, { value = s.Default or s.Minimum })
                    local F = { Settings = s }
                    function F:GetValue() return el.state.value end
                    -- UpdateValue(v, silent): silent=true -> без колбэка (MacLib-сигнатура).
                    function F:UpdateValue(v, silent)
                        el.state.value = clamp(v, s.Minimum, s.Maximum)
                        if not silent and s.Callback then pcall(s.Callback, el.state.value) end
                    end
                    F.SetValue = F.UpdateValue
                    function F:SetCallback(fn) s.Callback = fn end
                    function F:UpdateName(n) s.Name = n end
                    function F:SetVisibility(v) el.visible = v end
                    liveProps(F, el, "Slider", { Value = "value" })
                    bindFlag(flag, F)
                    return F
                end

                -- ScaleSlider: слайдер для «живых» масштабных параметров, которые
                -- меняют раскладку прямо во время д��ага (UI Scale �� подобные).
                -- Относител��ный захват ручки -> нет джиттера при рескейле. API
                -- совпадает со Slider.
                function SectionFunctions:ScaleSlider(s, flag)
                    s = s or {}
                    s.Minimum = s.Minimum or 0.8
                    s.Maximum = s.Maximum or 1.4
                    s.Increment = s.Increment or 0.05
                    s.Rounding = s.Rounding or 2
                    local el = add("ScaleSlider", s, { value = s.Default or 1.0 })
                    local F = { Settings = s }
                    function F:GetValue() return el.state.value end
                    function F:UpdateValue(v, silent)
                        el.state.value = clamp(v, s.Minimum, s.Maximum)
                        if not silent and s.Callback then pcall(s.Callback, el.state.value) end
                    end
                    F.SetValue = F.UpdateValue
                    function F:SetCallback(fn) s.Callback = fn end
                    function F:UpdateName(n) s.Name = n end
                    function F:SetVisibility(v) el.visible = v end
                    liveProps(F, el, "ScaleSlider", { Value = "value" })
                    bindFlag(flag, F)
                    return F
                end

                function SectionFunctions:Input(s, flag)
                    s = s or {}
                    local el = add("Input", s, { text = s.Default or "" })
                    local F = { Settings = s }
                    function F:GetText() return el.state.text end
                    F.GetInput = F.GetText
                    function F:SetText(t) el.state.text = t or ""; if s.Callback then pcall(s.Callback, el.state.text) end end
                    F.UpdateText = F.SetText
                    function F:Clear() el.state.text = "" end
                    function F:SetCallback(fn) s.Callback = fn end
                    function F:SetOnChanged(fn) s.OnChanged = fn end
                    function F:UpdatePlaceholder(p) s.Placeholder = p end
                    function F:UpdateName(n) s.Name = n end
                    function F:SetVisibility(v) el.visible = v end
                    liveProps(F, el, "Input", { Text = "text" })
                    bindFlag(flag, F)
                    return F
                end

                function SectionFunctions:Keybind(s, flag)
                    s = s or {}
                    -- Mobile=true means the +/- FAB toggle exists. FAB itself
                    -- starts OFF -- otherwise every combat bind dumps a 28px
                    -- icon button on screen (lag + "all keybinds enabled").
                    local el = add("Keybind", s, { key = s.Default, listening = false, fab = false })
                    s._el = el
                    -- стабильный id для персиста FAB (позиция/видимость) по flag,
                    -- иначе индексный "kb"..i плывёт при смене порядка биндов.
                    el.mobileFlag = flag or (("kb" .. tostring(#(Engine.keybindEls or {}) + 1)))
                    local reg = Engine.keybindEls
                    if not reg then
                        reg = {}
                        Engine.keybindEls = reg
                    end
                    reg[#reg + 1] = el
                    local F = { Settings = s, _el = el }
                    function F:GetKeybind() return el.state.key end
                    F.GetBind = F.GetKeybind
                    function F:SetKeybind(k) el.state.key = k end
                    F.Bind = F.SetKeybind
                    function F:Unbind() el.state.key = nil end
                    function F:SetCallback(fn) s.Callback = fn end
                    function F:SetOnBinded(fn) s.onBinded = fn end
                    function F:SetOnBindHeld(fn) s.onBindHeld = fn end
                    function F:SetBlacklist(list) s.Blacklist = list end
                    function F:SetListName(name) s.ListName = name end
                    function F:GetListName() return s.ListName or s.Name end
                    function F:UpdateName(n) s.Name = n end
                    function F:SetVisibility(v) el.visible = v end
                    function F:ShowMobileButton(v) el.state.fab = (v ~= false) end
                    function F:HideMobileButton() el.state.fab = false end
                    F.SetMobileButton = F.ShowMobileButton
                    -- MacLib-совместимые имена.
                    function F:SetMobileButtonVisibility(v) el.state.fab = v and true or false end
                    function F:SetMobileImage(assetId) s.MobileImage = assetId; el.state.mobileImage = assetId end
                    liveProps(F, el, "Keybind", { Bind = "key" })
                    bindFlag(flag, F)
                    return F
                end
                -- Bind -- алиас Keybind (MacLib н����ывает его так в части сборок).
                SectionFunctions.Bind = SectionFunctions.Keybind

                function SectionFunctions:Dropdown(s, flag)
                    s = s or {}
                    local st = { value = nil, multi = {} }
                    if s.Multi then
                        if type(s.Default) == "table" then
                            for _, v in ipairs(s.Default) do st.multi[v] = true end
                        end
                    else
                        -- MacLib допускает Default как ЧИСЛОВОЙ индекс в Options
                        -- (напр. Default = 1). Резолвим в само значение опции.
                        if type(s.Default) == "number" and s.Options then
                            st.value = s.Options[s.Default]
                        else
                            st.value = s.Default
                        end
                    end
                    local el = add("Dropdown", s, st)
                    local F = { Settings = s }
                    function F:GetValue() return s.Multi and el.state.multi or el.state.value end
                    function F:SetValue(v) if s.Multi then el.state.multi = v else el.state.value = v end; if s.Callback then pcall(s.Callback, v) end end
                    F.UpdateSelection = F.SetValue
                    function F:UpdateOptions(o) s.Options = o end
                    -- MacLib option-management API (п.11)
                    function F:GetOptions() return s.Options or {} end
                    function F:InsertOptions(newOpts)
                        s.Options = s.Options or {}
                        for _, o in ipairs(newOpts) do s.Options[#s.Options + 1] = o end
                    end
                    function F:ClearOptions() s.Options = {} end
                    function F:RemoveOptions(remove)
                        local rm = {}
                        for _, o in ipairs(remove) do rm[o] = true end
                        local kept = {}
                        for _, o in ipairs(s.Options or {}) do if not rm[o] then kept[#kept + 1] = o end end
                        s.Options = kept
                    end
                    function F:IsOption(name)
                        for _, o in ipairs(s.Options or {}) do if o == name then return true end end
                        return false
                    end
                    function F:SetCallback(fn) s.Callback = fn end
                    function F:UpdateName(n) s.Name = n end
                    function F:SetVisibility(v) el.visible = v end
                    liveProps(F, el, "Dropdown", { Value = function(e) return s.Multi and e.state.multi or e.state.value end })
                    bindFlag(flag, F)
                    return F
                end

                function SectionFunctions:Colorpicker(s, flag)
                    s = s or {}
                    local el = add("Colorpicker", s, { color = s.Default or COL.cyan, alpha = s.Alpha or 1 })
                    local F = { Settings = s }
                    function F:GetColor() return el.state.color end
                    -- MacLib: SetColor НЕ вызывает Callback (тихая установка). Обновляем и
                    -- HSV-состояние поп��вера, чтобы палитра открылась на новом цвете.
                    function F:SetColor(c)
                        el.state.color = c
                        if c and c.ToHSV then
                            local h, sv, v = c:ToHSV()
                            el.state.hsv = { hue = h, sat = sv, val = v }
                        end
                    end
                    function F:GetAlpha() return el.state.alpha end
                    function F:SetAlpha(a) el.state.alpha = a end
                    function F:SetCallback(fn) s.Callback = fn end
                    function F:UpdateName(n) s.Name = n end
                    function F:SetVisibility(v) el.visible = v end
                    liveProps(F, el, "Colorpicker", { Color = "color", Alpha = "alpha" })
                    bindFlag(flag, F)
                    return F
                end

                function SectionFunctions:CreateCustomElement(s)
                    local el = add("Custom", s)
                    return { _el = el }
                end

                -- Подмешиваем зарегистрированные ч��рез PatchSection/ExtendSection/
                -- RegisterElement методы -> они доступны на секции наравне со
                -- встроенными (для секций, созданных после регистрации).
                for exName, exFn in pairs(Nova._sectionExt) do
                    SectionFunctions[exName] = exFn
                end

                return SectionFunctions
            end
            return TabFunctions
        end
        return TabGroupFunctions
    end

    return WindowFunctions
end

-- Notify: MacLib-совмес��имая сигнатура {Title, Description, Lifetime}.
function Nova:Notify(Settings)
    Settings = Settings or {}
    Engine.notify(Settings.Title or "Notify", Settings.Description or "",
        Settings.Lifetime or 3, Settings.Color or COL.cyan)
end

-- === Глобальное управл��ние нотификациями (публичное API) ===
-- Включить/выключить показ всех тостов. Когда выключено -- Nova:Notify мо��ча
-- ничего не делает (тосты не соз��аются).
function Nova:SetNotificationsEnabled(v)
    v = v and true or false
    app.custom.notifyEnabled = v
    Engine.notifyEnabled = v
    return v
end
function Nova:ToggleNotifications()
    return Nova:SetNotificationsEnabled(not (Engine.notifyEnabled ~= false))
end
function Nova:NotificationsEnabled() return Engine.notifyEnabled ~= false end
-- Прозрачность тостов 0.2..1.0.
function Nova:SetNotificationOpacity(o)
    o = clamp(tonumber(o) or 1, 0.2, 1)
    app.custom.notifyOpacity = o
    Engine.notifyOpacity = o
    return o
end
-- Сброс всех активных тостов немедленно.
function Nova:ClearNotifications()
    Engine.clearToasts()
end

----------------------------------------------------------------------------
-- МОБИЛЬНЫЕ ПЛАВАЮЩИЕ КНОПКИ: публичное API (масштаб/прозрачность/режим/сброс).
----------------------------------------------------------------------------
-- Режим видимости: "auto" (по устройству) | "always" (форс вкл) | "off" (форс выкл).
function Nova:SetMobileMode(mode)
    if mode == "always" then app.custom.mobileBtn = true
    elseif mode == "off" then app.custom.mobileBtn = false
    else app.custom.mobileBtn = nil end
    return mode
end
function Nova:GetMobileMode()
    local v = app.custom.mobileBtn
    if v == true then return "always" elseif v == false then return "off" else return "auto" end
end
function Nova:SetMobileScale(v)
    v = clamp(tonumber(v) or 1, 0.7, 1.6)
    app.custom.mobileScale = v
    return v
end
    function Nova:SetKeybindScale(v)
    v = clamp(tonumber(v) or 1, 0.7, 1.8)
    app.custom.keybindScale = v
    return v
    end
    function Nova:SetMobileOpacity(v)
    v = clamp(tonumber(v) or 1, 0.3, 1)
    app.custom.mobileOpacity = v
    return v
    end
-- Сброс позиций всех плавающих кнопок на дефолт (спасение, ес��и утащили за край).
function Nova:ResetMobilePositions()
    if Engine.resetMobilePos then Engine.resetMobilePos() end
end

----------------------------------------------------------------------------
-- CONFIG SYSTEM: п��пки Library/Folder + флаги + опциональная ТЕМА UI + AutoLoad.
----------------------------------------------------------------------------
-- Формат файла конфига (JSON):
--   { flags = {...}, theme = {...}|nil, meta = { changesUI = bool } }
-- theme присутствует, только если при сохранении включён «Save UI» -> по этому
-- же признаку конфиг «меняет UI» (meta.changesUI). Старый плоски�� форма�� (только
-- флаги) читается ка�� back-compat. Все ФС-операции опциональны �� под pcall.
Nova.Library = "Nova"
Nova.Folder  = "Configs"
Nova.activeConfig = nil            -- имя загруженного конфига (метка ACTIVE)
-- Настройки менеджера (сохраняются в _settings.json):
Nova.cfgSaveUI = true              -- включать тему UI при сохранении
Nova.cfgApplyUIOnLoad = true       -- применять тему UI при загрузке (глоб. тумблер)
Nova.cfgAutoLoadEnabled = true     -- авто��агрузка включена
Nova.cfgAutoLoadName = nil         -- какой конфиг автозагружать
Nova.cfgAutoSave = false           -- авто-сохранять изменения �� AUTO-конфиг
Nova.cfgAutoSaveScope = "all"      -- "ui" = только тема | "all" = флаги + тема
-- Игнорировать масштабные ключи конфига (uiScale/fontScale/notifyScale/autoRescale)
-- при загрузке. Де��олт наследуем от Engine.ignoreConfigScale (мобила -> ВКЛ).
Nova.cfgIgnoreScale = Engine.ignoreConfigScale and true or false
Engine.ignoreConfigScale = Nova.cfgIgnoreScale

local HAS_FS = type(writefile) == "function" and type(readfile) == "function"
local function hasFS() return HAS_FS end
local function cfgDir() return Nova.Library .. "/" .. Nova.Folder end
local function cfgPath(name) return cfgDir() .. "/" .. (name or "default") .. ".json" end
local function settingsPath() return cfgDir() .. "/_settings.json" end

local _folderAt = 0
local _cfgList, _cfgListAt = nil, 0
local function invalidateCfgList()
    _cfgListAt = 0
end
local function ensureFolders()
    local now = os.clock()
    if now - _folderAt < 1 then return end
    _folderAt = now
    if type(makefolder) ~= "function" or type(isfolder) ~= "function" then return end
    if not isfolder(Nova.Library) then makefolder(Nova.Library) end
    local dir = cfgDir()
    if not isfolder(dir) then makefolder(dir) end
end

-- Флаги -> сериализуемая таблица (определяем тип по доступным геттерам).
local function serializeFlags()
    local out = {}
    for flag, ctrl in pairs(Nova.Flags) do
        local ok, v
        if ctrl.GetState then ok, v = pcall(ctrl.GetState, ctrl)
        elseif ctrl.GetValue then ok, v = pcall(ctrl.GetValue, ctrl)
        elseif ctrl.GetText then ok, v = pcall(ctrl.GetText, ctrl)
        elseif ctrl.GetColor then ok, v = pcall(function() local c = ctrl:GetColor(); return { c.R, c.G, c.B } end)
        elseif ctrl.GetKeybind then ok, v = pcall(function() local k = ctrl:GetKeybind(); return k and k.Name or nil end) end
        if ok and v ~= nil then out[flag] = v end
    end
    return out
end

-- Восстановление значений. РАНЬШЕ ветки были завязаны на UpdateState/UpdateValue/
-- SetText/SetColor -> Dropdown (у него SetValue, значение = строка/таблица) НЕ
-- восстанавливался («дропдауны не сохраняются»). Теперь маршрутизируе�� по ТИПУ
-- значения + доступным сеттерам, покрывая toggle/slider/text/keybind/color/
-- dropdown (single-строка и multi-словарь выбранных опций).
-- Флаги-масштабы Customize зарегистрированы как обычные слайдеры (ui_scale/
-- text_scale/notify_scale/auto_rescale) -> при загрузке их Callback'и applyUiScale
-- и т.п. срабатывали В ОБХОД гейта applyTheme, из-за чего «Keep my scale» не работал
-- (масштаб всё равно менялся). Здесь п��опускаем эти флаги, если игнор масштаба включён.
local SCALE_FLAGS = {
    ui_scale = true, text_scale = true, notify_scale = true, auto_rescale = true,
}
local function applyFlags(data)
    local skipScale = Engine.ignoreConfigScale
    for flag, v in pairs(data or {}) do
        local ctrl = Nova.Flags[flag]
        if ctrl and not (skipScale and SCALE_FLAGS[flag]) then
            local tv = type(v)
            if tv == "boolean" and ctrl.UpdateState then
                pcall(ctrl.UpdateState, ctrl, v)
            elseif tv == "number" and ctrl.UpdateValue then
                pcall(ctrl.UpdateValue, ctrl, v)
            elseif tv == "string" then
                if ctrl.SetKeybind then pcall(function() ctrl:SetKeybind(Enum.KeyCode[v]) end)
                elseif ctrl.SetValue then pcall(ctrl.SetValue, ctrl, v)   -- single dropdown
                elseif ctrl.SetText then pcall(ctrl.SetText, ctrl, v) end
            elseif tv == "table" then
                -- массив из 3 чисе�� = цвет {r,g,b}; иначе словарь = multi-dropdown
                if #v >= 3 and type(v[1]) == "number" and ctrl.SetColor then
                    pcall(ctrl.SetColor, ctrl, Color3.new(v[1], v[2], v[3]))
                elseif ctrl.SetValue then
                    pcall(ctrl.SetValue, ctrl, v)                          -- multi dropdown
                end
            end
        end
    end
end

