-- ЛОГОТИП: сменить арт/подпись/иконку/скорость перелива. Любое поле опционально.
--   Nova:SetLogo({ art = {"..line1..","..line2.."}, label="MyHub", icon="target", speed=1.3 })
-- Перес��итываем cols (макс. ширина строки в кодовых точках) под новый ��рт.
function Nova:SetLogo(opts)
    opts = opts or {}
    local LG = Engine.logo
    if opts.name    ~= nil then LG.name = opts.name end
    if opts.tagline ~= nil then LG.tagline = opts.tagline end
    if opts.icon    ~= nil then LG.icon = opts.icon end
    if opts.speed   ~= nil then LG.speed = opts.speed end
    -- glyphs -> добавить/переопределить битмапы букв (для кастомного во��дмарка).
    -- Передавай карту { A = {"X X",...}, ... }; строки 'X'/' '. Буквы без битмапа
    -- рисуются о��ычным шрифто�� (авто-откат).
    if type(opts.glyphs) == "table" then
        LG.glyphs = LG.glyphs or {}
        for k, v in pairs(opts.glyphs) do LG.glyphs[k:upper()] = v end
    end
    return LG
end
function Nova:GetLogo() return Engine.logo end

-- Персист настроек менеджера.
local function saveSettings()
    if not (hasFS() and HttpService) then return end
    ensureFolders()
    local s = {
        saveUI = Nova.cfgSaveUI, applyUIOnLoad = Nova.cfgApplyUIOnLoad,
        autoLoadEnabled = Nova.cfgAutoLoadEnabled, autoLoadName = Nova.cfgAutoLoadName,
        autoSave = Nova.cfgAutoSave, autoSaveScope = Nova.cfgAutoSaveScope,
        ignoreScale = Nova.cfgIgnoreScale,
    }
    pcall(function() writefile(settingsPath(), HttpService:JSONEncode(s)) end)
end
local function loadSettings()
    if not hasFS() then return end
    pcall(function()
        if type(isfile) == "function" and isfile(settingsPath()) then
            local raw = readfile(settingsPath())
            local ok, s = pcall(function() return HttpService:JSONDecode(raw) end)
            if ok and type(s) == "table" then
                if s.saveUI ~= nil then Nova.cfgSaveUI = s.saveUI end
                if s.applyUIOnLoad ~= nil then Nova.cfgApplyUIOnLoad = s.applyUIOnLoad end
                if s.autoLoadEnabled ~= nil then Nova.cfgAutoLoadEnabled = s.autoLoadEnabled end
                Nova.cfgAutoLoadName = s.autoLoadName
                if s.autoSave ~= nil then Nova.cfgAutoSave = s.autoSave end
                if s.autoSaveScope ~= nil then Nova.cfgAutoSaveScope = s.autoSaveScope end
                if s.ignoreScale ~= nil then
                    Nova.cfgIgnoreScale = s.ignoreScale
                    Engine.ignoreConfigScale = s.ignoreScale
                end
            end
        end
    end)
end
loadSettings()

-- Тумблеры менеджера (каждый сразу персистит настройки).
function Nova:SetSaveUI(v) Nova.cfgSaveUI = v and true or false; saveSettings() end
function Nova:GetSaveUI() return Nova.cfgSaveUI end
function Nova:SetApplyUIOnLoad(v) Nova.cfgApplyUIOnLoad = v and true or false; saveSettings() end
function Nova:GetApplyUIOnLoad() return Nova.cfgApplyUIOnLoad end
function Nova:SetAutoLoadEnabled(v) Nova.cfgAutoLoadEnabled = v and true or false; saveSettings() end
function Nova:GetAutoLoadEnabled() return Nova.cfgAutoLoadEnabled end
function Nova:SetAutoLoad(name) Nova.cfgAutoLoadName = name; saveSettings() end
function Nova:GetAutoLoad() return Nova.cfgAutoLoadName end
function Nova:SetAutoSave(v) Nova.cfgAutoSave = v and true or false; saveSettings() end
function Nova:GetAutoSave() return Nova.cfgAutoSave end
function Nova:SetAutoSaveScope(s) Nova.cfgAutoSaveScope = (s == "ui") and "ui" or "all"; saveSettings() end
function Nova:GetAutoSaveScope() return Nova.cfgAutoSaveScope end
-- Игнор масштабов конфига: сразу отражаем в Engine (его читает applyTheme) + персист.
