end
function Nova:GetIgnoreConfigScale() return Nova.cfgIgnoreScale end

-- Один тик авто-сох��анения (вызывается из onDraw). Раз в 0.7с СЕРИАЛИЗУЕМ текущее
-- состояние (по scope) и, если JSON отличается от прошлого снимка, пишем файл.
-- Снимо��-сравнение вместо dirty-хуков по всем сеттерам -> надёжно ловит ЛЮБОЕ
-- изменение (toggle/slider/dropdown/цвет/тема) без правки десятко�� методов.
-- Scope: "ui" -> только тема (флаги берём из файла), "all" -> флаги + тема.
local _asAccum, _asSnap = 0, nil
-- Сброс снимка авто-сохранения. Зовём при загрузке/переключении конфига, чтобы
-- первый тик после загрузки сравн��вался с ТОЛЬКО ЧТО применённым состоянием, а не
-- со старым снимком (иначе он посчитал бы это «изменени��м» и записал).
local function resetAutoSaveSnap() _asSnap = nil; _asAccum = 0 end
function Nova:AutoSaveTick(dt)
    -- ЦЕЛЬ авто-сохранения = АКТИВНЫЙ (загруженный) конфиг, а не фиксированный
    -- autoLoadName. Иначе: загрузил ConfigB -> autosave продолжал писать в ConfigA
    -- (autoLoad-цель) состояние ConfigB -> старый конфиг перезаписывался (жалоба).
    -- Теперь autosave всегда пишет туда, что реально открыто.
    local target = Nova.activeConfig or Nova.cfgAutoLoadName
    if not (Nova.cfgAutoSave and target) then _asSnap = nil; return end
    _asAccum = _asAccum + (dt or 0)
    if _asAccum < 1 then return end
    _asAccum = 0
    if not (hasFS() and HttpService) then return end
    local name = target
    local scope = Nova.cfgAutoSaveScope or "all"
    local payload
    if scope == "ui" then
        -- «UI only»: сохраняем ТОЛЬКО тему (флаги берём из уже лежащего файла,
        -- чтобы не потерять их). Такой конфиг МЕНЯЕТ UI -> changesUI = true.
        local flags = {}
        pcall(function()
            if type(isfile) == "function" and isfile(cfgPath(name)) then
                local raw = readfile(cfgPath(name))
                local ok, d = pcall(function() return HttpService:JSONDecode(raw) end)
                if ok and type(d) == "table" then flags = d.flags or {} end
            end
        end)
        payload = { flags = flags,
            theme = Engine.captureTheme and Engine.captureTheme() or nil,
            meta = { changesUI = true } }
    else
        -- «Everything»: флаги всегда; тему -- ТОЛЬКО если включён Save UI theme.
        -- changesUI отражает, реально ли писали тему -> корректный бей��ж «UI» и
        -- корректное поведение при загрузке (��ез темы UI не трогается).
        local includeUI = Nova.cfgSaveUI and Engine.captureTheme ~= nil
        payload = { flags = serializeFlags(),
            theme = includeUI and Engine.captureTheme() or nil,
            meta = { changesUI = includeUI and true or false } }
    end
    local okj, json = pcall(function() return HttpService:JSONEncode(payload) end)
    if not okj then return end
    -- ключ снимка учитывает �� имя цели (сменили AUTO -> первый тик перезапишет)
    local snap = name .. "|" .. scope .. "|" .. json
    if snap == _asSnap then return end       -- ничего не поменялось
    _asSnap = snap
    pcall(function() ensureFolders(); writefile(cfgPath(name), json) end)
    uiMetaCache[name] = (payload.meta.changesUI) and true or false
end

function Nova:ConfigExists(name)
    if not (hasFS() and type(isfile) == "function") then return false end
    local ok, res = pcall(isfile, cfgPath(name))
    return ok and res == true
end

-- Кэш «меняет ли конфиг UI» -> бейдж в списке без чтени�� фай��а каждый кадр.
local uiMetaCache = {}
function Nova:ConfigHasUI(name)
    if uiMetaCache[name] ~= nil then return uiMetaCache[name] end
    local res = false
    if hasFS() then
        pcall(function()
            if type(isfile) == "function" and isfile(cfgPath(name)) then
                local raw = readfile(cfgPath(name))
                local ok, d = pcall(function() return HttpService:JSONDecode(raw) end)
                if ok and type(d) == "table" then
                    -- ДОВЕРЯЕМ meta.changesUI, если meta есть: конфиг мог хранить
                    -- theme, но быть помечен как «не меняет UI» -> бейдж «UI» НЕ
                    -- показываем. Только для старого формата без meta смотрим theme.
                    if type(d.meta) == "table" then
                        res = d.meta.changesUI and true or false
                    else
                        res = (d.theme ~= nil)
                    end
                end
            end
        end)
    end
    uiMetaCache[name] = res
    return res
end

-- SaveConfig: пишет ф��аги + (опц.) тему. includeUI по умолчанию = Nova.cfgSaveUI.
-- writefile п��резаписывает -> Overwrite = просто повторный SaveConfig(имя).
function Nova:SaveConfig(name, opts)
    opts = opts or {}
    local includeUI = opts.includeUI
    if includeUI == nil then includeUI = Nova.cfgSaveUI end
    local payload = {
        flags = serializeFlags(),
        theme = (includeUI and Engine.captureTheme) and Engine.captureTheme() or nil,
        meta  = { changesUI = includeUI and true or false },
    }
    local json = HttpService and HttpService:JSONEncode(payload)
    if hasFS() and json then
        ensureFolders()
        pcall(function() writefile(cfgPath(name), json) end)
        invalidateCfgList()
    end
    uiMetaCache[name] = includeUI and true or false
    Nova.activeConfig = name
    return payload
end
Nova.OverwriteConfig = Nova.SaveConfig

-- LoadConfig: приме��яет флаги; тему -- только если она есть И включён applyUIOnLoad
-- (либо принудительно opts.applyUI). Back-compat: плоский старый формат = флаги.
function Nova:LoadConfig(name, opts)
    if not hasFS() then return false end
    opts = opts or {}
    local ok, raw = pcall(readfile, cfgPath(name))
    if not ok or not raw then return false end
    local ok2, data = pcall(function() return HttpService:JSONDecode(raw) end)
    if not (ok2 and type(data) == "table") then return false end
    local flags = data.flags or data          -- старый ��ормат = сами флаги
    applyFlags(flags)
    local applyUI = opts.applyUI
    if applyUI == nil then applyUI = Nova.cfgApplyUIOnLoad end
    -- КЛЮЧЕВОЕ: конфиг, сохранённый с выключенным «changes UI» (meta.changesUI ==
    -- false), НЕ ДО��ЖЕН трогать твой UI при заг��уз��е, даже если theme случайно
    -- леж��т в файле. Уважаем метку самого конфига поверх глобаль��ого applyUIOnLoad.
    local cfgChangesUI = true
    if type(data.meta) == "table" then cfgChangesUI = data.meta.changesUI and true or false end
    if data.theme and applyUI and cfgChangesUI and Engine.applyTheme then
        Engine.applyTheme(data.theme)
    end
    Nova.activeConfig = name
    -- Переключили активный конфиг -> сбрасываем снимок autosave: цель теперь = этот
    -- конфиг, и первый тик сравнится с только что применённым состоянием (не запишет
    -- лишнего и НЕ тронет прежний конфиг).
    resetAutoSaveSnap()
    return true
end

function Nova:RefreshConfigList()
    local now = os.clock()
    if _cfgList and now - _cfgListAt < 1 then return _cfgList end
    local list = {}
    if HAS_FS and type(listfiles) == "function" and isfolder(cfgDir()) then
        for _, f in ipairs(listfiles(cfgDir())) do
            local name = f:match("([^/\\]+)%.json$")
            if name and name ~= "_settings" and name ~= "_data" then
                list[#list + 1] = name
            end
        end
    end
    table.sort(list)
    _cfgList, _cfgListAt = list, now
    return list
end
Nova.GetConfigs = Nova.RefreshConfigList

function Nova:DeleteConfig(name)
    if not name or type(delfile) ~= "function" then return false end
    local ok = pcall(delfile, cfgPath(name))
    if ok then
        uiMetaCache[name] = nil
        invalidateCfgList()
        if Nova.activeConfig == name then Nova.activeConfig = nil end
        if Nova.cfgAutoLoadName == name then Nova.cfgAutoLoadName = nil; saveSettings() end
    end
    return ok
end

-- Автозагрузка при старте: разработчик вызывает Nova:LoadAutoloadConfig().
function Nova:LoadAutoloadConfig()
    if not Nova.cfgAutoLoadEnabled then return false end
    local name = Nova.cfgAutoLoadName
    if name and name ~= "" and Nova:ConfigExists(name) then
        return Nova:LoadConfig(name)
    end
    return false
end
-- Алиас с заглавной L -> совместимость с MacLib (MacLib:LoadAutoLoadConfig()).
Nova.LoadAutoLoadConfig = Nova.LoadAutoloadConfig

-- FORCE AUTOLOAD / FAL API. Это отдельный быстрый слой для значений элементов,
-- независимый от полного SaveConfig. Он используется ForceAutoLoad=true.
local function falDir()
    return cfgDir() .. "/FAutoLoad"
end
local function falPath(flag)
    return falDir() .. "/" .. tostring(flag) .. ".syl"
end
local function falEnsure()
    if type(makefolder) ~= "function" or type(isfolder) ~= "function" then return end
    pcall(function()
        if not isfolder(falDir()) then makefolder(falDir()) end
    end)
end
local function falRead(flag)
    if not (hasFS() and type(isfile) == "function" and isfile(falPath(flag))) then return nil end
    local ok, raw = pcall(readfile, falPath(flag))
    if not ok then return nil end
    local good, data = pcall(function() return HttpService:JSONDecode(raw) end)
    return good and type(data) == "table" and data or nil
end
local function falValue(ctrl)
    local c = ctrl.Class or inferClass(ctrl)
    local value
    if c == "Toggle" and ctrl.GetState then value = ctrl:GetState()
    elseif (c == "Slider" or c == "ScaleSlider") and ctrl.GetValue then value = ctrl:GetValue()
    elseif c == "Input" and ctrl.GetText then value = ctrl:GetText()
    elseif c == "Keybind" and ctrl.GetKeybind then
        local k = ctrl:GetKeybind(); value = k and k.Name or nil
    elseif c == "Dropdown" and ctrl.GetValue then value = ctrl:GetValue()
    elseif c == "Colorpicker" and ctrl.GetColor then
        local c3 = ctrl:GetColor(); value = { c3.R, c3.G, c3.B, ctrl.GetAlpha and ctrl:GetAlpha() or 1 }
    end
    return value
end
function Nova:FALSave(flag, ctrl)
    if not (flag and ctrl and hasFS() and HttpService) then return false end
    falEnsure()
    local payload = { type = ctrl.Class or inferClass(ctrl), value = falValue(ctrl) }
    if (ctrl.Class or inferClass(ctrl)) == "Keybind" and ctrl._el then
        payload.mbVisible = ctrl._el.state.fab and true or false
    end
    local ok, raw = pcall(function() return HttpService:JSONEncode(payload) end)
    if not ok then return false end
    return pcall(writefile, falPath(flag), raw)
end
function Nova:FALLoad(flag, ctrl, delay)
    local data = falRead(flag)
    if not data or not ctrl then return false end
    local value = data.value
    local c = ctrl.Class or inferClass(ctrl)
    if c == "Keybind" and type(value) == "string" then
        ctrl:SetKeybind(Enum.KeyCode[value])
        if data.mbVisible ~= nil and ctrl.SetMobileButtonVisibility then ctrl:SetMobileButtonVisibility(data.mbVisible) end
    elseif c == "Colorpicker" and type(value) == "table" and #value >= 3 then
        ctrl:SetColor(Color3.new(value[1], value[2], value[3]))
        if value[4] and ctrl.SetAlpha then ctrl:SetAlpha(value[4]) end
    else
        local cb = ctrl.Settings and ctrl.Settings.Callback
        if ctrl.Settings then ctrl.Settings.Callback = nil end
        setFlagByClass(ctrl, value)
        if ctrl.Settings then ctrl.Settings.Callback = cb end
    end
    return true
end
function Nova:FALClear(flag)
    if not flag or type(delfile) ~= "function" then return false end
    return pcall(delfile, falPath(flag))
end
function Nova:FALSetData(flag, value)
    if not (flag and hasFS() and HttpService) then return false end
    falEnsure()
    local ok, raw = pcall(function() return HttpService:JSONEncode({ type = "Custom", value = value }) end)
    if not ok then return false end
    return pcall(writefile, falPath(flag), raw)
end
function Nova:FALGetData(flag, default)
    local data = falRead(flag)
    return data and data.value ~= nil and data.value or default
end

