-- КОРНЕВА�� ОТРИСОВК��
----------------------------------------------------------------------------
Engine.onDraw(function(dt)
    -- ЧИСТАЯ БИ��ЛИОТЕКА: без построенного окна (Nova:Window) не рисуем НИЧЕГО.
    -- Раньше здесь срабатывал захардкоженный фолбэк-прототип (NAV/PAGES:
    -- Syllinse/Aura/AutoTotem...) -- это вводило в заблуждение при запуске nova.lua
    -- напрямую. Теперь окно рисует ТОЛЬКО потребитель через публичный API
    -- (см. demo.lua). Нет окна -> пустой кадр.
    if not (Engine.model and Engine.model.hasBuilt) then return end

    -- Пере��ив акцента -- пересчитываем COL.cyan/violet + фазу gradPhase до отрисовки.
    if Engine.updateAccentGrad then Engine.updateAccentGrad(dt) end
    -- Авто-сохранение AUTO-конфига (throttled, только при изменениях).
    if Nova.cfgAutoSave then Nova:AutoSaveTick(dt) end

    -- (перетаскивание окна применяется в glassPaint -- самом раннем пасе кадра --
    -- чтобы фон-шейдер и DI использовали одну позицию; см. коммент там)
    local x, y = WIN.pos.X, WIN.pos.Y
    local w, h = WIN.size.X, WIN.size.Y
    local sheet = Engine.sheet
    local sideW = sheet and 0 or M.side
    if not sheet then
        sidebar(x, y, h, dt)
    end

    local cx = x + sideW
    local cw = w - sideW
    topbar(cx, y, cw, dt)

    -- Фон контент���: сообщ��ем стеклу границу контент��ой зоны (setContentHole),
    -- дальше ��оле ВСЕГДА рисуется DI (immediate-mode -> без шлейфа при дра��е,
    -- живой Opacity без пересбо��ки шейдера). Стекло держи�� здесь ��розрачную
    -- дырку; нет Drawing("Shader") -> DI просто рисует по прямоугольни��у.
    local fy = y + M.top
    local fh = h - M.top
    if Engine.glassFxActive and Engine.glassFxActive() then
        Engine.setContentHole(sideW, M.top)
    end
    -- Поле ��онтента в��егда рисуе��ся через DI (immediate-mode -> без шлейфа,
    -- ж��вой Opacity без пересборки шейд��ра). Если стекло собралось, оно держит
    -- зд��сь прозрачную дырку; если нет -- DI просто рисует по прямоугольни��у.
    Engine.drawContentBg(cx, fy, cw, fh, WIN and WIN.radius or 12)

    hit("content", cx, fy, cw, fh, Z.BODY, true)
    local sd = Engine.scrolled("content")
    if sd ~= 0 then
        app.scrollY = clamp(app.scrollY - sd * 40, 0,
            math.max(app.contentH - fh, 0))
    end

    Engine.pushClip(cx, fy, cw, fh)
    -- Партиклы: плавающий фоновый слой ПОД контентом. Клип прямоугольный, а окно
    -- скруглённое -> инсетим поле от краёв на радиус угла + запас, чтобы частицы
    -- не залезали в скруглённые углы и не торчали «з�� контентом». Дополнительно
    -- edge-fade в drawParticles гасит их у границ поля.
    local pin = (WIN and WIN.radius or 12) + 10
    Engine.drawParticles(cx + pin, fy + pin,
        math.max(cw - pin * 2, 24), math.max(fh - pin * 2, 24), dt)
    local maxY = 0
    local builtTab = Engine.model and Engine.model.hasBuilt
        and Engine.model.tabByName and Engine.model.tabByName[app.nav]
    if builtTab then
        -- Модель билдера: рисуем активную вкладку (секции в две колонки либо
        -- полностраничный кастомный контент; 3D-сцена и страницы Configs/Customize
        -- приходят сюда как CustomPage построенной вкладки).
        maxY = Engine.drawBuiltTab(builtTab, cx, fy, cw, fh, dt)
    else
        -- Вкладка выбр��на, но ещё не собрана: честная заглушка вместо пустого поля.
        text(cx + M.pad, fy + 20, 12, COL.faint,
            tostring(app.nav) .. " -- раздел ещё не собран", 1)
        maxY = fy + 40
    end
    Engine.popClip()

    -- Прячем шей��еры HSV-пикера, если в этом кад��е вкладка Customize не рисовалась.
    hidePickerFxIfIdle()

    app.contentH = maxY - (fy - app.scrollY) + 16

    -- Полоса прокрутки у правой кромки контента (ПЕРЕТАСКИВАЕМАЯ).
    if app.contentH > fh then
        local trackH = fh - 12
        local thumb = math.max(trackH * fh / app.contentH, 30)
        local maxScroll = math.max(app.contentH - fh, 1)
        local trackY0 = fy + 6
        local ty = trackY0 + (trackH - thumb) * clamp(app.scrollY / maxScroll, 0, 1)
        local sx = x + w - 7

        -- Широкая невидимая зона захвата (с��ма полоса тонкая 3px, но хватать её
        -- пальцем/курсором надо удобно) -> ключ scrollbar/thumb.
        local grabKey = "content/scrollthumb"
        hit(grabKey, sx - 5, ty, 13, thumb, Z.CONTENT + 5)
        local sst = stateOf(grabKey)
        sst.hover = approach(sst.hover, Engine.isHover(grabKey) and 1 or 0, dt, 16)

        -- клик по трек�� (вне ползунка) -> перепрыгнуть; ключ scrollbar/track.
        local trackKey = "content/scrolltrack"
        hit(trackKey, sx - 5, trackY0, 13, trackH, Z.CONTENT + 4)

        if Engine.clicked(grabKey) then
            -- запомнить смещение курсора внутри ползунка -> плавный захват без рывка
            sst.grab = Engine.input.mouse.Y - ty
        end
        if Engine.isActive(grabKey) then
            local off = sst.grab or (thumb * 0.5)
            local rel = (Engine.input.mouse.Y - off - trackY0) / math.max(trackH - thumb, 1)
            app.scrollY = clamp(rel, 0, 1) * maxScroll
        elseif Engine.clicked(trackKey) then
            -- ��рыжок к точке клика по треку (центрируем ползунок на курсоре)
            local rel = (Engine.input.mouse.Y - trackY0 - thumb * 0.5) / math.max(trackH - thumb, 1)
            app.scrollY = clamp(rel, 0, 1) * maxScroll
        end

        -- перерасчёт по��иции ползунка после возможног�� изменения scrollY
        ty = trackY0 + (trackH - thumb) * clamp(app.scrollY / maxScroll, 0, 1)
        local tw = 3 + sst.hover * 2         -- чуть толще на ховере/захвате
        rrect(sx - (tw - 3) * 0.5, trackY0, 3, trackH, COL.text, 0.05, 1.5)
        rrect(sx - (tw - 3) * 0.5, ty, tw, thumb, COL.cyan, 0.55 + sst.hover * 0.35, tw * 0.5)
    end

    -- ВНЕШН��Я РАМКА ОКНА -- поверх всех панелей (иначе непрозрачные сайдбар/топбар/
    -- конт��нт, замо��ающие окно с тем же скруглением, закрасили бы контур). Тонкий
    -- акцентный контур с лёг���им «дыханием» + разделитель сайдбар/контент.
    if sheet and app.drawerOpen then
        local dw = math.min(Engine.drawerW or 240, math.max(120, w - 36))
        local scrimX = x + dw
        local scrimW = math.max(1, w - dw)
        rrect(scrimX, y, scrimW, h, COL.app, 0.55, 0)
        hit("drawer/scrim", scrimX, y, scrimW, h, Z.OVERLAY)
        if Engine.clicked("drawer/scrim") then app.drawerOpen = false end
        sidebar(x, y, h, dt, dw)
        line(x + dw, y + 8, x + dw, y + h - 8, COL.text, 0.14, 1)
    end

    local pulse = 0.16 + 0.05 * math.sin(os.clock() * 1.1)
    rstroke(x, y, w, h, COL.cyan, pulse, WIN.radius, 1)
    if not sheet then
        line(x + M.side, y + 1, x + M.side, y + h - 1, COL.text, 0.05, 1)
    end
end)

----------------------------------------------------------------------------
-- ДЕМО, СОБРАННОЕ НА БИЛДЕР-API (тот же порядок вызовов, что у MacLib)
----------------------------------------------------------------------------
-- Это и е��ть доказатель��тво «API + вызовы как у старой либы»: ве��ь интерфейс
-- ниже строится декларативно через Nova:Window -> :TabGroup -> :Tab -> :Section
-- -> элементы с {Settings} + Flag. Рендерит его модельный проход выше.
-- ============================================================================
-- Демо-окно ��ынесено в demo.lua. Ниже -- ТОЛЬКО библиотечные билдеры страниц,
-- которые демо вставляет в свои табы через tab:InsertUI()/:InsertGeometry()/
-- :InsertConfigSection()/:InsertCustomizationSection().
-- ============================================================================
    Engine.buildUISettings = function(UISettings)

    -- СЕКЦИЯ SCALE: размер окна (UI Scale) + кегль (Text Scale). ��аньше UI Scale
    -- ошибочно мен��л только шрифт (п.2) -- теперь он ресайзит окно, а прежнее
    -- поведение вынесено в отдельный Text Scale.
    local ScaleSec = UISettings:Section({ Name = "Layout & Scale", Side = "Left", Icon = "maximize" })
    -- Разделение сайдбара на группы -- ��ЕРВЫМ пунктом и с явным именем, чт��бы легко
    -- нах��дилось (раньше пр��талось в Behaviour). Выкл -> плоск��й список вкладок.
    ScaleSec:Toggle({ Name = "Sidebar Groups", Default = app.custom.navGroups ~= false,
        Callback = function(v) app.custom.navGroups = v end
    }, "nav_groups")
    -- AUTO-RESCALE: авто-подгон окна и кегля под разрешение экрана (эталон FullHD).
    -- При ВКЛ слайдеры ниже работают как БАЗА, умножаемая на фактор устройства.
    ScaleSec:Toggle({ Name = "Auto Rescale", Default = Engine.autoRescale ~= false,
        Callback = function(v)
            Engine.autoRescale = v and true or false
            app.custom.autoRescale = Engine.autoRescale
            -- при выключении возвращаем кегль к ручному значению (без фактора).
            if not Engine.autoRescale then
                Engine.fontScaleCur = app.custom.fontScale or 1
                applyFontScale(app.custom.fontScale or 1)
            end
        end
    }, "auto_rescale")
    -- UI Scale меняет РАЗМЕР ОКНА на лету -> используем ScaleSlider (отн. драг,
    -- без джиттера при рескейле).
    ScaleSec:ScaleSlider({ Name = "UI Scale", Minimum = 0.8, Maximum = 1.4, Increment = 0.05,
        Rounding = 2, Default = app.custom.uiScale,
        Callback = function(v) applyUiScale(v) end }, "ui_scale")
    ScaleSec:Slider({ Name = "Text Scale", Minimum = 0.85, Maximum = 1.6, Increment = 0.05,
        Rounding = 2, Default = app.custom.fontScale,
        Callback = function(v) app.custom.fontScale = v; applyFontScale(v) end }, "text_scale")

    -- СЕКЦИЯ NOTIFICATIONS (перенесена из Customize, п.9): все на��тройки тостов в
    -- одном месте (устра��ён дубль, п.3) + ЖИВОЕ ПРЕВЬЮ, которое масш��абируется
    -- вместе с Notify Scale.
    local NotifySec = UISettings:Section({ Name = "Notifications", Side = "Right", Icon = "bell" })
    -- ГЛОБАЛЬНЫЙ ВЫКЛЮЧАТЕЛЬ нотификаций -- первым пунктом.
    NotifySec:Toggle({ Name = "Enable Notifications", Default = app.custom.notifyEnabled ~= false,
        Callback = function(v) Nova:SetNotificationsEnabled(v) end }, "notify_enabled")
    NotifySec:Slider({ Name = "Notify Scale", Minimum = 0.8, Maximum = 1.4, Increment = 0.05,
        Rounding = 2, Default = app.custom.notifyScale,
        Callback = function(v) applyNotifyScale(v) end }, "notify_scale")
    NotifySec:Slider({ Name = "Notify Opacity", Minimum = 0.2, Maximum = 1.0, Increment = 0.05,
        Rounding = 2, Default = app.custom.notifyOpacity or 1.0,
        Callback = function(v) Nova:SetNotificationOpacity(v) end }, "notify_opacity")
    NotifySec:Slider({ Name = "Notify Duration", Minimum = 1, Maximum = 10, Increment = 0.5,
        Rounding = 1, Suffix = "s", Default = app.custom.notifyDur,
        Callback = function(v) app.custom.notifyDur = v end }, "notify_dur")
    -- анимируемое состояние «выключено» для превью (��лавный красный оверлей)
    local _disT = 0
    NotifySec:CreateCustomElement({ Height = 84, Draw = function(px, py, pw, ph, dt)
        -- ЖИВАЯ, ТОЧНАЯ мини-копия н��стоящего тоста (drawToasts): тень, корпус
        -- COL.panel, переливающаяся тон-кромка, верхний блик, тон-бейдж с колокольчиком,
        -- заголовок+текст и бегущий таймер-прогресс. ��асштаб = Notify Scale, ал��фа =
        -- Notify Opacity, переливание = Shimmering Toasts. При выключенных
        -- нотификациях наезжает красный знак запрета ⊘ (строго в границах карточки).
        local ns = Engine.notifyScale or 1.0
        local op = Engine.notifyOpacity or 1
        local disabled = Engine.notifyEnabled == false
        local shimmer = Engine.toastShimmer
        _disT = Engine.approach(_disT, disabled and 1 or 0, dt, 10)

        local cardH = math.floor(58 * ns)
        local cardW = math.min(pw - 10, math.floor(268 * ns))
        local cx0 = px + (pw - cardW) * 0.5
        local cy0 = py + (ph - cardH) * 0.5
        local r = math.floor(12 * ns)
        local a = op * (1 - _disT * 0.5)          -- общая альфа (как в реальном тосте)
        local tclk = os.clock()

        -- Тон с переливанием hue вокруг акцента -- ровно как в drawToasts.
        local tone = COL.cyan
        if shimmer then
            local h, s, v = COL.cyan:ToHSV()
            tone = Color3.fromHSV((h + 0.05 * math.sin(tclk * 1.6)) % 1, s, math.min(1, v + 0.05))
        end

        -- тень -> корпус -> кромка -> верхний блик
        rrect(cx0 + 3, cy0 + 5, cardW, cardH, COL.app, 0.40 * a, r + 2)
        rrect(cx0, cy0, cardW, cardH, COL.panel, 0.98 * a, r)
        local edgeA = shimmer and (0.24 + 0.16 * (0.5 + 0.5 * math.sin(tclk * 2.2))) or 0.30
        rstroke(cx0, cy0, cardW, cardH, tone, edgeA * a, r, 1)
        rrect(cx0 + r * 0.5, cy0, cardW - r, 1, COL.text, 0.06 * a, 0)

        -- ��он-бейдж + колокольчик
        local bxr = math.floor(15 * ns)
        local bcx, bcy = cx0 + 14 + bxr, cy0 + cardH * 0.5
        rrect(bcx - bxr, bcy - bxr, bxr * 2, bxr * 2, tone, 0.16 * a, bxr)
        rstroke(bcx - bxr, bcy - bxr, bxr * 2, bxr * 2, tone, 0.55 * a, bxr, 1.4)
        Engine.drawIcon("Bell", bcx - bxr * 0.5, bcy - bxr * 0.5, bxr, tone, 0.95 * a, 1.3)

        -- заголовок + подпись
        local tx = cx0 + 14 + bxr * 2 + 10
        text(tx, cy0 + 11 * ns, 13 * ns, COL.text, "Nova", a)
        text(tx, cy0 + 30 * ns, 11 * ns, COL.dim,
            disabled and "Notifications OFF" or "Notification preview", 0.72 * math.max(a, 0.4))

        -- ЖИВОЙ таймер-прогресс (з��цикленный) -> превью «дышит�� как настоящий тост.
        local th, ins = 3, 8
        local frac = disabled and 1 or (1 - (tclk % 3) / 3)   -- 3с цикл, убывает
        rrect(cx0 + ins, cy0 + cardH - th - 5, cardW - ins * 2, th, COL.trackOff, 0.5 * a, th * 0.5)
        local fw = (cardW - ins * 2) * frac
        if fw > 1 then
            rrect(cx0 + ins, cy0 + cardH - th - 5, fw, th, tone, 0.9 * a, th * 0.5)
        end

        -- КРАСНЫЙ ЗНАК ЗАПРЕТА ⊘ при «выключено» (строго внутри карточки: кольцо +
        -- диагональ ВНУТРИ радиуса -> геометрически не может выйти за грани��ы).
        if _disT > 0.01 then
            local red = Color3.fromRGB(239, 68, 68)
            local t = _disT
            rrect(cx0, cy0, cardW, cardH, red, 0.12 * t, r)
            rstroke(cx0, cy0, cardW, cardH, red, 0.75 * t, r, 1.5)
            local mcx, mcy = cx0 + cardW * 0.5, cy0 + cardH * 0.5
            local rad = math.min(cardH, cardW) * 0.26
            Engine.ring(mcx, mcy, rad, red, 0.9 * t, 28, 2)
            local d = rad * 0.7071
            Engine.line(mcx - d, mcy - d, mcx + d, mcy + d, red, 0.9 * t, 2)
        end
    end })
    NotifySec:Button({ Name = "Send Test Notification", Icon = "bell",
        Callback = function() Nova:Notify({ Title = "Nova", Description = "Notification preview", Lifetime = app.custom.notifyDur }) end
    })

    -- СЕКЦИЯ BEHAVIOUR: позиция поиска + бинд меню (только поведен��е, без эффектов).
    local BehSec = UISettings:Section({ Name = "Behaviour", Side = "Left", Icon = "gauge" })
    BehSec:Dropdown({ Name = "Search Bar", Options = { "Sidebar", "Top Bar" },
        Default = app.custom.searchPos == "topbar" and "Top Bar" or "Sidebar",
        Callback = function(o) app.custom.searchPos = (o == "Top Bar") and "topbar" or "sidebar" end
    }, "ui_searchpos")
    -- Кейбинд открытия/закрытия меню (перен��сён сюда из старой вкладки Configs).
    BehSec:Keybind({ Name = "Menu Toggle", Default = Enum.KeyCode.RightControl,
        HideFromList = true,     -- UI-бинд НЕ пока��ываем в Keybind List HUD
        NoMobileButton = true,   -- нет смысла в FAB -- уже есть отдельная Mobile Button
        Callback = function() Engine.toggle() end
    }, "menu_key")

    -- ── СЕКЦИЯ KEYBIND LIST (для ПК): детальны�� настройки HUD-списка + живое
    -- превью, испо��ьзующее ту же Engine.kbListPaint, что и настоящий HUD. ──
    local KbSec = UISettings:Section({ Name = "Keybind List", Side = "Right", Icon = "keyboard-filled" })
    KbSec:Toggle({ Name = "Enable Keybind List", Default = app.custom.keybindList,
        Callback = function(v) app.custom.keybindList = v end
    }, "ui_kblist")
    -- Show Bound: ВЫКЛ -> только АКТИВНЫЕ (включённые) функции; ВКЛ -> все
    -- ЗАБИНЖЕННЫЕ (у которых задана клавиша), активные подсвечены.
    KbSec:Toggle({ Name = "Show All Bound", Default = app.custom.keybindListAll == true,
        Callback = function(v) app.custom.keybindListAll = v end
    }, "ui_kblist_all")
    KbSec:Toggle({ Name = "Show Icons", Default = app.custom.keybindListIcons ~= false,
        Callback = function(v) app.custom.keybindListIcons = v end
    }, "ui_kblist_icons")
    KbSec:Slider({ Name = "List Opacity", Minimum = 0.2, Maximum = 1, Increment = 0.05,
        Rounding = 2, Default = app.custom.keybindListOpacity or 1,
        Callback = function(v) app.custom.keybindListOpacity = v end }, "ui_kblist_op")
    KbSec:Slider({ Name = "List Scale", Minimum = 0.7, Maximum = 1.6, Increment = 0.05,
        Rounding = 2, Default = app.custom.keybindListScale or 1,
        Callback = function(v) app.custom.keybindListScale = v end }, "ui_kblist_scale")
    -- ЖИВОЕ ПРЕВЬЮ: тот же сборщик строк и та же отрисовка, что у HUD -> превью
    -- 1:1 отражает Show All Bound / Icons / Opacity / Scale и подсветку активных.
    KbSec:CreateCustomElement({ Height = 170, Draw = function(px, py, pw, ph, dt)
        rrect(px, py, pw, ph, COL.inset, 0.5, 12)
        Engine.gridRect(px, py, pw, ph, 12, COL.cyan, 0.05)
        rstroke(px, py, pw, ph, COL.line, 0.5, 12, 1)
        if not (Engine.kbListPaint and Engine.kbListRows) then return end
        local op = clamp(app.custom.keybindListOpacity or 1, 0.2, 1)
        local psc = 0.8 * clamp(app.custom.keybindListScale or 1, 0.7, 1.6)
        Engine.kbListPaint(px + 12, py + 12, psc, 1, Engine.kbListRows(), op)
    end })

    -- СЕКЦИЯ EFFECTS: тумб��еры г��адиентов ПООТДЕЛЬНОСТИ (акцент / иконки) + их
    -- скорости, мерцание тостов и фоновые партиклы. Это «выключить градиент и
    -- именно каких элементо����» -- каждый эффект гасится независимо.
    local FxSec = UISettings:Section({ Name = "Effects", Side = "Right", Icon = "sparkles" })
    FxSec:Toggle({ Name = "Gradient Accent", Default = app.custom.accentGrad,
        Callback = function(v)
            app.custom.accentGrad = v
            -- синхронизируем со слотами Customise: выкл -> B следует за A
            if not v then
                local a = app.custom.accent
                app.custom.accent2.r, app.custom.accent2.g, app.custom.accent2.b = a.r, a.g, a.b
            end
            if Engine.applyAccentPublic then Engine.applyAccentPublic() end
            if Engine.updateAccentGrad then Engine.updateAccentGrad() end
        end
    }, "fx_accentgrad")
    -- (Accent/Icon Speed слайдеры удален�� -- градиент теперь статичный A->B.)
    FxSec:Toggle({ Name = "Gradient Icons", Default = app.custom.iconGrad,
        Callback = function(v) app.custom.iconGrad = v; Engine.iconGrad = v end
    }, "fx_icongrad")
    FxSec:Toggle({ Name = "Shimmering Toasts", Default = app.custom.notifyShimmer,
        Callback = function(v) app.custom.notifyShimmer = v; Engine.toastShimmer = v end
    }, "fx_toastshim")
    -- ПЕРЕЛИВ мобильных кнопок (Mobile Button + keybind-FAB) -- отдельный тумблер.
    FxSec:Toggle({ Name = "Mobile Gradient", Default = app.custom.mobileGrad ~= false,
        Callback = function(v) app.custom.mobileGrad = v end
    }, "fx_mobilegrad")
    -- ПЕРЕЛИВ Keybind List HUD -- отдел��ный тумблер.
    FxSec:Toggle({ Name = "Keybind List Gradient", Default = app.custom.kbListGrad ~= false,
        Callback = function(v) app.custom.kbListGrad = v end
    }, "fx_kblistgrad")
    -- ── ФОНОВЫЙ ГРАДИЕНТ: явный вкл/выкл (жалоба «градиент к Background не
    -- применяется») + УНИВЕРСАЛЬНАЯ скорость всех градиентов. ──
    FxSec:Toggle({ Name = "Background Gradient", Default = app.custom.bgGradient ~= false,
        Callback = function(v) app.custom.bgGradient = v end
    }, "fx_bggrad")
    -- Один слайде�� управляет скоростью ВСЕХ градиентов (фон + переливающиеся иконки)
    -- через единые Engine.gradClock-часы. 0 -> заморозка.
    FxSec:Slider({ Name = "Gradient Speed", Minimum = 0, Maximum = 2, Increment = 0.1,
        Rounding = 1, Suffix = "x", Default = app.custom.gradSpeed,
        Callback = function(v)
            app.custom.gradSpeed = v
            Engine.gradSpeed = v
            Engine.iconGradSpeed = v
        end }, "fx_bgmotion")

    -- (Секция «Brand Logo» удалена -- бренд-иконка над вордмарком убрана.)

    -- ── ЧАСТИЦЫ: детальная настройк��. Секция слева. ──
    local PartSec = UISettings:Section({ Name = "Particles", Side = "Left", Icon = "sparkles" })
    PartSec:Toggle({ Name = "Enable Particles", Default = app.custom.particles ~= false,
        Callback = function(v) app.custom.particles = v; Engine.particlesOn = v end
    }, "fx_particles")
    PartSec:Dropdown({ Name = "Shape", Options = { "Dots", "Stars", "Bolts" },
        Default = ({ dots = "Dots", stars = "Stars", bolts = "Bolts" })[app.custom.partShape] or "Dots",
        Callback = function(o)
            app.custom.partShape = o:lower()
            Engine.syncParticleCfg()
        end }, "fx_partshape")
    PartSec:Dropdown({ Name = "Direction", Options = { "Up", "Down" },
        Default = app.custom.partDir == "down" and "Down" or "Up",
        Callback = function(o) app.custom.partDir = o:lower(); Engine.syncParticleCfg() end
    }, "fx_partdir")
    PartSec:Slider({ Name = "Count", Minimum = 6, Maximum = 80, Increment = 1,
        Rounding = 0, Default = app.custom.partCount,
        Callback = function(v) app.custom.partCount = v; Engine.syncParticleCfg() end }, "fx_partcount")
    PartSec:Slider({ Name = "Speed", Minimum = 0, Maximum = 3, Increment = 0.1,
        Rounding = 1, Suffix = "x", Default = app.custom.partSpeed,
        Callback = function(v) app.custom.partSpeed = v; Engine.syncParticleCfg() end }, "fx_partspeed")
    PartSec:Slider({ Name = "Size", Minimum = 0.4, Maximum = 3, Increment = 0.1,
        Rounding = 1, Suffix = "x", Default = app.custom.partSize,
        Callback = function(v) app.custom.partSize = v; Engine.syncParticleCfg() end }, "fx_partsize")
    PartSec:Slider({ Name = "Drift", Minimum = 0, Maximum = 3, Increment = 0.1,
        Rounding = 1, Suffix = "x", Default = app.custom.partDrift,
        Callback = function(v) app.custom.partDrift = v; Engine.syncParticleCfg() end }, "fx_partdrift")
    PartSec:Slider({ Name = "Glow", Minimum = 0.3, Maximum = 2, Increment = 0.1,
        Rounding = 1, Suffix = "x", Default = app.custom.partGlow,
        Callback = function(v) app.custom.partGlow = v; Engine.syncParticleCfg() end }, "fx_partglow")

    local OptSec = UISettings:Section({ Name = "Optimization", Side = "Left", Icon = "gauge" })
    OptSec:CreateCustomElement({
        Height = 200,
        Draw = function(x, y, w, h, dt)
            local qcur = Engine.quality or 1
            text(x + 14, y + 8, 13, COL.text, "Performance", 1)

            local names = { "Low", "Med", "High" }
            local hint = { "Light", "Normal", "Full" }
            local cellW = (w - 36) / 3
            local cellH = 58
            local cy0 = y + 32
            for i = 0, 2 do
                local cx = x + 14 + i * (cellW + 4)
                local key = "opt/q/" .. i
                hit(key, cx, cy0, cellW, cellH)
                if Engine.clicked(key) then Engine.applyQuality(i) end
                local on = qcur == i
                local hv = Engine.isHover(key) and 1 or 0
                rrect(cx, cy0, cellW, cellH, COL.panel, 1, 10)
                rrect(cx, cy0, cellW, cellH, COL.cyan, on and 0.22 or (0.04 + hv * 0.08), 10)
                rstroke(cx, cy0, cellW, cellH, COL.cyan, on and 0.65 or 0.14 + hv * 0.2, 10, 1)
                text(cx + 10, cy0 + 12, 15, COL.text, names[i + 1], 1)
                text(cx + 10, cy0 + 38, 10, COL.dim, hint[i + 1], 0.95)
            end

            local tabs, secs, els = 0, 0, 0
            for _, t in ipairs(model.tabs or {}) do
                tabs = tabs + 1
                for _, s in ipairs(t.sections or {}) do
                    secs = secs + 1
                    els = els + #(s.elements or {})
                end
            end
            local kbs = #(Engine.keybindEls or {})
            local stats = {
                { "Elements", tostring(els) },
                { "Tabs", tostring(tabs) },
                { "Sections", tostring(secs) },
                { "Keybinds", tostring(kbs) },
            }
            local sy = cy0 + cellH + 12
            local sw = (w - 36) / 4
            for i, st in ipairs(stats) do
                local sx = x + 14 + (i - 1) * (sw + 3)
                rrect(sx, sy, sw - 2, 42, COL.panel, 1, 8)
                text(sx + 8, sy + 6, 9, COL.dim, st[1], 0.95)
                text(sx + 8, sy + 20, 14, COL.text, st[2], 1)
            end
        end,
    })

    -- ── СЕКЦИЯ MOBILE: плаваю��ие кнопки (toggle-пилюля + keybind-FAB). Видимость,
    -- м��сштаб, прозрачность + ЖИВОЕ ПРЕВЬЮ (мини-пилюля NOVA + пример keybind-FAB),
    -- которое реагирует н�� слайдеры в реальном времени. С��кция справа. ──
    -- Кастомная иконка секции (юзерский SVG «нода/связанные кнопки»): в наборе нет
    -- "smartphone", поэтому регистрируем свой vector -> резолвер найдёт его первым.
    Engine.registerIcon("nova_mobicon", [[<svg width="46" height="46" fill="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M6 14c-2.206 0-4 1.794-4 4s1.794 4 4 4a4.003 4.003 0 0 0 3.998-3.98H10V16h4v2.039h.004A4.002 4.002 0 0 0 18 22c2.206 0 4-1.794 4-4s-1.794-4-4-4h-2v-4h2c2.206 0 4-1.794 4-4s-1.794-4-4-4-4 1.794-4 4v2h-4V5.98h-.002A4.003 4.003 0 0 0 6 2C3.794 2 2 3.794 2 6s1.794 4 4 4h2v4H6Zm2 4c0 1.122-.879 2-2 2s-2-.878-2-2c0-1.122.879-2 2-2h2v2Zm10-2c1.121 0 2 .878 2 2 0 1.122-.879 2-2 2s-2-.878-2-2v-2h2ZM16 6c0-1.122.879-2 2-2s2 .878 2 2c0 1.122-.879 2-2 2h-2V6ZM6 8c-1.121 0-2-.878-2-2 0-1.122.879-2 2-2s2 .878 2 2v2H6Zm4 2h4v4h-4v-4Z"></path></svg>]])
    local MobSec = UISettings:Section({ Name = "Mobile Buttons", Side = "Right", Icon = "nova_mobicon" })
    MobSec:Dropdown({ Name = "Show Buttons", Options = { "Auto (touch)", "Always", "Off" },
        Default = ({ auto = "Auto (touch)", always = "Always", off = "Off" })[Nova:GetMobileMode()],
        Callback = function(o)
            Nova:SetMobileMode(o == "Always" and "always" or (o == "Off" and "off" or "auto"))
        end }, "mob_mode")
    MobSec:Slider({ Name = "Button Size", Minimum = 0.7, Maximum = 1.6, Increment = 0.05,
        Rounding = 2, Default = app.custom.mobileScale or 1,
        Callback = function(v) Nova:SetMobileScale(v) end }, "mob_scale")
    MobSec:Slider({ Name = "Keybind Size", Minimum = 0.7, Maximum = 1.8, Increment = 0.05,
        Rounding = 2, Default = app.custom.keybindScale or 1,
        Callback = function(v) Nova:SetKeybindScale(v) end }, "mob_kbscale")
    MobSec:Slider({ Name = "Button Opacity", Minimum = 0.3, Maximum = 1, Increment = 0.05,
        Rounding = 2, Default = app.custom.mobileOpacity or 1,
        Callback = function(v) Nova:SetMobileOpacity(v) end }, "mob_opacity")
    -- Подпись имени под keybind-FAB. По умолчанию ВЫКЛ (просьба -- текс�� мешал).
    MobSec:Toggle({ Name = "Keybind Labels", Default = app.custom.keybindFabLabels == true,
        Callback = function(v) app.custom.keybindFabLabels = v end }, "mob_kblabels")
    -- ЖИВОЕ ПРЕВЬЮ: та же геометрия, что у настоящих плавающих кнопок (общ��е
    -- Engine.drawTogglePillPreview / drawKeyFabPreview). Button Size ма��штабирует
    -- пилюлю, Keybind Size -- FAB, независимо; Opacity виден сразу.
    MobSec:CreateCustomElement({ Height = 138, Draw = function(px, py, pw, ph, dt)
        local scT = clamp(app.custom.mobileScale or 1, 0.7, 1.6) * 0.9
        local scK = clamp(app.custom.keybindScale or 1, 0.7, 1.8) * 0.82
        local op = clamp(app.custom.mobileOpacity or 1, 0.3, 1)
        -- фон-подложка превью с тонкой тех-сеткой (без верхней полоски-блика)
        rrect(px, py, pw, ph, COL.inset, 0.5, 12)
        Engine.gridRect(px, py, pw, ph, 12, COL.cyan, 0.05)
        rstroke(px, py, pw, ph, COL.line, 0.5, 12, 1)
        -- Mobile Button (открытое состояние для наглядности) слева
        if Engine.drawTogglePillPreview then
            Engine.drawTogglePillPreview(px + 24, py + 16, scT, op, 0.4, 0)
        end
        -- пример круглого keybind-FAB (монограмма «A» -> нет iconId) справа
        if Engine.drawKeyFabPreview then
            Engine.drawKeyFabPreview(px + pw - 86, py + 12, scK, op, "Aimbot", nil, 0, 0, 0, 1)
        end
    end })
    MobSec:Button({ Name = "Reset Positions", Icon = "crosshair",
        Callback = function()
            Nova:ResetMobilePositions()
            Nova:Notify({ Title = "Nova", Description = "Mobile buttons reset to default position", Lifetime = 3 })
        end
    })
    end  -- <<< конец Engine.buildUISettings

    -- Бил��ер полностраничной 3D-сцены «Geometry» -- вставляется системно.
